                Translate(GUID, null, value.DisplayedName + " in a Bottle", "瓶中" + value.DisplayedNameLocalized, Language.ChineseTraditional);
                string text2 = "A";
                string text2Loc = "你的手牌中會產生";
                string text3 = "[define:" + value.Name + "]";
                string text3Loc = "[define:" + value.Name + "]";
                if (NameStartsWithVowel(value.DisplayedName))
                {
