                    text4Loc += "。";
                    text3 = string.Format("An {0} is defined as: {1} Power, {2} Health", value.DisplayedName, value.Attack, value.Health) + text4;
                    text3Loc = string.Format("{0}具有{1}點攻擊力與{2}點生命力", value.DisplayedNameLocalized, value.Attack, value.Health) + text4Loc;
                }
                string text5 = string.Concat(new string[] { text2, " ", value.DisplayedName, " is created in your hand. ", text3 });
                string text5LocCardName = value.DisplayedNameLocalized;
                string text5Loc = string.Concat(new string[] { text2Loc, " ", text5LocCardName, "卡牌。", text3Loc });
                Translate(GUID, null, text5, text5Loc, Language.ChineseTraditional);
                Translate(GUID, null, "While " + value.DisplayedNameLocalized + " is on the board, remove ally Terrain and Pelt cards and transform the rest into random Apostles.", value.DisplayedNameLocalized + "在檯面上時，移除友方地形與毛皮卡牌，將其餘卡牌隨機轉化為使徒。", Language.ChineseTraditional);
                Translate(GUID, null, "[c:bR]The Clock[c:] and your [c:bR]" + value.DisplayedNameLocalized + "[c:] will remain in that abandoned time.", "[c:bR]時鐘[c:]和你的[c:bR]" + value.DisplayedNameLocalized + "[c:]將留在被遺棄的時間中。", Language.ChineseTraditional);
                Translate(GUID, null, "False " + value.DisplayedNameLocalized, "偽" + value.DisplayedNameLocalized, Language.ChineseTraditional);
                Translate(GUID, null, "[c:bB]That " + value.DisplayedNameLocalized + " costs more energy than you have.[c:]", "[c:bB]" + value.DisplayedNameLocalized + "所需的能量超過你現有的能量。[c:]", Language.ChineseTraditional);
            }
            if (source == null)
            for (int max = 1; max <= 10; max++)
            {
                Translate(GUID, null, "[c:bB]Do you still not get it? It costs " + max.ToString() + " energy and you don't have enough.[c:]", "[c:bB]還不明白嗎？它需要" + max.ToString() + "點能量，而你沒有足夠的能量。[c:]", Language.ChineseTraditional);
                for (int count = 0; count < max; count++)
                {
                    Translate(GUID, null, "[c:bB]That costs " + max.ToString() + " energy and you have " + count.ToString() + ".[c:]", "[c:bB]它需要" + max.ToString() + "點能量，而你只有" + count.ToString() + "點。[c:]", Language.ChineseTraditional);
                }
            }


            // LifeCostAPI
            if (source == null) Debug.Log("Post Register Translations for LifeCostAPI");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped to play [c:bG]" + value.DisplayedNameLocalized + "[c:].", "你的[c:bG]天平[c:]傾斜得太厲害，無法打出[c:bG]" + value.DisplayedNameLocalized + "[c:]。", Language.ChineseTraditional);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]" + value.DisplayedNameLocalized + "[c:] requires you to pay in life, in which you can not fullfill without killing yourself.", "[c:bG]" + value.DisplayedNameLocalized + "[c:]需要支付生命，你付出代價就會殺死自己。", Language.ChineseTraditional);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would kill yourself if you played [c:bG]" + value.DisplayedNameLocalized + "[c:]. Your [c:bG]Scales[c:] are too tipped", "打出[c:bG]" + value.DisplayedNameLocalized + "[c:]會殺死你。你的[c:bG]天平[c:]已經太傾斜了。", Language.ChineseTraditional);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped and you lack the [c:gray]Foils[c:] to play " + value.DisplayedNameLocalized + ".", "你的[c:bG]天平[c:]傾斜過大，也缺少[c:gray]碎箔[c:]，無法打出" + value.DisplayedNameLocalized + "。", Language.ChineseTraditional);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You lack the foils to play that [c:gray]" + value.DisplayedNameLocalized + "[c:].", "你沒有足夠的碎箔打出[c:gray]" + value.DisplayedNameLocalized + "[c:]。", Language.ChineseTraditional);
                for (int count = 0; count <= 20; count++)
                {
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]" + value.DisplayedNameLocalized + "[c:] requires you pay it's cost in [c:gray]foils[c:], that which you have [c:gray]" + count.ToString() + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:]的費用需以[c:gray]碎箔[c:]支付，你目前有[c:gray]" + count.ToString() + "[c:]張。", Language.ChineseTraditional);
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:gray]" + value.DisplayedNameLocalized + "[c:] has the cost of [c:gray]" + count.ToString() + "[c:] foils, which you do not have.", "[c:gray]" + value.DisplayedNameLocalized + "[c:]需要[c:gray]" + count.ToString() + "[c:]張碎箔，你沒有足夠的碎箔。", Language.ChineseTraditional);
                }
            }

            // Sire_MoDeers
            if (source == null) Debug.Log("Post Register Translations for Sire_MoDeers");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.DisplayedName + "'s Protector", value.DisplayedNameLocalized + "的守護者", Language.ChineseTraditional);
            }

            if (source == null) Debug.Log("Post Register Translations Ended");
            stopwatch.Stop();
            if (source == null) Debug.Log($"PostRegisterTranslations 执行时间: {stopwatch.ElapsedMilliseconds} ms");
        }

        private static List<PostRegisterCardData> CachePostRegisterCardData(IEnumerable<CardInfo> source)
        {
            var cards = new List<PostRegisterCardData>();
            foreach (var card in source)
            {
                if (card.SafeIsUnityNull()) continue;
                cards.Add(new PostRegisterCardData(card, card.IsBaseGameCard()));
            }
            return cards;
        }

        private sealed class PostRegisterCardData
        {
            public PostRegisterCardData(CardInfo card, bool isBaseGameCard)
            {
                IsBaseGameCard = isBaseGameCard;
                DisplayedNameEnglish = card.DisplayedNameEnglish;
                DisplayedNameLocalized = card.DisplayedNameLocalized;
                DisplayedName = card.displayedName;
                Description = card.description;
                Name = card.name;
                Attack = card.Attack;
                Health = card.Health;
                Abilities = card.Abilities?.ToArray() ?? Array.Empty<Ability>();
            }

            public bool IsBaseGameCard { get; }
            public string DisplayedNameEnglish { get; }
            public string DisplayedNameLocalized { get; }
            public string DisplayedName { get; }
            public string Description { get; }
            public string Name { get; }
            public int Attack { get; }
            public int Health { get; }
            public Ability[] Abilities { get; }
            public bool HasDisplayedNameEnglish => DisplayedNameEnglish != null;
            public bool HasDisplayedName => DisplayedName != null;
        }
        private static bool NameStartsWithVowel(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            char c = name.ToLowerInvariant()[0];
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

    }

