    public class GrimoraMod
    {
        public static Dictionary<string, string> Cards = new();

        public static void RegisterCard(string en, string zh)
        {
            Cards.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Grimora Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start Grimora Mod", "啟動葛麗摩菈模組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RESET RUN", "重置冒險", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW LESHY RUN", "雷希的新一輪遊戲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE LESHY RUN", "繼續雷希這輪遊戲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW GRIMORA RUN", "葛麗摩菈的新一輪遊戲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE GRIMORA RUN", "繼續葛麗摩菈這輪遊戲", Language.ChineseTraditional);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This option will allow you to see what cards are left in your deck.", "啟用後可查看牌組裡剩下哪些卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This option will disable all effects that might cause motion sickness and other visually jarring effects.", "停用所有可能引發暈動症或造成視覺不適的特效。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Does not generate blocker pieces. Chests fill first row, enemy pieces fill first column.", "不生成阻擋棋子。寶箱填滿第一橫排，敵方棋子填滿第一直行。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Makes it so Cards that cost energy also take max energy.", "使需要能量的卡牌也會消耗能量上限。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the dll is placed in BepInEx/scripts, this will allow running certain commands that should only ever be ran to re-add abilities/cards back in the game correctly.", "將 DLL 放在 BepInEx/scripts 時，啟用此選項可執行特定指令。這些指令僅應用於將能力或卡牌正確重新加入遊戲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For players who want to continue playing with their deck after defeating Grimora.", "適合想在擊敗葛麗摩菈後，繼續使用原本牌組遊玩的玩家。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = Default. Use the mod's internal blueprint system.\n1 = Randomized. Encounters are completely randomized using the mod's internal card pool.\n2 = Custom. Encounters are from made and used from the JSON files.\n3 = Mixed. Encounters are from both default list and custom list.", "0＝預設。使用模組內建的藍圖系統。\n1＝隨機。使用模組內建卡池，完全隨機生成遭遇戰。\n2＝自訂。使用 JSON 檔案所製作的遭遇戰。\n3＝混合。同時使用預設清單和自訂清單的遭遇戰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = W for viewing deck, S for getting up from the table.\n1 = Up arrow for viewing deck, down arrow for getting up from the table.", "0＝按 W 查看牌組，按 S 離開牌桌。\n1＝按向上方向鍵查看牌組，按向下方向鍵離開牌桌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = Default. Flat 50% burn rate for each lever option on second shock.\n1 = Base 30% chance to burn plus 0%, 10%, or 20% for low, medium, high, respectively. Meaning, if the first shock is high then the second is high, the chance for the card to be destroyed is 70%.\n2 = Low: 12.5%, Medium: 17.5%, High 30%. Meaning, if the first shock is high, then the second one is also high, the chance for the card to be destroyed is 60%.\n3 = Low: 12.5%, Medium: 20%, High 27.5%. Meaning, if the first shock is high, then the second one is also high, the chance for the card to be destroyed is 55%.", "0＝預設。第二次電擊時，所有拉桿選項的燒毀率均為 50%。\n1＝基礎燒毀率為 30%，低、中、高強度分別加上 0%、10%、20%。因此若兩次電擊都選高強度，卡牌有 70% 機率被摧毀。\n2＝低：12.5%、中：17.5%、高：30%。因此若兩次電擊都選高強度，卡牌有 60% 機率被摧毀。\n3＝低：12.5%、中：20%、高：27.5%。因此若兩次電擊都選高強度，卡牌有 55% 機率被摧毀。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont change this value, it is used by the game to store certain events.", "請勿更改此值，遊戲會用它來儲存特定事件。", Language.ChineseTraditional);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Souls to select any card on the board, [creature] will deal 1 damage to the selected card if it is an opponent card, if it isn't, [creature] will heal it for 1 health.", "消耗 3 個靈魂，選擇檯面上的任意卡牌。若選中敵方卡牌，[creature]會對其造成 1 點傷害；否則，[creature]會為其恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Comin' right up!", "馬上來！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Shot", "靈魂衝擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Soul to deal 1 damage to the creature across from [creature].", "消耗 1 個靈魂，對[creature]正對面的生物造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disinter", "掘墓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to create a Skeleton in your hand.", "消耗 1 根骨頭，在你的手牌中生成一張骷髏。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Materialize", "魂影具象", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Souls for [creature] to summon a copy in your hand.", "消耗 2 個靈魂，使[creature]在你的手牌中召喚一張自身副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Souls, [creature] will trap a random opponent card in a coffin, which will release the original card again upon perishing.", "消耗 2 個靈魂，[creature]會將隨機一張敵方卡牌困在棺槨裡。棺槨陣亡時，會釋放原本的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funeral Rites", "殯葬儀式", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Sucker", "噬魂者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent creature perishes, [creature] will store a charge of soul energy, up to 4. Activating this sigil will add 3 soul energy to your current energy counter, and one max energy.", "敵方生物陣亡時，[creature]會儲存一份靈魂能量，最多 4 份。啟動此印記可使你目前的靈魂能量增加 3 點，能量上限增加一點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weighted Die", "加重骰子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones for the power of [creature] to be randomized between 0 and 5.", "消耗 2 根骨頭，使[creature]的攻擊力隨機變為 0 至 5 之間的數值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] alternates between striking the opposing space to the left and right from it.", "[creature]會交替攻擊左前方和右前方的對面卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is unaffected by the motion of the ship.", "[creature]不受船隻移動的影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike its adjacent slots, and each opposing space to the left, right, and center of it.", "[creature]會攻擊自身相鄰的卡槽，以及左前方、正前方和右前方的每個對面位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] yields no bones upon death.", "[creature]死亡時不會產生骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, gain 2 bones.", "[creature]殺死其他生物時，獲得 2 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Soul from you at the end of every turn and stores it as 2 Bones, up to a maximum of 8. When [creature] dies, you gain all bones contained in it.", "每回合結束時，[creature]會取走你的 1 個靈魂，將其轉為 2 根骨頭儲存，最多儲存 8 根。[creature]死亡時，你會獲得其中儲存的所有骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] empowers each Skeleton on the owner's side of the board, providing a +1 buff to their power.", "[creature]會強化擁有者一側檯面上的每張骷髏，使其攻擊力 +1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Shanty", "水手船歌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slots to the left, right, and center of it randomly, up to 3 times.", "[creature]會隨機攻擊左前方、正前方和右前方的對面卡槽，最多攻擊 3 次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the card opposing it is Frozen Away if not already frozen.", "[creature]陣亡時，若對面的卡牌尚未冰封，則對其施加凍結解放。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, gain a consumable item, if you have a free slot.", "[creature]死亡時，若你的道具欄還有空位，便會獲得一件消耗品道具。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Skeleton is created in each empty space on the owner's side. [define:Skeleton]", "打出[creature]時，在擁有者一側的每個空位生成一張骷髏。[define:Skeleton]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Horde", "骷髏軍團", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck Finder", "尋船者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Shipwreck is created on each empty adjacent space. [define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", "打出[creature]時，在每個相鄰空位生成一張沉船殘骸。[define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons Within", "內藏骸骨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, draw a card from your Skeleton pile.", "[creature]受到攻擊時，從你的骷髏牌堆抽一張牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full o' candy", "糖果滿溢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will yield candy upon death, maybe this will be useful for later.", "[creature]死亡時會掉落糖果，說不定之後會派上用場。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in a random direction.", "擁有者的回合結束時，[creature]會往隨機方向移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] moves, it leaves a trail of Embers. [define:arackulele.inscryption.grimoramod_Flames]", "每當[creature]移動時，會在身後留下餘燼。[define:arackulele.inscryption.grimoramod_Flames]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guarding Presence", "守護之姿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is placed opposite to an empty space, [creature] will move to that empty space.", "敵方生物被放置到某個空位的正對面時，[creature]會移動到該空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Starved", "渴骨者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have no Bones, at the start of your turn [creature] deals 2 more damage.", "你的回合開始時，若你沒有骨頭，[creature]會多造成 2 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space. If only one creature is in the opposing spaces, this card will strike that creature twice. ", "[creature]會攻擊每個對面位置。若對面所有位置上只有一隻生物，此卡牌會攻擊該生物兩次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Giant", "狂怒巨人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space.", "[creature]會攻擊每個對面位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fledgling", "幼雛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After one turn on the board, [creature] will evolve into a greater form.", "在檯面上經過一個回合後，[creature]會進化成更強大的形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Ability", "隨機能力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced with another sigil at random.", "抽到[creature]時，此印記會被隨機替換成另一個印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it haunts the space it died in. The first creature played on this space gain its old sigils.", "[creature]陣亡時，會附在死亡的卡槽上。第一隻打在該位置的生物會繼承它生前的印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunting Call", "幽魂呼喚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every turn [creature] is on the Board, it will take a Bone from you, if you have no Bones, it perishes.", "[creature]在檯面上的每個回合都會取走你一根骨頭。若你沒有骨頭，它便會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature in the opposing slot is dragged onto the owner's side of the board.", "[creature]陣亡時，會將正對面卡槽中的生物拖到擁有者一側的檯面上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle ally card perishes, [creature] gains 1 power.", "不帶有脆弱印記的友方卡牌陣亡時，[creature]會獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slot as if the board was flipped. A card in the far left slot will attack the opposing far right slot.", "[creature]會如同檯面左右翻轉一般攻擊對面卡槽。位於最左側的卡牌會攻擊對面最右側的卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Bonedigger sigil.", "[creature]陣亡時，其擁有者選擇一隻生物，使其獲得掘骨者印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Waterborne sigil.", "[creature]陣亡時，其擁有者選擇一隻生物，使其獲得水生印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 health per turn. When [creature] dies, the creature opposing it, as well as adjacent friendly creatures, are dealt 10 damage.", "[creature]每回合失去 1 點生命力。[creature]死亡時，正對面的生物及相鄰的友方生物會受到 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a severed limb is created in its place and this card moves into an adjacent open slot.", "[creature]即將受到攻擊時，會在原位生成一截斷肢，並移動到相鄰的空卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each time [creature] deals damage directly, it loses 1 power and health.", "每當[creature]造成直接傷害時，其攻擊力與生命力各降低 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, also play the cards in your hand that were adjacent to this card for free.", "打出[creature]時，也會免費打出你手牌中原本與此卡相鄰的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Douse", "澆熄", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played,[creature] will extinguish all cards on the Board.", "打出[creature]時，會熄滅檯面上所有卡牌的火焰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be attacked from the opposing slot. The opposing slot, if possible, instead attacks one of its adjacent friendly cards.", "[creature]不會受到正對面卡槽的攻擊。若能攻擊，正對面卡槽的卡牌會改為攻擊與其相鄰的一張友方卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards on the owner's side of the field are unaffected by Brittle.", "擁有者一側的卡牌不受脆弱印記影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike its adjacent slots, except other Raiders.", "[creature]會攻擊相鄰的卡槽，但不會攻擊其他劫掠者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it carves its Sigils into adjacent Cards.", "打出[creature]時，會將自身的印記刻在相鄰卡牌上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sculptor", "銘刻師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attempt to find a host in an adjacent friendly slot, hiding under it providing a +1/+1 buff. Cards on the left take priority.", "[creature]會嘗試在相鄰的友方卡槽尋找宿主，藏在其下並提供 +1/+1 增益。優先選擇左側卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] hits an opposing card, one of the targets adjacent allies will take damage as well ", "[creature]擊中對面卡牌時，目標身旁的一張友方卡牌也會受到傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it provides an energy soul to its owner.", "打出[creature]時，其擁有者會獲得一個靈魂能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HellHound's Thirst", "地獄犬之渴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for each bone the player currently has.", "玩家目前每有一根骨頭，帶有此印記的卡牌便獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wrath Of Halloween", "萬聖節之怒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil has 10 attack, 1 for each Candy Bucket Sawyer has left.", "帶有此印記的卡牌初始擁有 10 點攻擊力，索耶每剩下一個糖果桶，便對應 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trusty ol' Crew", "可靠的老船員", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every pirate on the board.", "檯面上每有一名海盜，帶有此印記的卡牌便獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inanimate Attack", "死物之擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every card that has 0 attack on the board.", "檯面上每有一張攻擊力為 0 的卡牌，帶有此印記的卡牌便獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Half Bones", "一半骨頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Bones that the owner has on their side of the table.", "此印記顯示的數值等於擁有者一側檯面上的骨頭數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Death", "雙重死亡", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Soul to add power to [creature] randomly between 1 and 6.", "消耗 1 個靈魂，使[creature]隨機增加 1 至 6 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to heal [creature] to max health.", "消耗 2 根骨頭，使[creature]的生命力恢復至上限。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alternating Strike", "交替打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchored", "錨定", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Area Of Effect Strike", "範圍打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "嗜血者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "無骨者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Thief", "竊骨者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty", "賞金", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning", "燃燒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Damage at the end of your turn, when it gets attacked by another Card, that card gets set on fire.", "你的回合結束時，[creature]受到 1 點傷害。受到其他卡牌攻擊時，會點燃攻擊它的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Strike", "混沌打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold Front", "寒鋒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collector", "收藏家", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic", "飄忽不定", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Strafe", "烈焰橫移", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Strike", "巨力打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter", "作祟者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook Line And Sinker", "全套誘餌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imbued", "靈魂灌注", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inverted Strike", "鏡像打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Bone Digger", "掘骨傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Submerge", "下潛傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lit Fuse", "引信", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loose Limb", "斷肢脫身", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malnourishment", "營養不良", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marching Dead", "亡者行軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessive", "佔有欲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteer", "傀儡師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raider", "劫掠者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Crawler", "潛膚者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slasher", "劈砍者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spirit Bearer", "攜魂者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of this card is equal to the number of Green Gems that the owner has on their side of the table.", "此卡牌的攻擊力等於擁有者一側檯面上的綠寶石數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION I - ABILITIES {0}", "附錄十二，第一節－能力 {0}", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION II - VARIABLE STATS {0}", "附錄十二，第二節－可變屬性 {0}", Language.ChineseTraditional);

            // Card
            RegisterCard("Skeleton", "骷髏");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The puppet becomes the puppeteer, yet still forever cursed by their dangling restraints.", "木偶成了操偶師，卻仍永遠受制於垂落的絲線。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "操偶師", Language.ChineseTraditional);
            RegisterCard("Animator", "操偶師");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A formless Creature, that yet lingers. Truly a horrific sight.", "無形的生物，依然徘徊不去。實在令人毛骨悚然。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apparition", "鬼影", Language.ChineseTraditional);
            RegisterCard("Apparition", "鬼影");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only a fool would need such assistance.", "只有傻子才需要這種幫助。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Graven Ashes", "刻墓之燼", Language.ChineseTraditional);
            RegisterCard("Graven Ashes", "刻墓之燼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's foul breath doesn't concern me, it's the Tampered Coffins it leaves behind!", "我不怕它的臭氣，怕的是它留下的那些搗毀之棺！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bal-Bal", "墓穴食屍鬼", Language.ChineseTraditional);
            RegisterCard("Bal-Bal", "墓穴食屍鬼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SCREAMING TERROR. THEY GO STRAIGHT THROUGH TO ATTACK THEIR PREY.", "尖嘯的恐怖。牠們會徑直穿過防線，攻擊獵物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Banshee", "報喪女妖", Language.ChineseTraditional);
            RegisterCard("Banshee", "報喪女妖");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bartender", "酒保", Language.ChineseTraditional);
            RegisterCard("The Bartender", "酒保");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "spent his days serving harmful cocktails for those deserving of his poisonous wrath. Doesn't regret it at all.", "他曾日日調製致命的雞尾酒，招待那些活該承受他劇毒怒火的人。他一點也不後悔。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Bones", "巨骨", Language.ChineseTraditional);
            RegisterCard("Big Bones", "巨骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burly Bones", "壯骨", Language.ChineseTraditional);
            RegisterCard("Burly Bones", "壯骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beefy Bones", "蠻骨", Language.ChineseTraditional);
            RegisterCard("Beefy Bones", "蠻骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cal C. Um", "鈣先生", Language.ChineseTraditional);
            RegisterCard("Cal C. Um", "鈣先生");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sizeable Bones", "巨大骨頭", Language.ChineseTraditional);
            RegisterCard("Sizeable Bones", "巨大骨頭");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Considerable Bones", "大骨頭", Language.ChineseTraditional);
            RegisterCard("Considerable Bones", "大骨頭");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vigorous Bones", "強韌骨頭", Language.ChineseTraditional);
            RegisterCard("Vigorous Bones", "強韌骨頭");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hefty Bones", "沉重的骨頭", Language.ChineseTraditional);
            RegisterCard("Hefty Bones", "沉重的骨頭");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RATHER BURLY SKELETON, IT IS VERY RICH IN CALCIUM.", "相當魁梧的骷髏，鈣質十分豐富。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This sack is full of body parts. Maybe you'll find something useful in there.", "這袋子裝滿殘肢。也許能在裡面找到有用的東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "血漬麻袋", Language.ChineseTraditional);
            RegisterCard("Bloody Sack", "血漬麻袋");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Collective", "骸骨叢集", Language.ChineseTraditional);
            RegisterCard("Bone Collective", "骸骨叢集");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUSANDS OF TINY BONES COALESCE INTO A HUMANOID FORM ONLY TO DISPERSE IN A CLATTERING SWARM THE NEXT MOMENT.", "數千根細小骨頭凝聚成人形，下一刻又散為喀啦作響的群骨。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "USED TO BE A VERY LOYAL DOG BACK IN THE DAY. WELL, ONE DAY HIS OWNER DIED.", "從前曾是非常忠心的狗。直到有一天，牠的主人死了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonehound", "白骨獵犬", Language.ChineseTraditional);
            RegisterCard("Bonehound", "白骨獵犬");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO YOU HAVE MADE IT HERE, YOU CANNOT END WHAT I HAVE STARTED, IT HAS GONE TOO FAR.", "你終究來到這裡了。你無法終結我開創的一切，事情早已無可挽回。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord", "白骨領主", Language.ChineseTraditional);
            RegisterCard("The Bonelord", "白骨領主");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD SHEDS ITS OLD HORNS, THEY TAKE ON A LIFE OF THEIR OWN, TO ONE DAY USURP THEIR MASTER.", "白骨領主蛻下舊角。它們有了自己的生命，終有一天會奪取主人的地位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelord's Horn", "骨王的號角", Language.ChineseTraditional);
            RegisterCard("Bonelord's Horn", "骨王的號角");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT PARTICULARLY INSPIRING. YOU CAN HAVE IT.", "實在沒什麼意思。送你了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap", "骨堆", Language.ChineseTraditional);
            RegisterCard("Bone Heap", "骨堆");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IF I AM TRAPPED, SO WILL YOU. YOU CANNOT END THIS.", "若我受困，你也一樣。你無法結束這一切。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Prince", "骨王子", Language.ChineseTraditional);
            RegisterCard("Bone Prince", "骨王子");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE FEEDS ON PEOPLES BREATH, MAYBE ONE IS STANDING RIGHT BEHIND YOU RIGHT NOW.", "她以人的氣息為食。說不定此刻，就有一隻站在你背後。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boo Hag", "陰靈女巫", Language.ChineseTraditional);
            RegisterCard("Boo Hag", "陰靈女巫");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE COMMANDS OTHERS WITH STRENGTH AND GLAMOUR. THEY WILL FOLLOW HER EVERYWHERE.", "她以力量與魅力號令眾人。無論她走到何處，他們都會追隨。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calavera Catrina", "骷髏夫人", Language.ChineseTraditional);
            RegisterCard("Calavera Catrina", "骷髏夫人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GROUP OF SKELETONS IS CALLED A CATACOMB. THIS IS A RATHER LARGE GATHERING.", "成群的骷髏稱為墓穴軍團。這次聚集的數量可不少。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catacomb", "墓穴軍團", Language.ChineseTraditional);
            RegisterCard("Catacomb", "墓穴軍團");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centurion", "百夫長", Language.ChineseTraditional);
            RegisterCard("Centurion", "百夫長");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heavily armoured warrior. Last of his century, leader to none.", "身披重甲的戰士。百人隊最後的倖存者，已無人可率領。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compound Fracture", "混魂碎骨", Language.ChineseTraditional);
            RegisterCard("Compound Fracture", "混魂碎骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CRUSHED BY THE ROOF OF HIS OWN HOUSE. LIVING ON AS A PILE OF GOO.", "被自家的屋頂壓碎，如今化為一灘黏液繼續活著。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SPIRIT THAT TAKES THE FORM OF AN EGG. ITS PRESENCE HARMS THOSE THAT GAZE UPON IT.", "化為蛋形的靈體。凡是注視它的人，都會被它的存在所傷。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dalgyal", "魔蛋", Language.ChineseTraditional);
            RegisterCard("Dalgyal", "魔蛋");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOREVER BOUND TOGETHER BY A TERRIBLE CURSE, THIS GROUP DANCES ONWARD INTO DOOM.", "可怕的詛咒將這群舞者永遠綁在一起。他們繼續起舞，迎向毀滅。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Danse Macabre", "亡靈舞者", Language.ChineseTraditional);
            RegisterCard("Danse Macabre", "亡靈舞者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadeye", "死人眼", Language.ChineseTraditional);
            RegisterCard("Deadeye", "死人眼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS EYE ONCE BELONGED TO AN ANCIENT GOD. IT GAZES UPON YOUR ARMY, PICKING ITS FAVORITE TO AID IT ON THE BATTLEFIELD.", "據說，這隻眼曾屬於遠古神明。它凝視你的軍隊，挑選最中意的一員，在戰場上助其一臂之力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS HAND ONCE BELONGED TO AN ANCIENT GOD. ANYTHING IT TOUCHES ROTS. AS WITH ANYTHING THAT ENDS, IT IS ALSO A NEW BEGINNING.", "據說，這隻手曾屬於遠古神明。凡它觸及之物都會腐爛。正如萬物的終結，它也是新的開始。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "死者之手", Language.ChineseTraditional);
            RegisterCard("Dead Hand", "死者之手");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DOOMED FATE SHOULD DISCOURAGE ONE FROM GOING ON, AT LEAST THATS WHAT A STILL LIVING MAN WOULD TELL YOU.", "注定毀滅的命運，本該讓人不再前進。至少，還活著的人會這麼告訴你。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Man Walking", "行屍走肉", Language.ChineseTraditional);
            RegisterCard("Dead Man Walking", "行屍走肉");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FAMED AMONG THE FOLLOWERS OF THE PHARAOH. THEY WERE BLESSED WITH ETERNAL LIFE LONG AGO.", "在法老的追隨者中聲名遠播。很久以前，牠們便獲賜永生。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pharaoh's Pets", "法老的寵物", Language.ChineseTraditional);
            RegisterCard("Pharaoh's Pets", "法老的寵物");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR WHOM THE BELL TOLLS? FOR WHOM THE TAP DRIPS DRY AND THE BATHWATER RUNS COLD.", "喪鐘為誰而鳴？為那水龍頭滴盡、浴水轉冷的人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Knell", "鳴鐘亡靈", Language.ChineseTraditional);
            RegisterCard("Death Knell", "鳴鐘亡靈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime", "鈴鐺", Language.ChineseTraditional);
            RegisterCard("Chime", "鈴鐺");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This lonesome doll was returned from seas of slate and silent shores... it stares lifelessly.", "這孤獨的人偶從灰暗的海域與寂靜的岸邊歸來……毫無生氣地凝望著。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doll", "人偶", Language.ChineseTraditional);
            RegisterCard("Doll", "人偶");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIDING IN A SUIT OF ARMOR, OR ICE, WHAT DOES IT MATTER. THIS SKELETON WON'T LAST FOREVER.", "躲在盔甲裡，還是寒冰裡，有什麼差別？這副骷髏都不會永存。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draugr", "屍鬼", Language.ChineseTraditional);
            RegisterCard("Draugr", "屍鬼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SAD SIGHT, NO ONE SHALL KNOW WHAT LIES AT THE BOTTOM OF THAT WELL.", "多麼悲哀的景象。再也不會有人知道，那口井底下藏著什麼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drowned Soul", "溺魂", Language.ChineseTraditional);
            RegisterCard("Drowned Soul", "溺魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO ONE KNOWS WHAT EXACTLY THE DYBBUK IS, SOME SAY IT IS BETTER LEFT UNKNOWN.", "沒人知道附鬼究竟是什麼。有人說，還是不知道的好。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dybbuk", "附鬼", Language.ChineseTraditional);
            RegisterCard("Dybbuk", "附鬼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ectoplasm", "靈質", Language.ChineseTraditional);
            RegisterCard("Ectoplasm", "靈質");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE ESSENCE OF A SPIRIT, HIDDEN IN EVERY CORNER AND EVERY SHADOW. ONCE YOU SEE ONE, YOU WILL FIND THE REST SOON ENOUGH.", "靈體的精華，藏在每個角落、每道陰影。一旦看見其中一個，很快便會發現其餘的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LIVING FAILURE, ITS KNOWLEDGE ONLY BROUGHT IT DEATH, OR AT LEAST AN APPROXIMATION OF IT.", "活生生的失敗品。知識只為它帶來死亡，或至少是近似死亡的東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneclaw", "骨爪", Language.ChineseTraditional);
            RegisterCard("Boneclaw", "骨爪");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "無骨者", Language.ChineseTraditional);
            RegisterCard("Boneless", "無骨者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's Skeleton seems to have left this lifeless husk in order to achieve greater things.", "它的骷髏似乎離開了這具死寂的軀殼，去追求更偉大的事物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Mummy", "次級木乃伊", Language.ChineseTraditional);
            RegisterCard("Lesser Mummy", "次級木乃伊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal servant to the Pharao, buried with him to serve eternally in death.", "法老忠實的僕從，與他一同入葬，在死後永遠侍奉他。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eidolon", "英靈", Language.ChineseTraditional);
            RegisterCard("Eidolon", "英靈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GOLEM ENCHANTED LONG AGO, BOUND TO PROTECT THE AGE OF SUN.", "遠古受魔法賦能的魔像，受命守護太陽紀元。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "QUITE A MISCHIEVOUS SPIRIT, IT SPREADS ITS FLAMES TO CAUSE DISMAY.", "相當頑皮的靈體，四處散播火焰，製造恐慌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ember Spirit", "燼魂", Language.ChineseTraditional);
            RegisterCard("Ember Spirit", "燼魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMILY WISHES TO REST IN PEACE, ONLY TO BE SUMMONED AGAIN AND AGAIN IN AN ETERNAL BATTLE.", "這一家人只想安息，卻在永無止境的戰鬥中一再被召回。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Walkers", "沃克一家", Language.ChineseTraditional);
            RegisterCard("The Walkers", "沃克一家");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is said their odor is so strong and repugnant, even the undead can feel it!", "據說那惡臭濃烈得令人作嘔，就連亡靈都感受得到！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Festering Wretch", "潰爛行屍", Language.ChineseTraditional);
            RegisterCard("Festering Wretch", "潰爛行屍");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flames", "火焰", Language.ChineseTraditional);
            RegisterCard("Flames", "火焰");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flameskull", "烈焰顱骨", Language.ChineseTraditional);
            RegisterCard("Flameskull", "烈焰顱骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always flying, always angry, always annoying nearby allies in the process.", "總在飛，總在生氣，也總在這過程中惹惱附近的盟友。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A waterlogged sailor who carries his tragic past beside him. I don't remember the details.", "渾身浸透的水手，身旁帶著悲慘的過往。細節我記不清了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forgotten Man", "遺忘者", Language.ChineseTraditional);
            RegisterCard("Forgotten Man", "遺忘者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEST FRIENDS, BROTHERS, AND FIGHTERS.", "摯友、兄弟，也是並肩作戰的戰士。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frank & Stein", "法蘭克與史坦", Language.ChineseTraditional);
            RegisterCard("Frank & Stein", "法蘭克與史坦");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FrankenStein", "弗蘭肯斯坦", Language.ChineseTraditional);
            RegisterCard("FrankenStein", "弗蘭肯斯坦");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghastly guardian spirit. It's presence lingers behind as it sprints through the dark.", "陰森的守護靈。它在黑暗中疾馳，留下揮之不去的氣息。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fylgja", "陪伴者", Language.ChineseTraditional);
            RegisterCard("Fylgja", "陪伴者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warding Presence", "警戒之影", Language.ChineseTraditional);
            RegisterCard("Warding Presence", "警戒之影");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT CREATED THESE BONES, WAR, FAMINE OR ANOTHER TRAGEDY? It may be insignificant now, but I fear what it might become...", "什麼造成了這些骸骨？戰爭、饑荒，還是另一場悲劇？眼下也許不起眼，但我害怕它將來的模樣……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "萬人冢", Language.ChineseTraditional);
            RegisterCard("Mass Grave", "萬人冢");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rising Hunger", "暴食", Language.ChineseTraditional);
            RegisterCard("Rising Hunger", "暴食");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "餓者骷髏", Language.ChineseTraditional);
            RegisterCard("Gashadokuro", "餓者骷髏");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE PIRATES CALL THIS SHIP THEIR HOME, EVEN IN DEATH. A SLAIN GIANTS SKULL SERVES AS THEIR FIGUREHEAD.", "海盜們將這艘船當成家，死後也一樣。被殺死的巨人顱骨，成了他們的船首像。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Ship", "鬼船", Language.ChineseTraditional);
            RegisterCard("Ghost Ship", "鬼船");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant", "巨人", Language.ChineseTraditional);
            RegisterCard("Giant", "巨人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMED RACE OF GIANTS IS SAID TO HAVE DIED OUT LONG AGO, THIS IS PROOF. TRULY A SIGHT TO BEHOLD.", "聞名的巨人一族據說早已滅絕，這就是證據。實在蔚為奇觀。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOUND TO EARTH, THEY CLING ON SO THEY MAY ONE DAY GET PROPER BURIAL.", "受困塵世的亡魂仍不願離去，只盼有朝一日能得到妥善安葬。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grateful Dead", "感恩亡魂", Language.ChineseTraditional);
            RegisterCard("Grateful Dead", "感恩亡魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LOWLY GRAVEBARD, MUSIC ALWAYS BROUGHT HIM COMFORT IN THE WORST OF TIMES. NOW, EVEN AT THE END OF THE WORLD HE SHARES HIS SONG.", "卑微的墓吟者。在最艱難的時候，音樂總能帶給他慰藉。如今，即使世界走向終結，他仍與眾人分享歌聲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravebard", "墓吟者", Language.ChineseTraditional);
            RegisterCard("Gravebard", "墓吟者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT HIS LIFE CARVING THESE CREATURES, THIS CARD CONTAINS A PART OF HIS SOUL.", "他用一生雕刻這些生物。這張卡牌裡，藏著他靈魂的一部分。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave Carver", "刻墓人", Language.ChineseTraditional);
            RegisterCard("Grave Carver", "刻墓人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE SPENDS HIS TIME ALONE DIGGING FOR BONES IN HOPES OF FINDING A TREASURE. JUST LIKE HIS GRANDMA BEFORE HIM.", "他獨自挖掘骨頭，盼望找到寶藏。就像他的祖母從前那樣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravedigger", "掘墓人", Language.ChineseTraditional);
            RegisterCard("Gravedigger", "掘墓人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A POOR, BRUTALIZED SOUL. THEIR MYCELIA PROBES FAR INTO THE SOIL, GUIDING THEIR SPADE.", "可憐而飽受摧殘的靈魂。菌絲深入土壤，為鏟子指引方向。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporedigger", "掘胞人", Language.ChineseTraditional);
            RegisterCard("Sporedigger", "掘胞人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A devoted guardian spirit. Even when dispelled, it grants a protective blessing.", "忠誠的守護靈。即使被驅散，仍會留下庇護的祝福。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haltia", "哈爾蒂亞", Language.ChineseTraditional);
            RegisterCard("Haltia", "哈爾蒂亞");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I advise against staring into it, you won't like what stares back.", "勸你別盯著它看。你不會喜歡回望你的東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Mirror", "鬧鬼魔鏡", Language.ChineseTraditional);
            RegisterCard("Haunted Mirror", "鬧鬼魔鏡");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY CALL HER THE RIDER OF THE APOCALYPSE. HER FLAMING BLADE CUTS THROUGH THE LIVING AND DEAD ALIKE.", "她被稱為天啟騎士。烈焰之刃斬過生者，也斬過亡者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Horseman", "無頭騎士", Language.ChineseTraditional);
            RegisterCard("Headless Horseman", "無頭騎士");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WOULDN'T GET TOO CLOSE DEAR. YOU CAN'T BREAK THE HOLD FROM THE DEEPEST PITS OF HELL, ONCE IT LATCHES ON.", "親愛的，最好別靠太近。來自地獄最深處的魔爪一旦纏上你，就再也掙不開了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellhand", "地獄魔爪", Language.ChineseTraditional);
            RegisterCard("Hellhand", "地獄魔爪");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Hound", "地獄犬", Language.ChineseTraditional);
            RegisterCard("Hell Hound", "地獄犬");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RABID DOG. IT KILLED ONE OF MY GHOULS.", "一隻瘋狗。牠殺了我的一隻食屍鬼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LEGENDS HAVE BEEN TOLD ABOUT THE LEGENDARY HYDRA, THE BEAST THAT SWALLOWS ALL AND THE BANE OF ALL THAT SAIL THE SEAS.", "傳說中的九頭蛇流傳著許多故事。牠是吞噬萬物的巨獸，也是所有航海者的災星。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hydra", "九頭蛇", Language.ChineseTraditional);
            RegisterCard("Hydra", "九頭蛇");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overtaken by it's gluttony in life, doomed to it's gluttony in death. Oddly inspires a greed for bones.", "生前遭貪食吞沒，死後仍注定受其折磨。奇怪的是，會激起對骨頭的貪慾。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jikininki", "食人鬼", Language.ChineseTraditional);
            RegisterCard("Jikininki", "食人鬼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalanche", "雪崩", Language.ChineseTraditional);
            RegisterCard("Avalanche", "雪崩");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "冰川", Language.ChineseTraditional);
            RegisterCard("Glacier", "冰川");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WONDER WHAT HAS BEEN FROZEN AWAY FOR SO LONG.", "不知道是什麼被冰封了這麼久。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Giant", "冰霜巨人", Language.ChineseTraditional);
            RegisterCard("Frost Giant", "冰霜巨人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Cube", "冰塊", Language.ChineseTraditional);
            RegisterCard("Ice Cube", "冰塊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CORPSE WHO DIED WITH HIS HEAD IN A GLACIAL STREAM. AFTER HIS REANIMATION, HE COULDN'T BEAR TO PART WITH THE ICE THAT HAD FORMED.", "把頭浸在冰川溪流裡死去的屍體。復活後，他捨不得讓凝結的冰離開自己。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After drowning her children and then herself, she continues to drown others.", "溺死自己的孩子，再投水自盡後，她仍繼續將他人拖入水中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La Llorona", "哭泣女妖", Language.ChineseTraditional);
            RegisterCard("La Llorona", "哭泣女妖");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manananggal", "魔娜娜迦", Language.ChineseTraditional);
            RegisterCard("Manananggal", "魔娜娜迦");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO BRUTALITY SATIATES THE MANANANGGAL. WHEN YOU SEE HER SEVER FROM HER TORSO, YOU TOO WILL BE A VICTIM OF THE HUNT.", "再多暴行也無法滿足魔娜娜迦。當你看見她的上下半身分離時，你也已成了獵殺的目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi, also known as the hairy ghost. It leeches the souls from those struck down near it.", "魔洛伊，又名毛鬼。它會吸取附近倒下者的靈魂。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi", "魔洛伊", Language.ChineseTraditional);
            RegisterCard("Moroi", "魔洛伊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS AGE OF GLORY IS LONG GONE, YET IT IS WHAT KEEPS HIM GOING.", "榮耀的歲月早已遠去，卻仍是支撐他前行的力量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummy Lord", "木乃伊領主", Language.ChineseTraditional);
            RegisterCard("Mummy Lord", "木乃伊領主");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL EFFORTS TO PRESERVE LIFE AFTER DEATH HAVE BEEN FUTILE, YET THE NECROMANCER GOES ON. HE HAS TO.", "讓生命在死後延續的一切努力都已白費，死靈法師卻依然繼續。他別無選擇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necromancer", "死靈法師", Language.ChineseTraditional);
            RegisterCard("Necromancer", "死靈法師");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A troublesome lake spirit that enjoys dragging others down to a watery grave.", "麻煩的湖中靈體，樂於將他人拖進水底的墳墓。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nixie", "水妖", Language.ChineseTraditional);
            RegisterCard("Nixie", "水妖");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shambling corpse of a pale, sickly noble. it spreads it's filth as it sheds it's flesh.", "蒼白病弱的貴族化成蹣跚的屍體。皮肉不斷剝落，也不斷散播汙穢。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosferat", "諾斯費拉圖", Language.ChineseTraditional);
            RegisterCard("Nosferat", "諾斯費拉圖");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Obol", "古銀幣", Language.ChineseTraditional);
            RegisterCard("Ancient Obol", "古銀幣");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT WILL ALL MAKE SENSE SOON. THE OBOL IS OLDER THAN TIME ITSELF, AND THUS IT WILL REVEAL ITSELF IN DUE TIME.", "一切很快就會明朗。這枚古銀幣比時間本身更古老，時機一到，自會顯露真容。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Armed Bandit", "獨臂強盜", Language.ChineseTraditional);
            RegisterCard("One Armed Bandit", "獨臂強盜");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Took the ten paces, that ordeal cost him an arm, and his life.", "他走了決鬥的十步，卻為此賠上一條手臂，還有性命。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT IS SAID ALL IS WELL THAT ENDS. IT IS SAID TIME IS LIKE AN OUROBOROS, IT DOES NOT END, IT ONLY REPEATS ITSELF.", "人們說，能結束就是好事。又說時間如銜尾蛇，從不終結，只是不斷重演。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ourobones", "銜骨蛇", Language.ChineseTraditional);
            RegisterCard("Ourobones", "銜骨蛇");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plague Doctor", "疫醫", Language.ChineseTraditional);
            RegisterCard("Plague Doctor", "疫醫");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS DETERMINED THE UNDEAD ARE SICK WITH A TERRIBLE ILLNESS. THE ONLY CURE IS DEATH.", "他判定亡靈罹患了可怕的疾病。唯一的解藥是死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EVIL TRICKSTER, THE POLTERGEIST HAS ENJOYED THEIR DEATH VERY MUCH.", "邪惡的搗蛋鬼。這隻惡靈很享受自己死後的日子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poltergeist", "惡靈", Language.ChineseTraditional);
            RegisterCard("Poltergeist", "惡靈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suit of ancient armour in which an occult spirit has taken up residence. Her iron fist drags more creatures to the fight.", "古老的盔甲，裡頭住進了神祕的靈體。她的鐵拳將更多生物拖入戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Armour", "附魔鎧甲", Language.ChineseTraditional);
            RegisterCard("Possessed Armour", "附魔鎧甲");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EXPERIMENT GONE WRONG, IN A FUTILE ATTEMPT TO CREATE A DANSE MACCABRE. THEY DO NOT FUNCTION TOGETHER.", "企圖創造亡靈舞者的實驗失敗了。它們無法協同運作。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Project", "實驗體", Language.ChineseTraditional);
            RegisterCard("Project", "實驗體");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shouldnt be seeing this right now", "你現在不該看見這個。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Cards", "無形生物", Language.ChineseTraditional);
            RegisterCard("Random Cards", "無形生物");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT SEEKS ONLY REVENGE.", "亡魂攜著死亡之鐮，只為尋求復仇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant", "亡魂", Language.ChineseTraditional);
            RegisterCard("Revenant", "亡魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ripper", "開膛手", Language.ChineseTraditional);
            RegisterCard("Ripper", "開膛手");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE RIPPER SOLVES EVERYTHING THROUGH SHEER STRENGTH. IT WILL PUNCH ANY ISSUE STRAIGHT IN THE FACE AND SOLVE IT, TOO.", "開膛手用純粹的力量解決一切問題。無論什麼難題，它都會迎面一拳打去，還真能解決。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a wonder this one has stayed together! Though it may lose that arm if it tries to flee.", "這傢伙居然還沒散架，真是奇蹟！不過要是試著逃跑，那條手臂可能就保不住了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotten", "腐屍", Language.ChineseTraditional);
            RegisterCard("Rotten", "腐屍");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twitching Arm", "抽搐的手臂", Language.ChineseTraditional);
            RegisterCard("Twitching Arm", "抽搐的手臂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The elusive Locker.", "難以捉摸的儲物櫃。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones Locker", "戴維·瓊斯的儲物櫃", Language.ChineseTraditional);
            RegisterCard("Davy Jones Locker", "戴維·瓊斯的儲物櫃");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellowbeard", "黃鬍子", Language.ChineseTraditional);
            RegisterCard("Yellowbeard", "黃鬍子");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebeard", "藍鬍子", Language.ChineseTraditional);
            RegisterCard("Bluebeard", "藍鬍子");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His songs raise the morale of only Skeletons, as no one else seems to like it.", "他的歌只鼓舞得了骷髏，因為其他人似乎都不喜歡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DISTANT RELATIVE OF THE SCREAMING SKULL, HE IS NOW THE SYMBOL OF PIRACY ALL AROUND THE WORLD", "尖叫顱骨的遠親，如今已是全世界海盜的象徵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crossbones", "十字骨", Language.ChineseTraditional);
            RegisterCard("Crossbones", "十字骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones", "戴維·瓊斯", Language.ChineseTraditional);
            RegisterCard("Davy Jones", "戴維·瓊斯");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true captain of the crew, respected by all yet still elusive. YELLOWBEARD ALWAYS GETS MORE BOOTY THAN HE DOES.", "船員們真正的船長，人人敬重，卻依然行蹤難測。黃鬍子拿到的戰利品總是比他還多。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MAYBE IT WASN'T THE BEST IDEA TO HOLD A BARREL FULL OF GUNPOWDER. I'M NOT SURE WETHER HE NOTICED.", "抱著一整桶火藥，或許不是什麼好主意。不知道他自己發現了沒有。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Pirate", "自爆海盜", Language.ChineseTraditional);
            RegisterCard("Exploding Pirate", "自爆海盜");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He betrayed his captain for that large hook, now he is sure to make anyone a double-crosser!", "他為了那支大鉤子背叛船長，如今一定也能讓任何人變成背叛者！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Mate Snag", "大副斯納格", Language.ChineseTraditional);
            RegisterCard("First Mate Snag", "大副斯納格");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parrots usually make great sea-side companions, this one just ate a poisoned cracker.", "鸚鵡通常是海上好夥伴，但這隻剛吃了一塊毒餅乾。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Polly", "波利", Language.ChineseTraditional);
            RegisterCard("Polly", "波利");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A keen eye socket allows him to attack anywhere, his musket helps too. marvelous indeed!", "敏銳的眼窩讓他能攻擊任何位置，火槍也幫了不少忙。真了不起！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Privateer", "私掠船長", Language.ChineseTraditional);
            RegisterCard("Privateer", "私掠船長");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swashbuckler", "豪俠", Language.ChineseTraditional);
            RegisterCard("Swashbuckler", "豪俠");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMERGING FROM AN OLD EGYPTIAN TOMB, MADE TO HOUSE THE LORDS OF OLD.", "自古老的埃及陵墓中現身，為容納昔日的領主而造。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcophagus", "石棺", Language.ChineseTraditional);
            RegisterCard("Sarcophagus", "石棺");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Screaming Skull", "尖叫顱骨", Language.ChineseTraditional);
            RegisterCard("Screaming Skull", "尖叫顱骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ONLY PAIN AND SUFFERING, NOTHING ELSE IS FELT BY THIS SKELETAL HEAD. WHAT A PITY.", "這顆骸骨頭顱只感受得到痛苦與折磨，再無其他。真可憐。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SKILLED HUNTER. DON'T TRUST YOUR EARS WHEN YOU HEAR ITS HAUNTING WHISTLE.", "身手高明的獵人。當你聽見它陰魂不散的口哨聲，別相信自己的耳朵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Silbon", "希爾邦", Language.ChineseTraditional);
            RegisterCard("Silbon", "希爾邦");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY HAVE LEARNED THE ANCIENT SPELL OF DEATH. YET IT IS TOO MUCH POWER TO BE WIELDED.", "它們學會了遠古的死亡咒語，卻沒有本事駕馭如此強大的力量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "骷髏法師", Language.ChineseTraditional);
            RegisterCard("Skelemagus", "骷髏法師");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]RISE MY ARMY, RIIIIIISE[c:]", "[c:bR]起來吧，我的軍團，起——來——！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Army", "骷髏軍團", Language.ChineseTraditional);
            RegisterCard("Skeleton Army", "骷髏軍團");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the faster draws in the west, but not fast enough.", "西部拔槍最快的槍手之一，可惜還不夠快。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slinger's Soul", "槍手之魂", Language.ChineseTraditional);
            RegisterCard("Slinger's Soul", "槍手之魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY SHOW UP OUT OF NOWHERE AND RELOCATE PEOPLE AS THEY PLEASE.", "它們憑空現身，隨心所欲地把人搬到別處。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sluagh", "幽魂軍團", Language.ChineseTraditional);
            RegisterCard("Sluagh", "幽魂軍團");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trick or treat!", "不給糖就搗蛋！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Bucket", "糖果桶", Language.ChineseTraditional);
            RegisterCard("Candy Bucket", "糖果桶");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAPPY HALLOWEEN!", "萬聖節快樂！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Monster", "糖果怪獸", Language.ChineseTraditional);
            RegisterCard("Candy Monster", "糖果怪獸");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectrabbit", "幽靈兔", Language.ChineseTraditional);
            RegisterCard("Spectrabbit", "幽靈兔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SPECTRE EMITS A FLUTE LIKE CALL, AN OMEN OF BOTH DEATH AND DESCTRUCTION", "大幽靈發出笛聲般的呼喚，預示著死亡與毀滅。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectre", "大幽靈", Language.ChineseTraditional);
            RegisterCard("Spectre", "大幽靈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH IS A CRUEL FATE. STARVATION AN EVEN CRUELER ONE. WHY DO YOU FIGHT, OH HUNGRY CHILD.", "死亡是殘酷的命運。餓死更是如此。飢餓的孩子啊，你為何而戰？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starved Man", "餓殍", Language.ChineseTraditional);
            RegisterCard("Starved Man", "餓殍");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT YEARS IN HIS STUDY, IN A TIRELESS ATTEMPT TO CHANGE HIS FATE. YET FATE IS A CRUEL MISTRESS.", "他在書房裡耗費多年，不知疲倦地試圖改變命運。可惜，命運是位殘酷的女主人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "召喚師", Language.ChineseTraditional);
            RegisterCard("Summoner", "召喚師");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tampered Coffin", "搗毀之棺", Language.ChineseTraditional);
            RegisterCard("Tampered Coffin", "搗毀之棺");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Tree", "枯樹", Language.ChineseTraditional);
            RegisterCard("Dead Tree", "枯樹");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its low cost is justified only by its low stats.", "低廉的費用，也只配得上它低下的屬性。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disturbed Grave", "驚擾之墓", Language.ChineseTraditional);
            RegisterCard("Disturbed Grave", "驚擾之墓");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LOWLY GRAVE. WHOEVER IS LAID TO REST HERE, I DO NOT KNOW.", "一座簡陋的墳墓。我不知道誰長眠於此。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kennel", "犬舍", Language.ChineseTraditional);
            RegisterCard("Kennel", "犬舍");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk", "方尖碑", Language.ChineseTraditional);
            RegisterCard("Obelisk", "方尖碑");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck", "沉船殘骸", Language.ChineseTraditional);
            RegisterCard("Shipwreck", "沉船殘骸");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flotsam", "浮木", Language.ChineseTraditional);
            RegisterCard("Flotsam", "浮木");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Water Urn", "水甕", Language.ChineseTraditional);
            RegisterCard("Water Urn", "水甕");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Voodoo Doll", "巫毒人偶", Language.ChineseTraditional);
            RegisterCard("Voodoo Doll", "巫毒人偶");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOTHING... NOTHING AGAIN... NO TREASURE IS LEFT ANYMORE.", "什麼都沒有……又是什麼都沒有……再也沒有寶藏了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomb Robber", "盜墓賊", Language.ChineseTraditional);
            RegisterCard("Tomb Robber", "盜墓賊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ephialtes", "厄菲阿爾忒斯", Language.ChineseTraditional);
            RegisterCard("Ephialtes", "厄菲阿爾忒斯");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Otis", "奧提斯", Language.ChineseTraditional);
            RegisterCard("Otis", "奧提斯");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undertaker", "殯葬師", Language.ChineseTraditional);
            RegisterCard("Undertaker", "殯葬師");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His service no longer needed, this lost soul buries without purpose..", "再也沒人需要他的服務，這迷失的靈魂只能漫無目的地埋葬。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walking Coffin", "行走之棺", Language.ChineseTraditional);
            RegisterCard("Walking Coffin", "行走之棺");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running Coffin", "奔走之棺", Language.ChineseTraditional);
            RegisterCard("Running Coffin", "奔走之棺");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Placeholder", "預留文字", Language.ChineseTraditional);
            RegisterCard("Placeholder", "預留文字");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE VAMPIRE IS A CREATURE OF LEGENDS. IN REALITY, LITTLE BLOOD TO DRINK AFTER EVERYONE HAS DIED.", "吸血伯爵是傳說中的生物。現實卻是，等大家都死了，也沒多少血能喝。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vampire", "吸血伯爵", Language.ChineseTraditional);
            RegisterCard("Vampire", "吸血伯爵");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vellum", "羊皮紙", Language.ChineseTraditional);
            RegisterCard("Vellum", "羊皮紙");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO NEVER BE SATISFIED, TO ALWAYS WANT MORE. THIS SPIRIT SHALL NEVER FIND ITS PEACE.", "永不滿足，總想要更多。這個靈體永遠不得安息。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengeful Spirit", "復仇之魂", Language.ChineseTraditional);
            RegisterCard("Vengeful Spirit", "復仇之魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS GELID SPECTER ENVELOPS WOULD-BE ATTACKERS IN AN ICY MIST.", "這冰冷的幽魂會以寒霧包覆企圖攻擊它的敵人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthr", "寒霜幽魂", Language.ChineseTraditional);
            RegisterCard("Warthr", "寒霜幽魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupted by the spirit of a rabid wolf. It's fury cannot be stopped.", "遭瘋狂的狼魂腐化。牠的怒火無人能擋。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wechuge", "威楚格", Language.ChineseTraditional);
            RegisterCard("Wechuge", "威楚格");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hideous beings that will jump out to consume freshly killed corpses. They only spare the bones of the victim.", "可怕的怪物，會突然現身吞食剛死去的屍體，只留下受害者的骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wight", "屍妖", Language.ChineseTraditional);
            RegisterCard("Wight", "屍妖");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY WARM WITH THEIR BODIES OF LIGHT, DRAWING HOPELESS SOULS INTO THEIR BEACON, DISPELLING THEIR FRIGHT.", "它們以發光的身軀帶來溫暖，將絕望的靈魂引入光中，驅散恐懼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will 'O' The Wisp", "鬼火", Language.ChineseTraditional);
            RegisterCard("Will 'O' The Wisp", "鬼火");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FALLEN GIANTS SPINE THAT IS TRYING TO FIND A NEW HOST. REGRETTABLY, MOST CREATURES ARE QUITE SMALL.", "死去巨人的脊柱，正試著尋找新的宿主。可惜，大多數生物都太小了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Writher", "扭曲者", Language.ChineseTraditional);
            RegisterCard("Writher", "扭曲者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Vertebrae", "尖刺脊椎骨", Language.ChineseTraditional);
            RegisterCard("Spiny Vertebrae", "尖刺脊椎骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SIMPLEST OF UNDEAD, CHARACTERIZED BY ITS ROTTEN SMELL. IT ALWAYS TRAVELS WITH OTHERS, SEEKING PROTECTION AND GUIDANCE.", "最單純的亡靈，特徵是腐爛的臭味。總與他人同行，尋求保護與指引。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie", "僵屍", Language.ChineseTraditional);
            RegisterCard("Zombie", "僵屍");

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimora Mod Achievements", "葛麗摩菈模組成就", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Reminder", "陰森的提醒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Kaycee and thaw at least 5 of your cards.", "擊敗凱茜，並解凍至少 5 張自己的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowards End", "懦夫的末路", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Sawyers second phase without hurting the hellhound.", "不傷害地獄犬，擊敗索耶的第二階段。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Season Of Storms", "風暴季節", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Royal and have no cards walk the plank.", "擊敗羅耀，且沒有任何卡牌被迫走跳板。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Black Bird//", "黑鳥//", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dark Slope. Defeat [redacted] without defeating [redacted].", "黑暗的斜坡。不擊敗[資料刪除]，擊敗[資料刪除]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonesaw", "骨鋸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "End a turn with at least 30 bones.", "在回合結束時擁有至少 30 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pile Of Skulls", "顱骨之堆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win with all challenges enabled and no antichallenges enabled.", "啟用所有挑戰，且不啟用任何反向挑戰的情況下獲勝。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance of Doom", "末日之舞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness the end of everything.", "見證萬物的終結。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Spirits Way", "靈體之路", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach 6 Souls by turn 3.", "最遲在第 3 回合達到 6 個靈魂。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wail Of The Damned", "受詛者的哀號", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the dead hand item when your deck is empty.", "牌組空了時，使用死者之手道具。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something Ends...", "有些事結束了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Something Begins. Get an ourobones to deal 6 damage.", "……有些事開始了。使銜骨蛇造成 6 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cull the weak", "淘汰弱者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice an Obol with 5 sigils to the Bonelord.", "向白骨領主獻祭一枚帶有 5 個印記的古銀幣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gateway to Dis", "通往狄斯之門", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win while Hell mode is active.", "在地獄模式啟用時獲勝。", Language.ChineseTraditional);

            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Horn", "骨質號角", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Horn, drains all of your current Soul but you gain a bone for each soul consumed.", "骨質號角會耗盡你目前的所有靈魂，每消耗一個靈魂，便獲得一根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives you a bone for each of your Souls, which are spent in the process, an unfortunate, but worthwhile sacrifice.", "消耗你的所有靈魂，每個靈魂換來一根骨頭。雖是犧牲，卻很值得。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "死者之手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dead Hand, draws you a new Hand of cards at the cost of your old one.", "死者之手會以捨棄原本手牌為代價，為你抽取一副新的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The severed hand of a forgotten god, left to take on a life of its own. You know what this does.", "被遺忘之神的斷掌，如今已自成生命。你知道它的用途。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embalming Fluid", "防腐液", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Embalming Fluid, pour it over a card and it will gain one health and attack.", "將防腐液倒在卡牌上，使其生命力與攻擊力各增加一點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare to put a member of your army to rest, increasing its stamina and vigor as you do so!", "準備讓你軍中的一員安息，同時增強它的耐力與活力！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravecarvers Chisel", "墓雕師之鑿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravecarvers chisel, select any card that has died previously to add to your hand.", "使用墓雕師之鑿，選擇一張先前死去的卡牌加入手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tool left behind by a mysterious creator, did he carve the gravebards statue too?", "神祕創作者遺留的工具。墓吟者的雕像也是他刻的嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Urn", "靈魂甕", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Soul Urn, spend all of your Soul and gain maximum Soul capacity for each Soul consumed.", "靈魂甕會消耗你所有的靈魂，每消耗一個，便提高一點靈魂上限。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Takes all of your Soul but increases your maximum by the amount taken, a certain acquaintance of mine would call this a return on investment.", "取走你所有的靈魂，並依取走的數量提高上限。我的某位熟人會把這叫作投資報酬。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mallet", "木槌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mallet, Whack a Card, it will become brittle and loose 1 Hp.", "木槌會敲擊一張卡牌，使其獲得脆弱印記並失去 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'd think this is comical, but it is quite cruel. Injures a card and leaves it frail.", "你也許覺得滑稽，其實這很殘忍。它會打傷卡牌，使其變得脆弱。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quill", "羽筆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own Quill, this lets you copy any card on the field to put in your hand.", "我的專屬羽筆，能複製場上任意一張卡牌，將副本放入你的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own tool, i will lend it to you for now. Youve seen this in action, havent you?", "這是我的工具，暫時借給你。你見過它怎麼用的，對吧？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ship Bottle", "瓶中船", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ship in a Bottle, fills the entire board with a scurvy Skeleton Crew.", "瓶中船會用一群患壞血病的骷髏船員填滿整個檯面。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fills the entire board with skeletons! Like a real Pirate, Royal would be proud.", "讓骷髏填滿整個檯面！這才像真正的海盜，羅耀會以你為榮。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salty Daryl", "鹽津津達瑞爾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Browntooth Barrie", "大髒牙巴里", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie Splinter", "乾巴瘦斯普林特", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freebooter Bethel", "走私鬼貝瑟爾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crazy Oakes Hayward", "瘋橡木疙瘩海沃德", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashton Swabby", "邋遢鬼阿什頓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plankton Braxton", "跳大海布拉頓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeller-eye Colby", "黃眼仁兒科爾比", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fishwife Nate", "賣魚佬內特", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Four-finger Fred", "缺手指弗雷德", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawg Julie", "野狗朱莉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Jones", "鬼心眼兒瓊斯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crabby Steele", "螃蟹臉斯蒂勒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank", "碎裂的野豬存錢瓶", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones up to three times.", "碎裂的野豬存錢瓶可額外獲得 2 根骨頭，最多使用三次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic from an age forsaken, this will grant you some extra bones in a pinch", "遭遺棄時代的遺物，能在緊要關頭給你一些額外骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank2", "碎裂的野豬存錢瓶2", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, two more times.", "碎裂的野豬存錢瓶可額外獲得 2 根骨頭，還能使用兩次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank3", "碎裂的野豬存錢瓶3", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, one more time.", "碎裂的野豬存錢瓶可額外獲得 2 根骨頭，還能使用一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trowel", "泥鏟", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trowel, dig up a random terrain and gain a few Bones.", "泥鏟會挖出一張隨機地形，並獲得一些骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This used to belong to a gravedigger. Digs for treasure, or Terrain. And get some Bones too for your efforts.", "這曾屬於一位掘墓人。挖出寶藏，或是地形，還能為你的辛勞換來幾根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelords Femur", "白骨領主的股骨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lords Femur, a mystery even to me.", "白骨領主的股骨，就連我也不了解。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have dug too far, i have let myself be used as a tool for too long. Just like i will lend you this tool, i am truly in power.", "你挖得太深了。我任人當作工具使喚，已經太久。如今換我把工具借給你，真正掌權的依然是我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Bottle", "亡魂瓶", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap Bottle", "骨堆瓶", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Revenant is created in your hand. [define:arackulele.inscryption.grimoramod_Revenant]", "在你的手牌中生成一張亡魂。[define:arackulele.inscryption.grimoramod_Revenant]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Bone Heap is created in your hand. [define:arackulele.inscryption.grimoramod_Bonepile]", "在你的手牌中生成一張骨堆。[define:arackulele.inscryption.grimoramod_Bonepile]", Language.ChineseTraditional);

            // ShowUntilInput
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:G]SANDSTORM[c:] IS BREWING!", "[c:G]沙塵暴[c:]即將來襲！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]At the end of a turn, the rightmost Card will take 1 Damage![c:]", "[c:G]回合結束時，最右側的卡牌會受到 1 點傷害！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS GETTING HOTTER!A [c:G]HEATWAVE[c:] IS STARTING!", "越來越熱了！[c:G]熱浪[c:]來襲！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards on the board will burn![c:]", "[c:G]檯面上所有卡牌都會燃燒！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TREES START SPROUTING AROUND YOU.AN [c:G]OVERGROWTH[c:] IS INBOUND!", "樹木開始在你周圍萌生。[c:G]叢林瘋長[c:]即將到來！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Trees will sprout every turn![c:]", "[c:G]每回合都會長出樹木！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HEAR WITCHES CHANTING.THE CLOCK STRIKES THE [c:G]WITCHING HOUR[c:]!", "你聽見女巫吟唱。時鐘敲響[c:G]巫術之時[c:]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Cards on enchanted slots will gain more attack and health![c:]", "[c:G]附魔卡槽上的卡牌會獲得更多攻擊力與生命力！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CAULDRON IS BUBBLING IN THE DISTANCE.YOUR CARDS ARE PUT IN THE [c:G]WITCHES CAULDRON[c:]!", "遠方的大鍋冒著泡。你的卡牌被投入[c:G]女巫的坩堝[c:]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]2 Cards will swap after the end of the turn![c:]", "[c:G]回合結束後，2 張卡牌會交換位置！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SKELETONS START DANCING IN THE DISTANCE, YOU CAN SEE GHOSTS MOVE AROUND.ITS THE [c:G]NIGHT OF THE LIVING DEAD[c:]!", "遠處的骷髏開始跳舞，幽靈四處遊蕩。這是[c:G]活死人之夜[c:]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Bone and soul cost of all cards are swapped![c:]", "[c:G]所有卡牌的骨頭費用與靈魂費用互換！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZOMBIES ARE APPROACHING FROM ALL SIDES.A [c:G]ZOMBIE INVASION[c:] WILL APPROACH!", "僵屍從四面八方逼近。[c:G]僵屍入侵[c:]即將開始！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every card is now a Zombie![c:]", "[c:G]所有卡牌都變成僵屍了！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE DIRT IS PLAGUED WITH SPIRITS FROM CENTURIES PAST.YOU'VE APPROACHED THE [c:G]HAUNTED GROUNDS[c:]!", "泥土中盤踞著數百年前的靈體。你已踏入[c:G]鬧鬼之地[c:]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every non Skeletal Card will gain Haunter![c:]", "[c:G]所有非骷髏類卡牌都會獲得作祟者印記！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE MOON RISES, GLOWING RED.A [c:G]BLOODMOON[c:] IS STARTING!", "月亮升起，泛著紅光。[c:G]血月[c:]降臨！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards loose a random sigil after being played![c:]", "[c:G]所有卡牌打出後都會隨機失去一個印記！[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient Guard stands in front of you, noticing you are trying to sneak past.", "一名古老的守衛擋在你面前，發現你想偷偷溜過去。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare enter my [c:R]TOMB[c:]!Prepare for death.", "竟敢闖入我的[c:R]陵墓[c:]！準備受死吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An imposing Man holding a sculpture of an Ankh blocks the way.", "一名手持安卡雕像的威嚴男子擋住去路。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My Ankh gives me life, you shall not rob my [c:R]TOMB[c:].", "安卡賜我生命，你休想劫掠我的[c:R]陵墓[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An old Pharaoh climbs out of his Sarcophagus.", "一位年邁的法老從石棺中爬出。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been called to protect my [c:R]TOMB[c:].", "我受召守護自己的[c:R]陵墓[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A holy figure looms over you.", "一道神聖的身影居高臨下地望著你。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Fate is sealed, my [c:R]TOMB[c:] shall not be disturbed.", "你的命運已定，我的[c:R]陵墓[c:]不容驚擾。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LONE GRAVE SITS SOLEMNLY IN FRONT OF YOU.", "一座孤墳靜靜立在你面前。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IN FRONT OF IT IS A MOUND OF EARTH, LEFT BY SOMEONE WHO'S ALREADY PASSED ON.", "墳前有一堆土，是某位已逝之人留下的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS A MEMBER OF YOUR UNDEAD HORDE COULD [c:bR]DIG THEM UP?[c:]", "也許你的亡靈軍團中，能派個成員將他們[c:bR]挖出來？[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS WOULDN'T BE WITHOUT REPERCUSSIONS OF COURSE, AS DEATH IS NEVER PERMANENT.", "當然，這麼做不會毫無代價。畢竟死亡從不永久。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF ROTTING FLESH, YOUR CARD WILL BECOME [c:bR]BRITTLE[c:], BUT [c:bR]ITS BONE COST WILL BE HALVED[c:].", "屍體的血肉似乎正在腐爛。你的卡牌會變得[c:bR]脆弱[c:]，但[c:bR]骨頭費用會減半[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A STARVED MAN, YOUR CARD WILL [c:bR]STARVE FOREVER[c:], BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 2[c:].", "屍體似乎是個餓死的人。你的卡牌將[c:bR]永遠飢餓[c:]，但[c:bR]骨頭費用會降低 2[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF AN INCORPOREAL GHOST, YOUR CARD WILL [c:bR]COST 2 SOULS[c:] , BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 1[c:].", "屍體似乎是個無形的幽靈。你的卡牌將[c:bR]需要 2 個靈魂[c:]，但[c:bR]骨頭費用會降低 1[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A CHAINED PRISONER, YOUR CARD WILL [c:bR]DEAL 1 MORE DAMAGE[c:] , BUT [c:bR]IT WILL BECOME VERY FRAIL[c:].", "屍體似乎是個戴著鐐銬的囚犯。你的卡牌會[c:bR]多造成 1 點傷害[c:]，但[c:bR]也會變得十分脆弱[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A MISCHIEVIOUS SPIRIT, YOUR CARD WILL [c:bR]HAUNT OTHERS[c:] , BUT [c:bR]WILL COST 3 SOULS[c:].", "屍體似乎是個頑皮的靈體。你的卡牌將[c:bR]附在他人身上[c:]，但[c:bR]需要 3 個靈魂[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MARVELOUS! THEY CAME CRAWLING BACK AFTER DIGGING UP THE CORPSE.", "太棒了！挖出屍體後，他們又爬回來了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY STILL CARE ABOUT YOU IT SEEMS!", "看來他們仍在乎你呢！", Language.ChineseTraditional);
            foreach (var value in Cards.Values)
            {
                string name = "[c:R]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TORN FROM ITS ETERNAL RESPITE WITH A RELUCTANT GROAN, THE " + name + " SHAMBLES BACK TO ITS RIGHTFUL PLACE AMONG YOUR HORDE.", name + "被從永恆的安息中拉出，發出不情願的呻吟，蹣跚回到你的亡靈大軍中應在的位置。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS BONES HOLLOWED THROUGH BY THE CREATURES OF THE SOIL, LEAVING IT FEELING UNNATURAL AND UNFAMILIAR.", "土中的生物蛀空了它的骨頭，讓它顯得怪異而陌生。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUGH THE WEIGHT OF CONSEQUENCE ALSO SEEMS LIFTED...", "不過，代價的重擔似乎也跟著減輕了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems i have finally been given my turn!", "看來終於輪到我了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After this i will finally be at peace.", "這次結束後，我終於能安息了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, it seems we will start in this frigid valley.", "好，看來要從這座冰冷的山谷開始。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It must be where Kaycees resides.", "這裡應該就是凱茜的住處。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't expect to meet you here again!", "沒想到又在這裡見到你！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems the deletion process has stalled!", "刪除程序似乎停住了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You again?", "又是你？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, i suppose we can go another time.", "好吧，我想可以再來一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still not deleted?", "還沒刪除嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Much seems to be contained on this disk.", "這張磁碟裡似乎裝了不少東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps the last run wasn't long enough.", "也許上次冒險還不夠久。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, im sure Kaycee has the energy for more battles.", "不過，凱茜肯定還有精力再打幾場。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frigid valley, again.", "又是冰冷的山谷。", Language.ChineseTraditional);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BITTER CHILL MIGHT HURT, BUT IT WON'T SLOW DOWN " + value + "!", "刺骨的寒意或許會傷人，但拖不慢" + value + "！", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BLOCKED IN ALL SLOTS. NO ARMY THIS TIME.", "所有卡槽都被堵住了。這次沒有軍團。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides. No Shipwrecks for the Forgotten Man.", "兩邊都被堵住了。遺忘者沒有地方放沉船殘骸。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, I love this one!", "噢，我最喜歡這個了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Electric Chair, it allows you to harness the power of lightning itself, letting you [c:B]empower[c:] your cards with mutating abilties!", "電椅能讓你駕馭閃電的力量，以變異能力[c:B]強化[c:]卡牌！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "However, I must warn you, it is no ordinary chair. With the ability to adjust the voltage, a higher level of course increases the unpredictability of the mutation.", "不過得先提醒你，這可不是普通的椅子。它能調整電壓，電壓越高，變異就越難預測。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The brave will master the current, the cowardly will blindly follow it.", "勇者掌控電流，懦夫只會盲目隨流而行。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you bold enough to tinker with its lever on the left, letting the voltage corrupt the selection of the sigils?", "你敢撥動左邊的拉桿，讓電壓扭曲印記的選擇嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SURELY YOUR CREATURE COULD BECOME MORE POWERFUL...", "你的生物肯定還能更強……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT YOU WOULD NEED TO RISK ANOTHER MOMENT UNDER THE SHOCK.", "不過，你得冒險再承受一段電擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BONES FLEW LEFT AND RIGHT AS YOU RETREATED FROM THE SCENE.", "你退出現場時，骨頭向四面八方飛散。", Language.ChineseTraditional);
            foreach (var value in Cards.Values)
            {
                string name = "[c:bR]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU EVER SO CAREFULLY PULL THE " + name + " AWAY FROM THE ELECTRICITY AND LEAVE.", "你極為小心地把" + name + "從電流中拉出，然後離開。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello, dear challenger, we meet again!", "你好，親愛的挑戰者，我們又見面了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready for a good ol' fashioned [c:R]DUEL[c:]?", "準備好來場老派的[c:R]決鬥[c:]了嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see, theres a third candle at play this time...", "看來這次還有第三根蠟燭……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel you have [c:bG]bested[c:] me this time...", "看來這次是你[c:bG]贏過[c:]我了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was an honour, either way!", "無論如何，都是我的榮幸！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "恭喜，你做得很好。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "讓我看看，下個區域是我自己的墓穴。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "也許你能克服重重難關，贏得勝利！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T'was well thought, i believe.", "這步想得很周到。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS GET RID OF THE OL' SLOTS FOR NOW!", "先把這些舊卡槽清掉吧！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its time for a different sort of game.", "該換個玩法了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont let the costs of the cards on your side of the board get above [c:R]10[c:]!", "別讓你這一側檯面上的卡牌總費用超過[c:R]10[c:]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you bust, you get punished, hit the perfect [c:R]10[c:] and you shall get a reward...", "超過就得受罰，剛好湊到[c:R]10[c:]則能得到獎勵……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was the ol' slot machine not enough for you?", "那臺老角子機還滿足不了你嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess we shall bring in some more heavy hitters so to say...", "看來得再請些更強的打手來了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets get those powerhouses out of the way first!", "先把那些強大的傢伙清出去吧！", Language.ChineseTraditional);
            foreach (var kvp in Cards)
            {
                string key = "[c:R]" + kvp.Key + "[c:]";
                string value = "[c:R]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, you've made " + key + " quite angry.", "哎呀，你把" + value + "惹得很生氣。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO? A TERRIBLE FATE WILL AWAIT YOU", "不願意？可怕的命運正等著你。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I FEEL WATCHED SOMEHOW", "總覺得有什麼在注視我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN ANCIENT ENERGY DEMANDS YOUR SACRIFICE", "一股古老的能量要求你獻祭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING-", "你願意獻祭一份初始——", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT", "等等。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOU BEAR A TERRIBLE CURSE", "看來你背負著可怕的詛咒。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU SHALL KEEP THE BOON, BUT FOR A FAR GREATER SACRIFICE", "你可以保留獎勵，但要付出遠更大的犧牲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CAN YOU GIVE UP YOUR ETERNAL ASHES?", "你能捨棄永恆之灰嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING BONES", "你願意獻祭一根初始骨頭嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A BRAVE SOUL", "勇敢的靈魂。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE GODS ANSWER YOUR PRAYERS, NOW CHOOSE", "諸神回應了你的祈禱，現在選吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE INANIMATE", "死物的獎勵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BATTLE, A DEAD TREE WILL SPAWN IN ON A RANDOM SPACE ON THE BOARD", "戰鬥開始時，在檯面上的隨機位置生成一張枯樹。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SUN KINGDOM", "太陽王國的獎勵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ON THE 4TH TURN OF A BATTLE, DRAW 2 RANDOM EGYPT CARDS", "戰鬥的第 4 回合，隨機抽取 2 張埃及卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF REPENTANCE", "懺悔的獎勵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GAIN AN ADDITIONAL SOUL AT THE START OF A BATTLE", "戰鬥開始時，額外獲得一個靈魂。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF EBONY EYES", "烏木雙瞳的獎勵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TERRAIN CARDS WILL PROVIDE 2 BONES ON DEATH", "地形卡牌死亡時會提供 2 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE ADVERSARY", "宿敵的獎勵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BOSS BATTLE, GAIN 3 EXTRA BONES", "頭目戰開始時，額外獲得 3 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SEASICK", "暈船的獎勵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AFTER PLACING 3 CARDS, A PIRATE SKELETON WILL BE PLAYED ON A RANDOM SPACE ON THE BOARD", "放置 3 張卡牌後，在檯面上的隨機位置打出一張海盜骷髏。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF THE CUT FINGER", "斷指的獎勵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DRAW AN ADDITIONAL CARD AT THE START OF A BATTLE", "戰鬥開始時，額外抽一張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A WISE CHOICE, NOW LEAVE BEFORE THE GODS GET TOO HUNGRY", "明智的選擇。趁諸神還沒太餓，快離開吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We spent a lot of time here, I'm sure you are eager to get going again!", "我們在這裡待了好一陣子，你肯定迫不及待想再次啟程！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard bids us farewell", "墓吟者向我們道別。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see you would rather hold on to the ash that you have collected.", "看來你寧願留著收集到的骨灰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still may be of use later...", "之後也許還能派上用場……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And don't feel bad, the Gravebard still enjoyed your company while it lasted!", "別難過，墓吟者還是很享受剛才有你作伴的時光！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if you wanted anything else, you are no longer able to afford it...", "就算你還想要別的，現在也已經買不起了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling sorry for you, the Gravebard offers to come with you.", "墓吟者同情你的處境，主動提出要與你同行。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard never runs out of stories to sing about.", "墓吟者總有唱不完的故事。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And as it so happens, they are willing to make you another offering, but they insist that you give them 6 grams of ash this time.", "他們願意再給你一份禮物，不過這次堅持要收 6 克骨灰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you willing to accept their terms?.", "你願意接受這個條件嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard is able to give you one final gift, but now they are asking a much higher price of 12 grams of ash!", "墓吟者還能送你最後一份禮物，但這次要價高得多，足足 12 克骨灰！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astoundingly, you have enough to pay such a fee, but are you willing to part with it?", "真沒想到，你竟付得起這個價錢。不過，你捨得嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will you offer 3 Grams worth of Ash?", "你願意獻上 3 克骨灰嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Gravebard has set up camp here.", "一位墓吟者在這裡紮營。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They play songs and elegies about long forgotten warriors and rulers.", "他們演奏歌謠與輓歌，吟唱早已被遺忘的戰士和統治者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though nowadays their audience consists mostly of various ghouls.", "只是如今的聽眾，多半是各種食屍鬼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are willing to play you a song and trade you an unknown gift in exchange for any grams of ash you happen to be carrying.", "他們願意為你演奏一曲，並拿一份神祕禮物，交換你隨身攜帶的骨灰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gravebard is willing to play you a song for an item. You have to pay in ash.", "墓吟者願意為你演奏一曲，並交換一件道具。你得用骨灰付款。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All the excess damage you have done may finally come in handy!", "你造成的那些過量傷害，總算有用武之地了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strum the Lute when you are ready to make a trade.", "準備好交易時，就撥動魯特琴吧。", Language.ChineseTraditional);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash, they hand you a pouch, and play a song about a brave knight from the crusades.", "他們收下" + price.ToString() + "克骨灰，遞給你一個袋子，並演奏一首關於十字軍勇敢騎士的歌。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even after a Demonic entity cursed them into a horse-like form, they were still able to liberate the lost souls trapped by the Demon!", "即使被惡魔詛咒成馬一般的形體，仍成功解放了被惡魔囚禁的迷失靈魂！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh right, the pouch, let's see what's inside!", "啊，對了，那個袋子！看看裡面有什麼吧！", Language.ChineseTraditional);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash in tow, they hand you another pouch, and play a tune about a sorceress from a mythical land.", "他們收下" + price.ToString() + "克骨灰，再遞給你一個袋子，並演奏關於神話之地女巫的曲子。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite pressure from a prophecy to be the hero of the land, they instead pulled from a dark tome and sided with a cloudy villain to conquer the land and find peace from fame in an unexpected way!", "雖然預言迫使其成為這片土地的英雄，卻選擇從黑暗典籍中取得力量，與雲霧般的反派聯手征服大地，以意想不到的方式擺脫名聲，尋得平靜！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I almost forgot! You must be dying to know what is in the pouch!", "差點忘了！你一定急著想知道袋子裡是什麼吧！", Language.ChineseTraditional);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling satisfied with  " + price.ToString() + " grams of ash, they hand you a pouch, and recount the tale of 4 islands.", "他們對" + price.ToString() + "克骨灰感到滿意，遞給你一個袋子，並講述4座島嶼的故事。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each of the islands had a ruler fixated on a selfish goal, all except for one...", "每座島都有個執著於私慾的統治者，只有一個例外……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One island had a secluded hermit covered in moss and fungi. They surrounded themselves with beasts, and would eternally trap anyone who would wander into their forest.", "一座島上住著隱居的隱士，全身覆滿苔蘚和菌菇。他與野獸為伴，將所有誤入森林的人永遠囚禁。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another island had a mysterious wizard covered head to toe in a green fur. Their true goal remained unknown, but seemed to involve the torturing of their own subjects...", "另一座島上有位神祕巫師，從頭到腳覆滿綠毛。真正的目的無人知曉，卻似乎與折磨自己的臣民有關……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The worst island however, was barely even an island at all! A metallic barge with a sleepless factory ruled by an arrogant, robotic tyrant...", "最糟的那一座，幾乎連島都稱不上！那是艘金屬駁船，載著永不停歇的工廠，由傲慢的機械暴君統治……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Which leaves the other island, a sprawling burial ground with a Crypt at the end of it. It was ruled by a woman who only wished for the power struggle to finally end...", "剩下的那座島是片遼闊墓地，盡頭有座墓穴。統治那裡的女子，只希望權力鬥爭早日結束……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! That would happen to be me!", "哎呀！那說的不就是我嘛！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think we now know how that story ended.", "我想，我們都知道那故事怎麼結束了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And truthfully, the story still isn't over yet, maybe we can reach the end together!", "其實故事還沒結束，也許我們能一起走到終點！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That being said, you have earned this item.", "話說回來，這件道具是你應得的。", Language.ChineseTraditional);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of ash with them, they hand you a pouch, and tell you about an ancient hunter of ghouls.", "他們帶走" + price.ToString() + "克骨灰，遞給你一個袋子，並講述一位古代食屍鬼獵人的故事。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though he was barely a hunter, instead he spent his time searching for something he could not obtain.", "他其實算不上獵人，反倒把時間都花在尋找某種無法得到的事物上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In the end he found a glimpse of what he had seeked, but paid a horrible price.", "最後，他終於窺見所求，卻付出慘痛代價。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should see whats inside that pouch.", "看看袋子裡有什麼吧。", Language.ChineseTraditional);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of your ash, they hand you a pouch, and reminisce about a medic from medieval times.", "他們收下你的" + price.ToString() + "克骨灰，遞給你一個袋子，並追憶一位中世紀醫師。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instead of being content with their life, they instead chased the love of their life for years.", "不願安於現狀，而是花了多年追尋一生的摯愛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This got them into much danger, but their friends were always there to help them out!", "因此屢次身陷險境，但朋友們總在身邊伸出援手！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets see what that pouch contains.", "看看那袋子裝了什麼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RISE MY ARMY! RIIIIIIIIIISE!", "起來吧，我的軍團！起——來——！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Otis![size:]", "[size:5]奧提斯！[size:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Ephialtes![size:]", "[size:5]厄菲阿爾忒斯！[size:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH? FIVE LANES? HOW BOLD.", "喔？五條路線？好大的膽子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SHAME", "真遺憾。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOUVE GIVEN UP YOUR REWARD FOR CHAOS", "看來你為了混亂，捨棄了獎勵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CANNOT BE DEFEATED", "我不可能被打敗。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I ALMOST FORGOT", "差點忘了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL OF THIS SUFFERING YOU CAUSED, ALL OF THIS PAIN", "你帶來的種種苦難，種種痛苦。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU OUGHT TO BE REWARDED FOR ALL THAT EXCESS DAMAGE", "你該因這些過量傷害獲得獎勵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS FOR YOUR EFFORTS", "收下這份努力的回報。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A TERRIBLE FOE, THIS WONT DEFEAT ME!", "真是可怕的對手，但這還打不倒我！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT DID YOU DO. I AM DOOMED.", "你做了什麼？我完了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FORMIDABLE OPPONENT, YOU DID WELL IT SEEMS.", "強勁的對手，看來你做得不錯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minor Ashes", "次級骨灰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Ashes", "高級骨灰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLD, MY LATEST CREATIONS! THE TWIN GIANTS!", "看哪，我最新的創作！雙子巨人！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HELLO?", "有人嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We survived, but... but...", "我們活下來了，可是……可是……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our tools did not.", "工具沒能倖免。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our talents still remain, but..", "我們的本領還在，可是……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must do things differently.", "我們得換個方法。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We cannot fuse two into one, but...", "無法將兩者合而為一，但……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can swap their souls, their Sigils.", "能交換它們的靈魂，它們的印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is once again time...", "又到時候了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time to swap the souls of your cards.", "交換你卡牌靈魂的時候。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time, it is...", "時候到了，是時候……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall work once more.", "我們會再次開工。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will get ugly...", "場面會很難看……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their bodies and souls, they are...", "它們的身體和靈魂，已經……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Switched.", "調換了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They lead new lives..", "它們有了新的生命……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With new purposes.", "也有了新的目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Till we meet again, one day... one day...", "直到某天重逢……總有一天……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE WILL PROVIDE A HELPFUL CURSE OR BLESSING, AS SOME CALL IT UPON YOUR ARMY IF YOU LEAVE HIM AN OFFERING.", "若你留下供品，他會賜給你的軍團有益的詛咒，也有人稱之為祝福。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE FOR YOUR SAKE HE IS FEELING GENEROUS.", "但願他肯慷慨些，這也是為你好。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD IS VERY HAPPY WITH THIS OFFERING", "白骨領主對這份供品十分滿意。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM VERY THANKFUL FOR THIS", "我非常感激。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS IN RETURN, YOU CAN USE IT TO CALL ME ANYTIME", "收下這份回禮，隨時都能用它呼喚我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CANNOT END THIS, END ME, THAT IS", "你無法終結這一切。也就是說，無法終結我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling overburdened enough with a full 3 items, you carried on.", "身上已帶滿 3 件道具，實在夠重了，你便繼續前進。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee says it's time to freeze!", "凱茜說，該結冰了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer thanks you for your contribution!", "索耶感謝你的貢獻！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer felt bad for you.", "索耶很同情你。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you're able to warm up next turn.", "希望下回合你能暖和起來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wonderful! I am pleasantly surprised by your triumph against me!", "太精彩了！你居然戰勝了我，真讓人驚喜！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...It seems you have bested this game.", "……看來你已征服這場遊戲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But alas, you have cheated.", "可惜啊，你作弊了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm absolutely astonished!", "我真是驚訝極了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've gone above and beyond what I thought you were capable of!", "你的表現遠遠超出了我的想像！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no where else to go beyond this...", "再往前，已經沒有別的地方了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So I owe it to you to know the truth...", "所以，我有責任讓你知道真相……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee, the REAL Kaycee...", "凱茜，真正的凱茜……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know about the Horrifying contents of the OLD_DATA.", "我知道 OLD_DATA 裡那些可怕的內容。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surely you have looked into it too..", "你肯定也調查過……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Windows into your world's greatest evils, both past and present.", "那是一扇扇窗口，通往你們世界古往今來最深重的邪惡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to destroy it, and...", "我想毀掉它，然後……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]THAT IS QUITE ENOUGH[c:]", "[c:R]夠了。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]IT IS TIME FOR THIS TO END.[c:]", "[c:R]該讓這一切結束了。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...But it seems i cannot move on just yet.", "……但我似乎還沒辦法就此離去。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goodbye.", "再見。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...You wish to continue? Endlessly? Splendid!", "……你想繼續？永無止境地玩下去？太好了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, take a card of your choosing.", "請選一張你喜歡的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR WEAK SPIRITS SHALL NOT HAUNT ME NO MORE.", "你那些弱小靈體，再也別想纏住我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH TOUCH WON'T HELP YOU HERE DEAR.\nI MADE THESE GIANTS SPECIAL, IMMUNE TO QUITE A FEW DIFFERENT TRICKS!", "親愛的，死亡之觸在這裡可沒用。\n這些巨人可是我特製的，對不少把戲都免疫！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD CANNOT BE POSSESSED!", "白骨領主不可能被附身！", Language.ChineseTraditional);
            foreach (var kvp in Cards)
            {
                string key = "[c:B]" + kvp.Key + "[c:]";
                string value = "[c:B]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " MIGHT HAVE SOME DIFFICULTY SUBMERGING IF IT'S FROZEN SOLID!", value + "凍得結結實實，恐怕很難潛水！", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " CAN'T POSSESS ANYTHING IF IT CAN'T MOVE!", value + "動不了，就沒法附身！", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " WILL HAVE A HARD TIME HOOKING ANYTHING IF IT'S FROZEN SOLID!", value + "凍得結實，恐怕很難用鉤子！", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " FINALLY! TO GET RID OF THAT FOUL SMELL!", value + "終於！可以擺脫那股惡臭了！", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS [c:R]HEAT[c:] UP SOME CARDS!", "來替卡牌[c:R]加熱[c:]吧！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-Your strikes are only making me [c:B]c-colder[c:]!", "你、你的攻擊只會讓我[c:B]更、更冷[c:]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR YOUR CARDS TO FREEZE! [c:B]CHILLED[c:] TO THE BONE!", "你的卡牌該結冰了！[c:B]寒冷刺骨[c:]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL THIS [c:bB]ICE[c:] IS TAKING UP TOO MUCH SPACE!", "這些[c:bB]冰塊[c:]太佔地方了！", Language.ChineseTraditional);
            foreach (var kvp in Cards)
            {
                string key = "[c:bR]" + kvp.Key + "[c:]";
                string value = "[c:bR]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRRR, I WILL ENJOY THE KABOOM OF " + key, "呀哈哈，我會好好欣賞" + value + "的爆炸！", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOIL ME ORANGES, THERES A-WAVES COMIN!", "煮我的橙子啊，浪頭來啦！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THESE WAVES WILL PUSH YE CARD OFF THE BOARD, BACK TO YER HAND!", "浪頭會把你的卡牌衝離檯面，送回手牌！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS PIRATE CANNOT BE TAKEN BACK UP BY THE WAVES! BUT EVEN THE ZESTIEST OF PIRATES WILL BE SHAKEN UP!", "這海盜可不會被浪頭捲走！但再有勁的海盜，也免不了被晃得七葷八素！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seven seas for the table!", "七大洋端上桌！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I WILL STORE THIS BONE FOR LATER", "喔，這根骨頭我要留著以後用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SPARE SOME SOULS?", "能分點靈魂嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLEASE, WON'T YOU SPARE SOME BONES FOR A POOR GHOUL LIKE ME?", "求求你，不能施捨幾根骨頭給我這可憐的食屍鬼嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HOW SAD. YOUR HAMMER COULD NOT BREAK THE ICE, AND SHATTERED", "喔，真可惜。你的錘子沒能破冰，自己倒碎了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FRAIL THING WILL SHATTER AFTER EXCESSIVE USE. THREE STRIKES, AND IT'S OUT, FOR THIS BATTLE AT LEAST.", "這東西太脆弱，用太多就會碎。敲三次就報廢了，至少這場戰鬥不能再用。", Language.ChineseTraditional);
            foreach (var kvp in Cards)
            {
                string key = "[c:lGr]" + kvp.Key + "[c:]";
                string value = "[c:lGr]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... it will be rather difficult to haunt " + key + " with their abilities at max capacity.", "喔……要在" + value + "能力全開的時候附身，恐怕很難。", Language.ChineseTraditional);
            }
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH DEAR! LOOKS LIKE YOU HAVE HOOKED SOMETHING OUT OF " + value + "!", "天啊！看來你從" + value + "裡釣出了什麼！", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bB]BRRRR![c:] I'VE BEEN FREEZING FOR AGES!", "[c:bB]冷死啦！[c:]我已經凍了好久！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S TURN UP THE [c:R]HEAT[c:] FOR A GOOD FIGHT!", "來把氣氛[c:R]炒熱[c:]，好好打一場！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh hey, looks like I've got another shot. Hope you watched the weather forecast!", "嘿，看來我又有機會了。但願你有看天氣預報！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH COME ON DUDE, I'M STILL [c:B]COLD![c:]", "拜託，老兄，我還是很[c:B]冷[c:]耶！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S FIGHT AGAIN SOON!", "咱們很快再戰！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "恭喜，你表現得很好。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE DEFEATED ONE OF MY LOVELY GHOULS, YOU WILL NOW START FIGHTS WITH AN ADDITONAL BONE.", "你打敗了我可愛的食屍鬼之一，今後每場戰鬥開始時都會多一根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAWYERS CATACOMBS ARE UP NEXT, A FILTHY PLACE WHERE LOTS ARE LAID TO REST.", "接著是索耶的地下墓穴，那地方髒兮兮的，埋了許多亡者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE THINKS IT IS A TERRIBLE PLACE TO BE.", "他覺得那裡糟透了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "C'mon dude, where are you going? Can't handle the cold?", "拜託，老兄，你去哪？受不了冷了？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, IT SEEMS I HAVE FINALLY [c:R]WARMED UP![c:]", "喔，看來我終於[c:R]暖起來[c:]了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M STILL NOT FEELING [c:R]WARMER![c:]", "我還是沒覺得[c:R]暖和[c:]些！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS SEE HOW YOU DEAL WITH [c:bB]THIS![c:]", "看看你怎麼應付[c:bB]這個[c:]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful, the life of your next card will be on a timer.", "小心，你下一張卡牌的生命可要開始倒數了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I look forward to the [c:brnO]explosive[c:] results!", "真期待那[c:brnO]爆炸性[c:]的結果！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card cannot explode, how dissapointing.", "你的卡牌不能爆炸，真掃興。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VAR, I SEE YOU MADE IT TO ME SHIP CHALLENGER!", "呀哈，挑戰者，你上了我的船啊！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'VE BEEN WAITING FOR A WORTHY FIGHT!", "我一直等著像樣的對決呢！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS A STORM IS BREWING, I HOPE ME SHIP CAN HANDLE IT", "風暴似乎要來了，但願我的船撐得住。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I SEE YEE ARE SEVERELY HAUNTED!", "喔，看來你被鬼纏得不輕啊！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "REVENANT, PACK YE BAGS, YOURE GETTING THROWN OVERBOARD!", "亡魂，收拾行李吧，要把你扔下船了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I OVERESTIMATED ME SKILL, GOOD LUCK CHALLENGER.", "我太高估自己的本事了。祝你好運，挑戰者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "讓我看看，下個區域就是我自己的墓穴。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "也許你能克服重重難關，取得勝利！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I beat the livin' PULP out o' ye!", "我把你打成果醬了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ME SHIP! I FEAR WE MAY BE SINKING.", "我的船！恐怕我們要沉了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO HOLD YEE BREATH!", "準備好憋氣吧！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY FISHPASTE, YE FOUND DAVY JONES TREASURE", "我的老魚醬啊，你找到了戴維·瓊斯的寶藏！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRG, TWAS JUST DA FIRST ROUND!\nLETS SEE HOW YE FARE 'GAINST ME PERSONAL SHIP AN CREW!", "呀哈，剛才只是第一輪！\n看看你怎麼對付我的船和親信船員！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOW NICE OF YOU TO COME KNOCK AT MY DOORSTEP ON THIS TRULY SPOOKY DAY! DO YOU PREFER TREATS, OR TRICKS?", "在這陰森的日子來敲我的門，真是太好了！你喜歡糖果，還是搗蛋？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AWAY, LOOK AWAY! IF YOU WANT TO FIGHT, GET IT OVER QUICK!", "別看，別看！想打的話，就快點結束！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "oh... I- I see you're here again... Please, get rid of that monster and maybe I'll find some more time for you", "喔……你、你又來了……拜託，解決那隻怪物，也許我就能多陪你一會兒。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE BEATEN THE VICIOUS CANDY MONSTER AND SAVED HALLOWEEN!", "你打敗了凶惡的糖果怪獸，拯救了萬聖節！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR GETTING IT OVER WITH, AND DON'T EVER RETURN!", "謝謝你結束這一切，再也別回來了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEXT UP IS ROYALS VERY OWN SHIP, THE LIMONCELLO.", "接著是羅耀自己的船，檸檬甜酒。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS TRUSTY CREW OF SWASHBUCKLERS RESIDES THERE, MAY THEY GIVE YOU A WARM WELCOME.", "他那群可靠的豪俠船員住在那裡，願他們給你個熱情的歡迎。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no... does this mean you will try again?", "噢，不……這代表你又要試一次？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HE IS GONE... WHAT A RELIEF.", "喔，他走了……終於鬆了口氣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR YOUR BONES, KIND SIR!", "多謝你的骨頭，好心先生！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW THAT THAT MONSTER IS GONE, WHY DONT WE PLAY A LITTLE LONGER", "既然那怪物走了，何不再玩久一點？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE YOU DONT MIND, I PAID GOOD MONEY TO PLAY THESE.", "希望你別介意，我可是花大錢才能用這些卡牌的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT THE CANDY MONSTER! HE HAS ENOUGH OF YOUR [c:R]TRICKS![c:]", "別動糖果怪獸！他已經受夠你的[c:R]把戲[c:]了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH NO, HE HAS ARRIVED! HE IS THIRSTY FOR YOUR [c:R]BONES![c:]", "糟了，他來了！他渴望著你的[c:R]骨頭[c:]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you!", "謝謝！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUUUUUUUR, PAINNNFULLLLL DEAAATHHH AWAIIITTTSSS YOUUUUUUU!", "痛——苦——的死——亡——在等——著——你——！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARRG! WALK OFF THE PLANK YEE DIRTY SCALLYWAG!!!", "呀！你這髒兮兮的無賴，給我走跳板下海！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My dogs will enjoy your bones!", "我的狗會好好享用你的骨頭！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]{0}[c:]... He's only here for the riches.", "一個[c:bR]{0}[c:]……他只為財富而來。", Language.ChineseTraditional);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased!", "骨王十分慷慨。\n[c:bR]" + value + "[c:]的骨頭費用降低了！", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] base health has increased!", "骨王十分慷慨。\n[c:bR]" + value + "[c:]的基礎生命力提高了！", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, it looks like [c:bR]" + value + "[c:] bone cost has decreased!", "哎呀，看來[c:bR]" + value + "[c:]的骨頭費用降低了！", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased greatly!", "骨王十分慷慨。\n[c:bR]" + value + "[c:]的骨頭費用大幅降低了！", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base health has increased greatly!", "骨王非常慷慨。\n[c:bR]" + value + "[c:]的基礎生命力大幅提高了！", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base attack has increased!", "骨王非常慷慨。\n[c:bR]" + value + "[c:]的基礎攻擊力提高了！", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]INCREASING THE HEALTH OF THE ENTIRE DECK?![c:] YOU FOOL!", "……什麼？白骨領主，你為什麼這麼做？！[c:bR]提升整副牌組的生命力？！[c:]蠢貨！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]DECREASING THE COST OF THE ENTIRE DECK?![c:] YOU FOOL!", "……什麼？白骨領主，你為什麼這麼做？！[c:bR]降低整副牌組的費用？！[c:]蠢貨！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN HP[c:], HOW SAD. NOW PLEASE LEAVE.", "你已經沒有卡牌能[c:bR]增加生命力[c:]了，真可惜。現在請離開。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]REDUCE THEIR BONE COST[c:], HOW SAD. NOW PLEASE LEAVE.", "你已經沒有卡牌能[c:bR]降低骨頭費用[c:]了，真可惜。現在請離開。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN ATTACK[c:], HOW SAD. NOW PLEASE LEAVE.", "你已經沒有卡牌能[c:bR]增加攻擊力[c:]了，真可惜。現在請離開。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK DECREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "真可惜。本該降低你整副牌組的費用，但看來白骨領主已經給過你這份禮物。走吧！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK INCREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "真可惜。本該提升你整副牌組的屬性，但看來白骨領主已經給過你這份禮物。走吧！", Language.ChineseTraditional);


            // ShowThenClear
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO BE BOARDED!", "準備接舷戰！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That hammer doesn't look very sturdy, you'll break it if you bash my ice!", "那把錘子看起來不怎麼結實，拿它砸我的冰會壞掉喔！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DID YOU REALLY THINK THE BONELORD WOULD LET YOU OFF THAT EASILY?!", "你真以為白骨領主會這麼輕易放過你？！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET THE [size:5][c:bR]BONELORD[c:][size:] COMMETH!", "讓[size:5][c:bR]白骨領主[c:][size:]降臨！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose as you will...", "隨你選吧……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose one.", "選一個。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time to rest.", "該休息了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Bartender![c:] Drink up!", "[c:bG]上吧，酒保！[c:]喝個痛快！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Undertaker![c:] Dont scream!", "[c:bG]上吧，殯葬師！[c:]別尖叫！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Slingers Soul![c:] Time for a duel!", "[c:bG]上吧，槍手之魂！[c:]決鬥的時候到了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go One Armed Bandit![c:] I hope i get lucky!", "[c:bG]上吧，獨臂強盜！[c:]但願好運降臨！", Language.ChineseTraditional);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your score is " + amnt.ToString() + ", acceptable.", "你的分數是" + amnt.ToString() + "，還算可以。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is 10, heres your prize!", "得分是 10，這是獎品！", Language.ChineseTraditional);
            for (int amnt = 11; amnt <= 100; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is " + amnt.ToString() + ", too bad!", "你的分數是" + amnt.ToString() + "，真遺憾！", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SUCH A SMALL TRAP CANNOT AFFECT GIANTS.", "這麼小的陷阱，奈何不了巨人。", Language.ChineseTraditional);

            // ShowMessage
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PUSH YOUR LUCK FOR ONE MORE ABILITY?\nOR PULL AWAY?", "再賭一把，多拿一個能力？\n還是就此收手？", Language.ChineseTraditional);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Bones", "不再加骨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You no longer gain the extra bones, from defeating bosses.", "不再獲得擊敗頭目所提供的額外骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's Kerfuffle", "凱茜的騷動", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fourth turn of every battle, all your cards will be Frozen Away.", "每場戰鬥的第四回合，你所有的卡牌都會受到凍結解放。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer's Showdown", "索耶的對決", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose 1 bone every 3rd turn, if you have less than 3, gain 1 Bone", "每 3 回合失去 1 根骨頭；若骨頭少於 3 根，則改為獲得 1 根。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Rumble", "羅耀大混戰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every third card you play gains the Lit Fuse sigil.", "每打出三張卡牌，第三張便獲得引信印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulless", "無魂者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons cost +1 Energy.", "骷髏的能量費用 +1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Hammer", "脆弱之錘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hammer gets repaired only after every Boss.", "錘子僅在每場頭目戰後修復。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jammed Chair", "卡住的電椅", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The electric chair is always set to level 3.", "電椅固定設為第 3 級。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wilted Clover", "枯萎三葉草", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is only 2 Cards present at every Card chest.", "每個卡牌寶箱只有 2 張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Mode", "地獄模式", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont play this one, seriously. (Makes encounters Significantly Harder)", "別選這個，說真的。（遭遇戰會大幅變難。）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infinite Lives", "無限生命", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't die. Really.", "你不會死。真的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Safe Chair", "安全電椅", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards are immune to electricity of the chair.", "你的卡牌不受電椅電流影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Lords Mercy", "白骨領主的憐憫", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a Bone when you place any free Card on the Board.", "在檯面上放置任何不需費用的卡牌時，獲得一根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing of the Ankh", "安卡的祝福", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start Pharaoh Battles and Bosses with an extra starting Bone and Energy.", "法老戰與頭目戰開始時，骨頭和能量各額外增加一點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengeant Ghouls", "復仇食屍鬼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee, Sawyer and Royal have new tricks up their sleeve", "凱茜、索耶和羅耀都有新的壓箱寶。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Roller", "豪賭客", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal is replaced by a new face", "羅耀會由一張新面孔取代。", Language.ChineseTraditional);

            // Debug
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Choice", "卡牌選擇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare Card Choice", "稀有卡牌選擇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debug Chests", "寶箱除錯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base Mod Cards To Deck", "將基礎模組卡牌加入牌組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Custom Mod Cards To Deck", "將自訂模組卡牌加入牌組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debug Tools", "除錯工具", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debug Encounters", "遭遇戰除錯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disable Combat Bell", "停用戰鬥鈴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disable Hammer", "停用錘子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disable Hand Model", "停用手部模型", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base Mod Cards To Hand", "將基礎模組卡牌加入手牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Custom Mod Cards To Hand", "將自訂模組卡牌加入手牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 1", "生成：對手卡槽 1", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 2", "生成：對手卡槽 2", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 3", "生成：對手卡槽 3", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 4", "生成：對手卡槽 4", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn All Opponent Slots", "生成：對手所有卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start at Twin Giants", "從雙子巨人開始", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start at Bonelord", "從白骨領主開始", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win Round", "贏得此輪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Round", "輸掉此輪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Bones", "增加骨頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Energy", "增加能量", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clear Deck", "清空牌組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reset Removed Pieces", "重置已移除的棋子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill Opponent Cards", "消滅對手卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Main Deck", "從主牌組抽牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Side Deck", "從副牌組抽牌", Language.ChineseTraditional);

            // Credits
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cat aka Bastard Man aka Little Guy", "貓，又名混帳傢伙，又名小不點", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "API Developers", "API 開發者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord", "白骨領主", Language.ChineseTraditional);
