    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "麥尼菲庫斯的新一輪遊戲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "麥尼菲庫斯的新一輪遊戲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "查看牌組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "魔法之塔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "黏液地牢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "熔岩地牢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "虛空地牢", Language.ChineseTraditional);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "自動解鎖麥尼菲庫斯的凱茜模組中的所有挑戰和初始牌組。這不會改變你的麥尼菲庫斯挑戰點數。如果之後改變心意，決定正常解鎖挑戰，挑戰點數仍會維持原值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "第二章的基礎巫師卡牌會保留原本的屬性。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "使用舊版 2D 平面卡牌設計，取代新版 3D 模型。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "在每張卡牌的背景加上潑漆效果，就像原版麥尼菲庫斯的最終戰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "以第三人稱視角遊玩麥尼菲庫斯的遊戲。想使用經典第一人稱視角時，請停用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "桌面模式下，在玩家周圍顯示格線。", Language.ChineseTraditional);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "空白魔思力", Language.ChineseTraditional);
            RegisterAbility("Blank Mox", "空白魔思力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "抽到帶有此印記的卡牌時，它會化為隨機一種魔思力水晶。\n此印記在其他卡牌上時，該卡牌會生成隨機一種魔思力水晶。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "無形魔思力", Language.ChineseTraditional);
            RegisterAbility("Undecided Mox", "無形魔思力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "打出帶有此印記的卡牌時，選擇此卡牌要提供的魔思力類型。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "紅寶石之心", Language.ChineseTraditional);
            RegisterAbility("Ruby Heart", "紅寶石之心");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "帶有此印記的卡牌陣亡時，在原位生成一張紅寶石魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "藍寶石之心", Language.ChineseTraditional);
            RegisterAbility("Sapphire Heart", "藍寶石之心");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "帶有此印記的卡牌陣亡時，在原位生成一張藍寶石魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "骨髓", Language.ChineseTraditional);
            RegisterAbility("Bone Marrow", "骨髓");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "你的非寶石卡牌陣亡時，帶有此印記的卡牌獲得 1 點攻擊力，最多增加至 5 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "激發", Language.ChineseTraditional);
            RegisterAbility("Stimulation", "激發");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "每回合結束時，帶有此印記的卡牌獲得 1 點攻擊力，上限為 4 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "激發（生命力）", Language.ChineseTraditional);
            RegisterAbility("Stimulation (Health)", "激發（生命力）");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "每回合結束時，帶有此印記的卡牌獲得 2 點生命力，上限為 10 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "死亡掠奪", Language.ChineseTraditional);
            RegisterAbility("Dead Draw", "死亡掠奪");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "非寶石卡牌死亡時，從你的牌組抽一張牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "綠寶石之心", Language.ChineseTraditional);
            RegisterAbility("Emerald Heart", "綠寶石之心");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "帶有此印記的卡牌陣亡時，在原位生成一張綠寶石魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "黏液", Language.ChineseTraditional);
            RegisterAbility("Gooey", "黏液");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "帶有此印記的卡牌受到攻擊時，攻擊者失去 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "精神寶石手", Language.ChineseTraditional);
            RegisterAbility("Mental Gemnastics", "精神寶石手");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "打出帶有此印記的卡牌時，依檯面上的寶石數量，從你的牌組抽取等量卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "掠奪", Language.ChineseTraditional);
            RegisterAbility("Loot", "掠奪");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "帶有此印記的卡牌造成直接傷害時，依造成的傷害量，從你的牌組抽取等量卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "生命竊取", Language.ChineseTraditional);
            RegisterAbility("Life Steal", "生命竊取");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "帶有此印記的卡牌造成直接傷害時，其擁有者恢復等同傷害量的生命。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "驅時之觸", Language.ChineseTraditional);
            RegisterAbility("Knockback Hit", "驅時之觸");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "帶有此印記的卡牌擊中對面卡牌時，會將目標往印記所示的方向踢開。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "長矛召喚", Language.ChineseTraditional);
            RegisterAbility("Impaled", "長矛召喚");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "帶有此印記的卡牌陣亡時，在原位生成一張長矛。長矛具有鋒利之刺，攻擊力 0、生命力 3。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "偉大魔思力", Language.ChineseTraditional);
            RegisterAbility("Magnus Mox", "偉大魔思力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "帶有此印記的卡牌在檯面上時，為其擁有者提供橘色、藍色和綠色寶石各一顆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "復活蘇生", Language.ChineseTraditional);
            RegisterAbility("Resurrection", "復活蘇生");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "非寶石卡牌陣亡時，該卡牌會復活，但帶有此印記的卡牌會失去 3 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "骰子力量", Language.ChineseTraditional);
            RegisterAbility("Rerolls", "骰子力量");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "每回合結束時，帶有此印記的卡牌攻擊力會重擲為 0 至 3 之間的隨機數值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "鋼鐵陷阱", Language.ChineseTraditional);
            RegisterAbility("Steel Trap", "鋼鐵陷阱");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "帶有此印記的卡牌陣亡時，對面的卡牌也會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "寶石護盾", Language.ChineseTraditional);
            RegisterAbility("Gem Shield", "寶石護盾");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "打出帶有此印記的卡牌時，檯面上所有寶石獲得護盾。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "鍍層工藝", Language.ChineseTraditional);
            RegisterAbility("Plating Work", "鍍層工藝");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "帶有此印記的卡牌在檯面上時，你這一側的所有寶石獲得鋒利之刺印記和 2 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "操偶師", Language.ChineseTraditional);
            RegisterAbility("Animator", "操偶師");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "帶有此印記的卡牌在檯面上時，所有攻擊力為 0 的非魔思力卡牌獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "寶石吸收者", Language.ChineseTraditional);
            RegisterAbility("Gem Absorber", "寶石吸收者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "打出帶有此印記的卡牌時，你這一側的所有寶石都會陣亡。每吸收一顆寶石，此卡牌獲得 1 點攻擊力和 2 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "下潛", Language.ChineseTraditional);
            RegisterAbility("Submerge", "下潛");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "回合結束時，帶有此印記的卡牌會潛入水下。再次浮出時，此卡牌會變成隨機一張觸手卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "使魔", Language.ChineseTraditional);
            RegisterAbility("Familiar", "使魔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "若檯面上沒有非寶石卡牌，帶有此印記的卡牌便會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "消逝", Language.ChineseTraditional);
            RegisterAbility("Fading", "消逝");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "帶有此印記的卡牌會在回合結束時陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "不定變體", Language.ChineseTraditional);
            RegisterAbility("Morph", "不定變體");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "打出帶有此印記的卡牌時，它會模仿對面的卡牌。若對面沒有卡牌，此卡牌便會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "矩陣乘法", Language.ChineseTraditional);
            RegisterAbility("Multiplication", "矩陣乘法");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "打出帶有此印記的卡牌時，抽取另一張同名卡牌，但其寶石費用不同。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "魔思力迴圈", Language.ChineseTraditional);
            RegisterAbility("Mox Cycle", "魔思力迴圈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "每回合結束時，檯面上所有魔思力會循環轉換為其他寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "魔思力掉落", Language.ChineseTraditional);
            RegisterAbility("Mox Strafe", "魔思力掉落");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "回合結束時，此卡牌往印記所示方向移動，並在原位留下一張魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "純粹主義", Language.ChineseTraditional);
            RegisterAbility("Purist", "純粹主義");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "與此卡牌正面相對的任何卡牌，都會失去所有印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "釀造坊", Language.ChineseTraditional);
            RegisterAbility("Brewery", "釀造坊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "每回合結束時，你會自動從副牌組抽一張魔思力卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "引火", Language.ChineseTraditional);
            RegisterAbility("Ignite", "引火");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "打出帶有此印記的卡牌時，以火焰填滿所有敵方空卡槽。火焰具有煩躁印記，攻擊力 0、生命力 1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "星空投影", Language.ChineseTraditional);
            RegisterAbility("Projection", "星空投影");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "帶有此印記的卡牌受到攻擊時，會移動並留下自身的星體投影。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "法術大全", Language.ChineseTraditional);
            RegisterAbility("Spell Book", "法術大全");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "打出帶有此印記的卡牌時，抽取一張隨機法術牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "法術學者", Language.ChineseTraditional);
            RegisterAbility("Scholar", "法術學者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "打出帶有此印記的卡牌時，隨機抽取一本布立尼的書。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "黃金之觸", Language.ChineseTraditional);
            RegisterAbility("Midas' Touch", "黃金之觸");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "帶有此印記的卡牌攻擊其他卡牌時，受攻擊卡牌會失去所有攻擊力並變成黃金。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "黃金之軀", Language.ChineseTraditional);
            RegisterAbility("Made of Gold", "黃金之軀");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "帶有此印記的卡牌陣亡時，擊殺者獲得 2 顆水晶。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "引爆召喚", Language.ChineseTraditional);
            RegisterAbility("Summon Runes", "引爆召喚");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "打出帶有此印記的卡牌時，在身旁召喚兩張符文。符文具有引爆者印記，攻擊力 0、生命力 1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "生命力法術", Language.ChineseTraditional);
            RegisterAbility("Spell of Health", "生命力法術");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "打出帶有此印記的法術時，你這一側的所有卡牌獲得 +2 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "攻擊法術", Language.ChineseTraditional);
            RegisterAbility("Spell of Attack", "攻擊法術");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "打出帶有此印記的法術時，你這一側的所有卡牌獲得 +1 攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "寒霜咒", Language.ChineseTraditional);
            RegisterAbility("Frost Spell", "寒霜咒");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "打出帶有此印記的法術時，所有屬於對手的卡牌攻擊力變為 0，但獲得 +2 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "強風咒", Language.ChineseTraditional);
            RegisterAbility("Spell of Wind", "強風咒");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "打出帶有此印記的法術時，你這一側的所有卡牌獲得飛空能力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "時針順碎語", Language.ChineseTraditional);
            RegisterAbility("Ruckus", "時針順碎語");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "打出帶有此印記的卡牌時，檯面上所有卡牌順時針移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "淨水咒", Language.ChineseTraditional);
            RegisterAbility("Spell of Water", "淨水咒");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "打出帶有此印記的法術時，檯面上每張卡牌的所有印記都會被抹除。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "火焰咒", Language.ChineseTraditional);
            RegisterAbility("Spell of Flame", "火焰咒");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "選擇檯面的一側。該側所有卡牌失去 2 點生命力（不會因此陣亡），並增加 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "點燃", Language.ChineseTraditional);
            RegisterAbility("Set Ablaze", "點燃");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "對面一側的每張卡牌失去 2 點生命力（不會因此陣亡），並增加 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "一次性法術", Language.ChineseTraditional);
            RegisterAbility("One Time Spell", "一次性法術");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "回合結束時，帶有此印記的法術會陣亡，並從你的牌組移除。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "貪慾之壺", Language.ChineseTraditional);
            RegisterAbility("Vase of Greed", "貪慾之壺");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "打出帶有此印記的法術時，棄掉你目前所有手牌，再抽 4 張新卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "侏儒化", Language.ChineseTraditional);
            RegisterAbility("Gnomification", "侏儒化");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "選擇一個卡槽，在其中召喚侏儒卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "詛咒", Language.ChineseTraditional);
            RegisterAbility("Cursed", "詛咒");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "打出帶有此印記的法術時，它會立刻陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "靈感", Language.ChineseTraditional);
            RegisterAbility("Inspiration", "靈感");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "選擇一張卡牌，使其獲得飛空與掠奪者，持續 1 回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "微積", Language.ChineseTraditional);
            RegisterAbility("Calculus", "微積");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "選擇一張卡牌，交換其攻擊力與生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "狂怒", Language.ChineseTraditional);
            RegisterAbility("Rage", "狂怒");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "選擇一張卡牌消滅。該卡牌擁有者的對手會受到等同其原本生命力的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "火球術", Language.ChineseTraditional);
            RegisterAbility("Fireball", "火球術");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "選擇一張卡牌，使其受到 2 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "冰封之觸", Language.ChineseTraditional);
            RegisterAbility("Cold to the Touch", "冰封之觸");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "帶有此印記的卡牌攻擊其他卡牌時，受攻擊的卡牌失去 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "冰封", Language.ChineseTraditional);
            RegisterAbility("Frozen", "冰封");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "每回合結束時，此卡牌會失去冰封生命力。冰封生命力耗盡，或此卡牌受到攻擊時，便會解凍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "強力牽引", Language.ChineseTraditional);
            RegisterAbility("Strong Pull", "強力牽引");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "所有敵方卡牌都會優先攻擊此卡牌，而非其他目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "置換反應", Language.ChineseTraditional);
            RegisterAbility("Displacement", "置換反應");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "抽到帶有此印記的卡牌時，會將另一張同名卡牌隨機插入你的牌組。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "寶石清算", Language.ChineseTraditional);
            RegisterAbility("Gem Reckoning", "寶石清算");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "每回合結束時，若此卡牌的擁有者未控制任何寶石，便棄掉你手牌中最左側的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "魔思力攻擊力", Language.ChineseTraditional);
            RegisterAbility("Mox Power", "魔思力攻擊力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "此印記顯示的數值等於擁有者一側檯面上的魔思力卡牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "魔思力生命力", Language.ChineseTraditional);
            RegisterAbility("Mox Health", "魔思力生命力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "此印記顯示的數值等於擁有者一側檯面上的魔思力卡牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "燭火臨近", Language.ChineseTraditional);
            RegisterAbility("Candle Proximity", "燭火臨近");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "此印記顯示的數值，依此卡牌靠近桌上蠟燭的程度決定。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "殺戮之力", Language.ChineseTraditional);
            RegisterAbility("Murder Power", "殺戮之力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "此印記顯示的數值等於對手一側檯面上的攻擊力總和。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "此印記顯示的數值等於你這一側檯面上攻擊力總和的一半。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "法術力量", Language.ChineseTraditional);
            RegisterAbility("Spell Power", "法術力量");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "此印記顯示的數值等於目前這座地牢中打出的法術總數。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "此印記顯示的數值等於本場戰鬥中打出的法術總數。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "反擊力量", Language.ChineseTraditional);
            RegisterAbility("Counterbattery Power", "反擊力量");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "此印記顯示的數值等於你在本場戰鬥中受到的傷害總量除以二。", Language.ChineseTraditional);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, ChineseTraditionalLanguagePack.Localize(info.rulebookName));
            }

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox", "魔思力", Language.ChineseTraditional);
            RegisterCard("Mox", "魔思力", "its a me moxio", "是我啦，魔思力奧！");
            RegisterCard("Ruby Mox", "紅寶石魔思力", "its a me moxio", "是我啦，魔思力奧！");
            RegisterCard("Emerald Mox", "綠寶石魔思力", "its a me moxio", "是我啦，魔思力奧！");
            RegisterCard("Sapphire Mox", "藍寶石魔思力", "its a me moxio", "是我啦，魔思力奧！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its a me moxio", "是我啦，魔思力奧！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear", "長矛", Language.ChineseTraditional);
            RegisterCard("Spear", "長矛", "ayo", "唉唷");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ayo", "唉唷", Language.ChineseTraditional);
            RegisterCard("Mage Pupil", "法師弟子", "Though weak, it can always be useful in the right situation.", "雖然弱小，只要時機對了，總能派上用場。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though weak, it can always be useful in the right situation.", "雖然弱小，只要時機對了，總能派上用場。", Language.ChineseTraditional);
            RegisterCard("Junior Sage", "新進賢者", "Although simple, it can prove itself to be useful.", "雖然簡單，仍能證明自己的用處。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Although simple, it can prove itself to be useful.", "雖然簡單，仍能證明自己的用處。", Language.ChineseTraditional);
            RegisterCard("Muscle Mage", "健壯法師", "An abomination of muscles, developed from drinking too many potions of the alchemist..", "喝了太多鍊金術士的藥水，變成肌肉畸形的怪物……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination of muscles, developed from drinking too many potions of the alchemist..", "喝了太多鍊金術士的藥水，變成肌肉畸形的怪物……", Language.ChineseTraditional);
            RegisterCard("Green Mage", "綠法師", "It draws its power from the mana of the mox on the board.", "它從檯面上的魔思力汲取魔力，化為力量。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws its power from the mana of the mox on the board.", "它從檯面上的魔思力汲取魔力，化為力量。", Language.ChineseTraditional);
            RegisterCard("Blue Mage", "藍法師", "Never doubt its utility.", "永遠別懷疑它的實用性。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Never doubt its utility.", "永遠別懷疑它的實用性。", Language.ChineseTraditional);
            RegisterCard("Blue Sporemage", "藍胞子法師", "", "");
            RegisterCard("Force Mage", "力場法師", "A mage, proficient in a martial stance which allows it block nearly anything..", "精通武術架勢的法師，幾乎能擋下任何攻擊……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage, proficient in a martial stance which allows it block nearly anything..", "精通武術架勢的法師，幾乎能擋下任何攻擊……", Language.ChineseTraditional);
            RegisterCard("Gem Fiend", "寶石妖魔", "A wretched, unstable creature of gems. It can tear through anything.", "可悲而不穩定的寶石生物。能撕碎任何東西。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wretched, unstable creature of gems. It can tear through anything.", "可悲而不穩定的寶石生物。能撕碎任何東西。", Language.ChineseTraditional);
            RegisterCard("Hover Mage", "懸浮法師", "Using its spells it soars high to hit directly", "藉法術飛上高空，發動直接攻擊。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using its spells it soars high to hit directly", "藉法術飛上高空，發動直接攻擊。", Language.ChineseTraditional);
            RegisterCard("Mage Knight", "法師騎士", "An intimidating and towering defense, however requiring gems to stay stable.", "高聳而令人生畏的防線，但需要寶石才能維持穩定。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An intimidating and towering defense, however requiring gems to stay stable.", "高聳而令人生畏的防線，但需要寶石才能維持穩定。", Language.ChineseTraditional);
            RegisterCard("Orange Mage", "橘色法師", "Using its spells, it boosts the damage of all gems.", "運用法術，提升所有寶石造成的傷害。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using its spells, it boosts the damage of all gems.", "運用法術，提升所有寶石造成的傷害。", Language.ChineseTraditional);
            RegisterCard("Practice Wizard", "實習巫師", "A lifeless practice target.. standing tall enough to block any attacks.", "沒有生命的練習靶……站得夠高，足以擋住任何攻擊。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lifeless practice target.. standing tall enough to block any attacks.", "沒有生命的練習靶……站得夠高，足以擋住任何攻擊。", Language.ChineseTraditional);
            RegisterCard("Ruby Golem", "紅寶石魔像", "A construct powered by Mox.As it perishes it leaves behind parts of itself.", "由魔思力驅動的構裝體，陣亡後會留下自身的部分殘骸。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A construct powered by Mox.As it perishes it leaves behind parts of itself.", "由魔思力驅動的構裝體，陣亡後會留下自身的部分殘骸。", Language.ChineseTraditional);
