            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Familiar", "狼使魔", Language.ChineseTraditional);
            RegisterCard("Wolf Familiar", "狼使魔", "It rips into its enemies with little to no remorse.", "撕咬敵人時，幾乎毫無悔意。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It rips into its enemies with little to no remorse.", "撕咬敵人時，幾乎毫無悔意。", Language.ChineseTraditional);
