            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Worm", "水晶蠕蟲", Language.ChineseTraditional);
            RegisterCard("Crystal Worm", "水晶蠕蟲", "Its body is made out of pure mana.. Gleaming and transforming into other gems.", "身軀由純粹魔力構成……閃耀著光芒，轉變成其他寶石。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its body is made out of pure mana.. Gleaming and transforming into other gems.", "身軀由純粹魔力構成……閃耀著光芒，轉變成其他寶石。", Language.ChineseTraditional);
