            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouroberyl", "銜寶蛇", Language.ChineseTraditional);
            RegisterCard("Ouroberyl", "銜寶蛇", "It gleams and takes different forms.. How majestic..", "閃爍光芒，變換形態……多麼壯麗……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It gleams and takes different forms.. How majestic..", "閃爍光芒，變換形態……多麼壯麗……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spellcaster", "法術大使", Language.ChineseTraditional);
            RegisterCard("Spellcaster", "法術大使", "It reads out spells from its book and casts them directly to your hand.", "從書中唸出咒語，直接施放到你的手牌裡。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It reads out spells from its book and casts them directly to your hand.", "從書中唸出咒語，直接施放到你的手牌裡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Magician", "混沌法師", Language.ChineseTraditional);
            RegisterCard("Chaos Magician", "混沌法師", "A scholar proficient in Chaos Theory, channeling a scramble unto the entire board.", "精通混沌理論的法術學者，將混亂之力引向整個檯面。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scholar proficient in Chaos Theory, channeling a scramble unto the entire board.", "精通混沌理論的法術學者，將混亂之力引向整個檯面。", Language.ChineseTraditional);
