            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Detonator", "寶石引爆者", Language.ChineseTraditional);
            RegisterCard("Gem Detonator", "寶石引爆者", "It went berserk after hearing mysterious whispers in a crypt.", "在墓穴裡聽見神祕低語後，便陷入狂暴。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It went berserk after hearing mysterious whispers in a crypt.", "在墓穴裡聽見神祕低語後，便陷入狂暴。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he", "他", Language.ChineseTraditional);
