            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homunculus", "人造人", Language.ChineseTraditional);
            RegisterCard("Homunculus", "人造人", "A strange, to say the least creature.", "至少可以說，是個奇怪的生物。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange, to say the least creature.", "至少可以說，是個奇怪的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimagius", "幻形獸", Language.ChineseTraditional);
            RegisterCard("Mimagius", "幻形獸", "It distorts itself into the form of the opposing card.", "扭曲自身，變成對面卡牌的模樣。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It distorts itself into the form of the opposing card.", "扭曲自身，變成對面卡牌的模樣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deflector", "偏轉器", Language.ChineseTraditional);
            RegisterCard("Deflector", "偏轉器", "You would not want to end up on the wrong side of it..", "你不會想與它為敵……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would not want to end up on the wrong side of it..", "你不會想與它為敵……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Auspex", "占星師", Language.ChineseTraditional);
            RegisterCard("Auspex", "占星師", "It harnesses the power of the stars for you..", "它能為你駕馭星辰的力量……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It harnesses the power of the stars for you..", "它能為你駕馭星辰的力量……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astral Sorcerer", "星界巫師", Language.ChineseTraditional);
            RegisterCard("Astral Sorcerer", "星界巫師", "A sorcerer proficient in summoning astral projections to protect itself when in danger.", "擅長召喚星體投影的巫師，危險時便用來保護自己。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sorcerer proficient in summoning astral projections to protect itself when in danger.", "擅長召喚星體投影的巫師，危險時便用來保護自己。", Language.ChineseTraditional);
