            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "real", "真實", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trinket Bearer", "道具攜帶者", Language.ChineseTraditional);
            RegisterCard("Trinket Bearer", "道具攜帶者", "A mischevious little goblin creature. It carries around valueables in its backpack.", "頑皮的小哥布林，揹包裡總帶著值錢的東西。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mischevious little goblin creature. It carries around valueables in its backpack.", "頑皮的小哥布林，揹包裡總帶著值錢的東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backpack", "揹包", Language.ChineseTraditional);
            RegisterCard("Backpack", "揹包", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimbot", "激勵機器人", Language.ChineseTraditional);
            RegisterCard("Stimbot", "激勵機器人", "Powered by stimulation, and steam..", "由激發與蒸汽驅動……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered by stimulation, and steam..", "由激發與蒸汽驅動……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magimorph", "變形法師", Language.ChineseTraditional);
            RegisterCard("Magimorph", "變形法師", "Its disgusting gooey body warps and distorts into distant forms. It's wonderous if you look at it right.", "令人作嘔的黏稠身軀，不斷扭曲成陌生的形態。換個角度看，也挺奇妙的。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its disgusting gooey body warps and distorts into distant forms. It's wonderous if you look at it right.", "令人作嘔的黏稠身軀，不斷扭曲成陌生的形態。換個角度看，也挺奇妙的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Performer", "表演者", Language.ChineseTraditional);
            RegisterCard("Performer", "表演者", "Watch it create a rabbit out of its wand..", "看它從魔杖裡變出兔子……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch it create a rabbit out of its wand..", "看它從魔杖裡變出兔子……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Senior Sage", "高階賢者", Language.ChineseTraditional);
            RegisterCard("Senior Sage", "高階賢者", "A Junior Sage that has mastered the art of Magicks.", "精通魔法技藝的新進賢者。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Junior Sage that has mastered the art of Magicks.", "精通魔法技藝的新進賢者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Mech", "藍寶石機甲", Language.ChineseTraditional);
            RegisterCard("Sapphire Mech", "藍寶石機甲", "A mage-like automaton piloted by a sapphire mox.. Admirable.", "由藍寶石魔思力操縱的法師型自動機器人……令人讚嘆。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage-like automaton piloted by a sapphire mox.. Admirable.", "由藍寶石魔思力操縱的法師型自動機器人……令人讚嘆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Titan", "紅寶石泰坦", Language.ChineseTraditional);
            RegisterCard("Ruby Titan", "紅寶石泰坦", "A perfected construct of a ruby golem, a monstrous machine of destruction.", "紅寶石魔像的完美構裝體，駭人的毀滅機器。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A perfected construct of a ruby golem, a monstrous machine of destruction.", "紅寶石魔像的完美構裝體，駭人的毀滅機器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleene's Scholar", "布立尼的學徒", Language.ChineseTraditional);
            RegisterCard("Bleene's Scholar", "布立尼的學徒", "A scholar in training, currently studying the works of Master Bleene.", "受訓中的法術學者，目前正在研讀布立尼大師的著作。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scholar in training, currently studying the works of Master Bleene.", "受訓中的法術學者，目前正在研讀布立尼大師的著作。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goranj's Warrior", "哥蘭吉的戰士", Language.ChineseTraditional);
            RegisterCard("Goranj's Warrior", "哥蘭吉的戰士", "A foe mentored by Master Goranj, proficient at dual striking.", "受哥蘭吉大師指導的敵人，精通雙重打擊。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A foe mentored by Master Goranj, proficient at dual striking.", "受哥蘭吉大師指導的敵人，精通雙重打擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cider Mage", "蘋果酒法師", Language.ChineseTraditional);
            RegisterCard("Cider Mage", "蘋果酒法師", "This mage has a secret formula of cider that nullifies the opponents spells..", "這位法師有個蘋果酒祕方，能讓對手的法術失效……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage has a secret formula of cider that nullifies the opponents spells..", "這位法師有個蘋果酒祕方，能讓對手的法術失效……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewer Sage", "釀造賢者", Language.ChineseTraditional);
            RegisterCard("Brewer Sage", "釀造賢者", "A sage, sitting still and perfecting his art of brewing..", "靜坐著的賢者，不斷精進釀造技藝……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sage, sitting still and perfecting his art of brewing..", "靜坐著的賢者，不斷精進釀造技藝……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soda Mage", "碳酸法師", Language.ChineseTraditional);
            RegisterCard("Soda Mage", "碳酸法師", "This pathetic mage melted away from drinking too much carbonated liquid..", "這可憐的法師喝了太多碳酸飲料，整個融化了……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This pathetic mage melted away from drinking too much carbonated liquid..", "這可憐的法師喝了太多碳酸飲料，整個融化了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whitesmith", "鍛寶匠", Language.ChineseTraditional);
            RegisterCard("Whitesmith", "鍛寶匠", "Their life's work was dedicated to reinforcing gems.", "畢生致力於強化寶石。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their life's work was dedicated to reinforcing gems.", "畢生致力於強化寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteer", "傀儡師", Language.ChineseTraditional);
            RegisterCard("Puppeteer", "傀儡師", "Its mastery of control magicks lets even Practice Wizards contribute.", "精湛的控制魔法，就連實習巫師也能發揮作用。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its mastery of control magicks lets even Practice Wizards contribute.", "精湛的控制魔法，就連實習巫師也能發揮作用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juggler", "雜耍者", Language.ChineseTraditional);
            RegisterCard("Juggler", "雜耍者", "It juggles around your mox cards, as if they were juggling balls..", "像拋接雜耍球一般，拋接你的魔思力卡牌……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It juggles around your mox cards, as if they were juggling balls..", "像拋接雜耍球一般，拋接你的魔思力卡牌……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Joker", "小丑", Language.ChineseTraditional);
            RegisterCard("Joker", "小丑", "Dedicated to the art of fun.. though most only find it annoying.", "一心鑽研逗樂的藝術……可惜，多數人只覺得煩。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dedicated to the art of fun.. though most only find it annoying.", "一心鑽研逗樂的藝術……可惜，多數人只覺得煩。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valkyrie", "女武神", Language.ChineseTraditional);
            RegisterCard("Valkyrie", "女武神", "A student that has trained under Master Orlu. It has become an expert in airborne magicks.", "師承歐魯大師的學徒，如今已精通飛行魔法。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A student that has trained under Master Orlu. It has become an expert in airborne magicks.", "師承歐魯大師的學徒，如今已精通飛行魔法。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valkyrie Thief", "女武神盜賊", Language.ChineseTraditional);
            RegisterCard("Valkyrie Thief", "女武神盜賊", "liar liar chicken friar.", "騙子騙子，雞毛撢子。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "liar liar chicken friar.", "騙子騙子，雞毛撢子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Maniac", "綠寶石狂徒", Language.ChineseTraditional);
            RegisterCard("Emerald Maniac", "綠寶石狂徒", "A crazed maniac.. Drawing out health from the mox..", "瘋狂的暴徒……從魔思力中汲取生命力……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A crazed maniac.. Drawing out health from the mox..", "瘋狂的暴徒……從魔思力中汲取生命力……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Daemon", "紅寶石惡魔", Language.ChineseTraditional);
            RegisterCard("Ruby Daemon", "紅寶石惡魔", "If not properly sustained, it will destroy your hand to fuel itself..", "若供給不足，就會摧毀你的手牌來維持自己……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If not properly sustained, it will destroy your hand to fuel itself..", "若供給不足，就會摧毀你的手牌來維持自己……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Friend", "寶石之友", Language.ChineseTraditional);
            RegisterCard("Gem Friend", "寶石之友", "fren", "好捧友");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "fren", "好捧友", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "德魯伊", Language.ChineseTraditional);
            RegisterCard("Druid", "德魯伊", "Just look at what you've done..", "看看你都做了什麼……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just look at what you've done..", "看看你都做了什麼……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Legs", "鏈鎖之腿", Language.ChineseTraditional);
            RegisterCard("Chained Legs", "鏈鎖之腿", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sealed Body", "封印之軀", Language.ChineseTraditional);
            RegisterCard("Sealed Body", "封印之軀", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bound Arms", "束縛之臂", Language.ChineseTraditional);
            RegisterCard("Bound Arms", "束縛之臂", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imprisoned Tyrant", "囚禁的暴君", Language.ChineseTraditional);
            RegisterCard("Imprisoned Tyrant", "囚禁的暴君", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication mage", "矩陣法師", Language.ChineseTraditional);
            RegisterCard("Multiplication mage", "矩陣法師", "This cycle can go on forever..", "這個循環可以永遠持續……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cycle can go on forever..", "這個循環可以永遠持續……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Invisible mage", "隱形法師", Language.ChineseTraditional);
            RegisterCard("Invisible mage", "隱形法師", "It drank the wrong potion and ended up invisible. How clumsy.", "喝錯藥水，結果變隱形了。真笨。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It drank the wrong potion and ended up invisible. How clumsy.", "喝錯藥水，結果變隱形了。真笨。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Sage", "水晶賢者", Language.ChineseTraditional);
            RegisterCard("Crystal Sage", "水晶賢者", "A young scholar, profoundly studying mana crystals.", "潛心研究魔力水晶的年輕法術學者。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young scholar, profoundly studying mana crystals.", "潛心研究魔力水晶的年輕法術學者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Guardian", "寶石守護者", Language.ChineseTraditional);
            RegisterCard("Gem Guardian", "寶石守護者", "The inverse of the Gem Detonator, this one seeks to protect all mox.", "與寶石引爆者相反，它想保護所有魔思力。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The inverse of the Gem Detonator, this one seeks to protect all mox.", "與寶石引爆者相反，它想保護所有魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembound Ripper", "寶石開膛手", Language.ChineseTraditional);
            RegisterCard("Gembound Ripper", "寶石開膛手", "It is unstable, but such is the price for unending power.", "並不穩定，但這就是無盡力量的代價。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unstable, but such is the price for unending power.", "並不穩定，但這就是無盡力量的代價。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "寶石吞噬者", Language.ChineseTraditional);
            RegisterCard("Gem Absorber", "寶石吞噬者", "It seeks out to consume all mana within Mox to grow stronger.", "企圖吞噬魔思力中的所有魔力，使自己更強。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seeks out to consume all mana within Mox to grow stronger.", "企圖吞噬魔思力中的所有魔力，使自己更強。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "骷髏法師", Language.ChineseTraditional);
            RegisterCard("Skelemagus", "骷髏法師", "Great power for a few, fleeting moments..", "強大的力量，卻只維持短短片刻……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great power for a few, fleeting moments..", "強大的力量，卻只維持短短片刻……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelesage", "骸骨賢者", Language.ChineseTraditional);
            RegisterCard("Skelesage", "骸骨賢者", "One of my own Junior Sages, lost and revived.", "我失去後又復活的一位新進賢者。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of my own Junior Sages, lost and revived.", "我失去後又復活的一位新進賢者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic Scholar", "煩躁學者", Language.ChineseTraditional);
            RegisterCard("Erratic Scholar", "煩躁學者", "A panicked scholar.. Always running from its problems..", "驚慌的法術學者……總在逃避自己的問題……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A panicked scholar.. Always running from its problems..", "驚慌的法術學者……總在逃避自己的問題……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Mage", "魔思力法師", Language.ChineseTraditional);
            RegisterCard("Mox Mage", "魔思力法師", "A Mox disguised as a mage.. It's not going to fool anyone.", "假扮法師的魔思力……根本騙不了人。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Mox disguised as a mage.. It's not going to fool anyone.", "假扮法師的魔思力……根本騙不了人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aurumtact", "點金術士", Language.ChineseTraditional);
            RegisterCard("Aurumtact", "點金術士", "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "因貪婪而受詛咒的年邁法術學者，會將碰到的任何事物封入純金。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "因貪婪而受詛咒的年邁法術學者，會將碰到的任何事物封入純金。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Mox", "連環魔思力", Language.ChineseTraditional);
            RegisterCard("Chained Mox", "連環魔思力", "A collection of 3 moxen, tangled together, combining their mana energy.", "3 顆魔思力纏繞形成的集合體，魔力融為一體。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of 3 moxen, tangled together, combining their mana energy.", "3 顆魔思力纏繞形成的集合體，魔力融為一體。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maux", "王馬王可", Language.ChineseTraditional);
            RegisterCard("Maux", "王馬王可", "In all my years, I have NEVER seen an imitation cruder than this.", "我活了這麼多年，從沒見過比這更粗糙的仿品。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In all my years, I have NEVER seen an imitation cruder than this.", "我活了這麼多年，從沒見過比這更粗糙的仿品。", Language.ChineseTraditional);
            RegisterCard("Stim Mage", "激勵法師", "It strives to grow stronger, disregarding its own wellbeing..", "不顧自身安危，一心追求更強的力量……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strives to grow stronger, disregarding its own wellbeing..", "不顧自身安危，一心追求更強的力量……", Language.ChineseTraditional);
            RegisterCard("Gourmage", "美食法師", "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "貪吃的法師，吞食你陣亡同伴的屍體來增強自己……真噁心。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "貪吃的法師，吞食你陣亡同伴的屍體來增強自己……真噁心。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunce", "呆瓜法師", Language.ChineseTraditional);
            RegisterCard("Dunce", "呆瓜法師", "This one can never seem to hit its target..", "這傢伙似乎總是打不中目標……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to hit its target..", "這傢伙似乎總是打不中目標……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grootslang", "巨蟒", Language.ChineseTraditional);
            RegisterCard("Grootslang", "巨蟒", "The mere graze of its fangs is enough to kill any creature. No matter the size.", "只要被毒牙輕輕擦過，任何生物都會喪命，無論體型大小。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mere graze of its fangs is enough to kill any creature. No matter the size.", "只要被毒牙輕輕擦過，任何生物都會喪命，無論體型大小。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bookworm", "書蟲", Language.ChineseTraditional);
            RegisterCard("Bookworm", "書蟲", "A rare kind of insect that absorbs knowledge out of books.", "能從書本吸收知識的稀有昆蟲。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rare kind of insect that absorbs knowledge out of books.", "能從書本吸收知識的稀有昆蟲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "鍊金術士", Language.ChineseTraditional);
            RegisterCard("Alchemist", "鍊金術士", "A supporting one. It brews potions to empower your cards.", "擅長支援，調製魔藥來強化你的卡牌。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A supporting one. It brews potions to empower your cards.", "擅長支援，調製魔藥來強化你的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Mage", "鳴鐘法師", Language.ChineseTraditional);
            RegisterCard("Chime Mage", "鳴鐘法師", "Its chime can prove to be quite annoying..", "它的鈴聲可真夠煩人的……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its chime can prove to be quite annoying..", "它的鈴聲可真夠煩人的……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revivor", "復生者", Language.ChineseTraditional);
            RegisterCard("Revivor", "復生者", "It brings a mage back from the dead, at the cost of its own health.", "消耗自身生命力，將一名法師從死亡中喚回。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It brings a mage back from the dead, at the cost of its own health.", "消耗自身生命力，將一名法師從死亡中喚回。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune Mage", "符文法師", Language.ChineseTraditional);
            RegisterCard("Rune Mage", "符文法師", "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "被召喚時，在身旁變出爆炸符文。容我說一句，這不是好主意。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "被召喚時，在身旁變出爆炸符文。容我說一句，這不是好主意。", Language.ChineseTraditional);
            RegisterCard("--~~--~~--", "--~~--~~--", "So it arrives.", "於是，它來了。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it arrives.", "於是，它來了。", Language.ChineseTraditional);
            RegisterCard("~-~-~-~-~-~", "~-~-~-~-~-~", "I foresaw its arrival.", "我早已預見它的到來。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I foresaw its arrival.", "我早已預見它的到來。", Language.ChineseTraditional);
            RegisterCard("~~--~~--~~", "~~--~~--~~", "At last, it is here.", "終於，它來了。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, it is here.", "終於，它來了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Sage", "狙擊賢者", Language.ChineseTraditional);
            RegisterCard("Sniper Sage", "狙擊賢者", "A mage whose training allows it to cast spells from afar.", "經過訓練，能從遠處施放法術的法師。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage whose training allows it to cast spells from afar.", "經過訓練，能從遠處施放法術的法師。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune", "符文", Language.ChineseTraditional);
            RegisterCard("Rune", "符文", "This is the last call, for alcohol.", "酒水最後加點囉。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "酒水最後加點囉。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame", "魔焰", Language.ChineseTraditional);
            RegisterCard("Flame", "魔焰", "This is the last call, for alcohol.", "酒水最後加點囉。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "酒水最後加點囉。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbit", "兔子", Language.ChineseTraditional);
            RegisterCard("Rabbit", "兔子", "This is the last call, for alcohol.", "酒水最後加點囉。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "酒水最後加點囉。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for booze.", "烈酒最後加點囉。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for ale.", "麥酒最後加點囉。", Language.ChineseTraditional);
            RegisterCard("Master Goranj", "哥蘭吉大師", "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "高大威嚴的哥蘭吉大師。不僅精通可怕的魔法，架勢更是穩如磐石。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "高大威嚴的哥蘭吉大師。不僅精通可怕的魔法，架勢更是穩如磐石。", Language.ChineseTraditional);
            RegisterCard("Master Bleene", "布立尼大師", "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "無私的布立尼大師。危急時會向你伸出援手……代價是喪失自衛能力。令人敬佩。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "無私的布立尼大師。危急時會向你伸出援手……代價是喪失自衛能力。令人敬佩。", Language.ChineseTraditional);
            RegisterCard("Master Orlu", "歐魯大師", "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "偉大的歐魯大師，展開蒼白羽翼翱翔，從上方進攻，從下方抽取卡牌……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "偉大的歐魯大師，展開蒼白羽翼翱翔，從上方進攻，從下方抽取卡牌……", Language.ChineseTraditional);
            RegisterCard("Master Magnus", "偉大大師", "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "我的名字是……奶昔祖拉！麥克風霸主！老派狠角色！想找刺激？我就送到你面前……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "我的名字是……奶昔祖拉！麥克風霸主！老派狠角色！想找刺激？我就送到你面前……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus", "偉大大師", Language.ChineseTraditional);
            RegisterCard("Master Magnus", "偉大大師", "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "薯條洛克，沒錯，我最強，像警察一樣震得你慌。肉團子，接下來換你，來個敲門笑話響噹噹！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "薯條洛克，沒錯，我最強，像警察一樣震得你慌。肉團子，接下來換你，來個敲門笑話響噹噹！", Language.ChineseTraditional);
            RegisterCard("Master Magnus", "偉大大師", "Meatwad get the money, see. Meatwad get the honeys, G. ", "肉團子賺大錢，懂嗎？肉團子有妞陪，兄弟。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meatwad get the money, see. Meatwad get the honeys, G. ", "肉團子賺大錢，懂嗎？肉團子有妞陪，兄弟。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phoenix", "鳳凰", Language.ChineseTraditional);
            RegisterCard("Phoenix", "鳳凰", "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "威嚴的飛禽，據說曾與歐魯大師聯手……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "威嚴的飛禽，據說曾與歐魯大師聯手……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleenehound", "尋寶獵犬", Language.ChineseTraditional);
            RegisterCard("Bleenehound", "尋寶獵犬", "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "忠心的犬，據說曾是布立尼大師的忠實夥伴。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "忠心的犬，據說曾是布立尼大師的忠實夥伴。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemy 101", "鍊金術入門", Language.ChineseTraditional);
            RegisterCard("Alchemy 101", "鍊金術入門", "[c:g2]Alchemy 101[c:]\n[c:g3]I[c:] [c:g1]never[c:] [c:g3]was[c:] [c:g1]that[c:] [c:g3]great[c:] [c:g1]at[c:] [c:g3]alchemy..[c:]", "[c:g2]鍊金術入門[c:]\n[c:g3]我[c:][c:g1]一直[c:][c:g3]都不[c:][c:g1]怎麼[c:][c:g3]擅長[c:][c:g1]這門[c:][c:g3]鍊金術……[c:]");
