            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A terrible creature of the sea.. Posessing 3 strange and powerful appendages.", "可怕的海中生物……生有 3 條詭異而強大的肢體。", Language.ChineseTraditional);
