            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goobert", "黏柏特", Language.ChineseTraditional);
            RegisterCard("Goobert", "黏柏特", "A replica of my goo mage.. Its loyalty is only matched by its suffering.", "我的黏液法師複製體……其忠誠與痛苦同樣深重。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A replica of my goo mage.. Its loyalty is only matched by its suffering.", "我的黏液法師複製體……其忠誠與痛苦同樣深重。", Language.ChineseTraditional);
