            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angry Witch", "憤怒魔女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Angry Witch", "憤怒魔女", "The witch in charge of anger will ignite flames in the opposite battlefield.", "掌管憤怒的魔女，會在對方戰場點燃火焰。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of anger will ignite flames in the opposite battlefield.", "掌管憤怒的魔女，會在對方戰場點燃火焰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arrogant Witch", "傲慢魔女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Arrogant Witch", "傲慢魔女", "The witch who mastered the power of arrogance appeared with the demon.", "掌握傲慢之力的魔女，與惡魔一同現身。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who mastered the power of arrogance appeared with the demon.", "掌握傲慢之力的魔女，與惡魔一同現身。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Mage", "咖啡法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Coffee Mage", "咖啡法師", "Mages who love coffee use gems to regulate their breath.", "愛喝咖啡的法師，用寶石調息。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mages who love coffee use gems to regulate their breath.", "愛喝咖啡的法師，用寶石調息。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny MagiChiking", "有趣的魔法雞", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Funny MagiChiking", "有趣的魔法雞", "A smelly Rooster who has learned magic.", "學會魔法的臭公雞。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A smelly Rooster who has learned magic.", "學會魔法的臭公雞。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Witch", "暴食魔女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Gluttonous Witch", "暴食魔女", "The witch in charge of gluttony committed a terrible sin.", "掌管暴食的魔女，犯下了可怕的罪孽。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of gluttony committed a terrible sin.", "掌管暴食的魔女，犯下了可怕的罪孽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Witch", "貪婪魔女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Greedy Witch", "貪婪魔女", "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "掌管貪婪之力的魔女，可惜只有死後，才能為我們帶來價值。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "掌管貪婪之力的魔女，可惜只有死後，才能為我們帶來價值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inquisitive Witch", "強欲魔女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Inquisitive Witch", "強欲魔女", "Nothing is more powerful than her curiosity.", "沒有什麼比她的好奇心更強大。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is more powerful than her curiosity.", "沒有什麼比她的好奇心更強大。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jealous Witch", "嫉妒魔女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Jealous Witch", "嫉妒魔女", "The witch in charge of jealousy has powerful magic and power.", "掌管嫉妒的魔女，擁有強大的魔法與力量。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of jealousy has powerful magic and power.", "掌管嫉妒的魔女，擁有強大的魔法與力量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Witch", "怠惰魔女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Lazy Witch", "怠惰魔女", "The witch in charge of the power of laziness is really a lazy guy.", "掌控怠惰之力的魔女，真是個懶傢伙。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of the power of laziness is really a lazy guy.", "掌控怠惰之力的魔女，真是個懶傢伙。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "色慾魔女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Lust Witch", "色慾魔女", "The witch in charge of lust, don't look into her eyes.", "掌管色慾的魔女，別看她的眼睛。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "掌管色慾的魔女，別看她的眼睛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "九色鹿", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Nine Color Deer", "九色鹿", "The colorful nine color deer has precious value.", "繽紛的九色鹿，具有珍貴價值。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "繽紛的九色鹿，具有珍貴價值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "魔法臭雞丁", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Stinky MagiChiking", "魔法臭雞丁", "Hatched by magic eggs.", "由魔法蛋孵化而生。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hatched by magic eggs.", "由魔法蛋孵化而生。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Maniac", "炸彈狂人", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Bomb Maniac", "炸彈狂人", "Even if it detonates itself, it never surrenders to others.", "即使引爆自己，也絕不向他人屈服。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "即使引爆自己，也絕不向他人屈服。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earl Bunny", "兔子伯爵", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Earl Bunny", "兔子伯爵", "The versatile Earl Bunny, not everyone can comprehend this art.", "多才多藝的兔子伯爵，不是每個人都能理解這門藝術。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The versatile Earl Bunny, not everyone can comprehend this art.", "多才多藝的兔子伯爵，不是每個人都能理解這門藝術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "中國龍", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Chinese Loong", "中國龍", "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "潛入深淵，鎮守四海安寧；飛上天空，護佑萬物平安。神龍行過萬里，處處都是祥瑞。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "潛入深淵，鎮守四海安寧；飛上天空，護佑萬物平安。神龍行過萬里，處處都是祥瑞。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "乳酪巫師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Cheese Wizard", "乳酪巫師", "A humorous wizard who is proficient in cooking, his cheese has magical power.", "幽默又精通料理的巫師，他的乳酪帶有神奇魔力。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "幽默又精通料理的巫師，他的乳酪帶有神奇魔力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "冰霜魔像", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Frost Golem", "冰霜魔像", "Once on the field, there is a strong sense of oppression.", "一上場，就帶來強烈壓迫感。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "一上場，就帶來強烈壓迫感。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "棒球法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Baseball Mage", "棒球法師", "His soul is bound under sportswear and can never be liberated.", "他的靈魂被運動服束縛，永遠無法解脫。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "他的靈魂被運動服束縛，永遠無法解脫。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "突襲法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Raid Mage", "突襲法師", "You will understand how terrifying it is for a robber to master magic.", "你會明白，強盜學會魔法有多可怕。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "你會明白，強盜學會魔法有多可怕。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "翡翠魔龜", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Jade Turtle", "翡翠魔龜", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "從頭到腳裹滿綠寶石的烏龜——竟然還有這樣的畫，實在令人驚嘆。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "從頭到腳裹滿綠寶石的烏龜——竟然還有這樣的畫，實在令人驚嘆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Cheese", "魔法乳酪", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Magic Cheese", "魔法乳酪", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Cuckoo", "猩紅布穀鳥", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Scarlet Cuckoo", "猩紅布穀鳥", "The success or failure of the angry magic bird often depends on its face.", "憤怒的魔法鳥，成敗往往都得看牠臉色。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The success or failure of the angry magic bird often depends on its face.", "憤怒的魔法鳥，成敗往往都得看牠臉色。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apprentice", "長矛學徒", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Spear Apprentice", "長矛學徒", "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "長矛法師的學徒。聰明人總會留一手，做好準備。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "長矛法師的學徒。聰明人總會留一手，做好準備。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "黑暗之眼", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("The Eye of Darkness", "黑暗之眼", "This precious pearl was once the devil's eye.", "這顆珍貴的珍珠，曾是魔鬼的眼睛。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This precious pearl was once the devil's eye.", "這顆珍貴的珍珠，曾是魔鬼的眼睛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Spell", "森林法術", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Forest Spell", "森林法術", "The forest spell obtained from Leshy can provide the most primitive defense.", "從雷希那裡獲得的森林法術，能提供最原始的防禦。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forest spell obtained from Leshy can provide the most primitive defense.", "從雷希那裡獲得的森林法術，能提供最原始的防禦。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "魔思力魔盾", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("MoxShield", "魔思力魔盾", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "鑲滿寶石的魔法盾牌，只要在場就讓人安心。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "鑲滿寶石的魔法盾牌，只要在場就讓人安心。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "星雲風暴", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Nebula Storm", "星雲風暴", "This cruel storm can directly take away an enemy.", "這場殘酷的風暴，能直接帶走一個敵人。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cruel storm can directly take away an enemy.", "這場殘酷的風暴，能直接帶走一個敵人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Contract", "靈魂契約", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Soul Contract", "靈魂契約", "Perhaps you need more card assistance, and a soul contract is a great choice.", "也許你需要更多卡牌幫忙，靈魂契約是不錯的選擇。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "也許你需要更多卡牌幫忙，靈魂契約是不錯的選擇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "慟哭之牆", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Wailing Wall", "慟哭之牆", "Such perseverance even moves the thorny walls to weep.", "這份毅力，連荊棘之牆都感動得落淚。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "這份毅力，連荊棘之牆都感動得落淚。", Language.ChineseTraditional);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "咖啡時間", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Coffee Time", "咖啡時間");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "[creature] 第一次受到傷害時，獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "傲慢之死", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Death of Arrogance", "傲慢之死");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "[creature] 死亡時，相鄰卡牌獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "貪婪之死", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Death of Greed", "貪婪之死");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "[creature] 死亡時，相鄰卡牌獲得 3 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "上帝生物", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("God Made", "上帝生物");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "打出 [creature] 時，每個相鄰的空位都會生成人造人。人造人具有：1 點攻擊力、1 點生命力，以及使魔印記。", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Fir Caller", "喚林者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "[creature] 死亡時，擁有者這一側的空位會被大冷杉填滿。大冷杉具有：0 點攻擊力、3 點生命力，以及奮力跳躍印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "回味無窮", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Lingering Taste", "回味無窮");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "[creature] 死亡時，相鄰卡牌獲得 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "乳酪熱愛", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Love of Cheese", "乳酪熱愛");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "打出 [creature] 時，抽一張乳酪卡牌。乳酪具有：0 點攻擊力、2 點生命力，以及回味無窮印記。", Language.ChineseTraditional);
            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Expansion", "魔法擴充包", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here comes the card of the fantasy world! More content will be added in the future!", "奇幻世界的卡牌來了！未來還會新增更多內容！", Language.ChineseTraditional);
        }
    }
    public class NevernamedsSigilariumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NevernamedsSigilarium Mod");
            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NevernamedsSigils", "無名者的印記", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pliers", "鉗子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scissors", "剪刀", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleach", "漂白劑", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skinning Knife", "剝皮小刀", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Hook", "魚鉤", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "死者之手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harpie's Birdleg Fan", "鳥身女妖的鳥腳扇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hoggy Bank", "小豬撲滿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Extra Battery", "額外電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield Generator", "護盾產生器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wiseclock", "順向鐘錶", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mrs Bombs Remote", "炸彈夫人的遙控器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hourglass", "沙漏", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magpies Glass", "喜鵲的放大鏡", Language.ChineseTraditional);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wriggling Pereiopod", "蠕動步足", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wormy Tail", "蟲蛀尾巴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Web", "網", Language.ChineseTraditional);
