            // Opponent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadowy Figure", "朦朧身影", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angler", "釣魚人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trader", "毛皮商", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapper", "獵人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy", "雷希", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificus", "麥尼菲庫斯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimora", "葛麗摩菈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer", "索耶", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee", "凱茜", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal", "羅耀", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Training Dummy", "訓練假人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goobert", "黏柏特", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pike Mage", "長矛法師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonely Wizard", "孤獨巫師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspector", "探長", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Melter", "熔解人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dredger", "挖泥工", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prospector", "礦工", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angler", "釣魚人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapper", "獵人", Language.ChineseTraditional);

            // ShowUntilInput
            Dictionary<GemType, string> gemTypesEn = new Dictionary<GemType, string>
            {
                { GemType.Orange, "橘色" },
                { GemType.Blue, "藍色" },
                { GemType.Green, "綠色" },
            };
            Dictionary<GemType, string> gemTypes = new Dictionary<GemType, string>
            {
                { GemType.Orange, "橘" },
                { GemType.Blue, "藍" },
                { GemType.Green, "綠" },
            };
            foreach (var gemType in gemTypes.Keys)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have the two " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "[c:] Gems needed to play that. Gain Gems by playing Mox cards.", "你沒有打出這張牌所需的兩顆" + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "[c:]寶石。打出魔思力卡牌可以獲得寶石。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gem skeptic sigil prevents you from playing that gem.", "寶石質疑者印記阻止你打出那顆寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play that until you're 3 off dying.", "再受 3 點或更少傷害就會敗北時，才能打出那張牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You want to play that? Start losing.", "想打出那張牌？先吃點虧吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play it, genius.", "天才，這張牌不能打出。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot play that card with the scales in this state.", "天平處於這種狀態時，你無法打出那張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play that one.", "你不能打出那張牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm afraid that one's forbidden, dear.", "親愛的，恐怕這張牌是禁用的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't allow you to play that card.", "我不允許你打出那張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play a gem card while a creature with the Gem Skeptic sigil is on your side of the board!", "你這一側的檯面上有帶著寶石質疑者印記的生物時，就無法打出寶石卡牌！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card cannot be played unless you are three or less damage from losing!", "再受三點或更少傷害就會敗北時，才能打出這張卡牌！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card cannot be played.", "這張卡牌無法打出。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides...", "兩邊都擋住了……", Language.ChineseTraditional);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absorber", "吸收者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a creature adjacent to [creature] is struck, [creature] will gain health equal to the amount of damage dealt.", "與 [creature] 相鄰的生物受到攻擊時，[creature] 獲得等同於該生物所受傷害的生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack unless forced to attack by another effect.", "[creature] 不會攻擊，除非受到其他效果強制攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trinket Bearer", "道具攜帶者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it grants it's owner a random item.", "打出 [creature] 時，擁有者獲得一件隨機道具。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] pulls out a random item.", "[creature] 掏出了一件隨機道具。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbait", "血之餌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood to return [creature] to your hand.", "支付 1 點鮮血，將 [creature] 返回你的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonefed", "骨飼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to heal [creature] for up to 3 health.", "支付 2 根骨頭，為 [creature] 恢復最多 3 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Strike", "骨驅打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to deal 1 damage to the creature opposing [creature].", "支付 2 根骨頭，對 [creature] 正對面的生物造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broodfeast", "盛宴之巢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 1 blood to create a copy of [creature] in your hand.", "每回合限一次，支付 1 點鮮血，在你的手牌中生成一張 [creature] 的複製品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnivore", "食肉動物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 blood to increase the power of [creature] by 3.", "支付 2 點鮮血，使 [creature] 的攻擊力增加 3。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Causality", "因果關係", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 currency to trigger a random effect.", "支付 1 點貨幣，觸發一種隨機效果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The universe seems in harmony already... nothing changes.", "宇宙似乎已經和諧……什麼也沒改變。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing happened...", "什麼事也沒發生……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing? Huh, that's disappointing.", "沒效果？哼，真掃興。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power buff, lucky you...", "攻擊力增益，算你走運……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Health buff, could be a lot better...", "生命力增益，還可以更好吧……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have dealt me a blow...", "你給了我一記重擊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dealt one direct damage!", "你造成了一點直接傷害！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess playing a perfect game is no match for pay to win mechanics.", "看來完美操作，也敵不過花錢就能贏的機制。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadbeat", "精力耗盡", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a creature on the same side of the board. That creature will perish.", "選擇檯面上同一側的一隻生物。該生物死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deck Drain", "牌組汲取", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Up to 3 times per turn, pay 1 blood to draw a random card from your deck.", "每回合最多 3 次，支付 1 點鮮血，從你的牌組抽取一張隨機卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dredge", "疏浚囤積", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to search your deck for any card, and add it to your hand.", "支付 4 根骨頭，從你的牌組搜尋任意一張卡牌，加入你的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Escape", "逃脫", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have a green gem, return [creature] to your hand.", "若你擁有綠色寶石，將 [creature] 返回你的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eternal Gallop", "永恆疾馳", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move [creature] in the direction inscribed on the sigil.", "讓 [creature] 沿印記標示的方向移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exalted Rune", "崇高符文", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood to create a 'Mox Pillar' in your hand. A mox pillar is defined as: 0 power, 4 health, Mox Sigil, Mighty Leap.", "支付 1 點鮮血，在你的手牌中生成一張「魔思力石柱」。魔思力石柱具有：0 點攻擊力、4 點生命力、魔思力印記，以及奮力跳躍印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fair Trade", "公平交易", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 pelt to remove an opponent's creature from the board, and add it to your hand.", "支付 1 張毛皮，將對手的一隻生物從檯面移除，加入你的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fetch", "骨驅衝刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to make [creature] move in the direction inscribed in the sigil.", "支付 1 根骨頭，讓 [creature] 沿印記標示的方向移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flip", "賭博按鈕", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "50/50 chance to either kill [creature] or give it +1 power and health.", "50/50 的機率：消滅 [creature]，或使其攻擊力與生命力各 +1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorge", "暴食", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] has less than 10 health, pay 1 blood to grant it +3 health.", "若 [creature] 的生命力低於 10，支付 1 點鮮血，使其生命力 +3。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You spent the last of your foils!.", "你花光最後的碎箔了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have 0 foil remaining.", "你還剩 0 片碎箔。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have 1 foil remaining.", "你還剩 1 片碎箔。", Language.ChineseTraditional);
            for (int currency = 2; currency <= 100; currency++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have " + currency + " foils remaining.", "你還剩" + currency + "張碎箔。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough teeth.", "你的牙齒不夠。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need more teeth to use that ability.", "你需要更多牙齒，才能使用那個能力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot pay the cost", "你付不起這筆費用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you deaf? Get more Robobucks.", "你聾了嗎？去多弄點機器幣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not running a charity, get more money.", "我可不是開慈善機構的，多帶點錢來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No robobucks, no sigil.", "沒有機器幣，就別想用印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No dice.", "沒門。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.", "嗯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough teeth to pay the cost.", "你的牙齒不足以支付費用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll need to perform better in battle if you wish to use that ability.", "想使用那個能力，你就得在戰鬥中表現得更好。", Language.ChineseTraditional);
            for (int currency = 0; currency <= 100; currency++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You require more foils to use this ability! You have " + currency + " foils.", "使用此能力需要更多碎箔！你目前有" + currency + "張碎箔。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh.", "唉。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need more Robobucks to use that sigil, and I don't give credit.", "想用那個印記，就得多帶點機器幣。我可不賒帳。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back when you're a little... mmm... richer.", "等你再……嗯……有錢一點再來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picky Eater", "挑食者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood to draw bones equal to the health of the sacrificed creature.", "支付 1 點鮮血，獲得等同於被犧牲生物生命力的骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Punching Bag", "沙包", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, choose any creature. That creature will strike this card for 1 damage. Afterwards, this card regains 1 health.", "每回合限一次，選擇任意一隻生物。該生物會攻擊這張卡牌，造成 1 點傷害。之後，這張卡牌恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remove", "移除按鈕", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill [creature].", "消滅 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharpen", "磨礪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have an orange mox gem, sacrifice it to give [creature] +1 attack power.", "若你擁有橘色魔思力寶石，犧牲它，使 [creature] 的攻擊力 +1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] sacrifices an orange gem to sharpen it's attack!", "[creature] 犧牲橘色寶石，磨礪自身的攻擊！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spellsword", "咒術之劍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All gems on the same side of the board as[creature] gain 2 power, attack, and perish.", "檯面上與 [creature] 同側的所有寶石都獲得 2 點攻擊力，發動攻擊，然後死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trained Flier", "飛行能手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grant [creature] the effect of the Airborne sigil until next upkeep. If the card already has Airborne, this will remove it's effect until next upkeep.", "讓 [creature] 獲得飛空印記的效果，直到下次維持階段。若該卡牌已有飛空，則改為移除該效果，直到下次維持階段。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trained Swimmer", "游泳能手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature will gain the effect of the Waterborne sigil for one turn.", "該生物獲得水生印記的效果，持續一回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upgrade Subroutine", "升級子程式", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] destroys another bot, this gains 1 point. When activated, the owner is presented with a choice of three sigils to permanently augment the card. Selecting a sigil spends points, and the more points accumulated when the sigil is activated, the higher quality the presented sigils will be.", "[creature] 摧毀另一個機器人時，獲得 1 點升級點數。啟用時，擁有者可從三種印記中選擇一種，永久強化這張卡牌。選擇印記會消耗點數；啟用印記時累積的點數越多，提供的印記品質就越高。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aculeate Grip", "螫刺之握", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played on the same side of the board as [creature], [creature] will move towards them as far as possible, dealing them one damage and increasing it's own health by 1.", "有生物在與 [creature] 同側的檯面上被打出時，[creature] 會盡可能向它靠近，對它造成一點傷害，並使自身生命力增加 1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allure", "媚骨天生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the round, [creature] will draw opposing creatures in front of itself.", "玩家的回合開始時，[creature] 會將對方生物吸引到自己正前方。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annihilation", "湮滅", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all creatures on the board are dealt 10 damage.", "[creature] 死亡時，檯面上所有生物都受到 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Guardian", "螞蟻守護者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal damage equal to it's attack power to any card which strikes a friendly ant.", "有卡牌攻擊友方螞蟻時，[creature] 對該卡牌造成等同於自身攻擊力的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antimagic", "反魔法", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any mox gems played while [creature] is on the board will immediately perish. [creature] will move to the position of the destroyed gem, gain 1 health, and immediately attack.", "[creature] 在檯面上時，任何被打出的魔思力寶石都會立即死亡。[creature] 會移動到被摧毀的寶石所在位置，獲得 1 點生命力，並立刻攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] destroys the played gem!", "[creature] 摧毀了打出的寶石！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armortify", "裝甲化", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card gains the armored sigil.", "[creature] 攻擊對面的生物並使其死亡時，這張卡牌獲得身穿裝甲印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artistic License", "藝術許可", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the creature opposing it loses all sigils.", "打出 [creature] 時，對面的生物失去所有印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trying to plunder me sigils? Yer a sour spoilsport!", "想搶老子的印記？你這掃興的混帳！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite your artistry, the soul of the moon is impervious...", "縱使你的技藝再精湛，月之魂仍無法撼動……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backup", "資料備份", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, the first card in it's owner's hand is played in it's place.", "[creature] 因戰鬥死亡時，擁有者手牌中的第一張卡牌會被打出到它的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls in backup.", "[creature] 呼叫後援。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandage Weaver", "繃帶編織者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn,[creature] will heal the cards to it's left and right for 1 health.", "回合結束時，[creature] 為左右兩側的卡牌各恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bastion", "堡壘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] recieves damage, it only takes half the damage it normally would, rounded up.", "[creature] 受到傷害時，只承受原本傷害的一半，向上取整。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Batch Delete", "批次刪除", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature and it perishes, any creatures on the board which share the same cost as the target perish also.", "[creature] 攻擊一隻生物並使其死亡時，檯面上與該目標費用相同的生物也都會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] shreds any other cards with the same cost as it's victim...", "[creature] 粉碎了所有與受害者費用相同的其他卡牌……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bejeweled", "寶石迷陣", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the field, lining up three gems of the same colour will remove those gems from the field. Any creatures which opposed those gems will be removed as well, and the opponent will take damage directly equal to their combined attack power. ", "[creature] 在場上時，將三顆同色寶石排成一線，就會將它們移出場外。與那些寶石正對的生物也會被移除，對手受到等同於這些生物攻擊力總和的直接傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bewilder", "撲朔迷離", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose any creature. Swap that creatures power and health.", "打出 [creature] 時，擁有者可以選擇任意一隻生物，交換該生物的攻擊力與生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bifurcated When Gempowered", "橘色兵分", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If its owner has an Orange Gem, [creature] will strike each opposing space to the left and right of the space across from it.", "若擁有者擁有橘色寶石，[creature] 會攻擊正對面位置的左右兩側。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bisection", "二分法", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, two copies of the victim are created in the owner's hand with zero power and halved health.", "[creature] 擊殺另一隻生物時，在擁有者的手牌中生成兩張該生物的複製品，攻擊力為零，生命力減半。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleach", "漂白劑", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opponent creatures lose all sigils.", "打出 [creature] 時，所有對方生物失去所有印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloated", "肥美多汁", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is worth blood equal to its health when sacrificed.", "[creature] 被犧牲時，提供等同於自身生命力的鮮血。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Artist", "鮮血藝術家", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every three cards which perish by combat while [creature] is on the board, [creature] will give it's owner a deathcard constructed from the cost, stats, and sigils of those creatures.", "[creature] 在檯面上時，每有三張卡牌因戰鬥死亡，[creature] 就會給予擁有者一張死亡卡，由這些生物的費用、屬性和印記組成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] constructs a deathcard from previous creatures deaths...", "[creature] 以先前死去的生物製作死亡卡……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it transforms to or from it's alternate form instead of perishing.", "[creature] 被犧牲時，會在原本與另一種形態之間切換，而不會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Dependent", "鮮血依賴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] does not strike another creature during the attack phase, it will perish at the start of the owner's next turn.", "若 [creature] 在攻擊階段未攻擊到其他生物，就會在擁有者下個回合開始時死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood From Stone", "石中取血", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may sacrifice terrain cards in order to play [creature].", "你可以犧牲地形卡牌來打出 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Gusher", "鮮血噴湧", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card, as well as creatures to the left and right of this card, gain 1 health.", "[creature] 攻擊對面的生物並使其死亡時，這張卡牌與左右兩側的生物各獲得 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "嗜血者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] deals damage to a creature, it gains 1 Health for each damage dealt.", "[creature] 對生物造成傷害時，每造成一點傷害，自身就獲得 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] consumes the blood of its prey!", "[creature] 吸食獵物的鮮血！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Magic", "血魔法", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the field, its owner may sacrifice any gems, even if those gems normally cannot be sacrificed.", "[creature] 在場上時，擁有者可以犧牲任何寶石，即使那些寶石原本無法被犧牲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodrunner", "血行者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage to a creature, it will move in the direction inscribed in the sigil.", "[creature] 對生物造成傷害時，會沿印記標示的方向移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Inspiration", "藍色靈感", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost a blue gem will gain a random sigil when played.", "[creature] 在檯面上時，所有費用包含藍色寶石的友方生物，在被打出時獲得一個隨機印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] empowers the Blue Gem cost creature with a random sigil!", "[creature] 為費用包含藍色寶石的生物賦予隨機印記！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombjuration", "爆彈咒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose an empty slot on either side of the board. A magic bomb is created in the chosen slot.", "打出 [creature] 時，擁有者可以選擇檯面任意一側的一個空位，在該位置生成魔法炸彈。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombs Away", "炸彈空投", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Payload is created in the opposing slot. [define:SigilNevernamed Payload]", "打出 [creature] 時，對面卡槽會生成酬載。[define:SigilNevernamed Payload]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] drops a payload into the opposing slot!", "[creature] 向對面卡槽空投酬載！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Dependent", "骨頭依賴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the user has 0 Bones, [creature] will perish.", "若使用者擁有 0 根骨頭，[creature] 就會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Duke", "骨公爵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 3 Bones are awarded instead of 1.", "[creature] 死亡時，獲得 3 根骨頭，而非 1 根。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelust", "骨慾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it generates 3 bones for its owner.", "[creature] 擊殺另一隻生物時，為擁有者生成 3 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Spurs", "骨刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it generates a bone for it's owner.", "[creature] 受到攻擊時，為擁有者生成一根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will target the least powerful opposing card when it attacks.", "[creature] 攻擊時，會以攻擊力最低的敵方卡牌為目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning", "燃燒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] takes 1 damage. Also, when [creature] is struck, the striker gains this sigil.", "擁有者的回合結束時，[creature] 受到 1 點傷害。此外，[creature] 受到攻擊時，攻擊者獲得此印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buzz Off", "蜉蝣衝擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and leave a mayfly in it's old place. A mayfly is defined as 1 power, 1 health, airborne, brittle.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動，並在原位留下一隻蜉蝣。蜉蝣具有：1 點攻擊力、1 點生命力、飛空印記，以及脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Call To Arms", "號召行動", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the creatures to it's left and right will immediately attack.", "打出 [creature] 時，左右兩側的生物會立刻攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Shedder", "卡牌脫落者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and leave a card in it's wake.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動，並在身後留下一張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caustic", "物腐毒生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it's killer perishes as well.", "[creature] 死亡時，擊殺它的生物也會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Center Strike", "中心打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack all opponent slots except for those in the leftmost and rightmost lanes.", "[creature] 會攻擊對手的所有卡槽，但最左與最右的路線除外。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Strike", "混沌打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random strike modifier sigil.", "抽到 [creature] 時，此印記會被替換為隨機一個改變攻擊方式的印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheater", "作弊者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, the opponent is dealt 1 damage.", "[creature] 攻擊對面的生物並使其死亡時，對手受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Maker", "電路繪製", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a conduit card is created to its left and right.", "打出 [creature] 時，左右兩側各生成一張導管卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Claw", "利爪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will lose all attack power if it is not directly adjacent to a card bearing the clawed sigil.", "若 [creature] 未與帶有利喙尖爪印記的卡牌直接相鄰，就會失去全部攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawed", "利喙尖爪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, claws are created to the left and right. Any creatures in those spaces will be killed.", "打出 [creature] 時，左右兩側會生成利爪。原本位於那些位置的生物都會被消滅。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawing Hand", "利爪之手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt damage equal to the number of cards in the owner's hand.", "[creature] 受到攻擊時，攻擊者受到等同於擁有者手牌數量的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleaving", "劈裂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes another creature, that creature will be cut in half. Half of the creature will move to the right, while the other half remains in place.", "[creature] 攻擊另一隻生物時，會將它劈成兩半。一半往右移動，另一半留在原位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cleaves it's target in half!", "[creature] 將目標劈成兩半！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coastguard", "海岸警衛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerges during the opponent's turn. When an opposing creature is placed opposite to an empty space, [creature] will move to that empty space while submerged.", "對手的回合期間潛入水下。敵方生物被放置到一個空位的正對面時，[creature] 會在潛水狀態下移動到該空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collateral Damage", "連帶傷害", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if [creature] is on the board, the nearest creature to this card will be dealt ten damage.", "擁有者的回合結束時，若 [creature] 在檯面上，距離這張卡牌最近的生物受到十點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collector", "收藏家", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will move in the direction inscribed on the sigil. Creatures in the way will be returned to the owner's hand.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動。擋路的生物會返回擁有者的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Commander", "指揮官", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the creatures to it's left and right will attack the striker.", "[creature] 受到攻擊時，左右兩側的生物會攻擊攻擊者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Strike When Powered", "充能雙擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit, it will strike the opposing space an additional time when it attacks.", "若 [creature] 在電路內，攻擊時會額外攻擊正對面的位置一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gift When Powered", "電流贈禮", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit when it perishes, a random card is created in your hand.", "若 [creature] 死亡時位於電路內，你的手牌中會生成一張隨機卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morsel When Powered", "充能一口點心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] is sacrificed while inside a completed circuit, ⁣it adds its stat values to the card it was sacrificed for.", "[creature] 在完整電路內被犧牲時，會將自身屬性值加到以它作為犧牲而打出的卡牌上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omnipotent When Powered", "充能全向打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit, it will strike every opposing space containing a card when it attacks. [creature] will strike directly if no creatures oppose it, or if it is not in a circuit.", "若 [creature] 在電路內，攻擊時會攻擊對面所有放有卡牌的位置。若沒有生物與它對峙，或它不在電路內，[creature] 就會直接攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered Quills", "充能鋒利之刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck while inside a completed circuit, the striker is dealt 2 damage.", "[creature] 在完整電路內受到攻擊時，攻擊者受到 2 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Print When Powered", "充能列印", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is inside a completed circuit, a gem will be created in its owners hand at the start of their turn.", "若 [creature] 在完整電路內，擁有者的回合開始時，其手牌中會生成一顆寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] prints a mox gem for its owner!", "[creature] 為擁有者印出一顆魔思力寶石！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repulsive When Powered", "充能排斥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is within a conduit, if another creature would strike it, it does not.", "[creature] 在電路內時，其他生物若要攻擊它，就會停止攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scavenge When Powered", "充能拾荒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is inside a completed circuit, opposing creatures also grant Bones upon death.", "[creature] 在完整電路內時，對方生物死亡也會提供骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splash Damage When Powered", "充能濺射傷害", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is within a conduit when it strikes a slot, creatures to the left and right of the struck slot will be dealt 1 damage.", "[creature] 在電路內攻擊一個卡槽時，該卡槽左右兩側的生物各受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulate When Powered", "充能激發", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is inside a completed circuit, it gains 2 health at the start of its owners turn.", "[creature] 在完整電路內時，擁有者的回合開始時，其生命力增加 2。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] stimulates its health!", "[creature] 激發了自身生命力！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Billowing Bond", "飛空契約", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures within a bond completed by [creature] gain the power of flight at the start of each turn.", "由 [creature] 締結的契約範圍內，生物會在每個回合開始時獲得飛行能力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Conduit", "寶石骷髏導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature within a circuit completed by [creature] perishes, a Gem Skeleton will be created in it's place.", "由 [creature] 接通的電路內，有生物死亡時，會在原位生成一隻寶石骷髏。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls forth a Gem Skeleton with the old magics!", "[creature] 以古老魔法喚出寶石骷髏！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Conduit", "綠寶石導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, its owner gains a green gem.", "若 [creature] 參與接通完整電路，擁有者獲得一顆綠色寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] completes a circuit, and grants its owner a green gem!", "[creature] 接通了電路，給予擁有者一顆綠色寶石！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] no longer completes a circuit, and no longer grants a green gem!", "[creature] 不再接通電路，也不再提供綠色寶石！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Friendship Bond", "友誼契約", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a bond completed by [creature] spawn Squirrels at the end of the owner's turn.", "擁有者的回合結束時，由 [creature] 締結的契約範圍內，空位會生成松鼠。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave Conduit", "掘骨導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completes a circuit. At the end of the owner's turn, [creature] will generate one bone for each creature contained within the circuit it completes.", "接通電路。擁有者的回合結束時，[creature] 會為自己接通的電路內的每隻生物，生成一根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] grants a bone for every creature in it's circuit.", "[creature] 為自身電路內的每隻生物提供一根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gun Conduit", "哨兵導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the slot opposing a card in a circuit completed by [creature], the moved creature is dealt 1 damage.", "有生物移動到由 [creature] 接通的電路內某張卡牌的對面卡槽時，該移動生物受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes a free shot!", "[creature] 趁機開了一槍！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hot Conduit", "灼熱導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature within a circuit completed by [creature] is struck, the striker gains the Burning Sigil. Also, creatures within this card's circuit do not take damage from the Burning sigil.", "由 [creature] 接通的電路內，有生物受到攻擊時，攻擊者獲得燃燒印記。此外，這張卡牌的電路內的生物不會受到燃燒印記的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot Conduit", "劫掠導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completes a circuit. At the start of the owner's turn, [creature] will draw 1 card to the owners hand for every empty space in the circuit it completes.", "接通電路。擁有者的回合開始時，[creature] 會為自己接通的電路內的每個空位，抽 1 張卡牌加入擁有者的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] draws a card for every empty space in it's circuit!", "[creature] 為自身電路內的每個空位抽一張卡牌！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malfunctioning Conduit", "故障導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completes a circuit. At the end of its owner's turn, random cards from its owners hand will be played in random spaces inside of the circuit completed by [creature]. Those cards gain the Burning Sigil.", "接通電路。擁有者的回合結束時，會將擁有者手牌中的隨機卡牌，打出到由 [creature] 接通的電路內的隨機位置。那些卡牌獲得燃燒印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] draws cards into it's circuit!", "[creature] 將卡牌拉進自身電路！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meaningless Bond", "空無契約", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may complete a bond, but provides no additional effect.", "[creature] 能締結契約，但不提供額外效果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nano Conduit", "奈米導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owners turn, creatures within a circuit completed by [creature] gain the Armored sigil.", "擁有者的回合結束時，由 [creature] 接通的電路內的生物獲得身穿裝甲印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] shields all creatures in its circuit!", "[creature] 為自身電路內的所有生物提供護盾！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Conduit", "紅寶石導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, its owner gains an orange gem.", "若 [creature] 參與接通完整電路，擁有者獲得一顆橘色寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] completes a circuit, and grants its owner an orange gem!", "[creature] 接通了電路，給予擁有者一顆橘色寶石！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] no longer completes a circuit, and no longer grants an orange gem!", "[creature] 不再接通電路，也不再提供橘色寶石！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Conduit", "藍寶石導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, its owner gains a blue gem.", "若 [creature] 參與接通完整電路，擁有者獲得一顆藍色寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] completes a circuit, and grants its owner a blue gem!", "[creature] 接通了電路，給予擁有者一顆藍色寶石！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] no longer completes a circuit, and no longer grants a blue gem!", "[creature] 不再接通電路，也不再提供藍色寶石！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stim Conduit", "激勵導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owners turn, creatures within a circuit completed by [creature] gain 1 Health.", "擁有者的回合結束時，由 [creature] 接通的電路內的生物各獲得 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] increases the health of every creature in it's circuit!", "[creature] 提升了自身電路內每隻生物的生命力！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tender Bond", "溫柔契約", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures within a bond completed by [creature] heal to full health at the start of the owner's turn.", "擁有者的回合開始時，由 [creature] 締結的契約範圍內的生物恢復全部生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Conduit", "尖刺導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature within a circuit completed by [creature] is struck, the striker is then dealt a single damage point.", "由 [creature] 接通的電路內，有生物受到攻擊時，攻擊者隨後受到一點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Confusion", "顛三倒四", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played opposite an opponents creature, swap that creatures power and health.", "[creature] 被打出到敵方生物正對面時，交換該敵方生物的攻擊力與生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card opposing [creature] is confused!", "[creature] 對面的卡牌陷入混亂！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copier", "影印設備", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a copy of it's murderer is created in your hand.", "[creature] 死亡時，你的手牌中會生成一張擊殺者的複製品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coward", "貪生怕死", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is targeted, it will leap out of the way.", "[creature] 成為目標時，會跳開躲避。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Strike Left", "偏左打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack the space to the left of it's intended target.", "[creature] 會攻擊原定目標左側的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Strike Right", "偏右打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack the space to the right of it's intended target.", "[creature] 會攻擊原定目標右側的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crossbones", "十字骨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it grants 2 bones to it's owner.", "打出 [creature] 時，擁有者獲得 2 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crunchy", "酥脆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it generates one bone for its owner.", "[creature] 被犧牲時，為擁有者生成一根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cute", "可愛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures that strike [creature] feel guilty, and will skip their next strike.", "攻擊 [creature] 的生物會感到內疚，並跳過自己的下一次攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Data Breach", "資料外洩", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner must draw a card from their deck and immediately discard it. The opponent is dealt damage equal to the drawn creatures attack power.", "[creature] 死亡時，擁有者必須從牌組抽一張卡牌，並立即棄置。對手受到等同於抽到的生物攻擊力的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadringer", "死鈴使者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive and on the board, it gains +1 power each time the bell is rung, if it has less than 5 power.", "[creature] 存活且在檯面上時，每次敲鈴，若其攻擊力低於 5，就獲得 +1 攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] powers up!", "[creature] 的攻擊力提升了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Snatch", "死亡掠奪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card from your deck.", "[creature] 死亡時，從你的牌組抽一張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decked Out", "全副武裝", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a card from a random temple's side deck is created in your hand.", "[creature] 受到攻擊時，會在你的手牌中生成一張來自隨機神廟副牌組的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "汙染者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner must draw a card from their deck and immediately discard it.", "[creature] 死亡時，擁有者必須從牌組抽一張卡牌，並立即棄置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperate", "孤注一擲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it deals one point of damage to the opponent.", "[creature] 死亡時，對對手造成一點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals a free point of damage as it perishes.", "[creature] 在死亡時額外造成一點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deus Hoof", "鹿神敬拜", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All friendly hooved creatures gain +1 Power and Health while [creature] is on the board. Also, all hooved creatures will attack anything that strikes [creature].", "[creature] 在檯面上時，所有友方有蹄類生物的攻擊力與生命力各 +1。此外，任何攻擊 [creature] 的目標，都會受到所有有蹄類生物的攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dexter Strike", "右前打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will also strike the slot to the right of the opposing slot when it attacks.", "[creature] 攻擊時，也會攻擊正對面卡槽右側的卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diagonal Strike", "對角打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, it will strike either to the left or right of its original target, prioritising striking slots containing creatures. If both or neither slots adjacent to the target contain creatures, [creature] will attack to the left or right at random.", "[creature] 攻擊時，會攻擊原定目標左側或右側的卡槽，優先選擇有生物的卡槽。若目標兩側都有生物，或兩側都沒有，[creature] 會隨機攻擊左側或右側。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disembowel", "開膛破肚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, an amount of guts equal to its remaining health are created in its owners hand.", "[creature] 被犧牲時，在擁有者的手牌中生成等同於其剩餘生命力數量的內臟。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s guts explode into your hands.", "[creature] 的內臟爆散到你的手中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Distraction", "魂不守舍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a distraction is left in its place and [creature] moves to the right.", "[creature] 即將受到攻擊時，會在原位留下誘餌，而 [creature] 向右移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diver", "潛行者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can strike the opposing card even while it is submerged.", "[creature] 即使面對潛水中的卡牌，也能攻擊它。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next card drawn while [creature] is alive and on the board will be duplicated.", "[creature] 存活且在檯面上時，下一張抽到的卡牌會被複製。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Divisibility Strike", "奇偶交替打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, [creature] will alternate between striking all odd indexed opponent slots, and all even indexed opponent slots.", "擁有者的回合結束時，[creature] 會在「攻擊所有奇數編號的對手卡槽」與「攻擊所有偶數編號的對手卡槽」之間切換。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Docile", "溫順", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will wait a set number of turns in between being allowed to attack.", "[creature] 每次攻擊後，必須等待固定回合數才能再次攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doomed", "命定者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will perish.", "回合結束時，[creature] 死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Tap", "協同攻擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly creature strikes an opponent creature, [creature] will also attack that opponent creature.", "友方生物攻擊敵方生物時，[creature] 也會攻擊該敵方生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] aids its comrades in battle!", "[creature] 在戰鬥中支援同伴！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Downdraft", "下沉氣流", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant the power of flight to creatures to it's left and right.", "[creature] 賦予左右兩側的生物飛行能力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw", "繪牌之手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its owner draws cards equal to the number inscribed on this sigil.", "打出 [creature] 時，擁有者抽取等同於此印記所示數字的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dripping", "流連", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and leave part of it's own body in it's wake.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動，並在身後留下自身的一部分軀體。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drop", "得手投棄", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If[creature] is drawn as part of your opening hand, it will be automatically played on a random board space for free.", "若 [creature] 被抽為起始手牌的一部分，就會自動免費打出到檯面上的隨機位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may search your deck for any card and create a duplicate of it in your hand.", "打出 [creature] 時，你可以從牌組搜尋任意卡牌，在手牌中生成一張複製品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Duppelgang", "雙重奏", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw copies of cards adjacent to it from your deck to your hand.", "打出 [creature] 時，從你的牌組抽取與其相鄰卡牌同名的卡牌，加入你的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eager", "渴望", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain +2 power for the duration of it's first turn on the board.", "[creature] 在檯面上的第一個回合期間，攻擊力 +2。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Easy Pickings", "輕而易舉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all other creatures on the board with 1 health will perish.", "打出 [creature] 時，檯面上所有生命力為 1 的其他生物都會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emancipation", "脫胎換骨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, copies of any bottled cards the owner possesses are created in the owner's hand.", "打出 [creature] 時，擁有者持有的所有瓶中卡牌，皆會在擁有者的手牌中生成複製品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Core", "綠寶石核心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, an Emerald Vessel is created in its place.", "[creature] 死亡時，原位生成一個綠寶石容器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "綠寶石之心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, an Emerald Mox is created in its place.", "[creature] 死亡時，原位生成一張綠寶石魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanting", "附魔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all creatures you control gain one of its other sigils, at random.", "打出 [creature] 時，你控制的所有生物都會隨機獲得它的一個其他印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endangered", "瀕危", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] has a one in four chance to perish.", "回合結束時，[creature] 有四分之一的機率死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy Lines", "敵軍戰線", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, it will target all opponent slots that it is NOT directly opposing.", "[creature] 攻擊時，會以正對面以外的所有對手卡槽為目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Dependent", "能量依賴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the user has 0 Energy, [creature] will perish.", "若使用者擁有 0 點能量，[creature] 就會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged", "憤怒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it gains 1 attack power.", "[creature] 受到攻擊時，攻擊力增加 1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Entangle", "盤根錯節", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its killer has their power reduced by half and rounded down for one turn.", "[creature] 死亡時，擊殺者的攻擊力減半並向下取整，持續一回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic", "飄忽不定", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. It will not move if the target slot is obstructed. Direction has a 50/50 chance to change after moving.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動。若目標卡槽被阻擋，就不移動。移動後，方向有 50/50 的機率改變。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Esprit De Corps", "團隊精神", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, creatures in the leftmost and rightmost slots on the same side of the board gain 1 power.", "[creature] 在檯面上時，同側最左與最右卡槽中的生物各增加 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While[creature] is alive and on the board, its owner may not take fatal damage.", "[creature] 存活且在檯面上時，擁有者不會受到致命傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even Strike", "偶數打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike all opposing spaces in even indexed columns when it attacks. Column index is counted from the left, starting at 1.", "[creature] 攻擊時，會攻擊所有偶數編號直列上的對面位置。直列從左到右編號，由 1 開始。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exceptional Sacrifice", "傳說祭品", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] counts as 6 Blood rather than 1 Blood when sacrificed. Does not pair well with many lives.", "[creature] 被犧牲時，算作 6 點鮮血，而非 1 點。與九命印記搭配的效果不佳。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodstarved Beast", "嗜血狂獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may search their graveyard for a card, and add that card to their hand.", "打出 [creature] 時，擁有者可以從自己的墓地搜尋一張卡牌，加入手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Corpse", "屍爆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all empty spaces on the board are filled with it's innards.", "[creature] 死亡時，檯面上所有空位都會填滿它的內臟。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Expulsion", "嘔物驅逐", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] takes damage, it regurgitates it's contents into the adjacent space to the right.", "[creature] 受到傷害時，將肚裡的東西吐到右側相鄰位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exsanguination", "放血", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, friendly creatures have their blood cost reduced by 1.", "[creature] 在檯面上時，友方生物的鮮血費用減少 1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye For Battle", "戰鬥之眼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will lose all attack power if it is not directly opposing an opponent's creature.", "若 [creature] 沒有正對敵方生物，就會失去全部攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Face To Face", "面對面", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it morphs to mimic the current opponent.", "抽到 [creature] 時，它會變形，模仿目前的對手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fan Tailed", "妖扇之尾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all friendly creatures on the board take flight.", "打出 [creature] 時，檯面上所有友方生物獲得飛行能力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fatal Flank", "致命側翼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes to combat, it creates a specific creature in all empty adjacent slots.", "[creature] 因戰鬥死亡時，在所有相鄰的空卡槽中生成特定生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fearsome", "凶神惡煞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot occupied by another creature, that creature will move to make way for it if there is room to do so.", "[creature] 攻擊並鎖定其他生物佔據的卡槽時，若有相鄰空位，該生物會逃到該空位讓路。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "File Explorer", "檔案總管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, choose two creatures from random selection of your deck. These creatures will define this cards power and health at random. If this card dies, the creatures used to define its stats perish as well.", "打出 [creature] 時，從牌組隨機提供的候選中，選擇兩隻生物。這些生物會隨機決定這張卡牌的攻擊力與生命力。若這張卡牌死亡，用來決定其屬性的生物也會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filter Feeder", "濾食之物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature perishes adjacent to [creature], the card will gain either 1 power or 1 health.", "與 [creature] 相鄰的生物死亡時，這張卡牌獲得 1 點攻擊力或 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebomb", "火焰引爆器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, creatures adjacent to it and opposing it take 2 damage and gain the Burning sigil.", "[creature] 死亡時，相鄰與正對面的生物受到 2 點傷害，並獲得燃燒印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] explodes, spraying fire everywhere!", "[creature] 爆炸，火焰四處飛濺！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire In The Hole", "小心炮彈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it's owner may choose an opponent slot. The creature in that slot will take ten damage.", "[creature] 死亡時，擁有者可以選擇一個對手卡槽。該卡槽中的生物受到十點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Resistant", "防火", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not take damage from the Burning sigil.", "[creature] 不會受到燃燒印記的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flank Blast", "側牌引爆器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, adjacent friendly creatures are dealt 10 damage.", "[creature] 死亡時，相鄰的友方生物受到 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flea Ridden", "跳蚤滿身", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes to combat, it creates a Flea in all empty adjacent slots. A Flea is defined as 0 Power, 1 Health, Eager, Frail", "[creature] 因戰鬥死亡時，在所有相鄰的空卡槽中生成跳蚤。跳蚤具有：0 點攻擊力、1 點生命力、渴望印記，以及脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flighty", "輕浮", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will move to a random available space.", "回合結束時，[creature] 移動到隨機一個可用位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil Record", "化石紀錄", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, terrain cards will award 3 additional bones when destroyed.", "[creature] 在檯面上時，地形卡牌被摧毀時會額外提供 3 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail", "脆弱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it will perish.", "[creature] 受到攻擊時，就會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Sacrifice", "脆弱犧牲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, the creature it was sacrificed for gains the Frail Sigil.", "[creature] 被犧牲時，以它作為犧牲而打出的生物獲得脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freefall", "自由落體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all airborne creatures require exactly 1 less of their respective cost to be played.", "[creature] 在檯面上時，所有飛空生物打出時所需的對應費用恰好減少 1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Friend Finder", "找呀找朋友", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random friend is created in the slots to it's left and right.", "打出 [creature] 時，左右兩側的卡槽各生成一位隨機好友。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fringe Strike", "邊路打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will always attack the leftmost and rightmost opponent lanes.", "[creature] 總是攻擊對手最左與最右的路線。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frog Friend", "眾蛙之友", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscrybed in the sigil. You may search your deck for any 'frog' or 'toad' creatures, and play them in [creature]'s old space.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動。你可以從牌組搜尋任意「蛙」或「蟾蜍」生物，打出到 [creature] 原本的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Dependant", "綠寶石依賴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no green mox gems, it will perish.", "若 [creature] 的擁有者未控制任何綠色魔思力寶石，這張卡牌就會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] requires an emerald mox to exist and perishes.", "[creature] 無法在缺少綠寶石魔思力時存活，因而死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Dependant", "紅寶石依賴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no orange mox gems, it will perish.", "若 [creature] 的擁有者未控制任何橘色魔思力寶石，這張卡牌就會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] requires a ruby mox to exist and perishes.", "[creature] 無法在缺少紅寶石魔思力時存活，因而死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Dependant", "藍寶石依賴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no blue mox gems, it will perish.", "若 [creature] 的擁有者未控制任何藍色魔思力寶石，這張卡牌就會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] requires a sapphire mox to exist and perishes.", "[creature] 無法在缺少藍寶石魔思力時存活，因而死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shedder", "寶石掉落", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscrybed in the sigil and drop a random Gem in its old place.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動，並在原位留下一顆隨機寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Skeptic", "寶石質疑者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, its owner may not play any mox gems.", "[creature] 在檯面上時，擁有者無法打出任何魔思力寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant", "巨人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, any strikes against its owner will target it instead.", "[creature] 在檯面上時，所有對擁有者的攻擊都改為以它為目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gift Bearer", "贈禮攜帶者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a random creature is created in your hand.", "[creature] 死亡時，你的手牌中生成一隻隨機生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glitterheart", "輝耀之心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, playing a mox gem will increase its health by 1.", "[creature] 在檯面上時，打出魔思力寶石會使它的生命力增加 1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is bolstered by the played gem.", "[creature] 因打出的寶石而獲得強化。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Globetrotter", "四海為家", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will move in the direction inscribed on the sigil. If obstructed, it will move to the other side of the board and begin to circle back.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動。若遇到阻礙，會移到檯面另一端，開始繞回。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Black Goat is created in its owners hand.", "打出 [creature] 時，在擁有者的手牌中生成一張黑山羊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Digger", "掘金者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 currency, up to five times per battle.", "擁有者的回合結束時，[creature] 生成 1 點貨幣，每場戰鬥最多五次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Rush", "淘金熱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opponent cards on the board perish, and are replaced by Gold Nuggets.", "打出 [creature] 時，檯面上所有對手卡牌死亡，並被金塊取代。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "黏液", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker loses 1 power.", "[creature] 受到攻擊時，攻擊者失去 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrape that gunk off the hull, lads! Full steam ahead!", "把船殼上的黏糊玩意刮乾淨，小子們！全速前進！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No amount of ooze can slow the motion of a celestial body...", "再多黏液，也無法減緩天體的運行……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Graveyard Shift", "墓地輪班", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it leaves something else in it's old space. Unlike Frozen Away, this new creature will retain the sigils and buffs of the original.", "[creature] 因戰鬥死亡時，會在原位留下另一隻生物。與凍結解放不同，這隻新生物會保留原本的印記與增益。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity", "萬有引力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose any opponent creature, and move it to any open space on their side of the board.", "打出 [creature] 時，擁有者可以選擇任意一隻對方生物，移動到自己這一側檯面的任意空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Inspiration", "綠色靈感", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost a green gem gain +2 health.", "[creature] 在檯面上時，所有費用包含綠色寶石的友方生物，生命力 +2。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gut Spewer", "嘔臟者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its innards are created in your hand.", "打出 [creature] 時，它的內臟會在你的手牌中生成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "先驅者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly creatures perishes, [creature] will move to fill it's empty space.", "友方生物死亡時，[creature] 會移動到留下的空位補位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harts Within", "內心之鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a random creature from the hooved tribe is created in your hand.", "[creature] 受到攻擊時，你的手牌中生成一隻隨機有蹄類族群生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter", "作祟者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies to combat, it haunts the space it died in. Creatures that enter this space absorb its old sigils.", "[creature] 因戰鬥死亡時，亡魂會留在死亡的位置。進入該位置的生物會吸收它原本的印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] leaves its sigils behind in the ethereal plane!", "[creature] 將自己的印記留在靈界！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature]s owner may choose a creature they control. That creature gains 1 health.", "擁有者的回合結束時，[creature] 的擁有者可以選擇一隻自己控制的生物，使該生物獲得 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healshield", "治療護盾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] does not take damage during a turn, it will gain Armor at the start of its owner's next turn.", "若 [creature] 在一個回合中未受到傷害，會在擁有者下個回合開始時獲得護甲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herald", "使節", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] attacks an opposing creature and it perishes, creatures to the left and right of this card gain 1 power.", "[creature] 攻擊對面的生物並使其死亡時，這張卡牌左右兩側的生物各獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Powered", "高功率", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owners turn, [creature] will consume 1 energy.", "擁有者的回合開始時，[creature] 消耗 1 點能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Home Run", "全壘打", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will remember the lane in which it was played, and will always attack that lane.", "[creature] 會記住自己被打出時所在的路線，並且總是攻擊該路線。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook Line And Sinker", "全套誘餌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, the opposing creature will be pulled into it's old space.", "[creature] 因戰鬥死亡時，對面的生物會被拉到它原本的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypermorphic", "超形態", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, [creature] will transform into a random card of the same type and quality.", "每個回合結束時，[creature] 變成一張同類型、同品質的隨機卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "點燃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature gains the Burning sigil.", "[creature] 攻擊一隻生物時，該生物獲得燃燒印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Immaculate Form", "無瑕形態", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, the gems cost of all friendly creatures is reduced by 2 gems.", "[creature] 在檯面上時，所有友方生物的寶石費用減少 2 顆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Immaterial", "縹緲之物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any attacks made against [creature] during the opponents turn will pass straight through, and hit the creature's owner directly.", "對手的回合中，對 [creature] 發動的攻擊會直接穿過它，擊中它的擁有者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Immortal Coil", "不朽之環", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, any friendly creatures that die to combat will return to the owner's hand, though slightly weakened.", "[creature] 存活且在檯面上時，任何因戰鬥死亡的友方生物都會返回擁有者的手牌，但會稍微變弱。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incontinent", "失禁", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a mess is created in its place and a card bearing this sigil moves to the right.", "[creature] 即將受到攻擊時，原位會生成污穢團，而帶有此印記的卡牌向右移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiring Sacrifice", "鼓舞之血", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it grants its sigils to the creature it was sacrificed for.", "[creature] 被犧牲時，將自己的印記授予以它作為犧牲而打出的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instant Effect", "即時效果", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After resolving on the board, [creature] will immediately perish.", "[creature] 在檯面上結算效果後，立即死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killing Joke", "殺戮玩笑", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost an orange gem will either gain +1 power or -1 power when played.", "[creature] 在檯面上時，所有費用包含橘色寶石的友方生物，被打出時攻擊力會 +1 或 -1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] randomly modifies the power of the Orange Gem cost card!", "[creature] 隨機調整了費用包含橘色寶石的卡牌攻擊力！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kin Bearer", "親族攜帶者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a random creature of the same tribe is created in your hand.", "[creature] 死亡時，你的手牌中生成一隻隨機的同族類生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindred", "親族之後", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, random common creatures of the same tribe will be played for free to its left and right.", "打出 [creature] 時，左右兩側會各免費打出一隻隨機的同族類普通生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "L33p Leaver", "跳躍機器人掉落器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will move in the direction inscrybed in the sigil and drop a L33pB0t in its old place.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動，並在原位留下一台跳33躍機0人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Landscaper", "景觀設計師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] is played, any terrain cards on the board are removed and added to it's owner's hand.", "打出 [creature] 時，檯面上所有地形卡牌都被移除，加入這張卡牌擁有者的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lash Out", "狂亂攻擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will attack a random opposing slot.", "擁有者的回合結束時，[creature] 攻擊隨機一個對手卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Airborne Latch", "飛空傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the airborne sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得飛空印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Latch", "惱人傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the annoying sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得煩躁印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Latch", "燃燒傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the burning sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得燃燒印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burrower Latch", "挖掘者傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the burrower sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得挖掘者印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Latch", "脆弱傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the frail sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temporarily Gemified", "暫時寶石化", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has been temporarily gemified until the end of battle.", "[creature] 暫時寶石化，直到戰鬥結束。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Latch", "寶石傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] perishes, its owner chooses a creature to become gemified.", "[creature] 死亡時，擁有者選擇一隻生物，使其寶石化。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter Latch", "作祟者傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the haunter sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得作祟者印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Null Latch", "空無傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the null conduit sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得無用導管印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overclocked Latch", "超頻傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain 1 power, and the overclocked sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得 1 點攻擊力與超頻印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Latch", "狙擊傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the sniper sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得狙擊手印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprinter Latch", "衝刺者傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the sprinter sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得衝刺者印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalwart Latch", "堅毅傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the stalwart sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得堅毅印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Totem Latch", "圖騰傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the sigil on their current totem.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得自己目前圖騰上的印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterborne Latch", "水生傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the waterborne sigil.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得水生印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaper", "躍行者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil, leaping over single card obstructions.", "擁有者的回合結束時，[creature] 沿印記標示的方向移動，能跳過單張卡牌的阻擋。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it creates a number of cards in the owner's hand equal to it's remaining HP, then perishes.", "[creature] 受到攻擊時，在擁有者的手牌中生成等同於自身剩餘生命力數量的卡牌，然後死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lockdown", "封鎖關隘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing creature loses attack power equal to the power of this card and gains the Stalwart sigil.", "打出 [creature] 時，對面的生物失去等同於這張卡牌攻擊力的攻擊力，並獲得堅毅印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] locks the opposing creature in place!", "[creature] 將對面的生物鎖在原地！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "孤獨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "每個相鄰空位都讓 [creature] 的攻擊力 +1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lurk", "水生哨兵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerges during the opponent's turn. When a creature moves into the space opposing [creature], they are dealt 1 damage.", "對手的回合期間潛入水下。有生物移動到 [creature] 正對面的位置時，該生物受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magitech", "魔法科技", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive and on the board, playing a mox gem will provide it's owner with an energy cell.", "[creature] 存活且在檯面上時，打出魔思力寶石會給予擁有者一個能量槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] channels electrical power through your gems!", "[creature] 透過你的寶石傳導電力！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malware", "惡意軟體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may not play [creature] unless you are three or less damage away from losing the game.", "只有再受三點或更少傷害就會敗北時，你才能打出 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marcescent", "凋而不落", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card gains it's attack power.", "[creature] 攻擊對面的生物並使其死亡時，這張卡牌獲得該生物的攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mason", "石匠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random obelisk is created in your hand.", "打出 [creature] 時，你的手牌中生成一座隨機方尖碑。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mauler", "猛擊者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal overkill damage directly to the opponent.", "[creature] 會將過量傷害直接造成給對手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Medicinal", "靈丹妙藥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it heals all friendly creatures by 2 and removes all negative sigils from friendly creatures.", "打出 [creature] 時，為所有友方生物恢復 2 點生命力，並移除所有友方生物的負面印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirrific", "鏡像傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it's owner chooses a creature to gain the Mirror rorriM ability.", "[creature] 死亡時，擁有者選擇一隻生物，使其獲得「鏡子子鏡」能力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mockery", "嘲弄", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is played opposite an opponent's creature, it's stats change to mimic that creature's stats.", "若 [creature] 被打出到敵方生物正對面，其屬性會變得與該生物相同。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph Mover", "無形移態", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random movement related sigil.", "抽到 [creature] 時，此印記會被替換為一個隨機的移動相關印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Motivator", "鬥志之源", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature gains 1 power.", "[creature] 攻擊一隻生物時，該生物獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moxcraft", "魔思力的世界", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a random mox is created in your hand.", "[creature] 受到攻擊時，你的手牌中生成一張隨機魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Max", "魔思力極限", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be played unless two cards which grant its respective mox cost colour are present on the owners side of the board.", "擁有者這一側的檯面上，必須有兩張提供這張卡牌所需魔思力費用顏色的卡牌，才能打出 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moxwarp", "魔思力躍遷", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, any enemy attack that enters a sapphire mox will be returned out of all ruby mox, and vice versa.", "[creature] 存活且在檯面上時，任何打到藍寶石魔思力的敵方攻擊，都會從所有紅寶石魔思力反射出去，反之亦然。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystery Mox", "神祕魔思力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random gem-granting sigil.", "抽到 [creature] 時，此印記會被替換為一個隨機提供寶石的印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature Of The Beast", "野性呼喚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a completely random creature is created in the owner's hand.", "[creature] 死亡時，在擁有者的手牌中生成一隻完全隨機的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obedient", "悉聽尊便", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move to an empty space on the same side of the board, chosen by it's owner.", "擁有者的回合結束時，[creature] 移動到檯面同側的一個空位，由擁有者選擇位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Odd Strike", "奇數打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike all opposing spaces in odd indexed columns when it attacks. Column index is counted from the left, starting at 1.", "[creature] 攻擊時，會攻擊所有奇數編號直列上的對面位置。直列從左到右編號，由 1 開始。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omni Guardian", "全能守護者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all friendly creatures on the board gain armour.", "打出 [creature] 時，檯面上所有友方生物獲得護甲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives the Armored sigil to all friendly creatures.", "[creature] 給予所有友方生物身穿裝甲印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crusher", "碎石者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a terrain card.", "[creature] 正對地形卡牌時，獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerly Departed", "屠鹿者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Hooved tribe.", "[creature] 正對有蹄類族群生物時，獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dog Gone", "獵犬者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Canine tribe.", "[creature] 正對犬類族群生物時，獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fowl Play", "戲鳥者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Avian tribe.", "[creature] 正對鳥類族群生物時，獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insectivore", "食蟲者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Insect tribe.", "[creature] 正對昆蟲類族群生物時，獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snakebite", "捕蛇者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Reptile tribe.", "[creature] 正對爬行動物族群生物時，獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Inspiration", "橘色靈感", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While[creature] is on the board, all friendly cards which cost an orange gem gain +1 power.", "[creature] 在檯面上時，所有費用包含橘色寶石的友方卡牌，攻擊力 +1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Organ Thief", "器官盜賊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it's remains are created in your hand.", "[creature] 擊殺另一隻生物時，該生物的殘骸會在你的手牌中生成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Osteoklepty", "竊骨術", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it steals all of the opponents bones for it's owner.", "打出 [creature] 時，它會偷走對手所有骨頭，交給擁有者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other Side", "彼岸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, any friendly creatures that die in combat will be returned to the owner's hand as skeletons.", "[creature] 在檯面上時，所有在戰鬥中死亡的友方生物都會以骷髏的形態返回擁有者的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Presence", "痛苦存在", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On upkeep, all creatures adjacent to [creature] vertically, horizontally, or diagonally take 1 damage.", "擁有者的回合開始時，與 [creature] 縱向、橫向或斜向相鄰的所有生物都會受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paralytic", "麻痺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature loses 1 power.", "[creature] 擊中生物時，該生物失去 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parthenogenesis", "單性生殖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies to combat, a larval form is left in it's old space that evolves into an exact clone after 1 turn.", "[creature] 在戰鬥中死亡時，會在原位置留下幼蟲形態，並於 1 回合後進化成完全相同的複製體。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect Form", "完美形態", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, the gems cost of all friendly creatures is reduced by 1 gem.", "[creature] 在檯面上時，所有友方生物的寶石費用減少 1 顆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantasmic", "幻影移行", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will move in the direction inscribed in the sigil, phasing past obstacles and wrapping around to the other side of the board if movement is impossible.", "回合結束時，[creature] 會沿印記標示的方向移動，穿過障礙物；若無法繼續移動，則會繞至檯面的另一端。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piercing", "穿刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a slot which has a creature queued behind it, the queued creature will take 1 damage.", "[creature] 攻擊的卡槽後方若有排隊中的生物，該生物會受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pinnacle Strike", "巔峰打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike all opponent spaces when it attacks.", "[creature] 攻擊時會攻擊所有對手的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Point Nemo", "尼莫點", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all creatures on the board gain the Waterborne sigil.", "打出 [creature] 時，檯面上的所有生物都會獲得水生印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potent", "強效犧牲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, the creature it was sacrificed for gains a random sigil.", "[creature] 被犧牲時，用這次犧牲打出的生物會獲得一個隨機印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preemptive Strike", "先制攻擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack once when first played.", "[creature] 首次打出時會攻擊一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] makes a free attack!", "[creature] 發動了一次免費攻擊！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Propagation", "繁衍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, a creature is created on the board to the left or right of this card.", "[creature] 攻擊並殺死對面的生物時，會在此卡牌左側或右側的位置生成一個生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prophecy", "預言", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may look at three cards from your deck and choose them in order. The next three cards you draw will be the cards you were shown, in the order that you chose them.", "打出 [creature] 時，你可以檢視牌組中的三張卡牌，並依序選擇。接下來抽到的三張牌會是這三張卡牌，順序與你選擇的順序相同。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will allow you to choose from three cards. These three cards will be the next three cards you draw from your deck, in the order you choose them here.", "我讓你從三張卡牌中選擇。你接下來從牌組抽到的三張牌，就是這三張，順序由你在這裡決定。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose three creatures, and alter your next draws.", "選擇三個生物，改變你接下來的抽牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know how this goes.", "你知道規矩。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose from three cards. These three cards will be the next three cards you draw from your deck, in the order you chose them.", "從三張卡牌中選擇。你接下來從牌組抽到的三張牌，就是這三張，順序與你選擇的順序相同。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose your next three draws.", "選擇你接下來要抽的三張牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmmm... your new prophecy overwrites the old, it would seem.", "嗯……看來你的新預言覆蓋了舊預言。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your new prophecy overwrites the old!", "你的新預言覆蓋了舊預言！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... very well", "嗯……好吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough cards left for a prophecy.", "剩下的卡牌不夠，無法進行預言。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough cards left to make a new prophecy!", "剩下的卡牌不夠，無法進行新的預言！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pure Heart", "純淨之心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Pinnacle Mox is created in its place.", "[creature] 死亡時，會在原位置生成一張巔峰魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pushover", "軟柿子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is opposed by an enemy creature, the card will perish.", "若 [creature] 正對面有敵方生物，此卡牌就會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put Sentry Here", "在此部署哨兵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Sentry Drone is created to its left and right.", "打出 [creature] 時，會在其左右兩側各生成一架哨兵無人機。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quad Strike", "四重打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space to the left and right of the spaces across from it as well as striking the space in front of it an additional time.", "[creature] 會攻擊正對面位置的左右兩側，並額外攻擊正前方的位置一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quickdraw", "快速出牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will automatically play itself from your deck onto a random space at the start of each battle.", "每場戰鬥開始時，[creature] 會自動從你的牌組打出至隨機位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ranger", "遊騎兵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose an opponent creature. That creature will take 10 damage.", "打出 [creature] 時，其擁有者可以選擇一個對手的生物，使其受到 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ravenous", "貪婪吞噬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills a creature, it will gain an additional strike against the opposing space until the end of combat.", "[creature] 殺死生物時，會獲得一次對正對面位置的額外攻擊，持續至戰鬥結束。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge", "蓄勢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner regains 1 energy. Does not affect the current energy maximum.", "打出 [creature] 時，其擁有者恢復 1 點能量。這不會改變目前的能量上限。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recycle", "回收利用", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, when any friendly creature perishes by combat a special card will be created in the owners hand. The card created depends on the temple of the friendly card which perishesd.", "[creature] 在檯面上時，每當友方生物在戰鬥中死亡，都會在擁有者的手牌中生成一張特殊卡牌。生成的卡牌取決於死亡生物所屬的神廟。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reflective", "鏡面反射", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is opposed by a creature, it gains power equal to the opposing creatures power.", "[creature] 正對面有生物時，會額外獲得等同於該生物攻擊力的攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regenerator", "再生者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, [creature] will heal 1 health.", "擁有者的回合開始時，[creature] 恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] regenerates one health!", "[creature] 恢復了 1 點生命力！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rememberance", "追憶", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may search their graveyard for a card. This sigil is replaced by that cards sigils.", "打出 [creature] 時，其擁有者可以從墓地選擇一張卡牌。此印記會被該卡牌的印記取代。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remote Controlled", "遙控", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Remote Controller is created in the owner's hand. When the remote controller is struck, [creature] will attack the striker.", "打出 [creature] 時，會在擁有者的手牌中生成一個遙控器。遙控器受到攻擊時，[creature] 會攻擊襲擊者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reroute", "重新導向", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will swap places with a random creature on the same side of the board.", "回合結束時，[creature] 會與檯面上同側的隨機生物交換位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resilient", "堅韌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All damage taken by [creature] is reduced to 1.", "[creature] 受到的所有傷害均降為 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retreat", "撤退", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it will move to a random empty space on the same side of the board.", "[creature] 受到攻擊時，會移動至檯面同側的隨機空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return Strike", "還擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it attacks in retaliation.", "[creature] 受到攻擊時會還擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revolve", "旋轉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards on the board are moved one space clockwise.", "打出 [creature] 時，檯面上所有卡牌都會順時針移動一格。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ripper", "開膛手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will move to and destroy any free, 1 health, non-terrain creatures played, and becomes stronger for each one consumed.", "在 [creature] 同側打出另一個非地形生物時，若該生物免費且生命力上限為 1，或是山羊，此卡牌會將其消滅並移到其位置（擁有堅毅時不移動）。每吞噬一個都會變得更強。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rock Eater", "磐石吞噬者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Terrain card is played on the same side of the board as [creature], it will be consumed, granting it's stats and sigils to the card.", "地形卡被打到 [creature] 所在的檯面同側時，會被吞噬，讓此卡牌獲得該地形卡的屬性與印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Core", "紅寶石核心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Ruby Vessel is created in its place.", "[creature] 死亡時，會在原位置生成一個紅寶石容器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running Strike", "奔襲打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] will move in the direction inscribed on the sigil, striking the space opposing it's destination as it does so.", "攻擊後，[creature] 會沿印記標示的方向移動，並在移動時攻擊目的地正對面的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rupture", "撕裂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage to a creature, half of that damage, rounded down, is also dealt to that creature's owner.", "[creature] 對生物造成傷害時，也會對該生物的擁有者造成該傷害一半的傷害，向下取整。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sanguine", "血氣", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is sacrificed, [creature] gains 1 power until the end of combat.", "每當生物被犧牲時，[creature] 獲得 1 點攻擊力，持續至戰鬥結束。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Core", "藍寶石核心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Sapphire Vessel is created in its place.", "[creature] 死亡時，會在原位置生成一個藍寶石容器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "藍寶石之心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Sapphire Mox is created in its place.", "[creature] 死亡時，會在原位置生成一張藍寶石魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Savage Ritual", "野蠻儀式", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it attacks once before dying.", "[creature] 被犧牲時，會在死亡前攻擊一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentriple", "三重哨兵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they, as well as any creatures to their left or right, are dealt 1 damage.", "生物移入 [creature] 正對面的位置時，該生物及其左右兩側的生物都會受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Bones", "尖銳骨骼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt damage equal to half the number of bones its owner has, rounded down.", "[creature] 受到攻擊時，攻擊者會受到等同於此卡牌擁有者的骨頭數量一半的傷害，向下取整。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharper Quills", "更鋒利之刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt 2 damage.", "[creature] 受到攻擊時，攻擊者會受到 2 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharpest Quills", "最鋒利之刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt 3 damage.", "[creature] 受到攻擊時，攻擊者會受到 3 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Shot", "銳射", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it gains +2 power and attacks once before dying.", "[creature] 死亡時，會獲得 +2 攻擊力，並在死亡前攻擊一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigil Mimic", "印記模仿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is played opposite an opponent's creature, this sigil is replaced by copies of that creatures sigils.", "若在對手生物的正對面打出 [creature]，此印記會被該生物的印記複本取代。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will also strike the slot to the left of the opposing slot when it attacks.", "[creature] 攻擊時，也會攻擊正對面卡槽左側的卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Siphon", "虹吸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures to the left of [creature] lose all attack power. That attack power is instead added to this card's power.", "[creature] 左側的生物失去全部攻擊力，失去的攻擊力會轉而加到此卡牌上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Animator", "毛皮操偶師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, all pelts gain it's attack power.", "[creature] 存活且在檯面上時，所有毛皮都會獲得等同於此卡牌攻擊力的攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Swarm", "骷髏群襲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive and on the board, all Skeletons will strike twice when attacking.", "[creature] 存活且在檯面上時，所有骷髏攻擊時都會攻擊兩次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimeball", "黏液球", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it permanently stains the opposing slot with slime. Any creatures in a slimy slot without made of stone lose 1 power.", "打出 [creature] 時，會用黏液永久沾染正對面的卡槽。黏液卡槽中沒有鐵石心腸印記的生物會失去 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snapshot", "快照", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the entire board reverts to the state it was in when [creature] was placed.", "[creature] 死亡時，整個檯面會恢復成 [creature] 被放置時的狀態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snare", "捕獸索", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played opposite a creature, that creature is ensnared and stored within the bearer, being released when the bearer perishes.", "在生物正對面打出 [creature] 時，該生物會被捕獲並封存在此卡牌內，直到此卡牌死亡才獲釋。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snip", "剪斷", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the creature opposing it is removed from the board without triggering on-death effects.", "打出 [creature] 時，正對面的生物會被移出檯面，不會觸發死亡效果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cuts it's opponent in half.", "[creature] 將對手剪成兩半。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soak", "浸潤", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any damage taken by [creature] is reduced by 1. Taking damage decrements the timer rendered on this sigil. When the timer rendered on this sigil reaches 0, the bearer will attack with power equal to it's health, then perish.", "[creature] 受到的傷害減少 1 點。每次受到傷害，此印記上顯示的計時器就會減少。計時器降至 0 時，此卡牌會以等同於自身生命力的攻擊力發動攻擊，然後死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiders Web", "蜘蛛網", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When any opponent card moves, with the exception of entering the board for the first time,[creature] will strike them for one damage.", "任何對手卡牌移動時，除了首次進入檯面以外，[creature] 都會對其造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splash Damage", "濺射傷害", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a slot, creatures to the left and right of the struck slot will be dealt 1 damage.", "[creature] 攻擊卡槽時，該卡槽左右兩側的生物都會受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splash Zone", "濺射區域", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the creatures to it's left or right are also dealt 1 damage.", "[creature] 受到攻擊時，左右兩側的生物也會受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The damage dealt to [creature] splashes out to its comrades.", "[creature] 受到的傷害波及了同伴。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Split Detonation", "斜向引爆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, diagonally adjacent enemy creatures are dealt 10 damage.", "[creature] 死亡時，斜對角相鄰的敵方生物會受到 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Split Sentry", "分岔哨兵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], any creatures to their left or right are dealt 1 damage.", "生物移入 [creature] 正對面的位置時，該生物左右兩側的生物都會受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spurred", "鞭策", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power while the slot opposing it is occupied.", "正對面的卡槽被佔據時，[creature] 獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Dependent", "松鼠依賴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no Squirrels, [creature] will perish. If this card is a squirrel, it cannot support itself.", "若 [creature] 的擁有者未控制任何松鼠，[creature] 就會死亡。即使此卡牌是松鼠，也無法維持自身。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel King", "松鼠王", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature, a squirrel is created in the owner's hand.", "[creature] 攻擊對面的生物時，會在擁有者的手牌中生成一張松鼠。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalwart", "堅毅", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is moved from the space it was placed in, it will immediately move back, shunting any card which may have moved there in the meantime out of the way.", "若 [creature] 離開最初被放置的位置，就會立即返回原位，並擠開其間移入該位置的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky Trail", "黏液軌跡", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] enters a space on the board, it permantently marks that space with its slime. Any creatures that enter that space without the Made of Stone sigil lose 1 power.", "[creature] 進入檯面上的位置時，會用黏液永久標記該位置。進入此位置且沒有鐵石心腸印記的生物會失去 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sturdy", "堅不可摧", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All damage taken by [creature] is reduced by 1.", "[creature] 受到的所有傷害均減少 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Subaquatic Spines", "水下尖刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will submerge during the opponent's turn. While submerged, opposing creatures attack it's owner directly, and will take 1 damage after attacking.", "[creature] 會在對手的回合下潛。下潛時，對面的生物會直接攻擊此卡牌的擁有者，並在攻擊後受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "召喚師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose from a selection of random cards to add to their hand.", "打出 [creature] 時，其擁有者可以從一組隨機卡牌中選擇一張加入手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supercharge", "超載充能", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it refreshes it's owner's energy to the current maximum.", "打出 [creature] 時，其擁有者的能量會恢復至目前上限。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] restores it's owner's energy.", "[creature] 恢復了擁有者的能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surging Quills", "蓄勢之刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt damage equal to the amount of times this has been struck.", "[creature] 受到攻擊時，攻擊者會受到等同於此卡牌已受攻擊次數的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sweeping Strike Left", "向左橫掃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will always attack the leftmost opponent creature. Overkill damage travels to the right instead of to the backlane.", "[creature] 一律攻擊最左側的對手生物。過量傷害會向右傳遞，而不會傷及後排。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sweeping Strike Right", "向右橫掃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will always attack the rightmost opponent creature. Overkill damage travels to the left instead of to the backlane.", "[creature] 一律攻擊最右側的對手生物。過量傷害會向左傳遞，而不會傷及後排。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Switch Strike", "交替打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owners turn [creature] will alternate between striking to the left or right of the opposing slot when it attacks, in addition to striking the opposing slot.", "[creature] 正常攻擊正對面的卡槽時，也會攻擊其左側或右側；擁有者的回合結束時切換額外攻擊的方向。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swooping Strike", "俯衝打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space a second time when attacking. Also, [creature]'s first strike each turn will occur directly, over opponent creatures.", "[creature] 攻擊時會額外攻擊正對面的位置一次。此外，[creature] 每回合的第一次攻擊會越過對手生物，直接攻擊對手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathic", "心靈感應", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures will stike the most powerful opponent card when they attack.", "[creature] 在檯面上時，所有友方生物都會攻擊對手攻擊力最高的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tempting Target", "誘人目標", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If an opponent creature would strike a space adjacent to [creature], it will instead strike [creature].", "若對手生物即將攻擊 [creature] 相鄰的位置，就會改為攻擊 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Termatriarch", "白蟻后", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] and a different card bearing the Termite King sigil are alive and on the board, a termite will be created in your hand at the start of your turn.", "[creature] 與另一張帶有白蟻王印記的卡牌同時存活且在檯面上時，你的回合開始時會在你的手牌中生成一張白蟻。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Termite King", "白蟻王", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] and a different card bearing the Termatriarch sigil are alive and on the board, a termite will be created in your hand at the start of your turn.", "[creature] 與另一張帶有白蟻后印記的卡牌同時存活且在檯面上時，你的回合開始時會在你的手牌中生成一張白蟻。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TestSigil", "測試印記", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will most likely fuck shit up.", "[creature] 多半會把一切搞得他媽一團糟。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thief", "盜賊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant an amount of currency when it kills another creature.", "[creature] 殺死其他生物時，會提供一定數量的貨幣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time Travel", "時間旅行", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is played, the opponent is obligated to skip their next turn.", "打出 [creature] 時，對手必須跳過下一個回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll pass my next turn.", "我會跳過下一個回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your opponent must skip their next turn!", "你的對手必須跳過下一個回合！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh. Fine. I'll pass.", "呃，好吧。我跳過。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fair enough dear, I'll pass.", "很公平，親愛的。我跳過。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tooth Puller", "拔牙者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will add one damage to the scales in the owner's favour, regardless of it's attack power or obstruction.", "擁有者的回合結束時，不論 [creature] 的攻擊力高低或是否被阻擋，都會在天平上增加 1 點有利於擁有者的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxic", "劇毒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck but does not perish, the striker perishes. Does not affect Made of Stone cards.", "[creature] 受到攻擊且未死亡時，攻擊者會死亡。對帶有鐵石心腸印記的卡牌無效。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s toxicity kills instantly!", "[creature] 的劇毒立即奪走性命！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traitor", "叛徒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will move onto the opponent's side of the board if unobstructed.", "打出 [creature] 時，若未被阻擋，就會移動到對手的檯面。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trajectile Quills", "投射之刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, an opponent creature of the owner's choosing is dealt 1 damage.", "[creature] 受到攻擊時，由其擁有者選擇一個對手生物，使其受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trampler", "踐踏者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. Cards in the way will be killed, and grant +1 attack power to the sigil bearer.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動。擋路的卡牌會被殺死，每張都會使印記持有者獲得 +1 攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transformer", "變形者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will transform to or from it's alternate form.", "回合結束時，[creature] 會切換成另一形態，或從該形態變回原形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmogrification", "變形術", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature will be changed into another form.", "[creature] 擊中生物時，該生物會變成另一種形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapjaw", "陷阱顎", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack to the left and the right of the opposing space if those slots are obstructed. If those slots are not obstructed, the strikes will be transferred to the directly opposing space.", "[creature] 會攻擊正對面位置的左右兩側。若其中的位置未被佔據，原本對該位置的攻擊會轉移至正對面的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trifling Sacrifice", "微薄祭品", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] counts as 2 Blood rather than 1 Blood when sacrificed.", "[creature] 被犧牲時算作 2 點鮮血，而非 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trio", "三重奏", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it is created to the left and right.", "打出 [creature] 時，會在左右兩側各生成一張此卡牌的複本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triple Strike", "三重打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space two extra times when attacking.", "[creature] 攻擊時會額外攻擊正對面的位置兩次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trophy Hunter", "戰利品獵人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will target the most powerful opposing card when it attacks.", "[creature] 攻擊時會鎖定對手攻擊力最高的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tuck And Roll", "蜷身翻滾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of combat, [creature] will move to the free space opposed by the least amount of attack power, taking into account queued creatures, flight, and Touch of Death.", "擁有者的回合開始時，[creature] 會移動到面對攻擊力最小的空位；計算時會考慮排隊中的生物、飛行與死亡之觸。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tug", "拖拽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will draw the queued opposing creature into the main opposing space, if possible.", "打出 [creature] 時，若有可能，就會把對面排隊中的生物拖至正對面的前排位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twin Bond", "雙生契約", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it is created adjacent, killing other creatures to make room if there is none. These cards share a health pool, and when either card dies, it's twin will die as well.", "打出 [creature] 時，會在相鄰位置生成此卡牌的複本；若沒有空位，則會殺死其他生物騰出空間。兩張卡牌共享生命力，其中一張死亡時，另一張也會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twister", "扭轉形態", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When struck, [creature] will transform to or from it's alternate form.", "[creature] 受到攻擊時，會切換成另一形態，或從該形態變回原形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unbalanced Leadership", "失衡領導", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature directly to the left of [creature] gains 2 power.", "[creature] 左側緊鄰的生物獲得 2 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Under Pressure", "壓力之下", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, 2 damage is dealt to the opponent creature. Also, when [creature] perishes, any adjacent creatures with this sigil also take ten damage.", "[creature] 死亡時，對面的生物會受到 2 點傷害。此外，[creature] 死亡時，相鄰且帶有此印記的生物也會受到 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] pops, dealing 2 damage to the opposing creature!", "[creature] 爆開，對正對面的生物造成 2 點傷害！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfocused Strike", "胡亂打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will target a random space when it attacks.", "[creature] 攻擊時會鎖定隨機位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unhammerable", "不可錘擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be killed using the hammer.", "無法使用錘子殺死 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlucky", "厄運", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, cards played by the opponent have a chance to have debuffed stats, or lose a random sigil.", "[creature] 存活且在檯面上時，對手打出的卡牌有機會降低屬性，或失去一個隨機印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unspeakable", "不可名狀", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card you control resolves on the board without being played from your hand, you may choose to play [creature] from your hand or deck instead.", "你控制的卡牌若未經由手牌打出，就在檯面上完成進場結算，你可以選擇改從手牌或牌組打出 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unstable Gems", "不穩定寶石", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost a mox gem will gain the brittle sigil when played.", "[creature] 在檯面上時，所有需要魔思力寶石費用的友方生物被打出時都會獲得脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] renders the gem cost creature unstable!", "[creature] 讓需要寶石的生物變得不穩定！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valuable", "珍貴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant an amount of currency when it perishes.", "[creature] 死亡時，會提供一定數量的貨幣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vampiric", "吸血", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card gains 1 health.", "[creature] 攻擊並殺死對面的生物時，此卡牌獲得 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Venator", "易形獵手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it will transform to or from it's alternate form.", "[creature] 殺死其他生物時，會切換成另一形態，或從該形態變回原形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vessel Shedder", "遺落容器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscrybed in the sigil and drop an Empty Vessel in its old place.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動，並在原位置留下一個空容器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Visceral", "血肉轉化", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, any leftover blood that is not used for the sacrifice will be converted into bones.", "[creature] 被犧牲時，支付犧牲費用後剩餘的鮮血會轉換成骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Viva La Revolution", "革命萬歲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owners turn, [creature] will revolve all creatures on the board clockwise. Also, [creature] will not attack it's original owner.", "擁有者的回合開始時，[creature] 會讓檯面上的所有生物順時針旋轉。此外，[creature] 不會攻擊原本的擁有者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterbird", "水鳥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] strikes a slot containing a submerged creature, that creature will re-emerge and [creature] will attack it instead of attacking directly.", "若 [creature] 攻擊的卡槽中有下潛的生物，該生物就會浮出水面，[creature] 會改為攻擊牠，而非直接攻擊擁有者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wavering Strike", "搖擺打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will alternate between striking to the left or right of where it would otherwise attack at the end of each turn.", "[creature] 正常攻擊時會打向原目標的左側或右側；擁有者的回合結束時切換方向。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weaver", "織網者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil and leave a Web in it's old space. [creature] can move back over webs it has placed.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動，並在原位置留下蜘蛛網。[creature] 可以移回自己放下的蜘蛛網上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures in the insect tribe will not attack [creature].", "昆蟲類族群的生物不會攻擊 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weird Latch", "詭異傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random latch sigil.", "抽到 [creature] 時，此印記會被隨機傳花印記取代。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wild Shape", "狂野變形", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it transforms based on what gem colours its owner controls.", "打出 [creature] 時，會依據擁有者目前控制的寶石顏色變形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] transforms based on its owner's gems...", "[creature] 依據擁有者的寶石變形……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wimpy", "軟弱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage to a creature, it will always deal 1 less damage than it should.", "[creature] 對生物造成的傷害一律比原本少 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wing Clipper", "剪翼者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opponent creatures with the Airborne sigil lose the Airborne sigil.", "打出 [creature] 時，所有帶有飛空印記的對手生物都會失去飛空印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] grounds all its opponents!", "[creature] 讓所有對手都落地了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wingrider", "搭翼者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a friendly airborne creature is played while [creature] is in the owner's hand, this card will be played adjacent to it.", "若 [creature] 在擁有者的手牌中時有友方飛空生物被打出，此卡牌就會被打到該生物的相鄰位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodsie Lord", "法樹領主", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Enchanted Pines are created on every empty space. An enchanted pine is defined as 0 power, 3 health.", "打出 [creature] 時，所有空位都會生成附魔松樹。附魔松樹具有 0 攻擊力、3 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wriggle", "蠕動", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played it deals 1 damage to all opponent creatures.", "打出 [creature] 時，對所有對手生物造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Writhe", "垂死掙扎", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it will attack all opposing spaces for 1 damage.", "[creature] 死亡時，會攻擊對手的所有位置，各造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ye filthy dog! Now one o' me maties needs to swab the poop deck!", "你這骯髒的狗東西！這下得叫我的夥伴去刷乾淨艉樓甲板了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1d4", "1d4 骰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil starts at 2, and will become a random number between 1 and 4 at the start of each subsequent turn.", "此印記代表的數值初始為 2，之後每個回合開始時，會變成 1 至 4 之間的隨機數值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power starts at 2, and will become a random number between 1 and 4 at the start of each subsequent turn.", "[creature] 的攻擊力初始為 2，之後每個回合開始時，會變成 1 至 4 之間的隨機數值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambitious", "野心勃勃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to highest power number present on the board, regardless of whether the card bearing it is friend or foe. Updates at the start of both the player and opponent turn.", "此印記代表的數值等於檯面上最高的攻擊力，不論該卡牌是敵是友。玩家與對手的回合開始時都會更新。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the power of the creature with the highest attack power on the board. Recalculates each turn.", "[creature] 的攻擊力等於檯面上攻擊力最高的生物的攻擊力，每個回合重新計算。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Plus Two", "螞蟻加二", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of ants on the board, plus two.", "此印記代表的數值等於帶有此印記的卡牌同側檯面上的螞蟻數量加二。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of friendly ants on the board, plus two.", "[creature] 的攻擊力等於檯面上的友方螞蟻數量加二。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Birds of a Feather", "同羽相聚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of avian tribe creatures on the board, including opponent creatures.", "此印記代表的數值等於檯面上的鳥類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of avian tribe creatures on the board, including opponent creatures.", "[creature] 的攻擊力等於檯面上的鳥類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood and Bone", "血與骨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the bone cost of the opposing card, or double the blood cost of the opposing card.", "此印記代表的數值等於對面卡牌的骨頭費用，加上其鮮血費用的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the bone cost of the opposing creature plus twice the blood cost of the opposing creature.", "[creature] 的攻擊力等於對面生物的骨頭費用，加上其鮮血費用的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boned", "定骨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of bones the owner possessed when the bearer was placed. Does not fluctuate with bone count changes post placement.", "此印記代表的數值等於此卡牌被放置時，擁有者持有的骨頭數量。放置後骨頭數量的變化不會影響此數值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to the number of bones the owner possessed when it was placed. Does not fluctuate with bone count changes post placement.", "[creature] 的生命力等於被放置時，擁有者持有的骨頭數量。放置後骨頭數量的變化不會影響此數值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab Dance", "螃蟹舞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of crustacean tribe creatures on the board, including opponent creatures.", "此印記代表的數值等於檯面上的甲殼類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of crustacean tribe creatures on the board, including opponent creatures.", "[creature] 的攻擊力等於檯面上的甲殼類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damage Dice", "傷害骰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil starts at 3, and will become a random number between 1 and 6 at the start of each subsequent turn.", "此印記代表的數值初始為 3，之後每個回合開始時，會變成 1 至 6 之間的隨機數值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power starts at 3, and will become a random number between 1 and 6 at the start of each subsequent turn.", "[creature] 的攻擊力初始為 3，之後每個回合開始時，會變成 1 至 6 之間的隨機數值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damage Scaling", "天平傷害", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to five minus the amount of damage until you lose the game.", "此印記代表的數值等於五減去你距離落敗還能承受的天平傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to five minus the amount of damage until you lose the game.", "[creature] 的攻擊力等於五減去你距離落敗還能承受的天平傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Director Of The Board", "檯面總監", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards on the board, including opponent cards.", "此印記代表的數值等於檯面上的卡牌數量，包含對手的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the total number of cards on the board, including opponent creatures.", "[creature] 的攻擊力等於檯面上的卡牌總數，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawn Out", "抽牌之力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards you have drawn this turn while it's bearer is on the board.", "此印記代表的數值等於本回合內，此卡牌在檯面上期間你抽到的卡牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of cards you have drawn this turn while it is on the board.", "[creature] 的攻擊力等於本回合內，此卡牌在檯面上期間你抽到的卡牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fabled", "傳奇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to twice the number of rare creatures on the board.", "此印記代表的數值等於檯面上的稀有生物數量的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to twice the number of rare creatures on the board.", "[creature] 的攻擊力等於檯面上的稀有生物數量的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firepower", "火焰之力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of creatures on the board with the Burning sigil.", "此印記代表的數值等於檯面上帶有燃燒印記的生物數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of creatures on the board with the Burning sigil.", "[creature] 的攻擊力等於檯面上帶有燃燒印記的生物數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Follow The Leader", "跟隨領袖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the attack power of the first card in your hand.", "此印記代表的數值等於你手牌中第一張卡牌的攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the attack power of the first card in your hand.", "[creature] 的攻擊力等於你手牌中第一張卡牌的攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greenhorn", "綠芽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to twice the number of Green gems on the owner's side of the board when the bearer was played.", "此印記代表的數值等於此卡牌被打出時，擁有者側檯面上綠色寶石數量的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to twice the number of Green gems on it's owner's side of the board when it was played.", "[creature] 的生命力等於被打出時，擁有者側檯面上綠色寶石數量的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Half Charged", "半充能", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the player's current energy, rounded up.", "此印記代表的數值等於玩家目前能量的一半，向上取整。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to half your current energy, rounded up.", "[creature] 的攻擊力等於你目前能量的一半，向上取整。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand On Heart", "手繫於心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards in your hand.", "此印記代表的數值等於你的手牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to the number of cards in your hand.", "[creature] 的生命力等於你的手牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Health Damage", "生命傷害", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to it's bearer's current health.", "此印記代表的數值等於此卡牌目前的生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to its health.", "[creature] 的攻擊力等於自身的生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herding Beast", "牧群之獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of hooved tribe creatures on the board, including opponent creatures.", "此印記代表的數值等於檯面上的有蹄類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of hooved tribe creatures on the board, including opponent creatures.", "[creature] 的攻擊力等於檯面上的有蹄類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lithophile", "親石者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of terrain cards on the board.", "此印記代表的數值等於檯面上的地形卡數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of terrain cards on the board.", "[creature] 的攻擊力等於檯面上的地形卡數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magicke Power", "魔法力量", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of sigils this card has removed with the Bleach Sigil or Artistic License Sigil.", "此印記代表的數值等於此卡牌透過漂白劑印記或藝術許可印記移除的印記數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of sigils it has removed with the Bleach Sigil or Artistic License Sigil.", "[creature] 的攻擊力等於此卡牌透過漂白劑印記或藝術許可印記移除的印記數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Half Squirrels", "半數松鼠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the number of Squirrels remaining in your side deck. ", "此印記代表的數值等於你的副牌組中剩餘松鼠數量的一半。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to half the number of Squirrels remaining in your side deck.", "[creature] 的攻擊力等於你的副牌組中剩餘松鼠數量的一半。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Hunter", "群獵者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of canine tribe creatures on the board, including opponent creatures.", "此印記代表的數值等於檯面上的犬類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of canine tribe creatures on the board, including opponent creatures.", "[creature] 的攻擊力等於檯面上的犬類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Power", "道具力量", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of items the owner holds.", "此印記代表的數值等於擁有者持有的道具數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of items it's owner holds.", "[creature] 的攻擊力等於擁有者持有的道具數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Power Plus", "強化道具力量", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to twice the number of items the owner holds.", "此印記代表的數值等於擁有者持有的道具數量的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to twice the number of items it's owner holds.", "[creature] 的攻擊力等於擁有者持有的道具數量的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sanguine Bond", "血之羈絆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of sacrifices made on the turn when the bearer was placed.", "此印記代表的數值等於此卡牌被放置的回合中所進行的犧牲次數。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of sacrifices made on the turn when it was placed.", "[creature] 的攻擊力等於此卡牌被放置的回合中所進行的犧牲次數。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sin Eater", "食罪者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of sigils present on the creatures that were sacrificed to play it's bearer.", "此印記代表的數值等於為打出此卡牌而犧牲的生物所帶有的印記總數。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the amount of sigils present on the creatures that were sacrificed to play it.", "[creature] 的攻擊力等於為打出此卡牌而犧牲的生物所帶有的印記總數。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starved", "飢渴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to seven minus the number of cards left in your deck.", "此印記代表的數值等於 7 減去你的牌組中剩餘的卡牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to seven minus the number of cards left in your deck.", "[creature] 的攻擊力等於 7 減去你的牌組中剩餘的卡牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strength In Numbers", "眾志成城", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of creatures bearing this sigil on the board, including opponent creatures.", "此印記代表的數值等於檯面上帶有此印記的生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of creatures bearing the same special damage stat on the board, including opponent creatures.", "[creature] 的攻擊力等於檯面上帶有相同特殊傷害屬性的生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trinket Vitality", "道具生命力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to double the number of items the owner holds.", "此印記代表的數值等於擁有者持有的道具數量的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to twice the number of items it's owner holds.", "[creature] 的生命力等於擁有者持有的道具數量的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "World Wide Web", "萬維網", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of arachnid tribe creatures on the board, including opponent creatures.", "此印記代表的數值等於檯面上的蛛形類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of arachnid tribe creatures on the board, including opponent creatures.", "[creature] 的攻擊力等於檯面上的蛛形類生物數量，包含對手的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abstain", "克制", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dupeglitch", "複製漏洞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sinister Strike", "左斜打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bully", "橫行霸道", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legion", "軍團", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodborn", "血裔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Divination", "占卜", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhume", "掘墓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eternal", "永恆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goated", "山羊祝福", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healer", "治療師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] is played, the opponent is obligated to skip their next turn.", "打出 [creature] 後，對手必須跳過下一個回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, random creatures of the same tribe will be played for free to its left and right.", "打出 [creature] 時，會在左右兩側免費打出隨機同族生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, [creature] will draw opposing creatures in front of itself.", "擁有者的回合開始時，[creature] 會將對方生物牽引到自己正前方。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Afterlife", "往生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a spectral copy of it is created in your hand. This copy lacks the Afterlife sigil, is free, and is both Immaterial and Doomed. ", "[creature] 死亡時，會在你的手牌中生成此卡牌的幽靈複本。此複本沒有往生印記、無需費用，並同時帶有縹緲之物與命定者印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast Resistant", "抗爆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] would take 10 or more damage from a single source, it takes 1 damage instead.", "若 [creature] 即將受到單一來源的 10 點以上傷害，則改為受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lanky", "瘦長", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage directly to the opponent, it will always deal 1 less damage than it should.", "[creature] 直接對對手造成的傷害一律比原本少 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peer Pressure", "同儕壓力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent occupied space.", "每有一個相鄰的位置被佔據，[creature] 就獲得 +1 攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy", "強健", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice [creature] to increase the health of a creature of your choosing by 4.", "犧牲 [creature]，使你選擇的生物增加 4 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Micromachine", "微型機械", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vagrant Spirit", "漂泊之靈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endoskeleton", "內骨骼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletal Beast", "骸骨獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buttress", "扶壁", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil a number of times equal to how many times it damaged another creature this turn.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動，次數等於此卡牌在本回合對其他生物造成傷害的次數。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] does not strike another creature during its turn, it will perish at the start of the owner's next turn.", "若 [creature] 在自己的回合未擊中其他生物，就會在擁有者的下一個回合開始時死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unnatural Contraption", "非自然裝置", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unnatural Cadaver", "非自然屍骸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrot On A Stick", "胡蘿蔔釣竿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind Controller", "意念控制器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycology", "真菌學", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, opposing creatures are drawn into its slot. If two creatures are drawn into the same slot this way, they become merged.", "[creature] 在戰鬥中死亡時，對方生物會被拉入此卡牌的位置。若兩個生物因此被拉入同一位置，就會融合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mutate", "變異", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] destroys another creatre, this gains 1 point. When activated, the owner is presented with a choice of three sigils to augment the card til the end of battle. Selecting a sigil spends points, and the more points accumulated when the sigil is activated, the higher quality the presented sigils will be.", "[creature] 消滅其他生物時，會獲得 1 點數。啟用此印記時，擁有者可以從三個印記中選一個強化此卡牌，持續至戰鬥結束。選擇印記會消耗點數；啟用時累積的點數越多，提供的印記品質越高。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raise Undead", "亡靈召喚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw 3 skeletons from your side deck to your hand.", "打出 [creature] 時，從你的副牌組抽取 3 張骷髏加入手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Growth Factor", "生長因子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another creature is played opposing [creature], this card gains health equal to that creature's health.", "其他生物被打到 [creature] 正對面時，此卡牌獲得等同於該生物生命力的生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shuffle", "洗牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, every card on the board is shuffled into a random space.", "打出 [creature] 時，檯面上的所有卡牌都會被打亂到隨機位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambidextrous", "左右開弓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, you draw an additional card at the start of your turn.", "[creature] 在檯面上時，你的回合開始時額外抽一張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Dependant", "電路依賴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is not within a completed circuit, it will perish.", "若 [creature] 不在完整的電路內，就會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rapid", "迅捷", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move as far as possible in the direction inscribed in the sigil.", "擁有者的回合結束時，[creature] 會沿印記標示的方向盡可能移到最遠處。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resistance", "電阻", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is within a completed circuit, it adds 1 power to the conduits making up the circuit.", "[creature] 位於完整的電路內時，構成該電路的導管會增加 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dig Deep", "深挖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 bone. This number increases by 1 when [creature] kills another creature.", "擁有者的回合結束時，[creature] 產生 1 根骨頭。[creature] 每殺死其他生物一次，此數量就增加 1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Startled", "驚怯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], this card will transform to or from it's alternate form.", "生物移入 [creature] 正對面的位置時，此卡牌會切換成另一形態，或從該形態變回原形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reflexive", "應激反應", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When its owner is dealt damage directly, [creature] will transform to or from it's alternate form.", "擁有者受到直接傷害時，[creature] 會切換成另一形態，或從該形態變回原形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talons", "鉤爪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, choose any card on the board. You may move it to any open space on the same side of the board.", "打出 [creature] 時，選擇檯面上的任意卡牌。你可以將其移至檯面同側的任意空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycobeast", "真菌獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycodaver", "真菌屍骸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Endoskeleton", "綠寶石內骨骼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Endoskeleton", "紅寶石內骨骼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Endoskeleton", "藍寶石內骨骼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may add to a bond, but provides no additional effect.", "[creature] 可以加入契約，但不提供額外效果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures that are a part of a bond containing [creature] will gain flight at the start of each turn.", "每個回合開始時，與 [creature] 同屬一份契約的生物會獲得飛行能力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures that are a part of a bond containing [creature] will heal equal to the number of cards in the bond at the start of the owners turn.", "擁有者的回合開始時，與 [creature] 同屬一份契約的生物會恢復生命力，數值等於契約中的卡牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed bond, fill all empty spaces on the same side of the board with squirrels at the end of turn.", "若 [creature] 位於完整的契約中，回合結束時會以松鼠填滿檯面同側的所有空位。", Language.ChineseTraditional);
        }
    }
    public class AllTheSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AllTheSigils Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Puddle", "酸液灘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A puddle of Acid, dangerous to the touch", "一灘酸液，碰觸十分危險。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jackalope", "鹿角兔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jacka", "傑卡", Language.ChineseTraditional);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abundance", "五穀豐登", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant one tooth per instance of Abundance when killed.", "[creature] 被殺死時，每一層五穀豐登都會提供 1 顆牙齒。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acidic Trail", "酸性軌跡", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil, and deal 1 damage to the opposing creature if it is able to move.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動；若能成功移動，則對正對面的生物造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Brittle", "啟用型脆弱傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 1 energy will allow the owner to give a creature Brittle.", "支付 1 點能量啟用後，擁有者可以給予一個生物脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Explode On Death", "啟用型引爆傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 1 energy will allow the owner to give a creature Explode On Death.", "支付 2 點能量啟用後，擁有者可以給予一個生物引爆者印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Nano Shield", "啟用型奈米護盾傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 1 energy / 2 bones will allow the owner to give a creature Nano Shield.", "支付 1 點能量／2 根骨頭啟用後，擁有者可以給予一個生物身穿裝甲印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Reach", "啟用型跳躍傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 2 energy will allow the owner to give a creature Reach.", "支付 2 點能量啟用後，擁有者可以給予一個生物奮力跳躍印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Agile", "敏捷", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, it will move out of the way.", "[creature] 即將被擊中時，會移開躲避。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Card jumped out of the way to save itself...", "這張卡牌為了保命，跳到一旁躲開了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trail they leave behind, hurts.", "牠們留下的痕跡，碰了很痛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All seeing", "全視之眼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all talking cards on your side of the board get +2 health.", "[creature] 在檯面上時，你這一側檯面上所有會說話的卡牌都獲得 +2 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alternating Scratch", "交替爪擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it will also attack a space adjacent to the attacked slot, the adjacent slot that it will attack will change between left or right at the end of each opponent's turn.", "[creature] 攻擊時，也會攻擊目標卡槽的相鄰位置。這個額外攻擊的位置會在每個對手回合結束時於左側與右側之間切換。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambush", "伏擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "生物移入 [creature] 正對面的位置時，會受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antler Bearer", "鹿角攜帶者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is killed, gain three random hooved tribe cards.", "[creature] 被殺死時，獲得三張隨機有蹄類卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The herd sticks together.", "獸群團結一心。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shielded", "護盾保護", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is dealt damage, the damage dealt is halved, rounded down.", "[creature] 受到的傷害減半，向下取整。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asleep", "休眠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has 0 attack for as long as it has this sigil, at the start of the player's turn this sigil will be removed from [creature].", "[creature] 帶有此印記時，攻擊力為 0。玩家的回合開始時，會從 [creature] 身上移除此印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bait", "魚餌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is played and there is no card opposite of [creature], the opposing creature will move to that spot.", "對方生物被打出時，若 [creature] 正對面沒有卡牌，該生物就會移到該位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noble Sacrifice", "高貴犧牲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is counted as 2 blood rather than 1 blood when sacrificed.", "[creature] 被犧牲時算作 2 點鮮血，而非 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blight", "枯萎", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it subtracts its stat values to the card it was sacrificed for.", "[creature] 被犧牲時，用這次犧牲打出的卡牌會減去此卡牌的屬性數值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Strike", "隨機打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike at opponent slots randomly when it attacks.", "[creature] 攻擊時會隨機攻擊對手的卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blinding Strike", "致盲打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature gains the Random Strikes Sigil.", "[creature] 對其他生物造成傷害時，該生物獲得隨機打擊印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They strike widly...", "牠們胡亂揮擊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Growth", "鮮血成長", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, the amount of blood it is counted as when sacrificed will increase.", "[creature] 攻擊時，犧牲此卡牌可提供的鮮血數量會增加。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is power in the blood.", "鮮血中蘊藏著力量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BloodGuzzler", "鮮血吞噬者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals damage, it gains 1 Health for each damage dealt.", "[creature] 每造成 1 點傷害，就獲得 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain life from the blood.", "從鮮血中獲得生命。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood shifter", "鮮血易形", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another card, it will turn into that card.", "[creature] 殺死其他卡牌時，就會變成該卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bodyguard", "保鑣", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will redirect the initial attack of a card to it, if the attack was targeting a card in an adjacent space.", "若卡牌的首次攻擊鎖定相鄰位置的卡牌，[creature] 會將該次攻擊轉向自己。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A protector, till the very end.", "守護到最後一刻。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier", "投彈蟲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 10 damage to a random creature during the end phase of the owner's turn.", "擁有者的回合結束階段，[creature] 會對隨機一個生物造成 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bond", "情同手足", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any creatures adjacent to [creature] will gain either +1 attack or +1 health, depending on which stat it is closest to.", "[creature] 左側有相鄰卡牌時，此卡牌獲得 +1 攻擊力；右側有相鄰卡牌時，則獲得 +1 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives no bones! Any bones gained from sigils or death will be negated.", "[creature] 不會提供骨頭！由此卡牌的印記或死亡獲得的骨頭都會被抵銷。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature has no bones!", "這個生物沒有骨頭！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Picker", "拾骨者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] kills a creature, it will generate 1 Bone.", "[creature] 殺死生物時，會產生 1 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Shard", "骨頭碎片", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will generate 1 bone when hit, if it lives through the attack.", "[creature] 被擊中且存活時，會產生 1 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A splinter of bone.", "一小片骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Box", "盒中之物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get removed from your deck on death, and a new creature contained within will be added to it.", "[creature] 死亡時會從你的牌組中移除，並把藏在其中的新生物加入牌組。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken", "破碎", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is permanently removed from your deck if it dies.", "[creature] 死亡時，會從你的牌組中永久移除。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is on fire, and will gain 1 power and loose 1 health each upkeep. Blocked by Fire Resistance.", "[creature] 正在燃燒，每到擁有者的回合開始時，都會獲得 1 點攻擊力並失去 1 點生命力。防火可阻止此效果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It rampages while on fire.", "牠在烈火中狂暴。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the towner's turn, [creature] will move in the direction inscribed in the sigil, and drop an acid puddle in their old space.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動，並在原位置留下酸液灘。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] counts as a Chicken.", "[creature] 視為雞。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choreography", "舞步編排", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On activation [creature] will cycle through: don't move, move left and move right. At the end of the owner's turn [creature] will move in the chosen way.", "每次啟用時，[creature] 會依序切換為不動、向左移動、向右移動。擁有者的回合結束時，[creature] 會依照選擇的方式移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coin Finder", "尋幣者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will grant the owner 1 foil.", "擁有者的回合結束時，[creature] 會給予擁有者 1 枚碎箔。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tooth for your thoughts?", "用一顆牙齒換你的心事，如何？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Consumer", "吞食者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it gains 2 health.", "[creature] 殺死其他生物時，獲得 2 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly", "懦夫", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack a card with a power 2 higher than its own.", "[creature] 不會攻擊攻擊力比自身高出超過 2 點的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadly Waters", "致命水域", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will kill cards that attacked over it while it was face-down. Does not affect cards that have Airborne or Made of Stone.", "[creature] 會殺死在此卡牌覆蓋時越過它攻擊的卡牌。對帶有飛空或鐵石心腸印記的卡牌無效。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathburst", "死亡爆發", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 1 damage to each oppsing space to the left, right, and center of it.", "[creature] 死亡時，會對正對面及其左右兩側的位置各造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the Start of its owner's turn [creature] will lose -1 attack and will gain +1 health.", "擁有者的回合開始時，[creature] 的攻擊力 -1、生命力 +1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperation", "絕望之力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is damaged to 1 health, it will gain 3 power.", "[creature] 受到傷害而只剩 1 點生命力時，獲得 3 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When so close to death, it strikes out.", "瀕臨死亡時，牠奮起反擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disease Absorbtion", "疫病吸收", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played, [creature] will take all negative sigils onto itself.", "打出 [creature] 時，會將同側其他卡牌的所有負面印記轉移到自己身上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How Noble.", "真高尚。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dive (Bones)", "下潛（骨頭）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to cause this card to flip face down at the end of the owner's turn.", "支付 2 根骨頭，使此卡牌在擁有者的回合結束時翻為覆蓋狀態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dive (Energy)", "下潛（能量）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 energy to cause this card to flip face down at the end of the owner's turn.", "支付 2 點能量，使此卡牌在擁有者的回合結束時翻為覆蓋狀態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multi-Strike", "多重打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike a card multiple times, if it lives through the first attack. Will not trigger -on attack- or -on damage- effects with the extra strikes.", "若目標卡牌在第一次攻擊後存活，[creature] 會多次攻擊該卡牌。額外攻擊不會觸發「攻擊時」或「造成傷害時」的效果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double scratch", "雙重爪擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it attacks twice and the space right and left of the attacked slot.", "[creature] 攻擊時會攻擊兩次，並攻擊目標卡槽左右兩側的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Blood", "鮮血繪者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing blood is created in your hand.", "打出 [creature] 時，會在你的手牌中生成一張隨機鮮血費用卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Bone", "骨頭繪者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing bone is created in your hand.", "打出 [creature] 時，會在你的手牌中生成一張隨機骨頭費用卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Card", "卡牌繪者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a card relating to it's ice cube parameter (default Stoat) is created in your hand.", "打出 [creature] 時，會根據此卡牌的冰塊參數，在你的手牌中生成對應的卡牌，預設為白鼬。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Jackalope", "鹿角兔子洞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Jackalope is created in your hand.", "打出 [creature] 時，會在你的手牌中生成一張鹿角兔。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Strafe", "移動繪者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] moves, a random card with a movement sigil is created in your hand.", "[creature] 移動時，會在你的手牌中生成一張帶有移動印記的隨機卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Cost", "費用繪者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card that has the same cost type as [creature] is created in your hand.", "打出 [creature] 時，會在你的手牌中生成一張費用類型與 [creature] 相同的隨機卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Energy", "能量繪者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing energy is created in your hand.", "打出 [creature] 時，會在你的手牌中生成一張隨機能量費用卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Mox", "魔思力繪者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing mox is created in your hand.", "打出 [creature] 時，會在你的手牌中生成一張隨機魔思力費用卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Support call", "支援呼叫", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a card from your sidedeck is created in your hand.", "打出 [creature] 時，會在你的手牌中生成一張來自副牌組的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drunk", "醉酒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike a random one of the opposing spaces to the left and right of the space across from it.", "[creature] 會隨機攻擊正對面位置左側或右側的其中一個位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dwarf", "矮化", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it will loose one unit of cost, as well as 1 power and 2 health (can't go below 1 health). A unit is defined as: 1 blood, 3 bones, 3 energy, or all mox.", "抽到 [creature] 時，此卡牌的費用減少一個單位，並失去 1 點攻擊力與 2 點生命力；生命力不會低於 1。一個單位為：1 點鮮血、3 根骨頭、3 點能量，或全部魔思力費用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dying", "瀕死", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will die after X number of turns.", "[creature] 會在 X 個回合後死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To The Slaughter", "送往屠宰場", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] will eat a random Chicken gaining the same amount of attack as the eaten chicken's health, and gaining the same amount of health as the eaten chicken's attack.", "每個回合結束時，[creature] 會隨機吃掉一隻雞，獲得等同於該雞生命力的攻擊力，以及等同於該雞攻擊力的生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric", "電力制導", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] decalres an attack, they will deal half the damage to cards adjacent to the target.", "[creature] 宣告攻擊時，會對目標相鄰的卡牌造成一半傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enforcer", "執法者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will cause adjacent creatures to attack.", "擁有者的回合開始時，[creature] 會使相鄰的生物發動攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enrage", "超頻領袖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will empower adjacent allies, increasing their strenght by 2. However, if they perish while empowered, they are permamently removed from your deck.", "[creature] 使相鄰的友方生物增加 2 點攻擊力。但若牠們在受此強化期間死亡，就會從你的牌組中永久移除。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Entomophage", "噬蟲菌體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 2 additional damage to cards of the insect tribe.", "[creature] 對昆蟲類族群的卡牌額外造成 2 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are a good source of protine I hear.", "聽說牠們是很好的蛋白質來源。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar will help with attacking when it's adjacent allies attack a card.", "使魔會在相鄰友方攻擊卡牌時協助攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fearful", "膽戰心驚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck without it resulting in death, it will be returned to its owner's hand.", "[creature] 受到攻擊且未死亡時，會返回擁有者的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charge", "充能", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 bones to choose an enemy creature that [creature] will strike.", "支付 3 根骨頭，選擇一個敵方生物，由 [creature] 攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "星火燎原", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature will gain the Burning Sigil. The Burning Sigil is define as: Each upkeep, this creature gains 1 strength but looses 1 health.", "[creature] 對其他生物造成傷害時，該生物獲得燃燒印記。燃燒的效果為：該生物的擁有者每次回合開始時，該生物獲得 1 點攻擊力並失去 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, it leaves a deadly mark", "戰鬥結束後，仍留下致命的痕跡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lure", "引誘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause facedown cards to become face up when attacking.", "[creature] 攻擊時，會使覆蓋的卡牌翻為正面朝上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Submerge are brought back to the surface", "下潛者被帶回水面。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature], a targeted card is moved to the owner's side of the board.", "打出 [creature] 時，指定一張卡牌，將其移至擁有者這一側的檯面。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone lord 5", "白骨領主 5", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 5 bones are rewarded instead of 1.", "[creature] 死亡時，會提供 5 根骨頭，而非 1 根。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frightened", "驚恐", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], [creature] will move away from that card to a random free adjacent spot, while prioritizing slots without any opposing creatures.", "生物移入 [creature] 正對面的位置時，[creature] 會遠離該生物，移至相鄰的隨機空位，並優先選擇沒有對面生物的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frightful", "令人生畏", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause opposing creatures to move out of the way when it attacks.", "[creature] 攻擊時，會迫使對方生物移開讓路。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it will gain one unit blood of cost, as well as one attack and two health.", "抽到 [creature] 時，此卡牌的鮮血費用增加一個單位，並獲得 1 點攻擊力與 2 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a large creature you have there", "你那隻生物可真大。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grazing", "放牧", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 1 health if there is no opposing creature.", "擁有者的回合結束時，若正對面沒有生物，[creature] 恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 1 Health at the end of it's owner's turn.", "此生物會在擁有者的回合結束時恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gripper", "夾持者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil, and try to move the opposing creature with it if it can.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動，並在可能時嘗試帶著正對面的生物一起移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trail they leave behind, hurts.", "牠們留下的痕跡，碰了很痛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haste", "匆忙", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack as soon as it gets played on the board if played not during combat.", "若在非攻擊階段打出 [creature]，此卡牌會在進入檯面時立即攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasteful", "急於出手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack as soon as it gets played on the board. It will not attack during normal combat. It will attack at the start of the owner's turn.", "[creature] 進入檯面時會立即攻擊。此卡牌不會在通常的攻擊階段攻擊，而是在擁有者的回合開始時攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herd", "獸群", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will summon a copy of itself each upkeep, up to three times.", "擁有者的回合開始時，[creature] 會在同側隨機空位召喚自身的複本，最多三次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hermit", "隱士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be placed on any terrain card. If it is their sigils and stats will be combined, and a name combination will be created.", "[creature] 可以放在任意地形卡上。若如此做，兩張卡牌的印記與屬性會合併，名稱也會組合在一起。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Tide", "漲潮", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, it will grant the waterborne sigil of cards that are played after it on it's side of the board. Does not affect cards that are Airborne.", "[creature] 在檯面上時，之後打到同側檯面的卡牌會獲得水生印記。對帶有飛空印記的卡牌無效。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The waters rise.", "潮水上漲了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homing", "追蹤", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the opposing slot is empty, and there is a creature in a neighbouring lane, [creature] will attack that creature instead of attacking the opposing slot.", "若正對面的卡槽為空，且相鄰路線上有生物，[creature] 會改為攻擊該生物，而非正對面的卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hoodini", "胡迪尼戲法", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will swap places with the opposing creature.", "打出 [creature] 時，會與正對面的生物交換位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Host", "巢穴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is the host of other creatures. It will give you such creature when struck.", "[creature] 是其他生物的宿主，受到攻擊時會給你體內寄宿的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause the opponant to skip their turn when played.", "打出 [creature] 時，會使對手跳過下一個回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time tic away", "時光之沙不停流逝。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhaustion", "疲憊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The attack of [creature] will be decreased by the same amount as its lost health.", "[creature] 的攻擊力會減少，減少量等於其已失去的生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hyped", "亢奮", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack at the start of the owner's turn in addition to during normal combat.", "[creature] 除了在通常的攻擊階段攻擊，也會在擁有者的回合開始時攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imbuing", "注靈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get specific buffs depending on which tribe is most promenent in the sacrifices that were used to summon it.", "[creature] 會依據為打出此卡牌而犧牲的生物中，數量最多的族類獲得特定增益。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inaccurate", "不精準", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike a random one of the opposing spaces to the left and right of the spaces across from it as well as the space in front of it.", "[creature] 會在正對面及其左右兩側的位置中，隨機選擇一個位置攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Timer", "老將", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the Start of its owner's turn [creature] will gain +1 attack and will take 1 damage.", "擁有者的回合開始時，[creature] 獲得 +1 攻擊力，並受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Injured", "受傷", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is hurt and will lose 1 health each time it declares an attack due to the strain of the injuries.", "[creature] 身負傷勢，每次宣告攻擊都會因傷口牽動而受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instant", "轉瞬即逝", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will perish immediately after its played.", "[creature] 被打出後會立刻死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Launcher", "發射者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will create another creature on a random empty space on the owner's side of the table.", "擁有者的回合結束時，[creature] 會在擁有者側檯面上的隨機空位生成另一個生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lead (Bones)", "牽引（骨頭）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to move this card one slot in the direction inscribed on the sigil.", "支付 2 根骨頭，使此卡牌沿印記標示的方向移動一個卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "one can lead  a horse to water...", "你可以把馬牽到水邊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lead (Energy)", "牽引（能量）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 energy to move this card one slot in the direction inscribed on the sigil.", "支付 2 點能量，使此卡牌沿印記標示的方向移動一個卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leech", "嗜血之蛭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it will heal 1 Health for each damage dealt to a card.", "[creature] 每對卡牌造成 1 點傷害，就恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vigor from blood!", "活力來自鮮血！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Left scratch", "左側爪擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it will also attack the space on the left of the attacked slot.", "[creature] 攻擊時，也會攻擊目標卡槽左側的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Gambler", "生命賭徒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 2 damage to the owner in exchange for a 0 to 6 increase in stats. Failing to pay this cost will result in death.", "擁有者的回合結束時，[creature] 會獲得總計 0 至 5 點的屬性提升，接著對玩家造成 2 點傷害。若玩家承受不起這個代價，就會落敗。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your blood, their strength!", "你的鮮血，牠們的力量！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Linguist", "語言學家", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all talking cards on your side of the board get +1 attack.", "[creature] 在檯面上時，你這一側檯面上所有會說話的卡牌都獲得 +1 攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Low Tide", "退潮", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, it will negate the waterborne sigil of cards that are played after it on it's side of the board.", "[creature] 在檯面上時，會使之後打到同側檯面的卡牌失去水生印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lullaby", "搖籃曲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all opposing creatures gain the asleep sigil.", "[creature] 死亡時，所有對方生物都會獲得休眠印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maneuver", "調遣", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will strafe in the direction inscribed on the sigil if there is a creature in the opposing slot from it. Else it will strafe in the opposite direction inscribed on the sigil.", "擁有者的回合開始時，若正對面的卡槽有生物，[creature] 會沿印記標示的方向移動，否則會往相反方向移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It runs", "牠跑了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Medic", "醫療兵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will try heal 1 damage to a friendly card for each instance of Medic.", "擁有者的回合開始時，[creature] 會隨機選擇一張其他友方卡牌；若該卡牌受傷，每層醫療兵會為其恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A good patching", "好好包紮一下。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Medical Aid", "醫療援助", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the opponent's turn, choose a hurt creature on the owner's side to heal for 1.", "對手的回合結束時，選擇擁有者側一個受傷的生物，恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas", "點石成金", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] kills a creature, it will generate 1 Foil for each instance of Midas the card has.", "[creature] 殺死生物時，此卡牌每一層點石成金都會產生 1 枚碎箔。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bounty, paid in full.", "賞金，分文不少。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mount", "坐騎", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards may be played on top of [creature]. If they are their sigils and stats will be combined, and a name combination will be created.", "卡牌可以打在 [creature] 上。若如此做，兩張卡牌的印記與屬性會合併，名稱也會組合在一起。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power from Movement", "移動之力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will gain 1 power and 1 health if it moved last round.", "擁有者的回合開始時，若 [creature] 在上一回合移動過，就會獲得 1 點攻擊力與 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each move, it grows", "每次移動，都會成長。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nurse", "護理師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the opponent's turn, [creature] will heal any adjacent friendly cards.", "對手的回合結束時，[creature] 會治療所有相鄰的友方卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nutritious", "營養豐富", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it adds 1 power and 2 health to the card it was sacrificed for.", "[creature] 被犧牲時，用這次犧牲打出的卡牌獲得 1 點攻擊力與 2 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature is so full of nutrients, the creature you play comes in stronger!", "那個生物營養滿滿，讓你打出的生物更加強壯！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone hoarder 1", "骨禮 1", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, 1 bone is rewarded.", "打出 [creature] 時，獲得 1 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opportunist", "機會主義者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 1 power for each instance of Opportunist, when the opposing slot is empty.", "正對面的卡槽為空時，[creature] 每一層機會主義者都會提供 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It takes it's chance when it gets it.", "機會來了，牠就把握。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paralysis", "癱瘓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will only attack every other turn. Some effects from sigils may bypass this.", "[creature] 每隔一回合才會攻擊。有些印記效果可以繞過此限制。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A shocking event.", "令人震驚的事。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasite", "寄生蟲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be placed on top of any card. If it is their sigils and stats will be combined, and a name combination will be created.", "[creature] 可以放在任意卡牌上。若如此做，兩張卡牌的印記與屬性會合併，名稱也會組合在一起。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pathetic Sacrifice", "可悲祭品", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is so pathetic, it is not a worthy or noble sacrifice. [creature] is meant to stay on the board, and thus can't be targeted by the hammer.", "[creature] 太過可悲，連成為祭品的資格都沒有。[creature] 只能留在檯面上，也無法成為錘子的目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is not a noble, or worthy sacrifice", "這稱不上高貴或合格的祭品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picky", "挑剔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannnot be summoned by using any free cards as sacrifice.", "不能使用任何免費卡牌作為祭品來召喚 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pierce", "貫穿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] attacks the card in queue behind it's initial target first when declaring an attack.", "[creature] 宣告攻擊時，會先攻擊原目標後方排隊中的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My creatures!", "我的生物！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poisonous", "有毒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature that killed it perishes as well.", "[creature] 死亡時，殺死此卡牌的生物也會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attacking something poisonous, isn't that smart.", "攻擊有毒的東西，可不聰明。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessor", "附身者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it will grant a random friendly card that is on the board it's base power and health.", "[creature] 死亡時，會將自身的基礎攻擊力與基礎生命力加到檯面上隨機一張其他友方卡牌上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It passes it's strength onto those who remain", "牠將力量傳給留下來的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powerful Possessor", "強力附身者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it will grant a random friendly card that is on the board it's base plus modified power and base plus modified health.", "[creature] 死亡時，會將自身基礎值加上修正值後的攻擊力與生命力，加到檯面上隨機一張其他友方卡牌上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Predator", "掠食者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 1 power for each instance of Predator, when the opposing slot has a card.", "正對面的卡槽有卡牌時，[creature] 每一層掠食者都會提供 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prideful", "驕傲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack a card with a power 2 lower than its own.", "[creature] 不會攻擊攻擊力比自身低了超過 2 點的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creature's pride will be it's downfall.", "生物的驕傲會成為牠的敗因。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "保護者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attacks on adjacent allies to hit directly.", "[creature] 會使對相鄰友方的攻擊改為直接攻擊其擁有者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They protect their allies, but who protects you?", "牠們保護盟友，但誰來保護你？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppets gift", "木偶之禮", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is on the board any cards with brittle won't die because of brittle.", "只要 [creature] 在檯面上，帶有脆弱印記的卡牌就不會因脆弱而死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Superior Sacrifice", "超凡祭品", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is counted as 4 blood rather than 1 blood when sacrificed.", "[creature] 被犧牲時算作 4 點鮮血，而非 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ram", "衝撞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will try to ram the card infront of it when played, or every upkeep till it succeeds once. It will send the rammed target to the queue if on my side, or back to the hand if on your side. Does not work during combat.", "打出 [creature] 時會嘗試衝撞正對面的卡牌，之後每逢擁有者的回合開始時也會嘗試，直到成功一次。被撞中的卡牌若在對手側，便退回後排隊列；若在玩家側，便返回手牌。攻擊階段無效。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moving creatures around? How Rude!", "擅自移動生物？真沒禮貌！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Strafe", "隨機移動", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is drawn, it will gain a random strafe sigil.", "抽到 [creature] 時，會隱藏此印記並獲得一個隨機移動印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How will it move?", "牠會如何移動？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recoil", "後座力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will take 1 damage each time they attack.", "[creature] 每次攻擊都會受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The strength causes the creature pain.", "這股力量讓生物承受痛苦。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen 1", "再生 1", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 1 health.", "擁有者的回合結束時，[creature] 恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 1 Health at the end of it's owner's turn.", "此生物會在擁有者的回合結束時恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen 2", "再生 2", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 2 health.", "擁有者的回合結束時，[creature] 恢復 2 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 2 Health at the end of it's owner's turn.", "此生物會在擁有者的回合結束時恢復 2 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen 3", "再生 3", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 3 health.", "擁有者的回合結束時，[creature] 恢復 3 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 3 Health at the end of it's owner's turn.", "此生物會在擁有者的回合結束時恢復 3 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen", "再生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen to full health.", "擁有者的回合結束時，[creature] 恢復全部生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal to full Health at the end of it's owner's turn.", "此生物會在擁有者的回合結束時恢復全部生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repellant", "排斥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature that killed it gets pushed into the back row.", "[creature] 死亡時，殺死此卡牌的生物會被推回後排。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resistant", "耐性", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will only ever take 1 damage from most things. Some effects might bypass this.", "[creature] 從大多數來源只會受到 1 點傷害。有些效果可能繞過此限制。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hardy creature that one is.", "真是個頑強的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resourceful", "資源豐富", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, instead of dying, it loses a random sigil. Resourceful will only remove itself when there are no other sigils on the card.", "[creature] 被犧牲時不會死亡，而是失去一個隨機印記。只有卡牌上沒有其他印記時，資源豐富才會移除自身。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retaliate", "還擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike those who strike their adjacent allies.", "[creature] 會攻擊襲擊相鄰友方的攻擊者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right scratch", "右側爪擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it will also attack the space on the right of the attacked slot.", "[creature] 攻擊時，也會攻擊目標卡槽右側的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rushing march", "急行軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move in the direction inscribed on the sigil, however if it hits a card whilst moving, [creature] will stop and the card it hit will perish.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動。若移動時撞上卡牌，[creature] 就會停下，被撞的卡牌則會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Schooling", "魚群協同", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant creatures with the waterborn 1 power.", "[creature] 使帶有水生印記的生物獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The waterborn stick together.", "水生生物團結一心。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a targeted card cut in two.", "打出 [creature] 時，將指定的卡牌剪成兩半。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My card!", "我的卡牌！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shapeshifter", "變形者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is ever changing. It will change its form once it's struck.", "[creature] 變幻無常，受到攻擊後就會改變形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Short", "矮小", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not be blocked by an opposing creature bearing the airborn sigil.", "帶有飛空印記的對面生物無法阻擋 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sickness", "疾病肆虐", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will loose 1 attack each time it declares an attack.", "[creature] 每次宣告攻擊都會失去 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature's strength leaves it as it strikes.", "生物出手時，力量也隨之流失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone lord 6", "白骨領主 6", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 6 bones are rewarded instead of 1.", "[creature] 死亡時，會提供 6 根骨頭，而非 1 根。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sluggish", "遲緩", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack during normal combat. It will instead attack after the Opponent's cards attack.", "[creature] 不會在通常的攻擊階段攻擊，而是在對手的卡牌攻擊後才攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bit slow there eh?", "動作有點慢啊，嗯？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Song of sleep", "安眠曲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a creature moves into the space opposing [creature], that creature will obtain the asleep sigil.", "生物移入 [creature] 正對面的位置時，該生物會獲得休眠印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawner", "繁殖移動", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move in the direction inscribed on the sigil and will create another creature in its old space.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動，並在原位置生成另一個生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stampede", "群起奔襲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause adjacent creatures to attack when played on the board if played not during combat.", "若在非攻擊階段打出 [creature]，此卡牌會使相鄰的生物發動攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power in Numbers", "人多力量大。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky", "如膠似漆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the card opposing [creature] moves, [creature] will try to move with it", "[creature] 正對面的卡牌移動時，[creature] 會嘗試跟著移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velocity", "風馳電掣", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. If it is able to move, it will gain 1 power and 1 health.", "擁有者的回合結束時，[creature] 會沿印記標示的方向移動。若成功移動，就獲得 1 點攻擊力與 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Wind", "強風", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is on the board, negate the airbone sigil of all cards that are played after it.", "[creature] 在檯面上時，會使之後打出的所有卡牌失去飛空印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Wind forces a landing.", "強風迫使牠們落地。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerged Ambush", "水下伏擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 1 damage to cards that attacked over it while it was face-down. Does not affect cards that are Airborne.", "[creature] 會對在此卡牌覆蓋時越過它攻擊的卡牌造成 1 點傷害。對帶有飛空印記的卡牌無效。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strikes from the water.", "牠從水中發動攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swallower", "吞噬者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] attacks, it will destroy the card it attacks if it has less health than it and heal to full health.", "[creature] 對卡牌造成傷害後，若目標仍存活、生命力低於此卡牌且沒有鐵石心腸，便會消滅目標並恢復全部生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gone in one gulp.", "一口吞掉。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sympathetic", "憐憫", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will only attack if the opposing creature has more or equal health to it.", "只有正對面生物的生命力大於或等於自身時，[creature] 才會攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take-Off (Bones)", "起飛（骨頭）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to give this card Airborne till the start of owner's next turn.", "支付 2 根骨頭，使此卡牌獲得飛空，持續至擁有者的下一個回合開始。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spread your wings and fly.", "展翅高飛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take-Off (Energy)", "起飛（能量）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 energy to give this card Airborne till the start of the owner's next turn.", "支付 2 點能量，使此卡牌獲得飛空，持續至擁有者的下一個回合開始。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrified", "驚慌失措", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], [creature] will move away from that card to a random free adjacent spot while pushing any creatures in it's way, while prioritizing slots without any opposing creatures.", "生物移入 [creature] 正對面的位置時，[creature] 會遠離該生物，移至相鄰的隨機空位，同時推開擋路的生物，並優先選擇沒有對面生物的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thick Shell", "厚重甲殼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, [creature] takes 1 less damage.", "[creature] 受到攻擊時，受到的傷害減少 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick shell on that creature protected it from one damage!", "那個生物的厚重甲殼擋住了 1 點傷害！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will try to steal a random default sigil from a card in the opposing lane when played, or at the start of the owner's turn until it does.", "打出 [creature] 時，會嘗試從正對面路線的卡牌偷取一個隨機原有印記；之後每逢擁有者的回合開始時都會再嘗試，直到成功。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If only I could steal the moon...", "要是連月亮都能偷走就好了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone prince 3", "骨王子 3", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 3 bones are rewarded instead of 1.", "[creature] 死亡時，會提供 3 根骨頭，而非 1 根。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone hoarder 3", "骨禮 3", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, 3 bones are rewarded.", "打出 [creature] 時，獲得 3 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tooth Bargain", "牙齒交易", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will put 1 point of damage of it's opponent's side of the scale. When it perishes, it will put 2 damage on the owner's side of the scale.", "打出 [creature] 時，會在對手的天平一側增加 1 點傷害。此卡牌死亡時，會在擁有者的天平一側增加 2 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deal with a devil I see...", "看來是和魔鬼做了交易……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toothpuller", "拔牙者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will add one point of damage to the opponent's scale.", "擁有者的回合結束時，[creature] 會在對手的天平一側增加 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That Hurts", "很痛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tooth Shard", "牙齒碎片", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will generate 1 foil when hit, if it lives through the attack.", "[creature] 被擊中且存活時，會產生 1 枚碎箔。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A splinter of gold.", "一小片金子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin", "混合毒素", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature looses 1 power and 1 health.", "[creature] 對另一個生物造成傷害時，該生物失去 1 點攻擊力和 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All things can be worn down, and in different ways.", "萬物都會磨損，方式各有不同。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Deadly)", "致命毒素", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature gains the Dying Sigil. The Dying Sigil is defined as: [creature] will die after 2 number of turns.", "[creature] 對另一個生物造成傷害時，該生物獲得奄奄一息印記。奄奄一息的效果是：[creature] 將在 2 回合後死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, it leaves a deadly mark", "戰鬥結束後，仍留下致命的痕跡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Sickening)", "致病毒素", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature gains the Sickness Sigil. The Sickness Sigil is defined as: When ever a creature bearing this sigil declares an attack, they will loose one attack.", "[creature] 對另一個生物造成傷害時，該生物獲得疾病肆虐印記。疾病肆虐的效果是：帶有此印記的生物每次宣告攻擊時，失去 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, it leaves sickness spreads in what it fights.", "即使戰鬥結束，疾病仍在對手身上蔓延。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Strength)", "力量毒素", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature looses 1 power.", "[creature] 對另一個生物造成傷害時，該生物失去 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, strength leaves it's target", "即使戰鬥結束，目標的力量也會流失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Vigor)", "活力毒素", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature looses 1 health.", "[creature] 對另一個生物造成傷害時，該生物失去 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trample", "踐踏", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals overkill damage to a card, the overkill damage will be sent to the owner.", "[creature] 對卡牌造成過量傷害時，超出的傷害會傳給該卡牌的擁有者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stampede can not be stopped.", "奔騰的獸群勢不可擋。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transform Chicken (Enemy Only)", "易形雞（僅敵人）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will transform a random creature on the board on the opponent's side into a Chicken. A Chicken is defined as 1 Attack, 1 Health.", "每個回合結束時，[creature] 會將對手一側檯面上的隨機一個生物變成雞。雞的數值為 1 攻擊力、1 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transform Chicken (Loose Cannon)", "易形雞（不分敵我）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will transform a random creature on the board into a Chicken. A Chicken is defined as 1 Attack, 1 Health.", "每個回合結束時，[creature] 會將檯面上的隨機一個生物變成雞。雞的數值為 1 攻擊力、1 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transform Chicken (Opposing)", "易形雞（對面）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played opposing [creature] it will turn into a Chicken. A Chicken is defined as 1 Attack, 1 Health.", "在 [creature] 正對面打出生物或有生物移入該位置時，該生物會變成雞。雞的數值為 1 攻擊力、1 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transient", "曇花一現", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will return to your hand.", "擁有者的回合結束時，[creature] 會返回你的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature blinks back into the owner's hand at the end of their turn.", "回合結束時，生物會閃回擁有者的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribal Ally", "族類盟友", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, A card of the same tribe is created in your hand. No tribe counts as a tribe of tribeless.", "打出 [creature] 時，會在你的手牌中產生一張同族類的卡牌。無族類視為一個「無族類」族類。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It calls for it's kin.", "它呼喚自己的同類。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribal Tutor", "族類搜尋", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may search your deck for a card of the same tribe and take it into your hand. No tribe counts as a tribe of tribeless.", "打出 [creature] 時，你可以從牌組中搜尋一張同族類的卡牌並加入手牌。無族類視為一個「無族類」族類。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribe Attack", "族類攻擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all other cards on your side of the board of the same tribe will gain +1 attack.", "[creature] 在檯面上時，你這一側的其他同族類卡牌都獲得 +1 攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribe Health", "族類生命", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all other cards on your side of the board of the same tribe will gain +1 health.", "[creature] 在檯面上時，你這一側的其他同族類卡牌都獲得 +1 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turbulent Waters", "混沌水域", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will force other creatures with waterborne to resurface and take 1 damage at the start of the owner's turn.", "擁有者的回合開始時，[creature] 會迫使其他帶有水生印記的生物浮出水面並受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The waters be rough.", "水面波濤洶湧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone prince 2", "骨王子 2", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 2 bones are rewarded instead of 1.", "[creature] 死亡時，獎勵 2 根骨頭，而非 1 根。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone hoarder 2", "骨禮 2", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, 2 bones are rewarded.", "打出 [creature] 時，獎勵 2 根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Underdog", "弱勢者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can only be played when you are losing.", "只有在你處於劣勢時才能打出 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vicious", "兇相畢露", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is attacked, it gains 1 power.", "[creature] 遭到攻擊時，獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hit just makes it angry.", "攻擊只會惹怒它。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warper", "穿場者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move to the right, jumping over any creatures in its path, if it encounters the edge of the board, it will loop over to the other side.", "擁有者的回合結束時，[creature] 會向右移動，跳過路徑上的所有生物。若到達檯面邊緣，則繞至另一側。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wild hunger", "狂野饑餓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move in the direction inscribed on the sigil, however if it hits a card whilst moving, [creature] will stop, the card it hit will perish and [creature] will gain 1+/1+.", "擁有者的回合結束時，[creature] 會朝印記標示的方向移動。若 [creature] 撞上卡牌，便會消滅對方並獲得 +1 攻擊力與 +1 生命力；若位置空出，[creature] 會移入該位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withering", "凋零", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will perish at the end of the opponant's turn.", "對手回合結束時，[creature] 會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zapper", "癱瘓之觸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature will gain the Paralysis Sigil. The Paralysis sigil is defined as: A card bearing this sigil will only attack every other turn.", "[creature] 對另一個生物造成傷害時，該生物獲得癱瘓印記。癱瘓的效果是：帶有此印記的卡牌每隔一回合才會攻擊。", Language.ChineseTraditional);
        }
    }
    public class BittysSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for BittysSigils Mod");
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides. No Eggs for you.", "兩側都被擋住了。沒有蛋給你。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No empty spaces. No firs for you.", "沒有空位。沒有冷杉給你。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive Squirrel Reproduction", "松鼠爆發式繁殖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, fill your side deck with squirrels.", "打出 [creature] 時，用松鼠填滿你的副牌組。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hauler", "搬運者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Adjacent friendly creatures will be pulled in the same direction.", "擁有者的回合結束時，[creature] 會朝印記標示的方向移動，相鄰的友方生物也會被拉向同一方向。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Swap", "心靈交換", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards on the board swap their power and health.", "打出 [creature] 時，檯面上所有卡牌的攻擊力與生命力互換。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mutual Hire", "相互雇用", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it is created in the opposing space.", "打出 [creature] 時，會在正對面的位置產生其副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charged Barrage", "充能彈幕", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 life to increase the power of all cards on your side of the board by 1.", "支付 4 點生命，使你這一側檯面上的所有卡牌各增加 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Health Roll", "生命骰子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to set the health of [creature] randomly between 1 and 6.", "支付 1 點能量，將 [creature] 的生命力設為 1 至 6 之間的隨機值。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigil Roll", "印記骰子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Life to add a random sigil to [creature].", "支付 4 點生命，為 [creature] 添加一個隨機印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wildlife Camera", "野獸相機", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another card, a copy of the killed card is created in your hand.", "[creature] 殺死另一張卡牌時，在你的手牌中產生被殺卡牌的副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dusty Quill", "塵封羽筆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a creature dies while [creature] is on the board, a corpse is raised in it's place. Corpses are defined as: 0/1.", "[creature] 在檯面上時，每當生物死亡，就在其位置生成一具屍體。屍體的數值為 0/1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleached Brush", "漂白之筆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing card will lose all its sigils.", "打出 [creature] 時，正對面的卡牌失去所有印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Soul", "強韌靈魂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve sigils from another card.", "[creature] 不能接收來自其他卡牌的印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Soul", "虛弱靈魂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not have its sigils transferred to another card.", "[creature] 的印記不能轉移至其他卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nonexistent Soul", "虛無靈魂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not have sigils transferred to, or from this card.", "印記不能轉入或轉出 [creature]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrophobia", "恐火症", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not be buffed at campsites.", "[creature] 不能在營火處獲得增益。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrophobia (Attack)", "恐火症（攻擊力）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve power buffs from campsites.", "[creature] 不能從營火獲得攻擊力增益。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrophobia (Health)", "恐火症（生命力）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve health buffs from campsites.", "[creature] 不能從營火獲得生命力增益。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repulsion", "排斥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not attack.", "[creature] 不能攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Mushrooms", "神秘蘑菇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, if there is a card on either side of [creature], they are fused together.", "擁有者的回合結束時，若 [creature] 左右任一側有卡牌，該側卡牌會與此卡牌融合；兩側分別判定。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move the opposing card and itself in the direction inscribed in the sigil.", "擁有者的回合結束時，[creature] 會將自己和正對面的卡牌一同移向印記標示的方向。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counter Attack", "反擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, the striker is then dealt damage equal to this card's attack.", "[creature] 受到攻擊時，攻擊者受到等同於此卡牌攻擊力的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Counter", "鏡面反擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, the striker is then dealt damage equal to the striker's attack.", "[creature] 受到攻擊時，攻擊者受到等同於其自身攻擊力的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Shifter", "全場移位", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. All cards will shift in the same direction, looping to the other edge of the board.", "擁有者的回合結束時，[creature] 會朝印記標示的方向移動。所有卡牌都會朝同一方向移動，並繞至檯面的另一側。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Shifter (Owner)", "全場移位（友方）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Friendly cards will shift in the same direction, looping to the other edge of the board.", "擁有者的回合結束時，[creature] 會朝印記標示的方向移動。友方卡牌都會朝同一方向移動，並繞至檯面的另一側。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Shifter (Opposing)", "全場移位（對面）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. The opposing cards will shift in the same direction, looping to the other edge of the board.", "擁有者的回合結束時，[creature] 會朝印記標示的方向移動。對方卡牌都會朝同一方向移動，並繞至檯面的另一側。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathbell", "喪鐘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the battle phase, [creature] perishes.", "擁有者的戰鬥階段開始、鐘聲響起時，[creature] 會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clockwise", "順時針", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, move all cards on the board clockwise.", "打出 [creature] 時，檯面上所有卡牌順時針移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stubborn", "頑固", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not have its stats swapped.", "[creature] 的屬性不能交換。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] is on the board, move all cards on the board clockwise.", "每個回合結束時，只要 [creature] 在檯面上，就將檯面上所有卡牌順時針移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fleeting", "稍縱即逝", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn [creature] will be discarded from your hand.", "回合結束時，[creature] 會從你的手牌中被棄置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Link", "靈魂連結", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all other allied cards bearing this sigil perish as well.", "[creature] 陣亡時，所有其他帶有此印記的友方卡牌也會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Draw", "空洞抽取", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, discard the oldest card in your hand, draw a card.", "打出 [creature] 時，棄置手牌中最早的一張牌，然後抽一張牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Barrage", "空洞彈幕", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards take 1 damage.", "打出 [creature] 時，所有卡牌受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Phobic", "寶石恐懼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls a Mox card, [creature] perishes.", "若 [creature] 的擁有者控制一張魔思力卡牌，[creature] 便會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foolhardy", "魯莽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve modifications from any source.", "[creature] 不能接受任何來源的修改。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jumper", "跳躍者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move itself to the first empty space in the direction inscribed in the sigil.", "擁有者的回合結束時，[creature] 會朝印記標示的方向移動到第一個空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Super Sprinter", "超級衝刺者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move itself as far as possible in the direction inscribed in the sigil.", "擁有者的回合結束時，[creature] 會朝印記標示的方向盡可能遠地移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eggist", "蛋之藝術", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on each empty adjacent space.", "打出 [creature] 時，在每個相鄰空位各產生一顆蛋。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fir Caller", "喚林者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Fir is created in each of the owner's spaces.", "打出 [creature] 時，在擁有者一側的每個空位各產生一棵大冷杉。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flipper", "翻轉者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] swaps its stats.", "擁有者的回合結束時，[creature] 會交換自己的屬性。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fleeting Draw", "稍縱即逝抽牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw 1 card with Fleeting.", "打出 [creature] 時，抽 1 張帶有稍縱即逝印記的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Outcast", "流放者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] is shuffled into the deck.", "回合結束時，[creature] 會被洗入牌組。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Repeater", "空洞中繼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all On Play sigils on that card are activated.", "[creature] 陣亡時，該卡牌上所有打出時觸發的印記都會啟動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replenish", "補充", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, draw a card.", "抽到 [creature] 時，抽一張牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Target Swap", "目標交換", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Target a Card: the card's stats are swapped.", "打出 [creature] 時，指定一張卡牌：交換該卡牌的屬性。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificial Growth", "獻祭成長", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it will grow into a more powerful form.", "[creature] 被犧牲時，會成長為更強大的形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Transformer", "紅寶石變形者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls a Ruby Mox, [creature] will be transformed; otherwise [creature] will transform into its base form.", "若 [creature] 的擁有者控制紅寶石魔思力，[creature] 便會變形；否則 [creature] 會變回基本形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gemify", "寶石化", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains buffs based on moxes in play on the owner's side. Orange is 1 Power. Green is 2 Health. Blue is lower Cost.", "[creature] 根據擁有者一側檯面上的魔思力獲得增益：橘色提供 1 點攻擊力，綠色提供 2 點生命力，藍色降低費用。", Language.ChineseTraditional);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corpse", "屍體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TestCard", "測試卡牌", Language.ChineseTraditional);
        }
    }
    public class BittysChallengesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for BittysChallenges Mod");
            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that a clover?", "那是三葉草嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see.", "原來如此。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh?", "哦？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you not like having a stacked deck?", "你不喜歡被動過手腳的牌組嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's fine with me.", "我無所謂。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will be more fair this way anyways.", "反正這樣會更公平。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "oh?", "哦？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my very own ouroboros.", "屬於我自己的銜尾蛇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "i will be sure to put it to good use.", "我一定會好好利用它。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros has followed you.", "銜尾蛇追隨你而來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it's fangs are beared, and it's ready for another fight.", "它露出獠牙，準備再次戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the unyielding ouroboros has returned,", "不屈的銜尾蛇回來了，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "growing stronger every death.", "每次死亡都令它更加強大。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "as inevitable as death,", "如同死亡般不可避免，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros has returned.", "銜尾蛇回來了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a serpent slithers out from the undergrowth.", "一條蛇從灌木叢中蜿蜒而出。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "perhaps you have seen it before?", "你或許見過它？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros has died.", "銜尾蛇死了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and yet, it will return.", "然而，它終將歸來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the serpent's wrath has been delayed.", "蛇的怒火暫且被延後了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for now.", "目前是如此。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros only grows stronger from death.", "銜尾蛇只會因死亡而更加強大。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it will be back.", "它會回來的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a-ah, the sigils...", "啊、啊，這些印記……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "o-oh, the power...", "喔、喔，這股攻擊力……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a-ah, the health...", "啊、啊，這生命力……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah...", "啊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chrysomallos, the golden ram.", "金羊，黃金公羊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what a glorious pelt....", "多麼華美的毛皮……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The golden ram.", "金色的公羊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "catch it before it escapes.", "趁它逃走前抓住它。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a rare sight", "難得一見", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it will not stay for long", "它不會久留", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what glittering wool,", "多麼閃亮的羊毛，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "attached to such a rare creature.", "竟長在如此稀有的生物身上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "oh?", "哦？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a rare chance to get a rare pelt.", "這是獲得稀有毛皮的難得機會。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "best make the most of it.", "最好把握機會。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You slay the glimmering creature, stealing its pelt.", "你殺死了閃閃發光的生物，奪走了它的毛皮。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The end of such a glorious creature.", "如此華麗的生物就此殞命。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And what a glorious pelt you have obtained.", "而你獲得了多麼華美的毛皮。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chrysomallos...", "金羊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How tragic your tale is...", "你的故事何等悲慘……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To be killed for your pelt...", "竟因毛皮而遭殺害……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Golden Ram lives another day.", "金羊又多活了一天。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time's up.", "時間到了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Golden Ram has found an escape route.", "金羊找到了一條逃脫路線。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The glimmer of the Golden Ram's fur blinds you,", "金羊皮毛的光芒晃花了你的眼，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "giving it the opportunity to escape.", "讓它有機會逃走。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "啊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [v:0] has taken a devastating blow from the [v:1].", "你的 [v:0] 受到 [v:1] 的毀滅性打擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will not be able to take it with your caravan.", "你將無法把它帶進你的隊伍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "啊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You won't be seeing your [v:0] again,", "你再也見不到你的 [v:0] 了，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It has taken too much damage.", "它受了太多傷。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "啊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you permanently kill your [v:0] on purpose?", "你是故意讓你的 [v:0] 永久死亡的嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A shame...", "真可惜……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha! There be my first mate!", "哈！我的大副來了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argh! There be snakes on me ship as well!", "啊！我的船上也有蛇！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha!", "哈！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I should hire ye to get rid of the rest of them!", "我該雇你把剩下的也清理掉！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha! It's dead!", "哈！它死了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what?", "什麼？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirates?", "海盜？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll allow it.", "准了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what?", "什麼？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cheating?", "作弊？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how dissapointing...", "真令人失望……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the game will be soured from a pitifully easy ascent.", "如此輕而易舉的攀升會敗壞這場遊戲的興致。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cheater...", "作弊者……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you no shame?", "你難道不知羞恥嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To cheat so blatantly...", "如此明目張膽地作弊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you should be dead.", "你本該死了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and yet...", "然而……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how dissapointing...", "真令人失望……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't tolerate this for much longer...", "我不會再容忍太久……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enough of this.", "夠了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yer not dead?", "你沒死？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah...", "啊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "back to normal then?", "那麼，恢復正常了？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll admit, I had gotten used to the changes...", "我得承認，我已經習慣那些變化了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Cards?", "虛弱卡牌？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is hard to explain...", "這很難解釋……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps they are sick? Yes.", "或許牠們生病了？沒錯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A crippling disease afflicted your meager troupe of creatures.", "一種使人虛弱的疾病侵襲了你那可憐的生物隊伍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterborne Cards?", "水生卡牌？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is hard to explain...", "這很難解釋……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps a mutation? Yes.", "或許是變異？沒錯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your caravan of creatures had a startling mutation,", "你的生物隊伍發生了驚人的變異，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They could only survive in the water.", "牠們只能在水中存活。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paralyzed Cards?", "癱瘓卡牌？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm...", "嗯……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your group of creatures were fatigued from the long journey,", "你的生物們因長途跋涉而疲憊，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "but there would be a long way to go yet.", "但前方仍有漫長的路要走。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Souled Cards?", "虛弱靈魂卡牌？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm...", "嗯……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will not be able to extract their souls into new creatures,", "你將無法將牠們的靈魂萃取到新的生物中，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For better or worse...", "無論是好是壞……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lives of past challengers weighed down on you...", "過往挑戰者的生命令你背負重擔……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "嗯？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How to explain this...", "該怎麼解釋呢……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You were running low on supplies that day...", "那天你的補給快要用盡了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll have fewer [c:G][v:0]s[c:] to work with.", "你能使用的 [c:G][v:0][c:] 會更少。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "嗯？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abundance of [c:G][v:0]s[c:]...", "大量的 [c:G][v:0][c:]……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Must be mating season...", "想必是交配季節到了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "嗯？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environmental effects?", "環境影響？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how interesting...", "真有意思……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In order to proceed,", "為了繼續前行，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you had to slog through the wetter parts of the swamp.", "你必須艱難地穿過沼澤中更加濕濘的地帶。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick[c:G][c:G]mud[c:] stuck to your boots, and hindered your movements...", "濃稠的[c:G][c:G]泥沼[c:]黏在你的靴子上，阻礙了你的行動……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frigid air was not the only obstacle in your way,", "刺骨的寒風並非你前進路上唯一的障礙，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the harsh ice and unforgiving snow also stood in your path.", "嚴酷的冰與無情的雪也橫亙在你的路上。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "before long you found yourself in...", "不久之後，你發現自己置身於……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a [c:B]hailstorm.[c:]", "一場[c:B]冰雹風暴。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You found yourself cornered against a sheer rock wall,", "你發現自己被逼到一面陡峭的石壁前，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the [c:G]cliffside.[c:]", "一處[c:G]懸崖邊。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Against the cold stone, there would be less space to fight.", "背靠冰冷的岩石，戰鬥的空間將更加狹小。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mycologists had left one of their experiments behind,", "真菌學家留下了一件實驗品，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "unbeknownst to them, it began to fester and grow.", "他們不知道的是，實驗品開始腐爛並生長。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "even the creatures fighting you would not be safe from the [c:G]fungal mass.[c:]", "即使是與你戰鬥的生物，也難逃[c:G]真菌團塊。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You stumbled across one of the Prospector's Camps.", "你偶然發現了礦工的一處營地。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The camp was filled with prospecting tools.", "營地裡堆滿了採礦工具。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "pickaxes, headlamps...", "礦鎬、頭燈……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and [c:bR]dynamite.[c:]", "還有[c:bR]炸藥。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came across one of the Angler's Ponds.", "你來到了釣魚人的一處池塘。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the area stank of rotting fish", "附近瀰漫著腐魚的惡臭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emanating from the nearby abandoned buckets of [c:dB]bait.[c:]", "那是從附近廢棄的[c:dB]魚餌[c:]桶中散發出來的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came across one of the Trapper's Hunting Grounds.", "你來到獵人的一處狩獵場。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the stench of blood hung in the air...", "空氣中瀰漫著血腥味……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you noticed the numerous [c:G]traps[c:] lying in wait.", "你注意到許多[c:G]陷阱[c:]正埋伏在那裡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came upon a strange [c:bR]totem.[c:]", "你遇到了一座奇怪的[c:bR]圖騰。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious energy swirled around it,", "神秘的能量在它周圍盤旋，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the creatures nearby seem more agressive than usual...", "附近的生物似乎比平常更加好鬥……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "啊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a [c:bR]Blood Moon.[c:]", "一輪[c:bR]血月。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Er...", "呃……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You...", "你……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...What?", "……什麼？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am at a loss for words.", "我無言以對。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wind was howling around you.", "狂風在你四周呼嘯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuck in the middle of a blizzard,", "你被困在暴風雪之中，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You heard rumbling from the mountains above.", "聽見上方山脈傳來隆隆巨響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here it comes...", "來了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "an [c:B]avalanche.[c:]", "一場[c:B]雪崩。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You stumble across a strange black stone.", "你偶然發現一塊奇怪的黑色石頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stone tablet sits in front of it, clearly made for sacrifices.", "它面前有一塊石板，顯然是用來獻祭的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps a certain creature may cause a reaction?", "或許某種生物能引起反應？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The obelisk trembles in delight.", "方尖碑因喜悅而震顫。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A goat is truly a worthy sacrifice.", "山羊的確是值得獻上的祭品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You won't be seeing it again.", "你再也見不到它了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The obelisk rumbles with anger.", "方尖碑因憤怒而隆隆震動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pelt is a truly pitiful sacrifice.", "毛皮實在是可悲的祭品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...That is not a proper sacrifice.", "……那不是合適的祭品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop this.", "住手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You...", "你……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is bloodshed without meaning.", "這是毫無意義的殺戮。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[v:0]...", "[v:0]……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm?", "嗯？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this?", "這是什麼？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heh heh heh...", "嘿嘿嘿……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ye walked into th' pirate's cove!", "你闖進海盜的藏身灣了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Me crew will get rid of ye quick!", "我的船員很快就會解決你！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You carve through the thick underbrush and foilage.", "你劈開茂密的灌木和枝葉。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees blotting out the sun...", "樹木遮住了陽光……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you travel, you hear the woods start to creak around you.", "行進時，你聽見周圍的樹林開始嘎吱作響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should know better than to walk in the darkness...", "你應該知道不該在黑暗中行走……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As your caravan of creatures travels, you hear a rushing sound.", "你的生物隊伍前行時，你聽見一陣奔流聲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You climb to a higher place as water flows around you.", "水流在你四周湧動，你爬到更高的地方。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are caught in a [c:B]flood.[c:]", "你被困在[c:B]洪流之中。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the terrain and flying creatures will be able to avoid the waters.", "只有地形和飛行的生物能避開水流。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As your caravan of creatures moves across a clearing, the winds blow stronger.", "你的生物隊伍穿過一片空地時，風勢漸強。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strong breeze greets your face, and you grasp onto the surroundings for dear life.", "強風迎面吹來，你拼命抓住周圍的東西保住性命。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creatures are blown [c:G]airborne.[c:]", "你的生物被風[c:G]吹上空中。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only burrowing and submerged creatures will be able to avoid the gusts.", "只有鑽地和潛水的生物能避開狂風。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Breeze blows...", "微風吹拂……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You come across a pile of corpses.", "你發現了一堆屍體。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange energy swirls around them as you approach.", "你靠近時，一股奇異的能量在屍體周圍盤旋。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Then...", "接著……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]The dead walk.[c:]", "[c:R]亡者行走。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]The dead walk.[c:]", "[c:R]亡者行走。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came across an overgrown glade.", "你來到一片草木叢生的林間空地。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees seemed taller, and stronger than usual.", "樹木似乎比平常更高、更茁壯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creatures grew faster as well.", "你的生物也長得更快了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#25C102>Flash Growth.</color>", "<color=#25C102>急速生長。</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "嗯？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're decreasing the number of vessels you have?", "你在減少自己的容器數量？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surely a player as bad as you needs the extra chump blockers?", "像你這麼差勁的玩家肯定需要多幾個炮灰擋刀吧？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "你會知道的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "嗯？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're increasing the number of vessels you have?", "你在增加自己的容器數量？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Makes sense.", "有道理。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After all, a player as bad as you needs the extra chump blockers.", "畢竟像你這麼差勁的玩家需要多幾個炮灰擋刀。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[v:0] vessels...", "[v:0] 個容器……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh?", "哦？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You couldn't even stick to the changes?", "你連這些改動都堅持不了？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pathetic.", "可悲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh?", "哦？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My own Ourobot?", "我自己的銜尾機器人？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must be masochistic if you thought this was a good idea.", "如果你覺得這是好主意，肯定有受虐傾向。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your funeral.", "你自找的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There it goes.", "它走了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just made it stronger.", "你只是讓它變得更強了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Of course, you knew that already.", "當然，你早就知道了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not worried.", "我可不擔心。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll come back to crush you later.", "它之後會回來碾碎你。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "嗯？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weaker starting cards?", "更弱的起始卡牌？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As if one health will make a difference.", "好像 1 點生命力能帶來什麼差別似的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "嗯？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Were my environments not good enough for you?", "我的環境對你來說還不夠好嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine.", "好吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm...", "嗯……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have found a...", "你發現了一處……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Robot scrapyard.", "機器人廢料場。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's broken down robots everywhere.", "到處都是報廢的機器人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every robot in this area dies twice.", "這個區域的每個機器人都會死兩次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's the scrapyard again.", "又是廢料場。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know the drill.", "規矩你都知道。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eugh", "呃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is one of [c:O]HIS.[c:]", "這是[c:O]他[c:]的東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your... transformer bots will be more effective here.", "你的……變形者機器人在這裡會更有效。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They'll transform when played.", "打出時它們會變形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "你會知道的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your transformer bots will be more effective here.", "你的變形者機器人在這裡會更有效。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They'll tranform when played.", "打出時它們會變形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "啊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A favorite of mine.", "我最喜歡的東西之一。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each of your turns all cards will be moved clockwise.", "你的每個回合開始時，所有卡牌都會順時針移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure you've seen it before.", "我想你以前見過。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each of your turns all cards will be moved clockwise.", "你的每個回合開始時，所有卡牌都會順時針移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've seen it before.", "你以前見過。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "啊……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your <color=#25C102>G</color>[c:O]E[c:][c:B]M[c:]s will be more useful.", "你的<color=#25C102>寶</color>[c:O]石[c:][c:B]會[c:]更有用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "More useful than [c:R]he[c:] ever was able to make them...", "比[c:R]他[c:]能讓它們發揮的作用更大……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...As long as you keep that one alive.", "……只要你讓那一個活著。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your <color=#25C102>G</color>[c:O]E[c:][c:B]M[c:]s will be more useful.", "你的<color=#25C102>寶</color>[c:O]石[c:][c:B]會[c:]更有用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...As long as you keep that one alive.", "……只要你讓那一個活著。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heh", "呵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one will be quite...", "這個會相當……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shocking.", "令人震驚。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You find yourself in an electrical storm.", "你發現自己身處雷暴之中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is played, it will take 1 damage.", "打出卡牌時，該卡牌會受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it survives, it'll be stronger for a bit.", "如果它存活下來，就會暫時變得更強。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you'll find this one quite...", "你會發現這個相當……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shocking.", "令人震驚。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Parrot", "亡靈鸚鵡", Language.ChineseTraditional);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascender's Bane", "攀登者的禍根", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You start with a useless card in the deck.", "你開始時的牌組裡有一張無用的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Champions", "冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opponent cards have a chance to become a champion.", "對手的卡牌有機會成為冠軍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environmental Effects", "環境影響", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each battle, a random environmental effect may activate.", "每場戰鬥開始時，可能會啟用一個隨機的環境影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Famine", "饑荒", Language.ChineseTraditional);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The side deck has " + amnt.ToString() + " more cards.", "副牌組多了" + amnt.ToString() + "張卡牌。", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The side deck has " + amnt.ToString() + " less cards.", "副牌組少了" + amnt.ToString() + "張卡牌。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runaway Side Deck", "失控副牌組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Side Deck cards have the Fleeting sigil.", "你的副牌組卡牌帶有稍縱即逝印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Golden Fleece", "金色羊毛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Golden Ram appears randomly throughout the run.", "冒險期間會隨機出現一隻金色公羊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harder Bosses", "更強的頭目", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bosses' main cards are more powerful, and bosses are more agressive.", "頭目的主力卡牌更強，頭目也更加好鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "True Pirate", "真正的海盜", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirates invade Bosses. The Final Boss Challenge is harder.", "海盜入侵頭目戰，最終頭目挑戰變得更難。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Extra Lives", "額外生命", Language.ChineseTraditional);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The scales will reset once they hit 0, up to " + amnt.ToString() + " times for each candle.", "天平達到0時會重置，每支蠟燭最多重置" + amnt.ToString() + "次。", Language.ChineseTraditional);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botched Experiments", "拙劣實驗", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mycologists have a chance to make mistakes while fusing cards.", "真菌學家融合卡牌時可能出錯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Fecundity", "舊版繁殖力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reverts the Fecundity Nerf.", "撤銷繁殖力的削弱。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mulligan", "重新抽牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may redraw your hand at the start of each battle.", "你可以在每場戰鬥開始時重新抽取手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reverse Scales", "反向天平", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start all battles with 1 damage on the opponent's side of the scale.", "每場戰鬥開始時，對手一側的天平已有 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shocked Starters", "受驚的起始卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in starting deck attack every other turn.", "起始牌組中的卡牌每隔一回合才會攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprintmaggedon", "衝刺末日", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards get a random Sprinter sigil when drawn.", "所有卡牌被抽到時，都會獲得一個隨機的衝刺者印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traveling Ouroboros", "旅行的銜尾蛇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A traveling Ouroboros appears throughout the run.", "一隻旅行的銜尾蛇會在冒險途中出現。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfair Hand", "不公手牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your starting hand is randomly drawn.", "你的起始手牌會隨機抽取。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive Noise", "爆炸噪音", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card dies, a loud boom will play. All cards explode on death.", "卡牌死亡時會響起巨大的爆炸聲。所有卡牌死亡時都會爆炸。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aquatic Starters", "水生起始卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in starting deck have the Waterborne sigil.", "起始牌組中的卡牌帶有水生印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unspirited Starters", "失魂起始卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in the starting deck may not have their sigils transferred.", "起始牌組中卡牌的印記不能轉移。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Starters", "虛弱起始卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in the starting deck have 1 less health.", "起始牌組中的卡牌生命力減少 1 點。", Language.ChineseTraditional);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Champion", "藍色冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will cause all other non-Terrain cards on the same side to gain flight, as long as the champion is alive.", "只要這位冠軍存活，同一側所有其他非地形卡牌都會獲得飛空。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bright Red Champion", "鮮紅冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, this champion will heal all other non-terrain creatures on the opponent's side by 1.", "每個回合開始時，這位冠軍會為對手一側的所有其他非地形生物恢復 1 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyan Champion", "青色冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this champion perishes, it will deal 1 damage to every other creature on the board.", "這位冠軍陣亡時，會對檯面上的每個其他生物造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive", "爆炸性之物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature]; the other card, adjacent cards, and opposing cards will all be dealt 10 damage.", "其他卡牌可以放在 [creature] 上方；放上的卡牌、相鄰卡牌和正對面的卡牌都會受到 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a copy of it is created in the opponent's hand.", "[creature] 陣亡時，會在對手手牌中產生其副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragile", "易碎", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] perishes, it is permanently removed from your deck.", "[creature] 陣亡時，會從你的牌組中永久移除。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Champion", "綠色冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will deal 1 damage directly to you, after it destroys another creature.", "這位冠軍摧毀另一個生物後，會直接對其對手造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Light Blue Champion", "淺藍冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this champion perishes, it will deal 3 damage to creatures to the left and right of it as well as the opposing creature.", "這位冠軍陣亡時，會對其左右兩側的生物以及正對面的生物造成 3 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Light Green Champion", "淺綠冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will prevent all damage from the first strike dealt to it. Damage from effects like sigils will not be prevented.", "這位冠軍會防止第一次攻擊對其造成的所有傷害，印記等效果造成的傷害則無法防止。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magenta Champion", "品紅冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, this champion will attack for 1 damage in a random space on your side.", "每個回合開始時，這位冠軍會攻擊你這一側的隨機一個位置，造成 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muddy", "汙泥濁浪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature], but will be unable to attack for one turn and will gain Muddy. If [creature] is sacrificed, the sacrificing creature will be unable to attack for one turn.", "其他卡牌可以放在 [creature] 上方，但放上的卡牌在一回合內無法攻擊，並會獲得汙泥濁浪。若 [creature] 被犧牲，使用其作為祭品的生物在一回合內無法攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificial Slab", "獻祭石板", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature]; the other card will die.", "其他卡牌可以放在 [creature] 上方；放上的卡牌會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Champion", "橘色冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will steal 2 golden teeth from you if it damages you directly.", "這位冠軍直接對你造成傷害時，會從你身上偷走 2 顆金牙。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not attack every other turn.", "[creature] 每隔一回合無法攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purple Champion", "紫色冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each time you play a card, if the space opposing this champion is empty, that card will move to that space.", "每次你打出卡牌時，若這位冠軍正對面的位置為空，該卡牌會移到該位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seaworthy", "適航", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature], any Waterborne sigils on the card will be negated.", "其他卡牌可以放在 [creature] 上方，該卡牌上的所有水生印記都會失效。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Champion", "紅色冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion starts with 2 additional Health.", "這位冠軍初始時額外擁有 2 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter", "避難所", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adjacent cards are sheltered from environmental effects.", "相鄰卡牌不受環境影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalancher", "雪崩者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Creatures in the way will be killed. If [creature] is at the right most side of the board, it dies.", "擁有者的回合結束時，[creature] 會朝印記標示的方向移動，並殺死擋路的生物。若 [creature] 位於檯面最右側，就會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Creatures in the way will be killed.", "擁有者的回合結束時，[creature] 會朝印記標示的方向移動，並殺死擋路的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move to the right, jumping over any creatures in its path. If it encounters the edge of the board, it will loop over to the other side.", "擁有者的回合結束時，[creature] 會向右移動，跳過路徑上的所有生物。若到達檯面邊緣，則繞至另一側。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Champion", "白色冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this champion perishes, it will create a Boulder in its space. [define:Boulder]", "這位冠軍陣亡時，會在自己的位置產生一塊大石塊。[define:Boulder]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellow Champion", "黃色冠軍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion starts with 1 additional Power.", "這位冠軍初始時額外擁有 1 點攻擊力。", Language.ChineseTraditional);

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slot Spawner", "卡槽生成器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played, spawns a slot. Used for testing.", "打出時產生一個卡槽。用於測試。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played, converts the slot into a Raft.", "打出時將該卡槽轉變為木筏。", Language.ChineseTraditional);
            // Boon
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Angler's Pond", "環境：釣魚人的池塘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Bait Buckets.", "對手帶著魚餌桶開始戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Blizzard", "環境：暴風雪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, if there is not an Avalanche present on the board, one will be created on the left-most side of the board.", "每個回合開始時，若檯面上沒有雪崩，就在檯面最左側產生一個。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Blood Moon", "環境：血月", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Dire Wolf Pups.", "對手帶著恐狼幼崽開始戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Breeze", "環境：微風", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, all creatures gain or lose Airborne. Terrain, and creatures with Waterborne or Burrower are ignored.", "每個回合開始時，所有生物獲得或失去飛空。地形及帶有水生或挖掘者的生物不受影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Carrot Patch", "環境：胡蘿蔔地", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Rabbits.", "對手帶著兔子開始戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Cliffside", "環境：懸崖邊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the battle, the leftmost lane will be blocked with Cliffs.", "戰鬥開始時，最左側路線會被懸崖封鎖。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Factory", "環境：工廠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Upkeep, all cards are rotated clockwise.", "維持階段時，所有卡牌順時針移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Dark Forest", "環境：黑暗森林", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Trees. All of the opponent's terrain have +1 power.", "對手帶著樹木開始戰鬥。對手的所有地形獲得 +1 攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Prospector's Camp", "環境：礦工營地", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will start the battle with Dynamite on some of your spaces.", "戰鬥開始時，你的某些位置上會有炸藥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Electrical Storm", "環境：雷暴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is played, it takes 1 damage and gains 1 power.", "打出卡牌時，該卡牌受到 1 點傷害並獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Flash Growth", "環境：急速生長", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is played, any sigils that activate at the start of the turn are activated.", "打出卡牌時，該卡牌上所有在回合開始時啟動的印記都會啟動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Flood", "環境：洪流", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a creature is played, it gains Waterborne. Terrain, and creatures with Airborne are ignored.", "每當打出生物時，該生物獲得水生。地形及帶有飛空的生物不受影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Gem Sanctuary", "環境：寶石聖所", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All gems have +1 power.", "所有寶石獲得 +1 攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Graveyard", "環境：墓地", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature dies, it dies again.", "生物死亡時，會再次死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Hail Storm", "環境：冰雹風暴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, all of the turn owner's non-terrain cards take 1 damage.", "每個回合開始時，該回合擁有者的所有非地形卡牌受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Pirate's Hollow", "環境：海盜谷", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with a Minicello.", "對手帶著迷你切洛號開始戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Mud Swamp", "環境：泥沼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will start the battle with Mud on some of your spaces.", "戰鬥開始時，你的某些位置上會有泥沼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Fungal Field", "環境：真菌田", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Mushrooms.", "對手帶著蘑菇開始戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Obelisk", "環境：方尖碑", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with an Obelisk.", "對手帶著方尖碑開始戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Cursed Totem", "環境：詛咒圖騰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Cursed Totems.", "對手帶著詛咒圖騰開始戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Trapper's Hunting Grounds", "環境：獵人的狩獵場", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Steel Traps.", "對手帶著鋼製陷阱開始戰鬥。", Language.ChineseTraditional);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascender's Bane", "攀登者的禍根", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A reminder of past challengers.", "過往挑戰者的遺跡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalanche", "雪崩", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A monsterous mound of snow.", "一座巨大的雪堆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cliff", "懸崖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A solid wall of rock.", "堅實的岩石牆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clover", "三葉草", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal member of Royal's crew.", "羅耀船員中忠誠的一員。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite", "炸藥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A box of dynamite.", "一箱炸藥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chrysomallos", "金羊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mystical, glittering being.", "神祕且閃閃發光的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Cube", "冰塊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A block of ice.", "一塊冰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minicello", "迷你切洛號", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A miniture version of a famous pirate's ship.", "一艘著名海盜船的縮小版。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mud", "泥沼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mushrooms", "蘑菇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of strange mushrooms. They attract anything nearby.", "一堆奇怪的蘑菇，會吸引附近的一切。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk", "方尖碑", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tall mysterious stone.", "一塊高大的神祕石頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificial Altar", "獻祭祭壇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flat mysterious stone.", "一塊扁平的神祕石頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raft", "木筏", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dry patch in the flood.", "洪流中的一塊乾地。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter", "避難所", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter from the storm.", "躲避風暴的避難所。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Totem", "詛咒圖騰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A totem surrounded in mysterious energy.", "一座被神祕能量包圍的圖騰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own Ouroboros.", "我自己的銜尾蛇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wooden Board", "木板", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A regular wooden board.", "一塊普通的木板。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Firstmate", "鼴鼠大副", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ourobot", "銜尾機器人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Living {0}", "活著的{0}", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps a mutation?", "或許是變異？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raft Slot", "木筏卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prevents creatures on this slot from submerging into the water.", "防止此卡槽上的生物潛入水中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muddy Slot", "泥沼卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played on this slot, it cannot attack for one turn.", "生物被打出至此卡槽時，該生物在一回合內無法攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hail Slot", "冰雹卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, a creature in this slot takes 1 damage.", "擁有者的回合開始時，此卡槽上的生物受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flooded Slot", "浸水卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it gets submerged in the water unless it is flying.", "生物被打出至此卡槽時，除非會飛，否則會潛入水中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Windy Slot", "多風卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, a creature in this slot will alternate between flying and not flying. This effect is ignored if the creature naturally flies, submerges, or burrows.", "擁有者的回合開始時，此卡槽上的生物會在飛行與不飛行之間切換。原本會飛、潛水或鑽地的生物不受此效果影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Slot", "陰森卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature dies in this slot, it dies again.", "生物在此卡槽中死亡時，會再次死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Growth Slot", "成長卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, instantly evolve it if it has an evolve related sigil. If it does not have Fledgling, it instead gains Fledgling.", "生物被打出至此卡槽時，若帶有與進化相關的印記，便立刻進化；若沒有幼雛，則改為獲得幼雛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overclocking Slot", "超頻卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it takes 1 damage and gains 1 attack.", "生物被打出至此卡槽時，受到 1 點傷害並獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite Slot", "炸藥卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it takes 10 damage and explodes. The dynamite is removed.", "生物被打出至此卡槽時，受到 10 點傷害並爆炸。炸藥隨後被移除。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk Tablet", "方尖碑石板", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it is sacrificed.", "生物被打出至此卡槽時，會被犧牲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is truly a worthy sacrifice.", "這確實是值得獻上的祭品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a thing... does not bleed.", "這種東西……不會流血。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The obelisk does not react.", "方尖碑沒有反應。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, something greater.", "或許，需要更偉大的東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick [c:G]mud[c:] stuck to your boots, and hindered your movements...", "濃稠的[c:G]泥沼[c:]黏在你的靴子上，阻礙了你的行動……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The glade glowed with unnatural light.", "林間空地泛著不自然的光。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the area stank of rotting fish,", "附近瀰漫著腐魚的惡臭，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps they are sick?", "或許牠們生病了？", Language.ChineseTraditional);
        }
    }
    public class NewSpellCardToolkitMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NewSpellCardToolkit Mod");
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attack Up", "攻擊力提升", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Increases the target's attack for the rest of the battle.", "在本場戰鬥剩餘期間提升目標的攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attack Down", "攻擊力降低", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decreases the target's attack for the rest of the battle.", "在本場戰鬥剩餘期間降低目標的攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cataclysm", "大災變", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all other cards on the boards perish as well.", "[creature] 死亡時，檯面上所有其他卡牌也會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Damage", "直接傷害", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deals damage directly to a target.", "直接對目標造成傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Heal", "直接治療", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heals the target. This can heal the target beyond its original max health.", "治療目標。此效果可使目標的生命力超過原本的上限。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Twice", "抽牌兩次", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, draw two more cards and add them to your deck.", "[creature] 死亡時，額外抽兩張卡牌加入手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Control", "取得控制權", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Takes control of the targeted creature.", "取得目標生物的控制權。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give Sigils", "賦予印記", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives this card's sigils to the target.", "將此卡牌的印記賦予目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give Stats", "賦予屬性", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives this card's stats to the target.", "將此卡牌的屬性賦予目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give Stats and Sigils", "賦予屬性與印記", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives this card's stats and sigils to the target.", "將此卡牌的屬性與印記賦予目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell (Global)", "法術（全局）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played anywhere on the board, it will cause an immediate effect and then disappear.", "將此卡牌打出至檯面的任意位置時，會立即產生效果並消失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLOBAL SPELL.", "全局法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell (Global, Instant)", "法術（全局，瞬發）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will cause an immediate effect and then disappear.", "打出此卡牌時，會立即產生效果並消失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INSTA-GLOBAL SPELL.", "瞬發全局法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell (Targeted)", "法術（指定目標）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will target and affect a chosen space on the board and then disappear.", "打出此卡牌時，會選定並影響檯面上的一個位置，隨後消失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TARGETED SPELL.", "指定目標法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Command (Global)", "命令（全局）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played anywhere on the board, it will cause an immediate effect and then disappear.", "將此卡牌打出至檯面的任意位置時，會立即產生效果並消失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLOBAL COMMAND.", "全局命令。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Command (Global, Instant)", "命令（全局，瞬發）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will cause an immediate effect and then disappear.", "打出此卡牌時，會立即產生效果並消失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INSTA-GLOBAL COMMAND.", "瞬發全局命令。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Command (Targeted)", "命令（指定目標）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will target and affect a chosen space on the board and then disappear.", "打出此卡牌時，會選定並影響檯面上的一個位置，隨後消失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TARGETED COMMAND.", "指定目標命令。", Language.ChineseTraditional);

        }
    }
    public class P03SigilariumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for P03Sigilarium Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Urch1n Cell", "機械海膽電池", Language.ChineseTraditional);
            P03InKayceesModMod.RegisterCard("Urch1n Cell", "機械海膽電池");
            P03InKayceesModMod.RegisterCardPart("Urch1n", "機械海膽");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charge!", "充能！", Language.ChineseTraditional);
            P03InKayceesModMod.RegisterCard("Charge!", "充能！");
            P03InKayceesModMod.RegisterCardPart("Charge!", "充能！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upgrade!", "升級！", Language.ChineseTraditional);
            P03InKayceesModMod.RegisterCard("Upgrade!", "升級！");
            P03InKayceesModMod.RegisterCardPart("Upgrade!", "升級！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zap!", "電擊！", Language.ChineseTraditional);
            P03InKayceesModMod.RegisterCard("Zap!", "電擊！");
            P03InKayceesModMod.RegisterCardPart("Zap!", "電擊！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast!", "轟爆！", Language.ChineseTraditional);
            P03InKayceesModMod.RegisterCard("Blast!", "轟爆！");
            P03InKayceesModMod.RegisterCardPart("Blast!", "轟爆！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defend!", "防禦！", Language.ChineseTraditional);
            P03InKayceesModMod.RegisterCard("Defend!", "防禦！");
            P03InKayceesModMod.RegisterCardPart("Defend!", "防禦！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Junk", "廢料堆", Language.ChineseTraditional);
            P03InKayceesModMod.RegisterCard("Junk", "廢料堆");
            P03InKayceesModMod.RegisterCardPart("Junk", "廢料堆");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "S4LM0N", "機械鮭魚", Language.ChineseTraditional);
            P03InKayceesModMod.RegisterCard("S4LM0N", "機械鮭魚");
            P03InKayceesModMod.RegisterCardPart("S4LM0N", "機械鮭魚");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seed", "種子", Language.ChineseTraditional);
            P03InKayceesModMod.RegisterCard("Seed", "種子");
            P03InKayceesModMod.RegisterCardPart("Seed", "種子");

            // Ability

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION I - Additional Mechanics {0}", "附錄 XII，第 I 小節－額外機制 {0}", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield Absorption", "護盾吸收", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all creatures lose their shields. This creature gains 1 attack for each shield lost this way.", "打出 [creature] 時，所有生物失去護盾。每有一面護盾以此方式失去，此生物便獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rapid Recycle", "快速回收", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to choose another card you control to die and immediately respawn. You may only activate this ability once per turn.", "支付 1 點能量，選擇你控制的另一張卡牌，使其死亡並立刻重生。此能力每回合只能啟用一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supercharge", "超載充能", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: friendly cards gain 1 power until the end of the turn. This ability can only be activated once per turn.", "消耗一份燃料：友方卡牌獲得 1 點攻擊力，持續至回合結束。此能力每回合只能啟用一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copy and Paste", "複製貼上", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The controller of [creature] chooses two cards they control. The second card's sigils are replaced with the sigils of the first.", "[creature] 的控制者選擇其控制的兩張卡牌。第二張卡牌的印記會被第一張卡牌的印記取代。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card to copy sigils from", "選擇要複製印記的卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card to paste sigils onto", "選擇要貼上印記的卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cannon Fire", "火炮射擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: Create a Blast! card in hand. Blast! is defined as a spell that costs 2 energy and sets the target on fire. This ability can only be activated once per turn.", "消耗一份燃料：在手牌中產生一張「轟爆！」。「轟爆！」是一張費用為 2 點能量、使目標著火的法術。此能力每回合只能啟用一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: Create a Blast! card in hand. Blast! is defined as a command that costs 2 energy and sets the target on fire. This ability can only be activated once per turn.", "消耗一份燃料：在手牌中產生一張「轟爆！」。「轟爆！」是一張費用為 2 點能量、使目標著火的命令。此能力每回合只能啟用一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge Reserves", "充能儲備", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to create a Charge in your hand. Charge is defined as a spell that refills 1 Energy when played.", "支付 2 點能量，在手牌中產生一張「充能！」。「充能！」是一張打出時補充 1 點能量的法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to create a Charge in your hand. Charge is defined as a command that refills 1 Energy when played.", "支付 2 點能量，在手牌中產生一張「充能！」。「充能！」是一張打出時補充 1 點能量的命令。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Holo Weaver", "全息編織者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, create a Defend! card in hand. Defend! is defined as a spell that costs 2 energy and gives the target a shield.", "每回合一次，在手牌中產生一張「防禦！」。「防禦！」是一張費用為 2 點能量、為目標提供護盾的法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, create a Defend! card in hand. Defend! is defined as a command that costs 2 energy and gives the target a shield.", "每回合一次，在手牌中產生一張「防禦！」。「防禦！」是一張費用為 2 點能量、為目標提供護盾的命令。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Future Sight", "預見未來", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look at the top card of your deck. You can play it.", "查看牌組頂端的卡牌。你可以打出它。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil Fuel", "化石燃料", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Provides an additional energy cell.", "提供一個額外的能量槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dispenser", "分配器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a random item.", "獲得一個隨機道具。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overcharge", "過度充能", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Energy to increase the Power of this card by 1.", "支付 4 點能量，使此卡牌的攻擊力增加 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enrage", "超頻領袖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Energy equal to the Power of this card plus 2 to increase the Power of this card by 1.", "支付等同於此卡牌攻擊力加 2 的能量，使此卡牌的攻擊力增加 1 點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drive", "驅動", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: move in the direction inscribed in this sigil. This ability can only be activated once per turn.", "消耗一份燃料：朝此印記標示的方向移動。此能力每回合只能啟用一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "D-Pad", "十字鍵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move to an adjacent empty lane.", "移動至相鄰的空路線。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "D-Pad Left", "十字鍵向左", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move to the lane to the left, if it is empty.", "若左側路線為空，便移到該路線。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "D-Pad Right", "十字鍵向右", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move to the lane to the right, if it is empty.", "若右側路線為空，便移到該路線。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "下潛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: submerge during the opponent's turn. While submerged, opposing creatures attack its owner directly.", "消耗一份燃料：在對手回合期間潛入水中。潛水時，對方生物會直接攻擊其擁有者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tow Hook", "拖曳鉤", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: tow an opposing creature to your side of the board until end of turn. Creatures being towed cannot be hammered. This ability can only be activated once per turn.", "消耗一份燃料：將一個對方生物拖到你這一側檯面，直到回合結束。被拖曳的生物無法被錘擊。此能力每回合只能啟用一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Button Pusher", "按鈕推手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all activated sigils and sigils that trigger on play or on death are activated.", "打出 [creature] 時，所有可啟用印記，以及打出時或死亡時觸發的印記都會啟用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Control", "寄生控制", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opposing cards are moved to your side of the board.", "打出 [creature] 時，所有對方卡牌都會移到你這一側檯面。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Power", "能量攻擊力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of times the player has spent energy this turn.", "此印記代表的數值等於玩家本回合消耗能量的次數。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Holo Trap", "全息陷阱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the creature opposing it perishes as well. A Vessel is created in your hand.", "帶有此印記的卡牌陣亡時，正對面的生物也會陣亡。你的手牌中會產生一張容器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brittle Lord", "脆弱領主", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, cards with Brittle have Unkillable.", "只要 [creature] 存活，帶有脆弱的卡牌便擁有不死重生。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buck Wild", "狂野衝撞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon taking damage, this card will charge into the opposing slot, killing anything in its way.", "此卡牌受到傷害時，會衝向正對面的卡槽，殺死沿途的一切。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (1)", "燃燒卡槽（1）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts one turn.", "此卡槽著火了！回合結束時，會對其中的卡牌造成一點傷害。此效果持續一回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (2)", "燃燒卡槽（2）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts two turns.", "此卡槽著火了！回合結束時，會對其中的卡牌造成一點傷害。此效果持續兩回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (3)", "燃燒卡槽（3）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts three turns.", "此卡槽著火了！回合結束時，會對其中的卡牌造成一點傷害。此效果持續三回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (4)", "燃燒卡槽（4）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts four turns.", "此卡槽著火了！回合結束時，會對其中的卡牌造成一點傷害。此效果持續四回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burnt Out", "過燃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it sets the land on fire for three turns.", "[creature] 死亡時，會使地面燃燒三回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "on fire", "燃燒中", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catch Fire", "引燃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot, the target is set on fire.", "[creature] 選中一個卡槽時，會點燃該卡槽。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transforms When Unpowered", "未充能時變形", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is NOT within a circuit at the beginning of the turn, it will transform back into its original form.", "回合開始時，若 [creature] 不在電路內，便會變回原始形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterborne When Unpowered", "未充能時水生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is NOT within a circuit it submerges itself during its opponent's turn. While submerged, opposing creatures attack its owner directly.", "若 [creature] 不在電路內，便會在其對手的回合潛入水中。潛水時，對方生物會直接攻擊其擁有者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Short Circuit", "短路", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit at the beginning of the turn, create a Zap! in your hand. Zap! is defined as a spell that costs 2 energy and deals 1 damage to any target.", "回合開始時，若 [creature] 在電路內，便在你的手牌中產生一張「電擊！」。「電擊！」是一張費用為 2 點能量、對任意目標造成 1 點傷害的法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit at the beginning of the turn, create a Zap! in your hand. Zap! is defined as a command that costs 2 energy and deals 1 damage to any target.", "回合開始時，若 [creature] 在電路內，便在你的手牌中產生一張「電擊！」。「電擊！」是一張費用為 2 點能量、對任意目標造成 1 點傷害的命令。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transforms When Powered", "充能時變形", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit at the beginning of the turn, it will transform into a stronger form.", "回合開始時，若 [creature] 在電路內，便會變成更強的形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explodonate When Powered", "充能時櫻桃炸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit, it detonates itself and deals 10 damage to all five adjacent spaces.", "若 [creature] 在電路內，便會引爆自身，對周圍五個相鄰位置各造成 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics When Powered", "充能時精神寶石手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, if it is within a circuit, its owner draw cards equal to the number of Mox Cards on their side of the game board.", "打出 [creature] 時，若其在電路內，其擁有者抽取數量等同於己方檯面上魔思力卡牌數量的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trap When Powered", "充能時陷阱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes while in a circuit, the creature opposing it perishes as well. A Vessel is created in your hand.", "帶有此印記的卡牌在電路內陣亡時，正對面的生物也會陣亡。你的手牌中會產生一張容器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unkillable When Powered", "充能時不死重生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit when it perishes, a copy of it is created in your hand.", "[creature] 在電路內陣亡時，你的手牌中會產生其副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splice Conduit", "接合導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] completes a circuit, all cards within that circuit are moved towards it, splicing with it if possible.", "若 [creature] 完成一條電路，該電路內的所有卡牌都會移向它，並在可能時與它接合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky Conduit", "臭味導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] have Stinky.", "由 [creature] 接通的電路內的卡牌擁有臭味。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Airborne Conduit", "飛空導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] have Airborne.", "由 [creature] 接通的電路內的卡牌擁有飛空。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gas Conduit", "燃氣導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] have Fire Strike and Burnt Out.", "由 [creature] 接通的電路內的卡牌擁有火焰打擊和過燃。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bedazzling Conduit", "璀璨導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] are Gemified.", "由 [creature] 接通的電路內的卡牌會被寶石化。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Static Electricity", "靜電", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause all friendly cards to behave as if they are part of a completed conduit.", "[creature] 會使所有友方卡牌如同處於已完成的電路中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gas Generator", "燃氣發電機", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as it has fuel, [creature] will cause all friendly cards to behave as if they are part of a completed conduit.", "只要有燃料，[creature] 便會使所有友方卡牌如同處於已完成的電路中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Protector", "導管守衛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is within a completed circuit, damage that would be dealt to the conduits is dealt to this creature instead.", "[creature] 處於完整電路內時，原本對導管造成的傷害改由此生物承受。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Byte", "死亡位元組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, take 1 damage.", "帶有此印記的卡牌陣亡時，你受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Sprinter", "雙重衝刺", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a card bearing this sigil will move in the direction inscribed in the sigil twice.", "擁有者的回合結束時，帶有此印記的卡牌朝印記標示的方向移動兩次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brittle Summoner", "脆弱召喚師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random brittle card is created in your hand.", "打出 [creature] 時，你的手牌中會產生一張隨機的脆弱卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iterate", "迭代", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it with a different cost is created in your hand.", "打出 [creature] 時，你的手牌中會產生一張費用不同的副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tinkerer", "工匠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create three spell cards selected at random.", "打出 [creature] 時，產生三張隨機選取的法術牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create three command cards selected at random.", "打出 [creature] 時，產生三張隨機選取的命令牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phasers Ready", "相位炮就緒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create two Zap! cards in hand. Zap! is defined as a spell that costs 2 energy and deals 1 damage to any target.", "打出 [creature] 時，在手牌中產生兩張「電擊！」。「電擊！」是一張費用為 2 點能量、對任意目標造成 1 點傷害的法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create two Zap! cards in hand. Zap! is defined as a command that costs 2 energy and deals 1 damage to any target.", "打出 [creature] 時，在手牌中產生兩張「電擊！」。「電擊！」是一張費用為 2 點能量、對任意目標造成 1 點傷害的命令。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combat Research", "戰鬥研究", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, create a Forced Upgrade card in hand. Forced Upgrade is defined as a spell that costs 2 energy and caused any target to upgrade to a new version.", "[creature] 造成傷害時，在手牌中產生一張「強制升級」。「強制升級」是一張費用為 2 點能量、使任意目標升級為新版本的法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, create a Forced Upgrade card in hand. Forced Upgrade is defined as a command that costs 2 energy and caused any target to upgrade to a new version.", "[creature] 造成傷害時，在手牌中產生一張「強制升級」。「強制升級」是一張費用為 2 點能量、使任意目標升級為新版本的命令。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric", "電力制導", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] declares an attack, it will deal half the damage to cards adjacent to the target.", "[creature] 宣告攻擊時，會對目標相鄰的卡牌造成一半傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Mox Buff", "綠色魔思力增益", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it gains two health for each Green Mox its owner controls.", "打出 [creature] 時，其擁有者控制的每個綠色魔思力都使它獲得兩點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Blessing", "綠寶石祝福", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] provides +2 Health to all creatures you control.", "[creature] 為你控制的所有生物提供 +2 生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Shard", "綠寶石碎片", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, an Emerald Mox is created in its place and a card bearing this sigil moves to the right.", "[creature] 即將受到攻擊時，會在其位置產生一個綠寶石魔思力，帶有此印記的卡牌則向右移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armor Giver", "護甲賦予者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] enters, all opposing cards gain Nano Armor.", "[creature] 入場時，所有對方卡牌獲得奈米護甲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Siphon", "能量虹吸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever another card you own dies in combat, [creature] creates a Charge in your hand. Charge is a spell that refills 1 Energy when played.", "你擁有的另一張卡牌在戰鬥中死亡時，[creature] 會在你的手牌中產生一張「充能！」。「充能！」是一張打出時補充 1 點能量的法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever another card you own dies in combat, [creature] creates a Charge in your hand. Charge is a command that refills 1 Energy when played.", "你擁有的另一張卡牌在戰鬥中死亡時，[creature] 會在你的手牌中產生一張「充能！」。「充能！」是一張打出時補充 1 點能量的命令。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explodonate", "櫻桃炸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it explodes and deals 10 damage to all five adjacent slots.", "[creature] 死亡時，會爆炸並對周圍五個相鄰卡槽各造成 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Strike", "火焰打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, it sets the target space on fire for three turns.", "[creature] 攻擊時，會使目標位置燃燒三回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Strike When Fueled", "有燃料時火焰打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, if it is fueled, it consumes one fuel to set the target space on fire for three turns.", "[creature] 攻擊時，若有燃料，會消耗一份燃料，使目標位置燃燒三回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Stoker", "添柴者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on board, all fires you start will be stronger, causing them to last one turn longer.", "[creature] 在檯面上時，你點燃的所有火焰都會更強，持續時間延長一回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fling", "拋擲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, if one or more cards was sacrificed to play it, [creature] deals damage to a card of the player's choice equal to the total attack value of all sacrificed cards.", "打出 [creature] 時，若為打出它而犧牲了一張或多張卡牌，[creature] 會對玩家選擇的一張卡牌造成傷害，數值等同於所有被犧牲卡牌的攻擊力總和。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upgrade", "強制升級", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot, the target is immediately upgraded to a stronger version of itself.", "[creature] 選中一個卡槽時，目標立刻升級成更強的版本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Donation", "鮮血捐贈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards can be sacrificed to pay blood costs even if they normally could not.", "只要 [creature] 存活，所有友方卡牌都可以被犧牲以支付鮮血費用，即使它們平常無法被犧牲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Giver", "鐵石心腸賦予者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards are Made of Stone", "只要 [creature] 存活，所有友方卡牌都擁有鐵石心腸。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dust Giver", "粉塵賦予者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards have Magic Dust.", "只要 [creature] 存活，所有友方卡牌都擁有魔法粉塵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Roller", "煤煙滾滾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards which have fuel are Stinky.", "只要 [creature] 存活，所有有燃料的友方卡牌都擁有臭味。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Ignition", "寶石點燃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly gems have +1 Power, Flame Strike, Brittle, and Burnt Out.", "只要 [creature] 存活，所有友方寶石都擁有 +1 攻擊力、火焰打擊、脆弱和過燃。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel Strike", "燃料打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] consumes one fuel to attack and can only attack if it has fuel.", "[creature] 攻擊時消耗一份燃料，且只有有燃料時才能攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card carries an external fuel source which powers one or more of its sigils. When a card's fuel tank empties, those sigils cease to function.", "此卡牌攜帶外部燃料源，為其一個或多個印記供能。卡牌的燃料耗盡時，這些印記便會停止運作。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel", "燃料", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel Shield", "燃料護盾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] has fuel, it takes damage by losing fuel instead of health.", "只要 [creature] 有燃料，受到傷害時便會失去燃料而非生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel Siphon", "燃料虹吸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] deals damage directly to the opponent, it gains that much fuel.", "[creature] 直接對對手造成傷害時，獲得等量燃料。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full of Blood", "鮮血滿溢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can be sacrificed to pay blood costs.", "[creature] 可以被犧牲以支付鮮血費用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full of Oil", "燃油滿溢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it adds 3 health to each card on either side and across from it.", "[creature] 死亡時，會為左右兩側及正對面的每張卡牌增加 3 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully Loaded", "滿載", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it leaves a permanent +1 attack bonus in the lane it occupied.", "[creature] 死亡時，會在其佔據的路線留下永久的 +1 攻擊力加成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot has its power increased by one.", "此卡槽中的卡牌攻擊力增加一點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defend", "防禦", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot, the target gains Nano Armor.", "[creature] 選中一個卡槽時，目標獲得奈米護甲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Gift", "藍色魔思力禮物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, if you control an Blue Mox, gain a random card.", "[creature] 陣亡時，若你控制藍色魔思力，便獲得一張隨機卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Looter", "藍色魔思力掠奪者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage directly, if you control a Blue Mox, draw a card for each damage dealt.", "[creature] 造成直接傷害時，若你控制藍色魔思力，每造成一點傷害便抽一張牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist With Blue", "有藍純粹主義", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the owner of [creature] controls a Blue Mox, cards opposing [creature] have their sigils removed.", "若 [creature] 的擁有者控制藍色魔思力，與 [creature] 正對面的卡牌會失去印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Without Green", "無綠煩躁", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing [creature] gains 1 power unless the owner of [creature] also controls a Green Mox.", "[creature] 正對面的生物獲得 1 點攻擊力，除非 [creature] 的擁有者也控制綠色魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Mox Gift", "綠色魔思力禮物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, if you control a Green Mox, gain a random card.", "[creature] 陣亡時，若你控制綠色魔思力，便獲得一張隨機卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brittle Without Orange", "無橘脆弱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] will perish if its owner does not control an Orange Mox.", "[creature] 攻擊後，若其擁有者不控制橘色魔思力，便會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Airborne", "橘色魔思力飛空", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you control an Orange Mox, [creature] will ignore opposing cards and strike an opponent directly.", "若你控制橘色魔思力，[creature] 會無視正對面的卡牌，直接攻擊對手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Printer", "橘色魔思力印表機", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you control an Orange Mox, [creature] will draw a card from your side deck at the start of every turn.", "若你控制橘色魔思力，[creature] 會在每個回合開始時從你的副牌組抽一張牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Strike", "寶石打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] attacks once for each gem provider its owner controls.", "[creature] 為其擁有者控制的每個寶石提供者各攻擊一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Power", "綠寶石之力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of green gems its owner controls.", "此印記代表的數值等於其擁有者控制的綠色寶石數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopper", "跳蟲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, [creature] moves to an empty space of its owner's choosing.", "每個回合結束時，[creature] 會移到其擁有者選擇的空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kraken Transformer", "克拉肯變形者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of your turn, [creature] will transform to, or from, Kraken mode.", "你的回合開始時，[creature] 會變成克拉肯形態或從該形態變回。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Latch", "惱人傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Annoying sigil.", "[creature] 陣亡時，其擁有者選擇一個生物，使其獲得煩躁印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Latch", "死亡傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will die at the end of the turn. When [creature] perishes, its owner chooses a creature to gain this sigil. This will repeat.", "[creature] 會在回合結束時死亡。[creature] 陣亡時，其擁有者選擇一個生物，使其獲得此印記。此過程會重複。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Latch", "首個印記傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the first sigil this card has.", "[creature] 陣亡時，其擁有者選擇一個生物，使其獲得此卡牌的第一個印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Airborne Latch", "飛空傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Airborne sigil.", "[creature] 陣亡時，其擁有者選擇一個生物，使其獲得飛空印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Latch", "導管傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Null Conduit sigil.", "[creature] 陣亡時，其擁有者選擇一個生物，使其獲得無用導管印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rampage Latch", "狂暴傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Rampager sigil. The target will immediately rampage once when the latch is applied.", "[creature] 陣亡時，其擁有者選擇一個生物，使其獲得狂暴者印記。目標獲得此傳花時會立刻狂暴一次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky Latch", "臭味傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Stinky sigil.", "[creature] 陣亡時，其擁有者選擇一個生物，使其獲得臭味印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swapper Latch", "交換者傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Swapper sigil. The target will immediately swap stats once when the latch is applied.", "[creature] 陣亡時，其擁有者選擇一個生物，使其獲得交換者印記。目標獲得此傳花時會立刻交換一次屬性。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lootbox", "戰利品箱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] kills a card, a random card is created in your hand.", "每當 [creature] 殺死一張卡牌，你的手牌中就會產生一張隨機卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Synchronized Fate", "命運相連", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, you lose the game.", "[creature] 死亡時，你輸掉遊戲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Dust", "魔法粉塵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it leaves one of its gems behind on the board. Any future cards in that space will provide those gems.", "[creature] 死亡時，會在檯面上留下一顆它的寶石。之後在該位置的卡牌都會提供那些寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Slot", "藍色魔思力卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide a Blue Mox.", "此卡槽中的卡牌會提供藍色魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Slot", "橘色魔思力卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide an Orange Mox.", "此卡槽中的卡牌會提供橘色魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Mox Slot", "綠色魔思力卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide a Green Mox.", "此卡槽中的卡牌會提供綠色魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Mox Slot", "偉大魔思力卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide all three moxen.", "此卡槽中的卡牌會提供全部三種魔思力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miner", "礦工", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] buries itself during its opponent's turn. While buried, opposing creatures attack its owner directly. When it comes back up, it creates a card in its owner's hand.", "[creature] 會在其對手的回合鑽入地下。鑽地期間，對方生物會直接攻擊其擁有者。它重新出現時，會在其擁有者手牌中產生一張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rubber Stamp", "橡皮圖章", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever you play [creature], it becomes a copy of another creature of your choosing. If this creature has other abilities, those abilities will be transferred (up to the maximum of 4).", "每當你打出 [creature]，它會變成你選擇的另一個生物的副本。若此生物有其他能力，這些能力也會轉移（最多 4 個）。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Launch Missile", "發射導彈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can skip its attack this turn to launch a missile that lands on the next turn, splashing damage to adjacent spaces. Use carefully - ammo is limited.", "[creature] 可以跳過本回合的攻擊來發射一枚導彈，導彈會在下回合落下，並對相鄰位置造成範圍傷害。請謹慎使用，彈藥有限。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Launch Self", "發射自身", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can sacrifice itself to launch a missile that lands on the next turn, splashing damage to adjacent spaces.", "[creature] 可以犧牲自己發射一枚導彈，導彈會在下回合落下，並對相鄰位置造成範圍傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flammable", "易燃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it detonates and sets adjacent spaces on fire for three turns.", "[creature] 死亡時會引爆，使相鄰位置燃燒三回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arsonist", "縱火犯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it sets all spaces on the board on fire for four turns.", "打出 [creature] 時，檯面上所有位置都會燃燒四回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refueler", "補給燃料者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as it has fuel, [creature] will attempt to move beside any creatures you play that also use fuel. Each turn, [creature] will refuel adjacent creatures.", "只要有燃料，[creature] 便會嘗試移到你打出的其他用燃料生物旁邊。每回合，[creature] 都會為相鄰生物補充燃料。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Second Chance", "第二次機會", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a friendly non-Brittle creature dies, if [creature] is on the battlefield, a 1/1 skeleton will be created in its place.", "友方非脆弱生物死亡時，若 [creature] 在戰場上，會在該生物的位置產生一個 1/1 骷髏。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonus Energy Conduit", "額外能量導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, it provides a reserve of energy equal to the player's current maximum energy.", "若 [creature] 是完整電路的一部分，便提供等同於玩家目前能量上限的能量儲備。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclocked", "外骨骼超頻", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it permanently becomes an Exeskeleton with the same abilities. If [creature] has Unkillable, it will be unaffected.", "[creature] 死亡時，會永久變為具有相同能力的骷髏機器人。若 [creature] 擁有不死重生，則不受影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overheat", "過熱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the scales are in your favor, [creature] loses 1 power. When the scales aren't in your favor, [creature] gains 1 power.", "天平對你有利時，[creature] 失去 1 點攻擊力。天平未對你有利時，[creature] 獲得 1 點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power Drain", "能量流失", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] consumes all of its owner's available energy each turn.", "[creature] 每回合消耗其擁有者所有可用能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "純粹主義", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards opposing [creature] have their sigils removed.", "[creature] 正對面的卡牌會失去印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This handles actually removing abilities. You should never see this ability on a card!!!", "這會實際移除能力。你不應該在卡牌上看到此能力！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty Hunter", "賞金獵人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When drawn, [creature] will turn into a random bounty hunter.", "抽到 [creature] 時，它會變成一個隨機賞金獵人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nerf This!", "削弱這招！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it gains a randomly selected negative ability.", "抽到 [creature] 時，它獲得一個隨機選取的負面能力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apotheosis", "神化", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it gains a randomly selected rare ability.", "抽到 [creature] 時，它獲得一個隨機選取的稀有能力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge", "蓄勢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, one energy will be refilled (up to the player's maximum energy)", "打出 [creature] 時，補充一點能量，至多不超過玩家的能量上限。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alarm Clock", "鬧鐘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature that this sigil is pointing to will gain +1 attack. The clock will turn at the beginning of the player's turn.", "此印記指向的生物會獲得 +1 攻擊力。時鐘會在玩家回合開始時轉動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Blessing", "紅寶石祝福", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] provides +1 Attack to all creatures you control.", "[creature] 為你控制的所有生物提供 +1 攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Warrior", "橘色魔思力戰士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it attacks all enemy cards opposite Orange Mox providers its owner controls.", "打出 [creature] 時，它會攻擊其擁有者所控制的橘色魔思力提供者正對面的所有敵方卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burst", "爆裂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards sacrificed to pay for [creature] explode, dealing 10 damage to each adjacent card.", "為支付 [creature] 而犧牲的卡牌會爆炸，對每張相鄰卡牌造成 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Consumer", "寶石吞噬者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all gem vessels on its owner's side of the board are sacrificed.", "打出 [creature] 時，其擁有者一側檯面上的所有寶石容器都會被犧牲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emergence Latch", "奔湧傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When cards sacrificed to pay for [creature] die, their owner chooses a card to gain their first sigil.", "為支付 [creature] 而犧牲的卡牌死亡時，其擁有者選擇一張卡牌，使其獲得被犧牲卡牌的第一個印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Macabre Growth", "可怖成長", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains the attack and health of all cards sacrificed to play it.", "[creature] 獲得為打出它而犧牲的所有卡牌的攻擊力和生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shatter", "碎裂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards sacrificed to pay for [creature] drop 4 bones instead of 1 when they die.", "為支付 [creature] 而犧牲的卡牌死亡時，會掉落 4 根骨頭而非 1 根。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts Sacrifice", "內臟祭品", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards sacrificed to pay for [creature] slime the opposing slot when they die. Cards in slimed slots have one less power.", "為支付 [creature] 而犧牲的卡牌死亡時，會使正對面的卡槽沾上黏液。處於黏液卡槽的卡牌攻擊力減少一點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Charger", "藍色魔思力充能者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it creates a Charge in your hand for each Blue Mox its owner controls. Charge is a spell that refills 1 Energy when played.", "打出 [creature] 時，其擁有者每控制一個藍色魔思力，便在你的手牌中產生一張「充能！」。「充能！」是一張打出時補充 1 點能量的法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it creates a Charge in your hand for each Blue Mox its owner controls. Charge is a command that refills 1 Energy when played.", "打出 [creature] 時，其擁有者每控制一個藍色魔思力，便在你的手牌中產生一張「充能！」。「充能！」是一張打出時補充 1 點能量的命令。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Blessing", "藍寶石祝福", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] reduces the cost of all cards in your hand by 1.", "[creature] 使你手牌中所有卡牌的費用降低 1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrap Dumper", "廢料傾倒者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, a broken bot is played on the opposing space.", "打出帶有此印記的卡牌時，會在正對面的位置打出一個損壞的機器人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrap Salvage", "廢料回收", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, add the total cost of all cards sacrificed to play it, then create a Charge! for each energy, create a Zap! for each gem, create an Upgrade! for each blood, and create a Defend! for each bone.", "打出 [creature] 時，合計為打出它而犧牲的所有卡牌費用：每點能量產生一張「充能！」，每顆寶石產生一張「電擊！」，每點鮮血產生一張「升級！」，每根骨頭產生一張「防禦！」。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bulldoze", "推土", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to cause this card to move in the direction inscribed in the sigil. Creatures that are in the way will be pushed in the same direction.", "支付 1 點能量，使此卡牌朝印記標示的方向移動。擋路的生物會被推向同一方向。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shred", "粉碎", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shred a card from your hand to get +1 Attack (until end of turn). The shredded card behaves as if it died. Unkillable cards and cards Made of Stone cannot be shredded.", "粉碎手牌中的一張卡牌以獲得 +1 攻擊力，持續至回合結束。被粉碎的卡牌視同死亡。不死重生及鐵石心腸的卡牌不能被粉碎。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Side Deck Power", "副牌組攻擊力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards its owner has drawn from the side deck.", "此印記代表的數值等於其擁有者從副牌組抽取的卡牌數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimed Slot", "黏液卡槽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will have its attack reduced by one.", "此卡槽中的卡牌攻擊力降低一點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phase Through", "相位穿越", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its controller's turn, [creature] moves one space in the direction indicated, moving through other cards if necessary until it finds an empty space.", "控制者的回合結束時，[creature] 會朝標示方向移動一格，必要時穿過其他卡牌，直到找到空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Heart", "太陽之心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, its heart stays behind and provides conduit power to the slot.", "[creature] 死亡時，其心臟會留下來，為該卡槽提供導管能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Powered", "太陽能供電", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card slot stays powered at all times, even if it is not in a completed circuit.", "即使不在完整電路內，此卡槽也始終保持供電。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overwhelming Entrance", "壓倒性登場", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opposing creatures are tossed into new slots. Non-conduit terrain is not affected.", "打出 [creature] 時，所有對方生物都會被拋到新的卡槽。非導管地形不受影響。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Familiar", "召喚使魔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it plays a techbeast in an empty adjacent slot.", "打出 [creature] 時，它會在相鄰空卡槽打出一隻科技獸。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zip of Death", "死亡時速", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take 2 damage.", "受到 2 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Target Required", "需要目標", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can only attack lanes that have cards in them.", "[creature] 只能攻擊有卡牌的路線。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Controlled", "操控", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is under control of its opponent. At the end of the turn, it will return to its owner. While being controlled, it cannot be hammered.", "[creature] 由其對手控制。回合結束時會歸還擁有者。被控制期間無法被錘擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "火球術", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its turn, [creature] chooses a card slot to set on fire for three turns.", "其回合結束時，[creature] 會選擇一個卡槽，讓它燃燒三回合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimeball", "黏液球", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its turn, [creature] will choose one slot to become slimed. Cards in a slimed slot lose one power.", "其回合結束時，[creature] 會選擇一個卡槽使其沾上黏液。黏液卡槽中的卡牌失去一點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Vandal", "黏液破壞者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it slimes all slots on the board. Cards in slimed slots lose one power.", "打出 [creature] 時，它會使檯面上所有卡槽沾上黏液。黏液卡槽中的卡牌失去一點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full of Guts", "內臟滿溢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it slimes the opposing slot.", "[creature] 死亡時，會使正對面的卡槽沾上黏液。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seed Sprinter", "種子衝刺者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its controller's turn, [creature] moves one space in the direction indicated (if it can) and plants a seed in its previous space.", "控制者的回合結束時，[creature] 會朝標示方向移動一格（若能移動），並在原位置種下一顆種子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vessel Heart", "容器之心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, a vessel is created in its place.", "帶有此印記的卡牌陣亡時，會在其位置產生一個容器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zap", "電擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deals damage directly to the target.", "直接對目標造成傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Urchin Spawn Conduit", "海膽生成導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Urchin Cells at the end of the owner's turn.", "由 [creature] 接通的電路內的空位會在擁有者回合結束時產生海膽電池。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to set the power of [creature] randomly between 1 and 6.", "支付 2 點能量，將 [creature] 的攻擊力設為 1 至 6 之間的隨機值。", Language.ChineseTraditional);
        }
    }
    public class P03InKayceesModMod
    {
        public static Dictionary<string, string> Consumables = new();
        public static Dictionary<string, string> Mods = new();
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, string> CardParts = new();

        public static void RegisterConsumable(string en, string zh)
        {
            Consumables.Add(en, zh);
        }

        public static void RegisterMod(string en, string zh)
        {
            Mods.Add(en, zh);
        }
        public static void RegisterCard(string en, string zh)
        {
            Cards[en] = zh;
        }
        public static void RegisterCardPart(string en, string zh)
        {
            CardParts[en] = zh;
        }
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for P03InKayceesMod Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW P03 RUN", "P03的新一輪遊戲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE P03 RUN", "繼續P03這輪遊戲", Language.ChineseTraditional);

            // Ability: Base
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Death", "雙重死亡", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head Shot", "爆頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is immune to the effects of Touch of Death, Stinky, and fire.", "[creature] 免疫死亡之觸、臭味和火焰的效果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no Gem Vessels, [creature] perishes.", "若 [creature] 的擁有者沒有控制寶石容器，[creature] 便會陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mine Cryptocurrency", "挖掘加密貨幣", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When part of a conduit, [creature] will generate cryptocurrency.", "作為導管的一部分時，[creature] 會產生加密貨幣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stamp Paperwork", "文件蓋章", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to stamp this paperwork as properly filed and ready for further processing.", "支付 1 點能量，為文件蓋章，確認其已妥善歸檔並準備好進一步處理。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Strike", "強力打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] attacks all cards in all lanes opposing it, or attacks just the center opposing lane if there are no cards it can attack.", "[creature] 會攻擊所有正對面路線中的卡牌；若沒有可以攻擊的卡牌，則只攻擊正中央的對面路線。", Language.ChineseTraditional);
            // Ability: Multiverse
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Bomb Latch", "多元宇宙炸彈傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature in any universe to gain the Multiverse Detonator sigil.", "[creature] 陣亡時，其擁有者選擇任意宇宙中的一個生物，使其獲得多元宇宙引爆器印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Brittle Latch", "多元宇宙脆弱傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature in any universe to gain the Brittle sigil.", "[creature] 陣亡時，其擁有者選擇任意宇宙中的一個生物，使其獲得脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Detonator", "多元宇宙引爆器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all adjacent cards in all universes are dealt 10 damage", "[creature] 死亡時，所有宇宙中的相鄰卡牌都受到 10 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Full of Oil", "多元宇宙燃油滿溢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it adds 3 health to the creature on either side and across from it in every universe.", "[creature] 死亡時，會為每個宇宙中左右兩側及正對面的生物各增加 3 點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Fully Loaded", "多元宇宙滿載", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it leaves a permanent +1 attack bonus in the lane it occupied in every universe.", "[creature] 死亡時，會在每個宇宙中其所佔據的路線留下永久的 +1 攻擊力加成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Guardian", "多元宇宙守護者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is placed opposite to an empty space in any universe, [creature] will move to that empty space.", "任意宇宙中的對方生物被放置在空位正對面時，[creature] 會移至該空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Burrower", "多元宇宙挖掘者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an empty space would be struck, [creature] will cross universes to move to that space to receive the strike instead.", "空位即將受到攻擊時，[creature] 會跨越宇宙移至該位置，代替它承受攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Null Conduit", "多元宇宙無用導管", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuits completed by [creature] are completed in every universe.", "由 [creature] 接通的電路會在每個宇宙中完成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Mighty Leap", "多元宇宙奮力跳躍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will leap across universes to block attacks that occur in this lane in any universe.", "[creature] 會跨越宇宙，阻擋任意宇宙中此路線發生的攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Sentry", "多元宇宙哨兵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature] in any universe, they are dealt 1 damage.", "生物在任意宇宙中移入 [creature] 正對面的位置時，受到 1 點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Shield Latch", "多元宇宙護盾傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature in any universe to gain the Nano Armor sigil.", "[creature] 陣亡時，其擁有者選擇任意宇宙中的一個生物，使其獲得奈米護甲印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Sprinter", "多元宇宙衝刺者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move to the next universe.", "擁有者的回合結束時，[creature] 會移到下一個宇宙。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Strike", "多元宇宙打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space in every universe other than its own.", "[creature] 會攻擊自身所在宇宙以外的每個宇宙中，每一個正對面的位置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Great Mox", "多元宇宙偉大魔思力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Green, Orange, and Blue Gem is provided to the owner's side in every universe.", "打出 [creature] 時，每個宇宙中的擁有者一側各獲得一顆綠色、橘色和藍色寶石。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Hoarder", "多元宇宙囤積者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may search the multiverse for a card that has perished that is capable of traversing the multiverse.", "打出 [creature] 時，你可以在多元宇宙中搜尋一張已陣亡且能跨越多元宇宙的卡牌。", Language.ChineseTraditional);


            // Card: Base
