    public class SmallTweakBorneMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SmallTweak_Borne Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike an opponent directly, even if there is a creature opposing it, unless the creature has this sigil.", "[creature]會直接攻擊對手，即使對面有生物也是如此；但若對面生物也有此印記則不會。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] submerges itself during its opponent's turn. While submerged, opposing creatures attack its owner directly, unless that creature has this sigil.", "[creature]在對手的回合中潛入水下。潛水期間，對方生物會直接攻擊其擁有者，除非該生物也有此印記。", Language.ChineseTraditional);

        }
    }
    public class TooManySigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for TooManySigils Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ants Minus", "減一蟻力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cards power is equal to the amount of Ant's on field, minus this one.", "此卡牌的攻擊力等於場上螞蟻的數量，減去這張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is damaged, It takes half the Damage it would normally.", "此卡牌受到傷害時，只會受到平常一半的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bell Presser", "按鈴者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cards power is equal to the amount of times the bell has been rung.", "此卡牌的攻擊力等於鈴鐺被敲響的次數。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Borrowed Time", "借來的時間", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card perishes its Icecube is summoned if done in time, or else if over the EvolveTurns a corrupt version will be summoned.", "此卡牌陣亡時，若還在時限內，就會召喚冰封的生物；若超過進化回合數，則會召喚其腐化版本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coins Within", "內藏硬幣", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is struck it provides 1 foil to its owner, as long as it lives anyway.", "此卡牌被擊中且仍存活時，為其擁有者提供1枚碎箔。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Covalesce", "休養", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is alive during your endstep, This card gains 1 health.", "你的回合結束時，若帶有此印記的卡牌仍存活，則該卡牌獲得1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Pack", "死亡包裹", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it provides 1 Item to its owner.", "帶有此印記的卡牌陣亡時，為其擁有者提供1個道具。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Out Of Water", "離水之魚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card switches from having Airborne to Waterborne and so on. If neither are present will start with Waterborne.", "回合結束時，此卡牌在飛空與水生印記之間切換。若兩者都沒有，則從水生開始。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain One Battery", "獲得一節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains one Max Energy.", "打出帶有此印記的卡牌時，擁有者獲得1點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Two Batteries", "獲得兩節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains two Max Energy.", "打出帶有此印記的卡牌時，擁有者獲得2點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Three Batteries", "獲得三節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains three Max Energy.", "打出帶有此印記的卡牌時，擁有者獲得3點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Four Batteries", "獲得四節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains four Max Energy.", "打出帶有此印記的卡牌時，擁有者獲得4點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Five Batteries", "獲得五節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains five Max Energy.", "打出帶有此印記的卡牌時，擁有者獲得5點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Six Batteries", "獲得六節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains six Max Energy.", "打出帶有此印記的卡牌時，擁有者獲得6點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Locked", "心之鎖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, It only takes 1 Damage.", "帶有此印記的卡牌受到傷害時，只會受到1點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, a card is added to your hand.", "帶有此印記的卡牌受到傷害時，將一張卡牌加入你的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is on the field during your endstep, a card is launched to one of your empty spaces.", "你的回合結束時，若帶有此印記的卡牌在場上，會將一張卡牌投放到你的一個空位。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose One Battery", "失去一節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses one Max Energy.", "打出帶有此印記的卡牌時，擁有者失去1點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Two Batteries", "失去兩節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses two Max Energy.", "打出帶有此印記的卡牌時，擁有者失去2點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Three Batteries", "失去三節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses three Max Energy.", "打出帶有此印記的卡牌時，擁有者失去3點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Four Batteries", "失去四節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses four Max Energy.", "打出帶有此印記的卡牌時，擁有者失去4點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Five Batteries", "失去五節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses five Max Energy.", "打出帶有此印記的卡牌時，擁有者失去5點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Six Batteries", "失去六節電池", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses six Max Energy.", "打出帶有此印記的卡牌時，擁有者失去6點最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Fourth Chance Instakill", "四分之一機率即死", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card would be attacked, there is a 25% chance that the striker perishes.", "此卡牌即將受到攻擊時，攻擊者有25%的機率陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotting", "腐爛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is alive during your endstep, this card loses 1 power and 1 health.", "你的回合結束時，若帶有此印記的卡牌仍存活，該卡牌會失去1點攻擊力和1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is on field during your endstep, this card moves in the direction inscribed in the sigil, and a card is played in its previous space.", "你的回合結束時，若帶有此印記的卡牌在場上，它會朝印記標示的方向移動，並在原位置打出一張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, It takes 1 less Damage.", "帶有此印記的卡牌受到傷害時，受到的傷害減少1點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treasure Tracker", "尋寶者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At The end of the Owners turn, this card will provide the owner with 1 foil.", "擁有者的回合結束時，此卡牌為擁有者提供1枚碎箔。", Language.ChineseTraditional);

        }
    }
    public class PizzaTowerCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for PizzaTowerCards Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Tower Expansion", "披薩塔擴展", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Tower Themed Cards", "披薩塔主題卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Anchovi", "飛行鯷魚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying fish, how ridiculous.", "會飛的魚，真荒謬。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Rat", "壞老鼠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bad rat. No, not that kind.", "一隻壞老鼠。不，不是那種。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandit Chicken", "強盜雞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Speedy and goes well with sauce.", "速度很快，配醬汁也很搭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Box Goblin", "披薩盒哥布林", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Expert with demolitions, not so much with clothing.", "擅長爆破，卻不怎麼擅長穿衣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brick", "磚塊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chef's best friend and an impressive wall.", "廚師最好的朋友，也是令人印象深刻的牆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can of Whoop Ass", "痛扁罐頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardboard Tank", "紙板坦克", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobile and fragile machine of war.", "一台能移動又脆弱的戰爭機器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Slime", "乳酪泥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harmless.", "無害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fake Peppino", "偽佩皮諾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A half baked clone of a paranoid chef.", "偏執廚師的半生不熟複製人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fork Knight", "叉子騎士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly, but can still catch someone off guard if placed right.", "膽小，但放在正確位置仍能讓人措手不及。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gabaghoul", "冷肉惡鬼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deadly spirit, haunting from beyond the grave.", "來自墳墓彼端、徘徊不去的致命靈體。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gerome", "傑羅姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tower janitor, unlocker of secrets, not here though", "塔樓管理員、祕密的解鎖者，不過這裡可不是", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost John", "幽靈約翰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit of a fallen John, seeking revenge.", "陣亡約翰的靈魂，正在尋求復仇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost King", "幽靈王", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruler of the Pizzascape.", "披薩境地的統治者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Knight", "幽靈騎士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defender of the Pizzascare.", "披薩驚魂的守衛者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gustavo", "古斯塔沃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A helpful chef, always there for his friends", "樂於助人的廚師，總是陪伴朋友", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentucky Kenny", "肯塔基肯尼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tosses hot wings, too hot.", "丟出香辣雞翅，辣得過頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mini John", "迷你約翰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "May be small, but still packs a punch.", "也許很小，卻依然很有力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Monster", "乳酪怪物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Stretcher.", "伸展者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mushroom Monster", "蘑菇怪物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't Make a Sound.", "別出聲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pineapple Monster", "鳳梨怪物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sausage Monster", "香腸怪物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomato Monster", "番茄怪物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mr. Stick", "史提克先生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An inventor and a salesman, two traits that spell greed", "發明家兼推銷員，這兩種特質都意味著貪婪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Noise", "噪音", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An insufferable nuisance, though he does have tricks up his sleeve", "令人受不了的麻煩鬼，不過他確實留有幾手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noise Bomb", "噪音炸彈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dangerous, but can be useful.", "危險，但可能有用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noisette", "諾伊塞特", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The girlfriend of The Noise, also runs a cafe", "噪音的女友，也經營著一家咖啡館", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noisey", "吵鬧鬼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can't attack, but can be used as a wall.", "無法攻擊，但能當作一道牆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Olive Trooper", "橄欖兵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An invasive, alien species.", "入侵的外來物種。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pencer", "潘瑟", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tries to act noble, but is really just a coward.", "想表現得高貴，實際上卻只是個膽小鬼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pepperoni Goblin", "辣腸哥布林", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An annoyance.", "真煩人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pepperoni Goblin Bat", "辣腸哥布林蝙蝠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An annoyance, but now it flys.", "很煩人，而且現在還會飛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pepperman", "甜椒人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An artist and a narcissist, but strong", "藝術家兼自戀狂，不過很強", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peppibot", "佩皮機器人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A robotic replication of a paranoid chef.", "偏執廚師的機器人複製品。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peppino", "佩皮諾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paranoid and ready to pound anything into the ground", "偏執，隨時準備把任何東西砸進地面", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peppino Clone", "佩皮諾複製人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An imperfect clone of a paranoid chef.", "偏執廚師的不完美複製人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pillar John", "石柱約翰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Structural integrity is important, and this one is more than happy to supply", "結構的完整性很重要，而這傢伙很樂意提供支撐", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pineacool", "酷鳳梨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's one cool customer.", "真是個酷傢伙。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Face", "披薩臉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ruler of the Pizza Tower, powerful and fast", "披薩塔的統治者，強大又迅速", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ruler of the Pizza Tower, powerful and holding a secret if it can evolve", "披薩塔的統治者，力量強大；若能進化，還藏著一個祕密", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Pizza Face", "破碎的披薩臉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The broken ruler of the Pizza Tower", "破碎的披薩塔統治者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gear", "齒輪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Head", "披薩頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ruler of the Pizza Tower, powerful and... goofy", "披薩塔的統治者，強大而且……滑稽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ruler of the Pizza Tower, powerful, goofy, and angry", "披薩塔的統治者，強大、滑稽又憤怒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizzard", "披薩法師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mystical wizard... did I grab the wrong deck?", "一位神祕的巫師……我拿錯牌組了嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Slug", "披薩蛞蝓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cranky smoker from the Pig City.", "來自豬城的暴躁煙鬼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Soldier", "披薩士兵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A conscript, ready for war.", "準備上戰場的徵召兵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizzice", "冰披薩", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen pizza.", "冰凍披薩。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ranch Shooter", "牧場射手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Easily spooked and trigger happy.", "容易受驚，也很愛開槍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snick", "刺尼克", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An out of work porcupine running a game expo", "一隻失業的豪豬，正在舉辦遊戲博覽會", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snick.EXE", "刺尼克.EXE", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... odd. I don't remember that one.", "嗯……奇怪。我不記得那個。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowman", "雪人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can't attack, but it's nose is far from a harmless carrot.", "不能攻擊，但牠的鼻子絕非無害的胡蘿蔔。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toppins", "配料小人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adorable and delicious", "可愛又美味", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treasure Chest Guy", "寶箱男", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Won't attack, but can provide some useful resources.", "不會攻擊，但能提供一些有用的資源。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UFOlive", "幽浮橄欖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vigilante", "義警", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cheese slime fighting for justice", "為正義而戰的乳酪泥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weenie", "小香腸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weenie.", "小香腸。", Language.ChineseTraditional);

        }
    }
    public class InGameCardCreatorMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for InGame_Card_Creator Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You entered the [c:bR]card creation[c:] mode.", "你進入了[c:bR]卡牌創作[c:]模式。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears that you lost normally.", "看來你正常地輸了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only worthy challengers may access the Card Creator.", "只有合格的挑戰者才能使用卡牌創作器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try again, but this time open the backroom door normally.", "再試一次，不過這次要正常打開密室的門。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "current card", "目前的卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should give it a name.", "你該給它取個名字。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please type the description.", "請輸入描述。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time for you to return.", "是時候讓你回去了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loading portraits.", "正在載入卡面。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "previous page", "上一頁", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "next page", "下一頁", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And another. This time I will use its [c:bR]power[c:].", "再選一張。這次我會使用它的[c:bR]攻擊力[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose the [c:bR]complexity[c:] of card. This determines when it is unlocked in the tutorial.", "選擇卡牌的[c:bR]複雜程度[c:]。這決定了它在教學中何時解鎖。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "free", "免費", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, choose a card to draw the [c:bR]cost[c:] from.", "請選擇一張卡牌，從中取得[c:bR]費用[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you want to add another [c:bR]cost[c:]?", "你想再增加一種[c:bR]費用[c:]嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which card it will evolve into.", "選擇它會進化成哪張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which card it will create upon death.", "選擇它死亡時會產生哪張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How many turns[c:] should it take for this card to evolve?", "這張卡牌需要[c:bR]多少回合[c:]才能進化？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And another. This time I will use its [c:bR]health[c:].", "再選一張。這次我會使用它的[c:bR]生命力[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "regular", "常規", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "rare", "稀有", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hidden", "隱藏", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose the [c:bR]type[c:] of card.", "選擇卡牌的[c:bR]類型[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now choose some cards from which we will extract the [c:bR]sigils[c:]. Note that some may not work correctly.", "現在選擇幾張卡牌，我們會從中提取[c:bR]印記[c:]。注意有些印記可能無法正常運作。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finally, choose the hidden [c:bR]special abilities[c:] and [c:bR]traits[c:]. Again, some may not function properly.", "最後，選擇隱藏的[c:bR]特殊能力[c:]和[c:bR]特性[c:]。同樣，有些可能無法正常運作。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cost (set)", "費用（設定）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cost (add)", "費用（增加）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "sigils", "印記", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "tribes", "族類", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "sp. abilities", "特殊能力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "portrait", "卡面", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "complexity", "複雜程度", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "alternate portrait", "備用卡面", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "finish", "完成", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a property.", "選擇一項屬性。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now choose the [c:bR]tribes[c:].", "現在選擇[c:bR]族類[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "export and quit", "匯出並離開", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "export and create another", "匯出並建立另一張", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quit without exporting", "不匯出直接離開", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "create another without exporting", "不匯出直接建立另一張", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What should I do with this card?", "我該怎麼處理這張卡牌？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exporting card...", "正在匯出卡牌……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card has been created, loaded, and exported to IGCCExports inside the BepInEx plugins folder.", "卡牌已建立、載入並匯出至 BepInEx 外掛資料夾內的 IGCCExports。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]Special Ability of {0}[c:].", "[c:bR]{0}的特殊能力[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]Trait of {0}[c:].", "[c:bR]{0}的特性[c:]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]No Special Abilities. No Traits[c:].", "[c:bR]無特殊能力。無特性[c:]。", Language.ChineseTraditional);
