                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of [c:bR]" + value + " bones[c:].", "費用為[c:bR]" + value + "根骨頭[c:]。", Language.ChineseTraditional);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of [c:bR]" + value + " blood[c:].", "費用為[c:bR]" + value + "點鮮血[c:]。", Language.ChineseTraditional);
