            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of [c:bR]1 bone[c:].", "費用為[c:bR]1根骨頭[c:]。", Language.ChineseTraditional);
