            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 turn", "1回合", Language.ChineseTraditional);
            Dictionary<GemType, string> gemTypesEn = new Dictionary<GemType, string>
