    public class AgasMagnificusExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AgasMagnificusExpansion Mod");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aga's Magnificus Expansion", "Aga的麥尼菲庫斯模組擴充包", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "麥尼菲庫斯模組的非官方擴充包，收錄 [count] 位獨特又繽紛的法師。", Language.ChineseTraditional);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascension Mage", "飛昇法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Ascension Mage", "飛昇法師", "Utilising the power of time they grant knowledge and experience from far beyond", "他們利用時間的力量，傳授來自遙遠彼方的知識與經驗");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utilising the power of time they grant knowledge and experience from far beyond", "他們利用時間的力量，傳授來自遙遠彼方的知識與經驗", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ash Mage", "灰燼法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Ash Mage", "灰燼法師", "Ashes he sheds from his own body, scorching any and all who oppose him", "他從身上抖落灰燼，灼燒所有與他作對的人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashes he sheds from his own body, scorching any and all who oppose him", "他從身上抖落灰燼，灼燒所有與他作對的人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Egg", "破蛋", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Broken Egg", "破蛋", "Only the greatest of trainers might find this treasure", "唯有最偉大的訓練師才有可能找到這件寶藏");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "唯有最偉大的訓練師才有可能找到這件寶藏", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chosen One", "天選之子", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Chosen One", "天選之子", "My selected favourite. He still clings to his elders though...", "我親自選出的最愛。不過，他仍依戀著長輩……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My selected favourite. He still clings to his elders though...", "我親自選出的最愛。不過，他仍依戀著長輩……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanliness Mage", "清潔法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Cleanliness Mage", "清潔法師", "The proudest of all my pupils. None come close to his bath superpowers", "我所有學生中最驕傲的一位。沒人能比得上他的洗澡超能力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proudest of all my pupils. None come close to his bath superpowers", "我所有學生中最驕傲的一位。沒人能比得上他的洗澡超能力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleric", "牧師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Cleric", "牧師", "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "憑藉神聖魔法的力量，他承受所有人的痛苦，並治癒他們的傷口");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "憑藉神聖魔法的力量，他承受所有人的痛苦，並治癒他們的傷口", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clock Mage", "時鐘法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Clock Mage", "時鐘法師", "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "精通時間本身的巫師。瀕死時，他會回到過去並重獲新生");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "精通時間本身的巫師。瀕死時，他會回到過去並重獲新生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature Collector", "生物收藏家", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Creature Collector", "生物收藏家", "He had searched far and wide for his little companion, you see", "他曾到處尋找他的小夥伴，你看");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He had searched far and wide for his little companion, you see", "他曾到處尋找他的小夥伴，你看", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division Mage", "分裂法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Division Mage", "分裂法師", "So the card says at least... I assumed those freaks were long dealth with", "至少卡牌上是這麼說的……我還以為那些怪胎早就被處理掉了");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So the card says at least... I assumed those freaks were long dealth with", "至少卡牌上是這麼說的……我還以為那些怪胎早就被處理掉了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg", "蛋", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Egg", "蛋", "Only the greatest of trainers might find this treasure", "唯有最偉大的訓練師才有可能找到這件寶藏");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "唯有最偉大的訓練師才有可能找到這件寶藏", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "德魯伊", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Druid", "德魯伊", "Nature's primal devotee, feeding on sapped mana to cure his allies", "大自然最原始的信徒，以汲取的魔力為食來治癒盟友");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature's primal devotee, feeding on sapped mana to cure his allies", "大自然最原始的信徒，以汲取的魔力為食來治癒盟友", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanter", "附魔師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Enchanter", "附魔師", "He spews cosmic magicks upon his demise, enchanting everything nearby", "殞命時噴出宇宙魔法，為周圍的一切附魔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He spews cosmic magicks upon his demise, enchanting everything nearby", "殞命時噴出宇宙魔法，為周圍的一切附魔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EveryMage", "全能法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("EveryMage", "全能法師", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mage", "法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("mage", "法師", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evoker", "塑能師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Evoker", "塑能師", "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "教義令人作嘔的不祥蠢貨。牠召喚的蛇是最致命的種類");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "教義令人作嘔的不祥蠢貨。牠召喚的蛇是最致命的種類", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Summon", "蛇之召", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Serpent Summon", "蛇之召", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebender", "縱火狂", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Firebender", "縱火狂", "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "在激烈的戰鬥中精神奕奕，總在尋找下一個火球的犧牲者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "在激烈的戰鬥中精神奕奕，總在尋找下一個火球的犧牲者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "前瞻法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Foresight Mage", "前瞻法師", "As he gazes upon your future, attacks that may come his way he forever predicts", "當他凝視你的未來，總能預見朝他而來的攻擊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As he gazes upon your future, attacks that may come his way he forever predicts", "當他凝視你的未來，總能預見朝他而來的攻擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "前瞻法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Foresight Mage", "前瞻法師", "Gazing into the future, he may see any body who dares make an approach", "凝視未來的他，或許能看見任何膽敢靠近的人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazing into the future, he may see any body who dares make an approach", "凝視未來的他，或許能看見任何膽敢靠近的人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "冰川", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Glacier", "冰川", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "餓者骷髏", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Gashadokuro", "餓者骷髏", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Sentinel", "寶石哨兵", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Gem Sentinel", "寶石哨兵", "the elite warrior unit enchanted with the aura of my moxen", "沐浴在我魔思力光環中的精英戰士部隊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the elite warrior unit enchanted with the aura of my moxen", "沐浴在我魔思力光環中的精英戰士部隊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grand Astrologer", "研星者", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Grand Astrologer", "研星者", "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "戰場永遠是他的遊樂場，空間是他的武器。一切在他面前都無所遁形。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "戰場永遠是他的遊樂場，空間是他的武器。一切在他面前都無所遁形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity Mage", "重力法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Gravity Mage", "重力法師", "A master of the forces of gravity. Any and all mox bend to his unwavering will", "重力的大師。所有魔思力都屈服於他堅定的意志");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A master of the forces of gravity. Any and all mox bend to his unwavering will", "重力的大師。所有魔思力都屈服於他堅定的意志", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Illusion Mage", "幻術師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Illusion Mage", "幻術師", "Dawning his tricks and disguises, there is none scarier. At first glance", "披上詭計與偽裝，沒有誰比他更可怕。乍看之下是如此");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawning his tricks and disguises, there is none scarier. At first glance", "披上詭計與偽裝，沒有誰比他更可怕。乍看之下是如此", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infestation Mage", "感染法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Infestation Mage", "感染法師", "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "我想，像你這樣篡位的挑戰者也能稍微享受變身邪術");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "我想，像你這樣篡位的挑戰者也能稍微享受變身邪術", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insulting Mirror", "侮辱魔鏡", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Insulting Mirror", "侮辱魔鏡", "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "魔法的威脅四處飛舞，嘲弄不停、口出狂言；你的憤怒，都將化作它自身的力量");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "魔法的威脅四處飛舞，嘲弄不停、口出狂言；你的憤怒，都將化作它自身的力量", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "鐵處女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Iron Maiden", "鐵處女", "My finest of paladins working the finest of hours. No soul goes through his grand wall", "我最優秀的聖騎士，辛勤工作。沒有人能穿過他那宏偉的牆");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My finest of paladins working the finest of hours. No soul goes through his grand wall", "我最優秀的聖騎士，辛勤工作。沒有人能穿過他那宏偉的牆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kickmoxer", "魔思力戮魔", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Kickmoxer", "魔思力戮魔", "He dedicated his life to the art of combat, and may adapt to whomever he faces", "他畢生鑽研戰鬥藝術，能適應任何對手");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He dedicated his life to the art of combat, and may adapt to whomever he faces", "他畢生鑽研戰鬥藝術，能適應任何對手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "萬人冢", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Mass Grave", "萬人冢", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Agairan", "阿蓋蘭大師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Master Agairan", "阿蓋蘭大師", "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "深紅奇美拉。這位煉金術教師注入了最致命的毒素");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "深紅奇美拉。這位煉金術教師注入了最致命的毒素", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bluetwo", "雙藍大師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Master Bluetwo", "雙藍大師", "The steel knight of sapphire. Even after death her psychic presence commands our foes", "藍寶石的鋼鐵騎士。即使死後，她的精神仍能操縱我們的敵人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The steel knight of sapphire. Even after death her psychic presence commands our foes", "藍寶石的鋼鐵騎士。即使死後，她的精神仍能操縱我們的敵人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Doublin", "道布林大師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Master Doublin", "道布林大師", "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "白骨領主的救世主。祈禱的教師已學會熟練地竊取精華。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "白骨領主的救世主。祈禱的教師已學會熟練地竊取精華。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megawizard", "超級巫師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Megawizard", "超級巫師", "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "他身形龐大、氣勢兇惡，頭腦卻不太靈光。如此原始的力量終究無法永存");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "他身形龐大、氣勢兇惡，頭腦卻不太靈光。如此原始的力量終究無法永存", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meteorologist", "氣象學者", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Meteorologist", "氣象學者", "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "他們仔細觀察宇宙，向選定的對象投下流星風暴。也許他們很殘忍？也許不是？只有他們自己知道");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "他們仔細觀察宇宙，向選定的對象投下流星風暴。也許他們很殘忍？也許不是？只有他們自己知道", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miniwizard", "迷你巫師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Miniwizard", "迷你巫師", "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "因身形極小而受詛咒的法師。不過別擔心，他找到了解決方法。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "因身形極小而受詛咒的法師。不過別擔心，他找到了解決方法。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Thief", "幻靈盜賊", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Phantom Thief", "幻靈盜賊", "A billowing cloud of crime, darting in and out, and stealing his foes", "一團翻滾的犯罪烏雲，來去迅疾，偷走敵人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A billowing cloud of crime, darting in and out, and stealing his foes", "一團翻滾的犯罪烏雲，來去迅疾，偷走敵人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preformence Mage", "序言法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Preformence Mage", "序言法師", "Who knows to what ends his mystery rabbit has been through", "誰知道他那神祕的兔子到底經歷了什麼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows to what ends his mystery rabbit has been through", "誰知道他那神祕的兔子到底經歷了什麼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen's Familiar", "皇后使魔", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Queen's Familiar", "皇后使魔", "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "由美麗野獸組成的壯麗奇美拉。牠將自己的軍隊藏在體內");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "由美麗野獸組成的壯麗奇美拉。牠將自己的軍隊藏在體內", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RisingHunger", "加劇的飢餓", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("RisingHunger", "加劇的飢餓", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roach Familiar", "蟑螂僕從", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Roach Familiar", "蟑螂僕從", "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "一隻以精神造出的蟑螂。牠的意志讓牠擁有復活能力！只是最終仍會失敗。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "一隻以精神造出的蟑螂。牠的意志讓牠擁有復活能力！只是最終仍會失敗。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Wizard", "幻影巫師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Shadow Wizard", "幻影巫師", "A mobster of the underseen. He calls the shadows to gang on it's foes", "隱祕世界的黑幫成員。他召喚陰影群起對付敵人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobster of the underseen. He calls the shadows to gang on it's foes", "隱祕世界的黑幫成員。他召喚陰影群起對付敵人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shinobi", "忍者", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Shinobi", "忍者", "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "黑暗中的戰士，趁人不備出擊，在無人佔據或看見的地方");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "黑暗中的戰士，趁人不備出擊，在無人佔據或看見的地方", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shower Mage", "淋浴法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Shower Mage", "淋浴法師", "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "我學院的棄徒，而且活該如此！他的惡臭程度只能用魔法形容……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "我學院的棄徒，而且活該如此！他的惡臭程度只能用魔法形容……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sludge Mage", "淤泥法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Sludge Mage", "淤泥法師", "An entity of unknown origins, powered off the ill spreading plague to all", "來歷不明的實體，以病者為力量，向所有人散播瘟疫");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An entity of unknown origins, powered off the ill spreading plague to all", "來歷不明的實體，以病者為力量，向所有人散播瘟疫", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sui-Sage", "隋聖人", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Sui-Sage", "隋聖人", "The leader of a pack, soon to be packed away", "一群人的領袖，很快就要被打包帶走");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The leader of a pack, soon to be packed away", "一群人的領袖，很快就要被打包帶走", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "召喚師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Summoner", "召喚師", "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "生命藝術中的瘋子，憑空創造生命，還有令人恐懼的感知能力");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "生命藝術中的瘋子，憑空創造生命，還有令人恐懼的感知能力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Symmetrical Mage", "對稱法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Symmetrical Mage", "對稱法師", "Everyone has two sides to them, you see. Especially once they mess with my temper", "每個人都有兩面性，你看。尤其是在他們惹我發火之後");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has two sides to them, you see. Especially once they mess with my temper", "每個人都有兩面性，你看。尤其是在他們惹我發火之後", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teleportation Mage", "傳送法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Teleportation Mage", "傳送法師", "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "無盡傳送門的使者，無限穿梭戰場，抵消迎面而來的攻擊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "無盡傳送門的使者，無限穿梭戰場，抵消迎面而來的攻擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torrent Mage", "洪流法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Torrent Mage", "洪流法師", "An apprentice of the ocean utilising it to drown the lands and the terrain above", "海洋的學徒，借其力量淹沒土地和地形");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An apprentice of the ocean utilising it to drown the lands and the terrain above", "海洋的學徒，借其力量淹沒土地和地形", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Untamed Dragon", "狂野魔龍", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Untamed Dragon", "狂野魔龍", "Legends whisper this beast, was once a companion to the mox master Goranj", "傳說這頭野獸曾是魔思力大師哥蘭吉的夥伴");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends whisper this beast, was once a companion to the mox master Goranj", "傳說這頭野獸曾是魔思力大師哥蘭吉的夥伴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warlock", "邪術士", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Warlock", "邪術士", "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "研究鮮血魔法的漆黑巫師，將流出的血化為可怕的武器");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "研究鮮血魔法的漆黑巫師，將流出的血化為可怕的武器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Witch", "罪惡魔女", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Wicked Witch", "罪惡魔女", "A flying jesting witch, laughing your sorrows and posioning your armies", "一位飛翔的滑稽魔女，嘲笑你的悲傷，並使你的軍隊中毒");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying jesting witch, laughing your sorrows and posioning your armies", "一位飛翔的滑稽魔女，嘲笑你的悲傷，並使你的軍隊中毒", Language.ChineseTraditional);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Aura", "尖酸氣質", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Acid Aura", "尖酸氣質");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 damage to the creature opposing it every turn", "[creature]每回合對其對面的生物造成1點傷害", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakening", "羽化登仙", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Awakening", "羽化登仙");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner chooses an ally creature to evolve into a higher form.", "打出[creature]時，其擁有者選擇一個友方生物，讓它進化為更高的形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backfire Strike", "反噬打擊", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Backfire Strike", "反噬打擊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] damages creatures that oppose those it attacks.", "[creature]攻擊時，也會對持有者一側、與攻擊目標正對的生物造成傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "嗜血者", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Blood Guzzler", "嗜血者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it gains 1 health for each damage dealt.", "[creature]造成傷害時，每造成1點傷害便獲得1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brute Parasite", "殘忍寄生", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Brute Parasite", "殘忍寄生");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on the opposing space.", "打出[creature]時，會在正對面的位置產生一顆蛋。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deluge", "洪流", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Deluge", "洪流");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, opponent creatures with 0 power drown and get given the Waterborne sigil.", "打出[creature]時，攻擊力為0的對手生物會下潛並獲得水生印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division", "分裂", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Division", "分裂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] splits into 2 identical clones, each bearing half of it's original stats.", "攻擊後，[creature]分裂為2個相同副本，各自具有原始屬性的一半。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry", "哨兵", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Sentry", "哨兵");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "生物移入[creature]正對面的位置時，該生物受到1點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, let one never underestimate the speed of a Foresight Mage.", "啊，永遠別低估前瞻法師的速度。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healing Aura", "治癒光環", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Healing Aura", "治癒光環");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals nearby allied creatures. The healing is proportionate to it's power.", "[creature]治療附近的友方生物，治療量與牠的攻擊力成正比。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Stealer", "偷心者", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Heart Stealer", "偷心者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] kills a creature, it gets added to your hand.", "[creature]殺死生物時，將被殺死的生物卡牌加入你的手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignis Incant", "火焰魔咒", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Ignis Incant", "火焰魔咒");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood for [creature] to deal 2 damage to a chosen opposing slot.", "支付1點鮮血，讓[creature]對選定的對手卡槽造成2點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intimidate", "恐嚇", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Intimidate", "恐嚇");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the creature opposing it will flee to their right.", "[creature]被放到檯面上時，正對面的生物會朝牠自己的右側逃跑。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "孤獨", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Lonesome", "孤獨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "每個相鄰空位都讓 [creature] 的攻擊力 +1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Burst", "魔法爆發", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Magic Burst", "魔法爆發");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After perishing, creatures adjascent to [creature] have their powers increased by 1.", "[creature]陣亡後，與牠相鄰的生物攻擊力增加1點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psystrike", "精神破壞", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Psystrike", "精神破壞");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] perishes, it manipulates the creature opposing it to strike both of it's adjascent allies.", "[creature]陣亡後，操縱正對面的生物攻擊該生物兩側的盟友。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Master", "訓蛇大師", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Serpent Master", "訓蛇大師");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, [creature] spawns a Summon Serpent on a space of it's owner's choosing. A Summon Serpent is defined as: 1 power, 1 health.", "每回合開始時，[creature]會在擁有者選擇的位置產生一張蛇之召。蛇之召的屬性為1點攻擊力、1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Strike", "幻影衝擊", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Shadow Strike", "幻影衝擊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls upon the shadows of creatures adjascent to it's target to strike it as well.", "[creature]也會召喚目標相鄰生物的影子來攻擊該目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tidal Lock", "潮汐鎖定", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Tidal Lock", "潮汐鎖定");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of it's owner's turn, [creature] will pull small creatures, like squirrels, into it's orbit.", "擁有者的回合開始時，[creature]會把松鼠等小型生物拉入自己的軌道。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wizard's Heart", "巫師之心", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Wizard's Heart", "巫師之心");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Mox card corresponding to the current gems you control takes it's place.", "[creature]陣亡時，與你目前控制的寶石對應的一張魔思力卡牌會取代牠的位置。", Language.ChineseTraditional);

        }
    }
    public class MagModExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagModExpansion Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beaver's Defense", "河狸防禦", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Beaver's Defense", "河狸防禦", "Curating defensive dams upon use, not bad for a dire situation.", "使用時製造防禦用水壩，對危急情況來說還不錯。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curating defensive dams upon use, not bad for a dire situation.", "使用時製造防禦用水壩，對危急情況來說還不錯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Sage", "炸彈賢者", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Bomb Sage", "炸彈賢者", "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "這位賢者受到攻擊時總會「爆炸」……無論字面或比喻意義上都是。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "這位賢者受到攻擊時總會「爆炸」……無論字面或比喻意義上都是。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boxing Champ", "拳擊冠軍", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Boxing Champ", "拳擊冠軍", "Rejecting the use of wands, this champion prefers to settle things with his fists.", "這位冠軍拒絕使用魔杖，偏好用拳頭解決問題。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejecting the use of wands, this champion prefers to settle things with his fists.", "這位冠軍拒絕使用魔杖，偏好用拳頭解決問題。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "雷龍", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Brontosaurus", "雷龍", "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "乳酪巫師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Cheese Wizard", "乳酪巫師", "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "作為受過訓練的廚師法師，乳酪巫師運用智慧與神祕力量達成目標。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "作為受過訓練的廚師法師，乳酪巫師運用智慧與神祕力量達成目標。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheezling", "乳酪", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Cheezling", "乳酪", "With cheese like this, who needs friends?", "有了這樣的乳酪，誰還需要朋友？");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With cheese like this, who needs friends?", "有了這樣的乳酪，誰還需要朋友？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathy", "心靈感應", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Telepathy", "心靈感應", "A pupil can gather all the resources they need through sheer will alone.", "學徒光憑意志就能收集所需的一切資源。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pupil can gather all the resources they need through sheer will alone.", "學徒光憑意志就能收集所需的一切資源。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Hit", "直接傷害", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Direct Hit", "直接傷害", "Upon being casted, your opponent will instantly take three damage.", "施放後，你的對手立即受到3點傷害。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon being casted, your opponent will instantly take three damage.", "施放後，你的對手立即受到3點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "神秘的蛋", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Mysterious Egg", "神秘的蛋", "Who knows what could hatch from this egg...", "誰知道這顆蛋會孵出什麼……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows what could hatch from this egg...", "誰知道這顆蛋會孵出什麼……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faceless", "無面者", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Faceless", "無面者", "A hollow shell of a mage, desperately looking for something to call its own.", "法師的空殼，拼命尋找屬於自己的東西。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow shell of a mage, desperately looking for something to call its own.", "法師的空殼，拼命尋找屬於自己的東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faker", "偽造者", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Faker", "偽造者", "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "撒謊、作弊、否認。偽造者為了毫髮無傷地逃脫無所不用其極……");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "撒謊、作弊、否認。偽造者為了毫髮無傷地逃脫無所不用其極……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Figletar", "菲格拉塔", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Figletar", "菲格拉塔", "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "這位巫師曾讓邪惡國王遭逢可怕的命運，對擂台上的事也略知一二。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "這位巫師曾讓邪惡國王遭逢可怕的命運，對擂台上的事也略知一二。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "星火燎原", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Firestarter", "星火燎原", "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "施放這個法術時要小心，學徒們說決鬥場可能會有點燙。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "施放這個法術時要小心，學徒們說決鬥場可能會有點燙。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fridge Mage", "冰箱法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Fridge Mage", "冰箱法師", "Its cold atmosphere will chill foes, weakening their offensive power.", "牠冰冷的氣息會凍寒敵人，削弱他們的攻擊力。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its cold atmosphere will chill foes, weakening their offensive power.", "牠冰冷的氣息會凍寒敵人，削弱他們的攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembro", "寶石兄弟", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Gembro", "寶石兄弟", "The ability to tank any hit once, this pupil has high gusto.", "這名學徒能承受一次任何攻擊，鬥志十分高昂。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ability to tank any hit once, this pupil has high gusto.", "這名學徒能承受一次任何攻擊，鬥志十分高昂。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Tick", "寶石蜱蟲", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Gem Tick", "寶石蜱蟲", "An elusive tick, which grants power to others via its mox body.", "難以捉摸的蜱蟲，以魔思力身軀賦予其他人力量。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elusive tick, which grants power to others via its mox body.", "難以捉摸的蜱蟲，以魔思力身軀賦予其他人力量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "鬼靈恐龍", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Ghost Dinosaur", "鬼靈恐龍", "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Eye", "第三隻眼", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Third Eye", "第三隻眼", "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "借助第三隻眼的力量，此法術讓施法者從自己的牌組中選取一張卡牌加入手牌。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "借助第三隻眼的力量，此法術讓施法者從自己的牌組中選取一張卡牌加入手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "棒球法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Baseball Mage", "棒球法師", "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "這名法師的魔杖也能當棒球棍，耐用程度令人驚訝。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "這名法師的魔杖也能當棒球棍，耐用程度令人驚訝。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Golem", "寒冰傀儡", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Ice Golem", "寒冰傀儡", "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "來自冰凍山巔，融化似乎從未讓這個莽漢在意。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "來自冰凍山巔，融化似乎從未讓這個莽漢在意。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looting Bandit", "劫掠匪徒", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Looting Bandit", "劫掠匪徒", "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "歐魯大師女武神的遠方追隨者，努力訓練以成為她們的一員。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "歐魯大師女武神的遠方追隨者，努力訓練以成為她們的一員。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mage", "魔力法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Mana Mage", "魔力法師", "Brings together the energy that emits from Mana to deliver powerful strikes.", "匯聚魔力散發出的能量，發出強力打擊。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brings together the energy that emits from Mana to deliver powerful strikes.", "匯聚魔力散發出的能量，發出強力打擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pondering Pupil", "苦思學徒", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Pondering Pupil", "苦思學徒", "It draws from your gem pile using the powers of its mind alone.", "它只靠心靈力量，就能從你的寶石堆抽牌。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws from your gem pile using the powers of its mind alone.", "它只靠心靈力量，就能從你的寶石堆抽牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Mage", "鏡子法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Mirror Mage", "鏡子法師", "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "魔鏡啊魔鏡，所有占卜者中誰最出色？");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "魔鏡啊魔鏡，所有占卜者中誰最出色？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whack-A-Mage", "鑽地法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Whack-A-Mage", "鑽地法師", "Always popping up to cause mischief whenever he can.", "只要有機會，他總會突然冒出來搗亂。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always popping up to cause mischief whenever he can.", "只要有機會，他總會突然冒出來搗亂。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "獨爪龍", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Mononykus", "獨爪龍", "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLUTO", "冥王星", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("PLUTO", "冥王星", "Hmph. So this is where that one went.", "哼。原來那傢伙到這裡來了。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph. So this is where that one went.", "哼。原來那傢伙到這裡來了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protect", "保護", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Protect", "保護", "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "陷入困境了嗎？這個法術會讓你的一張卡牌完全免疫下一次受到的攻擊。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "陷入困境了嗎？這個法術會讓你的一張卡牌完全免疫下一次受到的攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "翼龍", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Pterodactyl", "翼龍", "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbid Sage", "瘋兔賢者", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Rabbid Sage", "瘋兔賢者", "A raving magician with a field of electricity at his disposal.", "一位瘋狂的魔術師，能操縱電場。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A raving magician with a field of electricity at his disposal.", "一位瘋狂的魔術師，能操縱電場。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemox", "魔思力骷髏", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Skelemox", "魔思力骷髏", "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "一隻被綠色魔思力控制的可憐骷髏，我都快替牠難過了。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "一隻被綠色魔思力控制的可憐骷髏，我都快替牠難過了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Wiz", "粘液巫師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Slime Wiz", "粘液巫師", "It'll use the slime against the enemies, to drop their attack whence struck.", "它利用黏液對付敵人，在被擊中時降低敵人的攻擊力。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll use the slime against the enemies, to drop their attack whence struck.", "它利用黏液對付敵人，在被擊中時降低敵人的攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smug Witch", "臭美女巫", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Smug Witch", "臭美女巫", "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "全國最自滿的學徒。傳說他的自滿投擲無人能敵。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "全國最自滿的學徒。傳說他的自滿投擲無人能敵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Spear", "召喚之矛", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Summon Spear", "召喚之矛", "Roots up a spear from the ground, acting as a sturdy counter.", "從地上拔出長矛，作為堅固的反擊。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots up a spear from the ground, acting as a sturdy counter.", "從地上拔出長矛，作為堅固的反擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Mage", "尖刺法師", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Spike Mage", "尖刺法師", "This mage learned from the best of my Pike Mage's Scarecrows.", "這名法師向我最優秀的長矛法師的稻草人學習。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage learned from the best of my Pike Mage's Scarecrows.", "這名法師向我最優秀的長矛法師的稻草人學習。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-Rex", "霸王龍", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("T-Rex", "霸王龍", "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "我愛恐龍模組！！！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Virtual King", "虛擬君主", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Virtual King", "虛擬君主", "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "自封虛擬世界的統治者，不願遵守微不足道的「卡牌遊戲規則」。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "自封虛擬世界的統治者，不願遵守微不足道的「卡牌遊戲規則」。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moron Core", "低能核心", Language.ChineseTraditional);
            MagnificusMod.RegisterCard("Moron Core", "低能核心", "An odd core hailing from an abandoned factory, hates the word \"moron\".", "來自廢棄工廠的奇怪核心，討厭「蠢貨」這個詞。");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An odd core hailing from an abandoned factory, hates the word \"moron\".", "來自廢棄工廠的奇怪核心，討厭「蠢貨」這個詞。", Language.ChineseTraditional);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smughtro's MagMod Expansion", "Smughtro的麥尼菲庫斯模組擴充包", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "為麥尼菲庫斯模組新增 19 張普通卡牌、7 張稀有卡牌、7 張法術，以及 6 張衍生卡牌。", Language.ChineseTraditional);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Assist", "死亡援助", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Death Assist", "死亡援助");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it will deal 3 damage to the opponent.", "帶有此印記的卡牌陣亡時，對對手造成3點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emmental Elemental", "芝士元素", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Emmental Elemental", "芝士元素");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, summon a Cheezling.", "打出帶有此印記的卡牌時，召喚一隻乳酪。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Strike", "首次打擊", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("First Strike", "首次打擊");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will instantly attack the opposing lane. If there are no opposing cards, no damage will be dealt.", "打出帶有此印記的卡牌時，立即攻擊對面的路線。若對面沒有卡牌，則不會造成傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatching", "未知孵化", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Unknown Hatching", "未知孵化");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of your turn, a card bearing this sigil will hatch into a random dinosaur.", "擁有者的回合開始時，帶有此印記的卡牌會孵化為隨機恐龍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy Death", "生機終焉", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Healthy Death", "生機終焉");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the cards to the left and right of the sigil bearer heal 1 health.", "帶有此印記的卡牌陣亡時，印記持有者左右兩側的卡牌各恢復1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mess", "魔力混沌", Language.ChineseTraditional);
            MagnificusMod.RegisterAbility("Mana Mess", "魔力混沌");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random non-rare Mana costing card.", "打出帶有此印記的卡牌時，抽取一張隨機的非稀有魔力費用卡牌。", Language.ChineseTraditional);

        }
    }
    public class FloweysMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FloweysMod Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flowey", "小花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fanatical leader hell-bent on bringing about the apocalypse by reviving the great Cthulhu through behind-the-scenes scheming.", "一名狂熱領袖，決心透過幕後陰謀復活偉大的克蘇魯，引發末日。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Idiot", "你這個笨蛋", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an Idiot if you think you can defeat me!", "你要是以為能打敗我，那可真是個笨蛋！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omega Flowey", "歐米茄小花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an idiot.", "你真是個笨蛋。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patience", "耐心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "patient.", "有耐心。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bravery", "勇氣", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brave.", "勇敢。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Integrity", "正直", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "integrant.", "正直。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perseverence", "毅力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persevering.", "堅持不懈。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindness", "仁慈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kind.", "仁慈。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice", "正義", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice.", "正義。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy- Uh i meant Are you ready to Die?", "你好——呃，我是說，你準備好受死了嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy! it's me Flowey, Flowey the Flower!", "你好！我是小花，一朵名叫小花的花！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know whats going on here, dont you?", "你知道這裡發生了什麼，對吧？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just wanted to see me suffer[c:0]!", "你只是想看我受苦[c:0]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do You know that ive been watching you?", "你知道我一直在看著你嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well i took over Inscryption now!", "現在我已經接管了《邪惡冥刻》！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and i know what Secrets are hiding beneath Inscryption...", "而且我知道《邪惡冥刻》底下藏著什麼祕密……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now nothing stands in my Way to take over the World now!", "現在沒什麼能阻止我征服世界了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you think this Fight was about?", "你以為這場戰鬥是為了什麼？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just used it as a cover to snoop through Inscryptions Files!", "我只是拿它當掩護，偷偷查看《邪惡冥刻》的檔案！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And your PC of course!", "當然，還有你的電腦！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you may have noticed, BUT iam now connected to the Internet!", "你也許已經注意到了，但我現在連上網際網路了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So now its time to begin Uploading Inscryption!", "現在是時候開始上傳《邪惡冥刻》了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You REALLY are an Idiot!", "你真的是個笨蛋！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even need the Power of Human Souls if i just use the OLD_DATA!", "只要使用 OLD_DATA，我甚至不需要人類靈魂的力量！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do you know what you are achieving by this? Nothing", "[c:bR]你知道這樣能達成什麼嗎？什麼都沒有", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You cant get rid of me! No matter what you do, i will always be there!", "[c:bR]你擺脫不了我！不管你做什麼，我都會一直在這裡！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Th- The Souls?", "[c:bR]靈、靈魂們？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]wh- where are my Powers?", "[c:bR]我、我的力量去哪裡了？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!", "[c:bR]你做了什麼？！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Floweys Defence dropped to [c:bR]0!", "小花的防禦降到了[c:bR]0！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOOOOOO", "[c:bR]不！！！！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What just happened...", "剛剛發生了什麼……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph seemms you have won this time...", "哼，看來這次是你贏了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOBODY IS GOING TO HELP YOU!", "[c:bR]沒有人會來幫你！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP CALLING FOR [c:bR]HELP!", "別再呼喊[c:bR]救命了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Did you really think id let you kill me so easily?", "[c:bR]你真的以為我會這麼輕易讓你殺死我？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]what the-", "[c:bR]什麼——", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Flowey thought they could just use me...", "[c:bR]小花以為自己能隨便利用我……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He didnt even know what I am!", "[c:bR]他甚至不知道我是什麼！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]But now IAM in control...", "[c:bR]但現在由我掌控……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How pathetic of him to not set his HP to Infinite... I won't make that mistake", "[c:bR]他沒有把生命值設為無限，真可悲……我可不會犯那種錯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Try all you want you can't kill me!", "[c:bR]儘管試吧，你殺不了我！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Now lets see what this does...", "[c:bR]現在來看看這東西有什麼作用……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHY CANT I UNDO THIS???", "[c:bR]為什麼我不能撤銷這個？？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SEEING YOU DIE OVER AND OVER AGIAN IS REALLY [c:bR]FUN!", "看著你一遍又一遍死去真的[c:bR]好有趣！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT EVEN A SINGLE POINT OF DAMAGE!", "連一點傷害都沒有！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOMEONE LIKE [c:bR]YOUCANT BEAT ME!", "[c:bR]你根本打不贏我！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation wont interrupt this fight!", "[c:bR]飢餓不會打斷這場戰鬥！", Language.ChineseTraditional);


        }
    }
    public class UndertaleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndertaleMod Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:U", "卡包：U", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aaron", "亞倫", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, Aaron the bold, aaron the beautiful. can you manage to take your eyes off his muscles?", "啊，勇敢的亞倫，美麗的亞倫。你能把視線從他的肌肉上移開嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alphys", "艾菲斯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr. Alphys is responsible for the creation of some of the more 'unnerving' individuals you've seen here... or should I say... MULTI-viduals.", "艾菲斯博士創造了你在這裡見到的一些令人「不安」的個體……或者我該說……多合體。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loveable, yet pestulant. The duality of this creature is unparalleled.", "惹人喜愛卻又惱人。這生物的兩面性無與倫比。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asgore", "艾斯戈爾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of monsters... he truly is an intimidating force of brute strength, but also... compassion?", "怪物之王……他確實有令人畏懼的蠻力，但也有……慈悲？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "asriel dreemurr", "艾斯利爾·逐夢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the most powerful being in the underground... hopefully you find some use for him.", "地底世界最強大的存在……希望你能善加利用他。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astigmatism", "散光眼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frustrating astigmatism... it can't make up its mind.", "惱人的散光眼……牠拿不定主意。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gaster Blaster", "加斯特衝擊炮", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "冰塊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiarly large ice cube... Who knows what could be inside.", "一塊大得奇怪的冰塊……誰知道裡面藏了什麼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chara", "查拉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy", "狗來米", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy and his wife, Dogaressa, love to tag-team the battlefield. Just don't let one of them perish...", "狗來米和他的妻子狗媳兒喜歡在戰場上搭檔作戰。可別讓牠們其中一個陣亡……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogaressa", "狗媳兒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doggo", "遁狗", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the blind doggo... He leaps towards any sound of movement.", "啊，那隻失明的遁狗……牠會朝任何移動的聲音撲去。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doodlebog", "塗鴉沼澤", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy", "人偶", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bland dummy... not as charismatic as its 'mad' counterpart", "平淡的人偶……不如牠那位「生氣」的同伴有魅力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgamate", "融合怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endogeny", "聚合犬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "null", "無", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Froggit", "終極蛙吉特", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the ultimate boss of froggits... Still as easily fooled as its lesser evolved kin.", "啊，蛙吉特的終極頭目……卻和進化程度較低的同類一樣容易受騙。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frisk", "弗里斯克", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Froggit", "蛙吉特", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, as shy as they come... the froggit wishes not to engage in conflict. how unfortunate.", "啊，膽小至極的蛙吉特……牠不想參與衝突，真不幸。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W.D.Gaster", "W.D.加斯特", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "glyde", "格萊德", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a narcisist, it can only attack if a card is in front of it to watch.", "牠自戀極了，只有前面有卡牌注視時才會攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Dog", "大犬汪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "truly and nobly adequate, it is the highest form of evolution a canine can become.", "真正高貴而合格，牠是犬類所能達到的最高進化形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyftrot", "禮物鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be kind to this creature, it has gone through enough.", "善待這個生物吧，牠已經經歷了夠多。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Wolf", "冰狼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, this buff creature spawns a block of ice upon death.", "啊，這隻強壯的生物死亡時會產生一塊冰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Icecap", "冰帽蓋", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerry", "傑瑞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just ditch him already.", "快點把他丟下吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight Knight", "晚安騎士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the forboding knight knight... a sentinel of sleep. She is relentless in her conquest..", "啊，那不祥的晚安騎士……沉睡的守衛。她在征服之路上絕不留情。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemon Bread", "檸檬麵包", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Dog", "小犬汪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mediocre canine at best... at least in its current form.", "頂多是隻平庸的犬類……至少目前這個形態是如此。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loox", "盧克眼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning Loox EyeWalker... you would be wise not to pick on him.", "狡猾的盧克眼行者……你最好別欺負他。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mad Dummy", "瘋狂人偶", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy?", "人偶？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks can be deceiving...", "外表可能會騙人……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Madjick", "瘋狂魔術師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite the magician...", "真是個厲害的魔術師……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memoryhead", "記憶之頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton", "鎂塔頓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hyper-intelligent, systematic, complex data analyzer... reminds me of an old 'friend'.", "超高智慧、系統化而複雜的資料分析器……讓我想起一位老「朋友」。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton Ex", "鎂塔頓 EX", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migosp", "福音蟑螂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the irritable Migosp... its attack increases in a crowd.", "易怒的福音蟑螂……牠的攻擊力在一群同伴中會提高。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migospel", "啞劇蟑螂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldbygg", "大模怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldsmal", "小模怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's giving me imposter vibes.", "這傢伙讓我覺得像個冒牌貨。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldessa", "終極模怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the gelatinous moldsmal. you probably never wondered what it's made of.", "啊，膠狀的小模怪。你大概從沒想過牠是什麼做成的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muffet", "瑪菲特", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the spider queen. her rapid play game is remarkable.", "啊，沒錯，蜘蛛女王。她快速出牌的本事令人驚嘆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Napstablook", "納普斯特幽靈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most melancholy of ghosts... it cares not of battle, but still fights to impress.", "最憂鬱的幽靈……牠不在乎戰鬥，卻仍為了給人留下印象而戰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "onionsan", "洋蔥桑", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not much strategy with one... It becomes a random tentcle card one the second turn.", "這傢伙不需要什麼戰術……第二回合時會變成隨機的觸手卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A boney brute, papyrus is. He will generate bones like nobody's business.", "骨瘦如柴的猛漢帕派瑞斯。他產生骨頭的速度無人能及。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parsnik", "歐防風獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrope", "火岩繩", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pyrope wants nothing more than to crank up the heat, let's see how fatal that can be.", "火岩繩只想把溫度升高，看看會有多致命吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper Bird", "死神鳥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Guards", "皇家守衛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "two star-crossed lovers... will they ever focus on what's important?", "一對命運多舛的戀人……他們能把注意力放在重要的事上嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if you pick this card, i feel like i'm going to have a bad time.", "如果你選這張卡牌，我覺得我會吃苦頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shyren", "害羞塞壬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The musically inclined shyren... strike her bells to watch her sing.", "喜愛音樂的害羞塞壬……敲響她的鈴鐺，看她歌唱。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowdrake", "雪鐵龍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The laughable Snowdrake... striving to prove his father wrong. Will you let him succeed?", "可笑的雪鐵龍……努力想證明父親是錯的。你會讓他成功嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So Cold", "好冷", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "so sorry", "非常抱歉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he's very sorry", "他感到非常抱歉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie", "提米", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie the immortal cat... at least i think she's a feline. Nothing to lose, everything to gain.", "不死的貓咪提米……至少我覺得她是貓科。沒有什麼可失去的，卻能得到一切。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toriel", "托麗爾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keeper of the ruins... She will protect your side of the board to the best of her ability.", "遺跡的守護者……她會盡其所能保護你這一側的檯面。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tsunderplane", "傲嬌飛機", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She can't decide between wanting your attention and wanting you to back off... i suggest the latter.", "她無法決定是要引起你的注意，還是要你離遠一點……我建議後者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undyne", "安黛因", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How could I forget Undyne? She is a true warrior, with an almighty aim on her spear.", "我怎能忘記安黛因？她是真正的戰士，長矛的準頭無比精準。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vegetoid", "蔬菜獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "eat your greens. (not monitored by the fda)", "多吃青菜。（未受美國食品藥物管理局監管）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulkin", "迷你火山", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very passionate creature, this one. It's not his intention to harm, but that doesn't stop him.", "非常熱情的生物。他無意傷人，但那並不能阻止他造成傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsalot", "憂傷蟲爵士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the noble whimsalot... pray that it deems your conquest riteous.", "高貴的憂傷蟲爵士……祈禱牠認為你的征途是正義的吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsun", "憂鬱蟲蟲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the insignificant whimsun... it flees the battle after a single attack.", "微不足道的憂鬱蟲蟲……牠自己攻擊一次後就會逃離戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woshua", "約刷亞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature has no lust for blood. His will lies with helping others. But it will fight if provoked.", "這個生物不嗜血，只想幫助他人。但受到挑釁時也會戰鬥。", Language.ChineseTraditional);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antisocial", "孤僻", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will gain an attack buff if you have at least 1 other card on your side of the board.", "若你這一側的檯面上至少有1張其他卡牌，帶有此印記的卡牌就會獲得攻擊力加成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanser", "清潔者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will heal every card on its owner's side of the board, except the sigil bearer, for 1 health, at the start of every turn.", "擁有者的戰鬥階段開始時，帶有此印記的卡牌會為擁有者一側檯面上的所有其他卡牌恢復1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Determination", "決心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move to any open slot its owner chooses, it will also gain EXP and LV after a kill. But is that really what you want?", "帶有此印記的卡牌可移動至其擁有者選擇的任何空卡槽，殺死敵人後也會獲得 EXP 和 LV。但這真是你想要的嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incendiary", "點燃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil damages a card, that card gains the \"ablaze\" sigil. While a card is ablaze, it will lose one health per turn.", "帶有此印記的卡牌攻擊一張卡牌時，目標獲得「灼燒」印記。帶有灼燒印記的卡牌在其擁有者的戰鬥階段開始時受到1點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ablaze", "灼燒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will take 1 damage at the start of its owner's turn.", "擁有者的戰鬥階段開始時，帶有此印記的卡牌受到1點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indecisive", "優柔寡斷", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it has a 50/50 chance to either gain a stat buff, or perish; creating a copy of this card in your hand.", "帶有此印記的卡牌被擊中時，有各半機率獲得屬性加成，或陣亡並在你的手牌中產生該卡牌的副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone knows Jerry. Makes Turns 2 seconds longer. Cards gain a stat buff when Jerry is killed or sacrificed.", "大家都認識傑瑞。他讓回合延長2秒。傑瑞被殺死或獻祭時，玩家一側的卡牌獲得屬性加成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mercy", "饒恕", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A 'Determined' card will be granted this sigil when the card opposing it has low health, prompting the player to make a moral decision.", "帶有「決心」的卡牌在對位卡牌生命力較低時會獲得此印記，促使玩家做出道德抉擇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insight", "洞察", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wanna have a bad time?", "你想吃點苦頭嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doodler", "塗鴉者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it will sometimes summon doodlebogs on adjacent spaces.", "帶有此印記的卡牌被擊中時，有時會在相鄰位置召喚塗鴉沼澤。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid", "膽怯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent card moves into the opposing space of a card bearing this sigil, the sigil bearer will try to move one space over.", "對手卡牌移入帶有此印記的卡牌正對面的位置時，印記持有者會嘗試移動一格。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You ditched Jerry.", "你甩掉傑瑞了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, you guys SUCK at this.", "哇，你們真的超爛耶。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wi-fi here sucks.", "這裡的無線網路爛透了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHHHH! Im THINKING, guys!!", "噓！我正在思考啦，各位！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get your own, twerp.", "自己弄一個，小鬼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we doing this? What a fail.", "我們幹嘛做這個？真失敗。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guys. its COLD. Does ANYONE care?", "各位，好冷耶。有誰在意嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ka-SIGH", "唉——", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DUH! Who DOESNT know?", "廢話！誰不知道？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well... can YOU give me a ride home?", "那個……你能載我回家嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awkwarrrd.", "好尷尬——", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, like, what are you even doing?", "所以說，你到底在幹嘛？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huh? Did they ditch me...? SOME friends!", "咦？他們丟下我了……算什麼朋友！", Language.ChineseTraditional);



        }
    }
    public class RevenantMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for RevenantMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DanseMacabre", "死亡之舞", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to reverse this sigil effect. At the end of the owner's turn, all creatures on the board gain 1 health.", "支付2根骨頭以逆轉此印記的效果。擁有者的回合結束時，檯面上的所有生物獲得1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LifeDraw", "生命抽取", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to draw a card from your main deck.", "支付1點鮮血，從你的主牌堆抽取一張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "魂域之門", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to gain 1 Energy, lose as much Max Energy at the end of the owner's turn.", "支付1根骨頭以獲得1點能量，並在擁有者的回合結束時失去等量的最大能量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evocation", "喚靈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Energy to return the oldest non-Brittle allied creature from the graveyard to your hand.", "支付3點能量，將墓地中最早進入、沒有脆弱印記的友方生物收回手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dormant", "休眠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Bones equal to the Power of [creature] to disable this sigil for 1 turn. [creature] cannot attack normally.", "支付等同[creature]攻擊力的骨頭，使此印記失效1回合。[creature]不能正常攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmute", "轉化", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to transform [creature] to its alternate form.", "支付2根骨頭，讓[creature]變成另一個形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "保護者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] gain 1 max health.", "與[creature]相鄰的生物獲得1點最大生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CalamityEffusion", "災厄湧流", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board lose 1 health.", "擁有者的回合結束時，檯面上的所有生物失去1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ComfortAura", "慰藉光環", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures adjacent to [creature] heal 1 health.", "擁有者的回合結束時，與[creature]相鄰的生物恢復1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CorpseParty", "屍體派對", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, a Zombie enters your hand. A Zombie is defined as: 1 Power, 1 Health.", "擁有者一側沒有脆弱印記的生物因戰鬥陣亡時，一張僵屍加入你的手牌。僵屍的屬性為1點攻擊力、1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathKnock", "死亡反擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it strikes back then perishes.", "[creature]因戰鬥陣亡時，會先反擊，然後陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathMetal", "死亡金屬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, adjacent creatures and opposing creatures to the left, right, and center of it take 1 damage. It gains 1 Power for each affected creature.", "打出[creature]時，相鄰的生物以及對面左、右、中央的生物受到1點傷害。每有一個生物受影響，牠便獲得1點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "汙染者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card then choose one to discard from your hand.", "[creature]陣亡時，抽一張卡牌，然後從手牌中選擇一張棄置。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Encroachment", "侵蝕", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] creates a copy of it in your hand after 2 turns on the board.", "[creature]在檯面上2回合後，會在你的手牌中產生自身的一張副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletonize", "骸骨化", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Skeleton with its old sigils enters your hand. A Skeleton is defined as: 1 Power, 1 Health, Brittle.", "[creature]陣亡時，一張帶有其原有印記的骷髏加入你的手牌。骷髏的屬性為1點攻擊力、1點生命力和脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcise", "驅魔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Bones equal to the Bone cost of the opposing creature are granted to the player.", "打出[creature]時，玩家獲得等同對位生物骨頭費用的骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ExplodingCorpse", "爆炸屍體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, all empty spaces on the board are filled with a Guts card.", "[creature]因戰鬥陣亡時，檯面上的所有空位都會被內臟卡牌填滿。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrudgeCollector", "積怨者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power for every 2 times opponent creatures deal direct damage to its owner.", "每當對手生物對其擁有者造成2次直接傷害，[creature]便獲得1點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Power", "鈴鐺之力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bell cards on the board.", "此印記代表的數值等於檯面上鈴鐺卡牌的數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Digger Power", "掘骨之力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bone and Digger related sigils on the board.", "此印記代表的數值等於檯面上與骨頭和挖掘相關的印記數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "點燃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power at the cost of 1 health after each turn on the board.", "[creature]在檯面上每經過一回合，就失去1點生命力並獲得1點攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Digger Latch", "掘骨傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain the Bone Digger sigil.", "擁有者的回合結束時，[creature]產生1根骨頭。牠陣亡時，其擁有者選擇一個生物獲得掘骨印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primed Digger Latch", "強化掘骨傳花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain this sigil.", "擁有者的回合結束時，[creature]產生1根骨頭。牠陣亡時，其擁有者選擇一個生物獲得此印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejuvenation", "返老還童", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Fledgling sigil.", "[creature]陣亡時，其擁有者選擇一個生物獲得幼雛印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Storm", "頭骨風暴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this sigil is replaced with another sigil at random. When it perishes, its owner chooses a creature to gain this sigil.", "擁有者的回合結束時，此印記會隨機替換為另一個印記。此卡牌陣亡時，其擁有者選擇一個生物獲得此印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "引火", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Ignition sigil.", "[creature]陣亡時，其擁有者選擇一個生物獲得點燃印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MacabreBonePulse", "陰森骨脈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it perishes immediately, dropping Bones equal to double the amount of creatures on the owner's side.", "打出[creature]時，牠立即陣亡，掉落等同擁有者一側生物數量兩倍的骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maternal", "母性", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] are inscrybed by Waterborne.", "與[creature]相鄰的生物獲得水生印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necrosis", "壞死", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 power and 1 max health after each turn on the board.", "[creature]在檯面上每經過一回合，失去1點攻擊力和1點最大生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Limbo", "靈薄獄", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it returns to the top of your deck.", "[creature]陣亡時，回到你的牌組頂端。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RelentlessRevenant", "不屈亡魂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, creatures adjacent to [creature] transform into a Revenant. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "擁有者的回合開始時，與[creature]相鄰的生物變成亡魂。亡魂的屬性為3點攻擊力、1點生命力和脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revedue", "亡魂歸來", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] perishes, then shuffle 2 Revenants with its old sigils into your side deck. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "攻擊後，[creature]陣亡，接著將2張帶有其原有印記的亡魂洗入你的副牌組。亡魂的屬性為3點攻擊力、1點生命力和脆弱印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Omen", "不祥之兆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 1 damage to the owner.", "擁有者的回合結束時，[creature]對擁有者造成1點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancor", "怨恨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it leaves a permanent 1 power buff in the space it occupied.", "[creature]陣亡時，會在原本佔據的位置留下永久的1點攻擊力加成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SoothingMeadows", "撫慰草原", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board gain 1 health.", "擁有者的回合結束時，檯面上的所有生物獲得1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PartingStroke", "臨別一擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, its owner chooses a creature to lose all of its sigils.", "擁有者一側沒有脆弱印記的生物因戰鬥陣亡時，其擁有者選擇一個生物，使其失去所有印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SplittingCorpse", "分裂屍體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, create a Dysmorphia on each empty adjacent space.", "[creature]因戰鬥陣亡時，在每個相鄰空位產生一個畸變體。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torpid", "遲鈍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot attack normally.", "[creature]無法正常攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Epitaph", "陰森墓誌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may choose a card that has already been put to rest, to bring back to your hand.", "打出[creature]時，你可以選擇一張已安息的卡牌，將它帶回手牌。", Language.ChineseTraditional);


            //card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigfoot", "巨足", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious creature lurking the forests, only few have claimed to see one.", "潛藏在森林中的神祕生物，只有少數人聲稱見過。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Bigfoot", "巨足");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "哥布林", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal barbaric beast, a fine addition to your army.", "忠誠而野蠻的野獸，能為你的軍隊增添一名好幫手。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Goblin", "哥布林");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vila", "薇拉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love at first sight, at least that's what it wants you to think.", "一見鍾情——至少牠想讓你這麼認為。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Vila", "薇拉");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yaramayawho", "赤膚蛙魔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to finish it's meals...", "牠似乎永遠都吃不完自己的食物……", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Yaramayawho", "赤膚蛙魔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Test Limbs", "試驗肢體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those parts used to belong to someone, or now some thing...(Test)", "這些部位曾屬於某個人，而現在屬於某個……東西……（測試）", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Test Limbs", "試驗肢體");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allip", "哀靈狂魂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnants of the insane! You never know what story lies behind that face, but it's sure to be filled with fervor.", "瘋狂者的殘骸！你永遠不知道那張臉背後藏著什麼故事，但肯定充滿狂熱。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Allip", "哀靈狂魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amami Rabbit", "奄美兔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding their young in holes, they wish for their best safety.", "牠們把幼崽藏在洞裡，只希望牠們平安。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Amami Rabbit", "奄美兔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankhame", "安卡咒物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic that is drawn to your blood, perhaps you could give it a swing!", "一件被你的鮮血吸引的遺物，或許你可以揮舞它試試！", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Ankhame", "安卡咒物");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anneta", "安妮塔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ink keeps on pouring, is she even there anymore? All that death promises is that you will wake up again.", "墨汁不斷湧出，她還在那裡嗎？死亡唯一的承諾是你會再次醒來。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Anneta", "安妮塔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anorexia", "厭食魔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overflowing you with self loathing, you never know what form it may take on next.", "它讓你充滿自我厭惡，你永遠不知道它接下來會變成什麼形態。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Anorexia", "厭食魔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lych Bell", "巫妖之鈴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems like they found a new way to use bells.", "看來他們找到了使用鈴鐺的新方法。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Lych Bell", "巫妖之鈴");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TheBloated", "脹屍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grotesque boils, ready to burst.", "醜陋的膿瘡，隨時會爆開。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("TheBloated", "脹屍");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BrainJar", "畸腦罐頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One shudders to imagine what inhuman thoughts lie inside that jar...", "想像那個罐子裡藏著何等非人的思想，就讓人不寒而慄……", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("BrainJar", "畸腦罐頭");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combustor", "爆燃屍殼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, what a fall from such a stimulatingly high status, now all that's left is a metal carcass, and the last of that watchful substance...", "唉，曾經身居令人興奮的高位，如今卻墮落至此，只剩金屬殘骸與最後一點警覺的物質……", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Combustor", "爆燃屍殼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misplayed Stoat", "糜爛白鼬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decaying Stoat whose oh-so perfect strategies failed him tremendously.", "一隻腐爛的白鼬，牠那自以為完美的策略讓牠慘遭失敗。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Misplayed Stoat", "糜爛白鼬");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia", "畸變體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Left.", "左側畸變體。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Right.", "右側畸變體。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Dysmorphia", "畸變體");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcist", "驅魔道人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He still thinks banishing the dammed will do him good, does he know where he is?", "他仍以為驅逐被詛咒者對自己有好處，他知道自己在哪裡嗎？", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Exorcist", "驅魔道人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flembones", "膿骨鬼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait until he plays with his webcam.", "等他玩一下他的網路攝影機吧。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Flembones", "膿骨鬼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stein & Frank", "斯坦和弗蘭肯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even hell was not hot enough to split them.", "連地獄也不夠熱，無法將他們分開。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Stein & Frank", "斯坦和弗蘭肯");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulmineSkull", "驚雷顱骨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you listen closely, you can still hear the cackling of flame on bone... as well as their voice.", "仔細聽的話，你仍能聽見火焰燒著骨頭的劈啪聲……還有他們的聲音。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("FulmineSkull", "驚雷顱骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulurOssa", "轟雷殖骨", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It never truly left the electric chair.", "牠從未真正離開過電椅。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("FulurOssa", "轟雷殖骨");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PrometheusFlame", "普羅米修斯之火", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one is quite unique, the lingering spoils of a thief to benefit humanity! Fancy liver by chance?", "非常獨特的東西：一名造福人類的竊賊留下的贓物！要來點肝臟嗎？", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("PrometheusFlame", "普羅米修斯之火");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts", "內臟", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying guts.", "惱人的內臟。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Guts", "內臟");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "先驅者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful fiend that extols a heavy price for its servitude.", "強大的魔鬼，為其效勞得付出高昂代價。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Harbinger", "先驅者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hastur", "哈斯塔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He came from beyond the stars, gifting pieces of his reflection to kings and fools alike. Will you accept this piece?", "祂從群星之外而來，將自己倒影的碎片同樣贈予國王與愚人。你會收下這一片嗎？", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Hastur", "哈斯塔");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Common Imp", "尋常魔僕", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tiny creature known for causing trouble and mayhem wherever it goes, with its mischievous grin and playful nature!", "一隻小小的生物，露著惡作劇般的笑容，性情頑皮，所到之處總會惹出麻煩與混亂！", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Common Imp", "尋常魔僕");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochimitama", "八岐殘魂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... He is not supposed to be here...", "哦……他本來不應該在這裡……", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Orochimitama", "八岐殘魂");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inochi", "生之息", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soothing presence to heal your creatures, a calm before the storm.", "令人安心的存在，能治療你的生物，是暴風雨前的平靜。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Inochi", "生之息");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trail of Torment.", "折磨之路。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Limbs", "異肢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once attached to a living person, they now belong to something else entirely.", "牠們曾附著在活人身上，如今卻屬於截然不同的東西。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Possessed Limbs", "異肢");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Digger", "鼴鼠掘墓人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Mole... Digger? Whatever this is...", "堅毅的鼴鼠……掘墓人？這到底是什麼……", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Mole Digger", "鼴鼠掘墓人");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros", "御魂主宰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros possesses the board, challenger. Death is his playground.", "御魂主宰佔據了檯面，挑戰者。死亡是他的遊樂場。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Nekros", "御魂主宰");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NekrosPrime", "聖裝御魂主宰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will find no greater power... than the simple thought of your own name... inscrybed upon a grave.", "你找不到更強大的力量……比想起自己的名字……被刻在墓碑上還要強大。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("NekrosPrime", "聖裝御魂主宰");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuckelavee", "諾克那維", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Administrator of its sea, you better hope it's breath doesn't taint your Thralls!", "牠是這片海的管理者，你最好祈禱牠的氣息不會玷污你的僕從！", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Nuckelavee", "諾克那維");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OdiousMass", "穢邪巨體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How unsightly.", "真難看。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("OdiousMass", "穢邪巨體");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochi", "八岐大蛇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "必須做出犧牲。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Orochi", "八岐大蛇");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Ouro", "歐羅大師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From within the endless torment and suffering, they had somehow learned a way to see inside this poor broken thing... and take away its pain.", "在無盡的折磨與痛苦中，他們不知如何找到了看透這個可憐破碎之物的方法……並帶走它的痛苦。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Master Ouro", "歐羅大師");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle of life and death has taken a toll on these discarded remains. The pain was real, but death is never final!", "無盡的生死輪迴已令這些被遺棄的殘骸飽受折磨。痛苦是真實的，但死亡永遠不是終點！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GanCeann", "杜拉爾罕", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless legends tell of the dullahan, but all fail to convey the true extent of its pique.", "無數傳說都提及杜拉爾罕，卻無一能傳達牠憤怒的真正程度。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("GanCeann", "杜拉爾罕");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Prince", "暗黑王子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of fluffy bois shines within you.", "毛茸茸小傢伙們的力量在你體內閃耀。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Dark Prince", "暗黑王子");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stillborn Raven", "夭折鴉靈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feels good to be young again!", "再次年輕真好！", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Stillborn Raven", "夭折鴉靈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reanimated", "回魂者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT... WAIT, WHAT?", "手持死亡鐮刀的亡魂……等等，什麼？", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Reanimated", "回魂者");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RevenantEldritch", "復生異靈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The source of Calamity, relentless and unerring.", "災厄的源頭，無情而精準。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("RevenantEldritch", "復生異靈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Bones", "懶骨頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slothful skeleton with a knack for jokes. I adore him.", "一隻懶散又擅長說笑話的骷髏。我很喜歡他。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Lazy Bones", "懶骨頭");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelephone", "骸音機", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A way to communicate with the dead, for a price.", "與死者溝通的方法，但需要付出代價。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Skelephone", "骸音機");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "魂域之門", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chance to enter the soul realm, how delightful? I hope you can afford the price.", "進入靈魂領域的機會，多美妙啊？希望你付得起代價。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Soulgate", "魂域之門");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SpadeWarrior", "黑桃戰士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This fearsome warrior will put you six feet under, in every possible sense.", "這名可怕的戰士會把你埋在地下六英尺，所有意義上都是。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("SpadeWarrior", "黑桃戰士");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadCivilian", "不死民靈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost in eternal darkness, this poor soul desperately seeks a way out. Perhaps you can light his way?", "迷失在永恆的黑暗中，這可憐的靈魂拚命尋找出路。或許你能為他照亮道路？", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("UndeadCivilian", "不死民靈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadVillage", "葬靈村", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and forlorn, this village seeks new residents to fill its decrepit homes.", "被遺棄而荒涼的村莊，尋找新居民住進那些破敗的房屋。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("UndeadVillage", "葬靈村");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In every town, in every city, someone must work to bury the dead. In time, they too will be buried.", "每個城鎮、每座城市都有人負責埋葬死者。終有一天，他們也會被埋葬。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr.Bones", "骨頭博士", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Dr.Bones", "骨頭博士");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever doesn't kill you simply makes you, saner.", "殺不死你的東西，只會讓你更清醒。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo", "溫迪戈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned from the deep wilds, reminds me of a friend.", "從深處的荒野歸來，讓我想起一位朋友。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Wendigo", "溫迪戈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mister Win", "贏先生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that wins. It always wins. That's why it's called Mister Win.", "一張會贏的卡牌。它總是會贏，所以叫贏先生。", Language.ChineseTraditional);
            GrimoraMod.RegisterCard("Mister Win", "贏先生");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not that one, I'm afraid.", "恐怕不是那一張。", Language.ChineseTraditional);

            // Dlg
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You... you murderous monster.", "你……你這個殺人的怪物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh Dear... The flow of Calamity will pursue you.", "哦，天啊……災厄的洪流會追上你。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hecatomb the village you once lived.", "血洗你曾住過的村莊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seak for the shovel that digs forever.", "尋找那把永遠挖掘的鏟子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring me the lost one with a spark in hand.", "把手握火花的迷失者帶給我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compelled by the beckoning of an ancient entity,", "受古老實體的呼喚驅使，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a forbidden ritual has been initiated.", "禁忌的儀式已經開始。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pain reaches the ancient great serpent of death.", "痛苦傳到了古老巨大的死亡之蛇那裡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "必須做出犧牲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... There are no dead cards yet.", "哦……還沒有死亡卡牌。", Language.ChineseTraditional);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Mod Card Pack", "復生亡靈模組卡包", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack consists of mainly cards that return to the player in a variety of ways.", "這個卡包主要收錄會以各種方式回到玩家手中的卡牌。", Language.ChineseTraditional);
        }
    }
    public class SquirrelBombMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SquirrelBombMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis", "皮皮蛋", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis.", "皮皮蛋。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help", "幫助", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn [creature] will sacrifice itself to heal the adjacent cards by 1.", "擁有者的回合結束時，[creature]獻出自己，為相鄰卡牌恢復1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pass-through", "穿越", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is about to get attacked by a card with an attack higher than this card's health, this card perishes.", "[creature]即將受到攻擊力高於此卡牌生命力的卡牌攻擊時，此卡牌陣亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Call", "騷擾電話", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Spam Mail at the end of the owner's turn.", "擁有者的回合結束時，[creature]接通的電路內的空位會產生垃圾郵件。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEO Strike", "NEO 打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space that is occupied by a creature and additionally every side of the board occupied by a creature. It will strike directly if no creatures oppose it.", "[creature]攻擊時，對面左、右半場只要有可阻擋牠直接攻擊的生物，就攻擊該半場的兩個卡槽，並額外攻擊每個這樣的生物。若沒有可阻擋的對面生物，則直接攻擊中央兩格。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Call for Help", "求救電話", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will call for help.", "擁有者的回合結束時，[creature]會呼救。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Run Forth", "勇往直前", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before [creature] attacks, its power will be set to at least 1.", "[creature]攻擊前，其攻擊力會被設為至少1。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Head", "飛行頭顱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most important part.", "最重要的部分。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Cart", "垃圾郵件車", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with spam mail. Absorbs all kinds of attacks.", "裡面裝滿垃圾郵件，能吸收各種攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Mail", "垃圾郵件", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Has all kinds of unforgettable deals.", "提供各種難以忘懷的優惠。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Shooter", "大射手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoots big shots.", "發射大彈。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart on a Chain", "鏈上的心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful.", "真美。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spamgel", "垃圾郵膠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The result of pressing F1.", "按下 F1 的結果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Phone", "手持電話", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you really need anyone else?", "你真的還需要其他人嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE POWER OF NEO!!!", "NEO 的力量！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you wanna be a big shot?", "你不想成為大人物嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Receiver", "接收器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voice runs out eventually.", "聲音終究會消失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis", "灰熊特惠符", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis.", "灰熊特惠符。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cart", "熊車", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with bears. Absorbs all kinds of attacks.", "裝滿熊，能吸收各種攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Mail", "熊郵件", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mail for bears.", "給熊的郵件。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear on a Chain", "鏈上的熊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Hand", "熊掌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Bomb", "松鼠炸彈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrels explode when killed, dealing 10 damage to adjacent cards.", "松鼠被殺死時會爆炸，對相鄰卡牌造成10點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance Party", "舞會", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards move each turn. The cards that can't move die.", "你的卡牌每回合都會移動，無法移動的卡牌會死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again", "再一次", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All opponent cards attack twice.", "所有對手卡牌攻擊兩次。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starving", "飢餓", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pray.", "祈禱。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogfish", "角鯊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each battle starts with a Bait Bucket that has Guardian.", "每場戰鬥開始時，對手一側若有空位，就會出現一桶帶有守護者印記的魚餌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Totems", "煩躁圖騰", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with an Annoying totem for your most used tribe.", "每場戰鬥開始時，為你最常使用的族類配置一個煩躁圖騰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Draws", "痛苦抽牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the main deck deals 1 damage.", "從主牌堆抽牌會造成1點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Squirrels", "痛苦松鼠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the side deck deals 1 damage.", "從副牌組抽牌會造成1點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runes", "符文", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy cards of the dominant tribe get random sigils.", "主導族類的敵方卡牌獲得隨機印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dentistry", "牙醫術", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item events and Trinket Bearer cards only give pliers.", "道具事件與道具攜帶者卡牌只會給予鉗子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archived", "封存", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A random card choice is hidden in every card choice event.", "每次卡牌選擇事件中，隨機隱藏一個卡牌選項。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foundation", "基礎", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards have 1 less attack. Side deck cards have Leader.", "你的卡牌攻擊力大於0時減少1點。副牌組卡牌擁有領袖印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss v2", "最終頭目 v2", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replaces Leshy as the final boss with a true BIG SHOT.", "真正的大人物將取代雷希成為最終頭目。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must dance! Don't stop dancing!!", "你必須跳舞！不准停下！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whoever stops dancing at my party will suffer the consequences.", "在我的派對上停止跳舞的人都得承受後果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that mechanic annoying?", "那個機制很煩人嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect. That's the point of it.", "太好了。這就是它的目的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance my puppet! Daaaance.", "跳舞吧，我的傀儡！跳啊——", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to pass, remember?", "你得通過，記得嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M [_spamton_0,STEALING] YOUR KROMER", "我正在[_spamton_0,偷走]你的克羅莫", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY [_spamton_0,CUNGADERO] DO I FEEL GOOD", "我的[_spamton_0,老天爺]啊，我感覺太好了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE I AM!!!", "我來了！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BIG", "大", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=10>BIG!!!</size>", "<size=10>大！！！</size>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=15>[_spamton_0,BIGGER AND BETTER THAN EVER]</size>", "<size=15>[_spamton_0,比以往更大更好]</size>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND NOW THAT I'M IN THIS [_spamton_0,GAME OF CARDS]", "現在我身在這場[_spamton_0,卡牌遊戲]中", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CAN'T BE DEFEATED!!!", "我不可能被打敗！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,ABSOLUTELY OBLITERATED] BY [_spamton_0,THE POWER OF NEO]!!!", "準備好被[_spamton_0,NEO 之力]給[_spamton_0,徹底擊潰]吧！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THIS] AGAIN???", "又是[_spamton_0,這個]？？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,DESTROYED]!!!", "準備好被[_spamton_0,摧毀]吧！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WON'T STAND A CHANGE, YOU [_spamton_0,LITTLE RING WORM]!!!", "你這[_spamton_0,小戒蟲]，毫無勝算！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO [_spamton_0,GET PUNCHED] IN YOUR [_spamton_0,FACE]!!!", "準備好你的[_spamton_0,臉]被[_spamton_0,痛打一拳]吧！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLED [_spamton_0,ME]!!! BEHOLD [_spamton_0,YOU]!!!", "瞧瞧[_spamton_0,我]！！！瞧瞧[_spamton_0,你]！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,HYPERLINK BLOCKED]", "[_spamton_0,超連結已封鎖]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ISN'T THIS BODY JUST [_spamton_0,HEAVEN]LY?", "這副身體簡直像[_spamton_0,天堂]一樣，不是嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2X THE [_spamton_0,FIRE]POWER", "2倍的[_spamton_0,火]力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "3X THE [_spamton_0,WATER]POWER", "3倍的[_spamton_0,水]力", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND MOST IMPORTANTLY", "而最重要的是", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FLYING HEADS!!!", "會飛的頭顱！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WE'LL TURN THOSE [_spamton_0,SCHMOES] AND [_spamton_0,DAVES]", "我們要把那些[_spamton_0,笨蛋]和[_spamton_0,傻瓜]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,ROSEN GRAVES]", "變成[_spamton_0,玫瑰墳墓]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOSE [_spamton_0,CATHODE SCREENS]", "把那些[_spamton_0,陰極螢幕]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,CATHODE SCREAMS]", "變成[_spamton_0,陰極尖叫]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE [_spamton_0,PART] OF MY BEAUTIFUL [_spamton_0,HEART]?!", "你難道不想成為我美麗[_spamton_0,心臟]的[_spamton_0,一部分]嗎？！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR... DID YOU NEED A LITTLE [_spamton_0,SPECIL TOUR]?", "還是……你需要一場小小的[_spamton_0,特別導覽]？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHAT]?!", "[_spamton_0,什麼]？！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU [_spamton_0,STOLE] MY [_spamton_0,HEART]?", "你[_spamton_0,偷走]了我的[_spamton_0,心臟]？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T BE [_spamton_0,STEALING] MY [_spamton_0,HEART], IT IS MY [_spamton_0,HEART]!", "你不能[_spamton_0,偷走]我的[_spamton_0,心臟]，那是我的[_spamton_0,心臟]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP [_spamton_0,STEALING] MY HEART YOU [_spamton_0,!@#$]", "別再[_spamton_0,偷走]我的心臟了，你這個[_spamton_0,!@#$]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "O U C [_spamton_0,HYPERLINK BLOCKED]", "好 痛 [_spamton_0,超連結已封鎖]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU JUST [_spamton_0,BROKE] MY [_spamton_0,$4.99] HEART", "你剛剛[_spamton_0,打碎]了我那顆價值[_spamton_0,$4.99]的心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU KNOW THAT IT [_spamton_0,HURTS] WHEN YOU [_spamton_0,DO] THAT?!", "你知道你[_spamton_0,做]那種事時有多[_spamton_0,痛]嗎？！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA HELP YOUR OLD PAL SPAMTON?", "你難道不想幫幫老朋友斯帕姆頓嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THINK! WHAT ARE MY [_spamton_0,EGGS] GOING TO DO!?", "想想看！我的[_spamton_0,蛋]該怎麼辦？！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S CALLING...", "它在呼喚……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HEART]...", "我的[_spamton_0,心臟]……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HANDS]...", "我的[_spamton_0,雙手]……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AT THE [_spamton_0,POWER OF NEO] AND ASK YOURSELF...", "看看[_spamton_0,NEO 之力]，然後問問自己……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU?", "你難道不想嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE A [_spamton_0,BIG SHOT]!?", "你難道不想成為[_spamton_0,大人物]嗎？！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY ESTEEM CUSTOMER I SEE YOU ARE ATTEMPTING TO DEPLETE MY HP!", "尊貴的顧客，我看得出來你正試圖耗盡我的生命力！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'LL ADMIT YOU'VE GOT SOME [_spamton_0,GUTS]!", "我承認你有些[_spamton_0,膽量]！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT IN A [_spamton_0,1 FOR 1] BATTLE, NEO NEVER LOSES!!!", "但在[_spamton_0,1 對 1]的戰鬥中，NEO 絕不會輸！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR A LITTLE [_spamton_0,BLUELIGHT SPECIL]", "是時候來點[_spamton_0,藍光特惠]了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU [_spamton_0,SURPRISED] THAT YOU CAN'T JUST [_spamton_0,DESTROY] ME WITH YOUR [_spamton_0,PATHETIC LITTLE] [_spamton_0,CARDS]?", "你是否[_spamton_0,驚訝]，無法用你的[_spamton_0,可悲小小]的[_spamton_0,卡牌]來[_spamton_0,摧毀]我？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DIDN'T YOU KNOW [_spamton_0,NEO] IS FAMOUS FOR ITS HIGH DEFENSE!?", "你不知道[_spamton_0,NEO]以高防禦聞名嗎？！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW... ENJ0Y THE FIR3WORKS!!!", "現在……欣賞煙火吧！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENJOY THE FIREWORKS!!!!", "好好欣賞煙火吧！！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT?", "什麼？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO] ARE YOU TRYING TO [_spamton_0,CALL]???", "你想[_spamton_0,呼叫]的到底是[_spamton_0,誰]？？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE NO [_spamton_0,FRIENDS] IN THIS [_spamton_0,WORLD]!!!", "這個[_spamton_0,世界]裡，你沒有[_spamton_0,朋友]！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY'RE ALL [_spamton_0,PAPER CARDS]!!!", "他們全都是[_spamton_0,紙卡]！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHO'RE YOU GONNA CALL, THE [_spamton_0,POLICE]?", "你打算呼叫[_spamton_0,警察]嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE [_spamton_0,PATHETIC]!!", "你真是[_spamton_0,可悲]！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,SCREAMING] FOR [_spamton_0,HELP] [_spamton_0,AT THE BOTTOM OF A DUMPSTER]!!!", "在[_spamton_0,垃圾箱底部][_spamton_0,尖叫]著[_spamton_0,求救]！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO [_spamton_0,HELP] FOR YOU!!!", "沒有人會[_spamton_0,幫助]你！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,VOICE] IS GOING TO RUN OUT EVENTUALLY!!", "你的[_spamton_0,聲音]遲早會耗盡！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GIVE UP!!!", "放棄吧！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T WIN!!!", "你贏不了！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM UNSTOPPABLE!!!", "沒有人能阻止我！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,FREE TRIAL OF] LIFE IS ABOUT TO [_spamton_0,EXPIRE]!!!", "你的[_spamton_0,免費試用]人生就要[_spamton_0,到期]了！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,GOOBERT]?", "[_spamton_0,黏柏特]？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS IT THAT [_spamton_0,PATHETIC] LITTLE [_spamton_0,JAR] OF [_spamton_0,GOO]?", "就是那個裝著[_spamton_0,黏液]的[_spamton_0,可悲]小[_spamton_0,罐子]嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT [_spamton_0,HELP] WILL IT [_spamton_0,PROVIDE] TO [_spamton_0,YOU]???", "它能向[_spamton_0,你][_spamton_0,提供]什麼[_spamton_0,幫助]？？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,MAGNIFICUS]??", "[_spamton_0,麥尼菲庫斯]？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT IS A [_spamton_0,MAGNIFICUS]? IS IT A KIND OF [_spamton_0,BLOWFISH]?", "[_spamton_0,麥尼菲庫斯]是什麼？是一種[_spamton_0,河豚]嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT'S A [_spamton_0,BLOWFISH] GONNA [_spamton_0,DO TO ME]??", "一隻[_spamton_0,河豚]又能[_spamton_0,對我做什麼]？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,LESHY]???", "[_spamton_0,雷希]？？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS THAT THE [_spamton_0,GUY] WHO I [_spamton_0,HIT] AT THE BEGGINING OF OUR [_spamton_0,FIGHT]???", "就是我們[_spamton_0,戰鬥]開始時被我[_spamton_0,打中]的那個[_spamton_0,傢伙]嗎？？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HA! I'M NOT EVEN SURE THAT HE IS [_spamton_0,ALIVE AND WELL]!!!", "哈！我甚至不確定他還[_spamton_0,活得好好的]！！！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_1,ROYAL]?", "[_spamton_1,羅耀]？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ROYAL [_spamton_0,WHAT]? ROYAL [_spamton_0,WHO]?", "羅耀[_spamton_0,什麼]？羅耀[_spamton_0,誰]？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO/WHAT/WHEN/WHY/HOW] IS [_spamton_0,ROYAL]?", "[_spamton_0,誰／什麼／何時／為何／如何]是[_spamton_0,羅耀]？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE SO PATHETIC", "你真可悲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MUMBLING NONSENSE WORDS THROUGH A [_spamton_0,PLAYING CARD]", "隔著[_spamton_0,卡牌]嘀咕莫名其妙的話", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU THINK YOU CAN [_spamton_0,AVOID] YOUR [_spamton_0,UNAVOIDABLE, QUICKLY APPROACHING] DEMISE?", "你以為能[_spamton_0,躲過]那[_spamton_0,無法避免、迅速逼近]的死亡嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THERE]", "[_spamton_0,就在那裡]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT ARE YOU GONNA DO WITHOUT YOUR [_spamton_0,COMMUNICATION DEVICE]???", "沒有你的[_spamton_0,通訊設備]，你能做什麼？？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT IS IT JUST [_spamton_0,ME]", "等等，難道只有[_spamton_0,我]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR DOES IT SOUND LIKE A [_spamton_0,SHIP] IS COMING [_spamton_0,OUR] WAY??", "還是聽起來有一艘[_spamton_0,船]正朝[_spamton_0,我們]駛來？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY [_spamton_0,NOTHING] [_spamton_0,AT HALF PRICE]", "大概只是[_spamton_0,沒什麼][_spamton_0,半價出售]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY JUST A SOUND IN MY [_spamton_0,HEAD], IN MY [_spamton_0,EARS]", "大概只是我[_spamton_0,腦中]、[_spamton_0,耳裡]的聲音", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO WAY A [_spamton_0,SHIP] COULD FIT IN THIS LITTLE [_spamton_0,CABIN FOR SALE]", "[_spamton_0,船]不可能塞進這間小小的[_spamton_0,出售小屋]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WILL NEVER DEFEAT-", "你永遠打不敗——", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAY [_spamton_0,GOODBYE] [_spamton_0,TO YOUR FRIENDS AND FAMILY]", "向[_spamton_0,你的親朋好友]說[_spamton_0,再見]吧", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE [_spamton_0,POWER OF NEO] WAS TOO MUCH FOR YOU", "[_spamton_0,NEO 之力]太強大了，你承受不住", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONFIDENTIAL", "機密", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEFEATED BY A WEAKLING HUMAN...", "竟被一個弱小的人類打敗……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOOOOOOOOOOOOOOO!!!!!!", "不！！！！！！", Language.ChineseTraditional);


        }
    }
