            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled With Whimsy And Joy! But When They Grow Up...", "充滿奇思妙想與歡樂！但當牠們長大……", Language.ChineseTraditional);
