            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jarvis. Call Happy On Whatsapp.", "賈維斯，用 WhatsApp 呼叫哈皮。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yr'sah", "伊爾莎", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Starlit Spear.", "星光之矛。", Language.ChineseTraditional);
