    public class StarCraftCardpackMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for StarCraft_Cardpack Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack: StarCraft", "卡包：星海爭霸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Characters from StarCraft One.", "《星海爭霸》初代的登場角色。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arbiter", "仲裁者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warp fields stabilized.", "折躍力場已穩定。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Danimoth", "達尼莫斯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heroic Arbiter.", "英雄級仲裁者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archon", "執政官", Language.ChineseTraditional);
