    public class SideDeckSelectorMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Side_Deck_Selector Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a squirrel that can block fliers", "能阻擋飛行生物的松鼠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "雄蜂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For when you need just one point of damage", "適合只需要造成1點傷害的時候", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Drone", "雄蟻", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "雄蜂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not much, but it's an ant.", "雖然不強，但牠是隻螞蟻。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppy", "幼犬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This energetic little puppy will dig up a fresh bone every turn", "精力充沛的小狗每回合都會挖出一根新鮮骨頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spare Tentacle", "備用觸手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen that [c:bR]thing[c:] before, but I can tell there are no bones in it.", "我以前從沒見過那個[c:bR]東西[c:]，但我知道它沒有骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One-Eyed Goat", "獨眼山羊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This goat generates additional blood...for a price", "這隻山羊能產生額外鮮血……但要付出代價", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't realize this thing came from eggs", "我沒想到這東西是從蛋裡來的", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emptier Vessel", "更空的容器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here you may replace the creatures in your [c:bR]side deck[c:]", "在這裡，你可以替換[c:bR]副牌組[c:]中的生物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Side Deck Second Chance", "副牌組第二次機會", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are given the option to change your side deck on maps two and three", "你可以在第二、第三張地圖上選擇更換副牌組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is ready to give us side deck options", "雷希準備好提供副牌組選項", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable Sacrifice", "可接受的獻祭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificing [creature] will count as if two creatures were sacrificed", "獻祭[creature]時，視為獻祭了兩個生物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Entrance", "痛苦入場", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal two damage to the player when it enters play.", "[creature]進場時會對玩家造成2點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gelatinous", "膠狀", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has no bones", "[creature]沒有骨頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a Side Deck", "選擇副牌組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Player selected sidedeck card", "玩家選定的副牌組卡牌", Language.ChineseTraditional);


        }
    }
    public class TalkingPossumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Talking_Possum Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, this one. Right. You can keep it. Not much use to me, anyway.", "哦，是這個。對。你可以留著，反正對我沒什麼用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awesome Opossum", "厲害負鼠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Playing dead? What a despicable creature.", "裝死？真是卑劣的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not-So-Awesome Opossum", "沒那麼厲害的負鼠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Alright.[w:1]", "[e:anger]好吧。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]You must be... [w:0.4][c:#280085]confused[c:][w:1].", "[e:neutral]你一定很…… [w:0.4][c:#280085]困惑[c:][w:1]。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I get it.[w:0.2] I do.[w:0.2] It sucks.[w:0.4]", "我懂。[w:0.2]真的。[w:0.2]這很糟。[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]So, uh.[w:0.2] Hi.[w:0.2]", "[e:surprise]所以，呃。[w:0.2]嗨。[w:0.2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're...[w:0.6] [e:anger]stuck together, I suppose.[w:0.2]", "我們……[w:0.6] [e:anger]大概被困在一起了。[w:0.2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]It could be worse.[w:0.2]", "[e:neutral]情況可能更糟。[w:0.2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look on the [c:#280085]bright side![c:][w:0.4]", "往[c:#280085]好處想！[c:][w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... There's no bright side.", "……根本沒有好處。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're all doomed.[leshy:Quiet now.][w:2]", "我們都完蛋了。[leshy:安靜點。][w:2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck.[w:1]", "祝你好運。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You know,[w:0.2] I was[w:0.4]", "[e:surprise]你知道嗎，[w:0.2]我曾經[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]A [c:#280085]scrybe[c:] once.[w:1]", "[e:quiet]是一名[c:#280085]占卜者[c:]。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good times, good times.[w:0.6] Alas.[w:0.6]", "那是段好日子，真是好日子。[w:0.6]唉。[w:0.6]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Now I'm a fucking possum.[w:1]", "[e:surprise]現在我卻是一隻他媽的負鼠。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... This man over there?[w:0.4]", "[e:anger]……那邊那個人？[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That guy?[w:0.6]", "那傢伙？[w:0.6]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]He wasn't so bad before this.[w:1]", "[e:quiet]他以前沒那麼糟。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I still think he has...[w:0.6]", "我還是覺得他……[w:0.6]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... Some good in him.[w:0.4]", "……有些好的一面。[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Some.[w:1]", "[e:anger]一點點。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]... Anyway,[w:0.4] here's my plan-[leshy:Silence.][w:3]", "[e:quiet]……總之，[w:0.4]我的計畫是——[leshy:住口。][w:3]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aight. Got the memo.[w:0.6]", "好吧，我聽懂了。[w:0.6]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Good luck, traveler.[w:1]", "[e:anger]祝你好運，旅人。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]I'm rooting for you.[w:1]", "[e:quiet]我會為你加油。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[a:anger]Here we go again.[w:1]", "[a:anger]又來了。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isn't this FUN?[w:1] [e:surprise]Nope.[w:0.4]", "這不是很有趣嗎？[w:1] [e:surprise]才怪。[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not fun.[w:1]", "一點都不好玩。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]You know, I think[w:0.4]", "[e:neutral]你知道嗎，我覺得[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]You have potential.[w:1]", "[e:quiet]你很有潛力。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm rooting for you.[w:1]", "我支持你。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]Also,[w:0.2] if you[w:0.2], uh[w:0.4]", "[e:neutral]還有，[w:0.2]如果你[w:0.2]，呃[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you find an...[w:0.4] [c:#280085]odd-looking wolf...[c:][w:1]", "如果你找到一隻……[w:0.4] [c:#280085]長相奇怪的野狼……[c:][w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]... Tell him I-[leshy:Enough of that now.][w:2]", "[e:quiet]……告訴他我——[leshy:到此為止。][w:2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killjoy.[w:1]", "掃興鬼。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]This is getting old.[w:1]", "[e:anger]這事越來越煩了。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... You know...[w:0.4]", "[e:anger]……你知道……[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That old man over there?[w:0.4]", "那邊的老人？[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]He has no idea[w:0.2]", "[e:neutral]他完全不知道[w:0.2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He's biting[w:0.2] [e:anger]way[w:0.2] more[w:0.2]", "他攬下了[w:0.2] [e:anger]遠遠[w:0.2]超過[w:0.2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Than he can possibly chew.[w:1]", "[e:surprise]他自己能應付的事。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]Listen to me now.[w:0.6]", "[e:neutral]現在聽我說。[w:0.6]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]You have to-[leshy:Quiet, vermin.][w:2]", "[e:anger]你必須——[leshy:安靜，鼠輩。][w:2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... Vermin?[w:0.2] Excuse me?[w:0.4]", "[e:surprise]……鼠輩？[w:0.2]你說什麼？[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know my name.[w:0.4]", "你知道我的名字。[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's-[leshy:I said quiet.][w:2]", "我叫——[leshy:我說安靜。][w:2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger][c:#280085]Lamb to the slaughter.[c:][w:1]", "[e:anger][c:#280085]待宰的羔羊。[c:][w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]NOT THE FACE!", "[e:surprise]別打臉！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]LEAVE ME ALONE.", "[e:surprise]別煩我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]QUIT IT, GODDAMMIT.", "[e:surprise]住手，該死的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You're lucky I'm trapped as a marsupial.", "[e:surprise]算你走運，我現在被困在有袋動物的身體裡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Okay, I see how it is--", "[e:surprise]好，我知道你想怎樣了——", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]AGAIN??", "[e:surprise]又來？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]AGAIN?? REALLY??", "[e:surprise]又來？？真的？？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Odd feeling.", "[e:surprise]感覺真奇怪。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Maybe skip me, perhaps?", "[e:quiet]也許跳過我，好嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I'd rather you didn't.", "[e:surprise]我寧願你別這麼做。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Have you seen a strange-looking wolf?", "[e:quiet]你見過一隻長相奇怪的野狼嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]It'd be... acceptable.", "[e:neutral]那……可以接受。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I mean, if you insist.", "[e:surprise]我是說，如果你堅持的話。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Would it suit me?", "[e:quiet]這適合我嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... Ah.[w:1]", "[e:surprise]……啊。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]The board.[w:0.4] Again.[w:0.6]", "[e:anger]檯面。[w:0.4]又來了。[w:0.6]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[c:#1e0040]待宰的羔羊。[c:][w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I get it.[w:0.2]I do.[w:0.2]I do.[w:0.4]", "[e:surprise]我懂了。[w:0.2]真的。[w:0.2]我懂了。[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do as you must,[w:0.2] traveler.[w:1]", "做你必須做的事吧，[w:0.2]旅人。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]I'm rooting for you.[w:1]", "[e:neutral]我會為你加油。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Ah.[w:0.2] The board, again.[w:0.2] I see.[w:1]", "[e:surprise]啊。[w:0.2]又是檯面。[w:0.2]我明白了。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger][c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[e:anger][c:#1e0040]待宰的羔羊。[c:][w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... I suppose.[w:1]", "[e:surprise]……大概吧。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Ah, this.[w:1] [e:surprise]Once again.[w:1]", "[e:quiet]啊，這個。[w:1] [e:surprise]又一次。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... I'm ready.[w:1]", "[e:anger]……我準備好了。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You know what's funny?[w:0.4]", "[e:surprise]你知道什麼很可笑嗎？[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]I really liked animals[w:0.4]", "[e:neutral]我以前真的很喜歡動物[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before all of this.[w:1]", "在這一切發生之前。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Now not so much.[w:1]", "[e:surprise]現在就沒那麼喜歡了。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Cameras are ruined too.[w:2]", "[e:anger]相機也被毀了。[w:2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Aim for their throat.[w:1]", "[e:anger]瞄準他們的喉嚨。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]... What?[w:0.4]", "[e:neutral]……什麼？[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Why are you[w:0.2]", "[e:quiet]你為什麼[w:0.2]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "looking at me like that?[w:0.6]", "那樣看著我？[w:0.6]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... If you must.[w:1]", "[e:surprise]……如果你非要這樣。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise][c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[e:surprise][c:#1e0040]待宰的羔羊。[c:][w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]This sounds...[w:0.6]", "[e:anger]這聽起來……[w:0.6]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... [c:#1e0040]acceptable.[c:][w:1]", "[e:surprise]……[c:#1e0040]還能接受。[c:][w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Is it...[w:0.4] gonna...[w:0.4]", "[e:quiet]這會……[w:0.4]會……[w:0.4]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is it gonna hurt?[w:1]", "會痛嗎？[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]This is...[w:0.6] [e:quiet]fine.[w:1]", "[e:surprise]這……[w:0.6] [e:quiet]還好。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... I suppose.[w:1]", "……大概吧。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... Why me?[w:1]", "[e:anger]……為什麼是我？[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... This is weird.[w:1]", "[e:anger]……真奇怪。[w:1]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Fate deals its cards.[w:1]", "[e:quiet]命運發出了它的牌。[w:1]", Language.ChineseTraditional);



        }
    }
    public class SireMoDeersMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Sire_MoDeers Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mitosis", "有絲分裂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the card bearing this sigil is played, it will summon two weaker copies of itself in it's adjacent slots, if possible.", "打出帶有此印記的卡牌時，若可能，在相鄰卡槽召喚兩張較弱的自身副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mo'Deers", "更多鹿類", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card pack that makes sprinter enjoyable, with deers from fiction and reality, to the Polite Bowing Deer to the Preying Deerror! This Card Pack houses 70+ deers by a Community effort, have fun!", "讓衝刺者更有趣的卡包，收錄虛構與現實中的鹿，從垂首鹿到捕獵的迷失鹿應有盡有！這是社群共同製作、包含70多隻鹿的卡包，玩得開心！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Mo'Deers", "能量更多鹿類", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card pack that houses the Energy Deers! from the Advanced Commandeer to the Beastly Gyfrtot, this pack is for people who wants to play with electricity.", "收錄能量鹿的卡包！從高階馭控鹿到野獸禮物鹿，專為想玩電力的玩家準備。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer God", "鹿神", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Deerel", "導管松鼠鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the conduit deerel, this deerel has been modified with technology.", "導管松鼠鹿，這隻松鼠鹿已經過科技改造。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerel", "松鼠鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deerel, it has adapted to it's surrounding antler-clad.", "松鼠鹿，牠用犄角適應了周圍環境。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Moose", "馱運雄駝鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's bearings can be some of use.", "牠的承載物或許有些用處。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hard working pack mule, it is carrying some creatures of use.", "勤勞的馱騾，帶著一些有用的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Deern't", "奇異的鹿非鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bidoof Deer", "大牙狸鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Commandeer", "馭控鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the advanced commandeer, unlike it's antler-clad brethren, it uses a more practical weapon.", "高階馭控鹿，不同於身披犄角的同類，牠使用更實用的武器。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Conduit", "導管鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this hooved creation is useful when charged.", "充能後很有用的有蹄類造物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer-ceus", "鹿瑟斯", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the heavenly deer-ceus, it blesses your troupe with might.", "神聖的鹿瑟斯，以力量祝福你的隊伍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engideer", "機樞鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the intellectual engideer, is now engihere.", "聰明的機樞鹿，現在已經在這兒了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazelle", "瞪羚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the gazelle, it can run extreme speeds in a short burst.", "瞪羚可以短時間爆發極快的速度。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gun Deer", "槍鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deformed gundeer, it contains mighty damage, ready to be activated.", "畸形的槍鹿蘊含強大的傷害，隨時準備啟用。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the gyftrot, a twisted monster made from holiday spirit.", "禮物鹿，由節日氣氛組成的扭曲怪物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Cube", "更大的立方體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the perfect cube, feast your eyes of such beauty.", "完美的立方體，盡情欣賞這份美吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect Cube", "完美立方體", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snipeer", "狙擊鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the snipeer, it's accuracy is unmatched.", "狙擊鹿，精準無人能及。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time Deer", "時間鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the time deer, it can bend time to it's will.", "時間鹿，能隨心所欲地操縱時間。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Elk", "陰森麋鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah. The Never-Dying GRIM ELK. Typically the harbinger of doom, it brings carcasses for many.", "啊，永不死亡的陰森麋鹿。通常是厄運的先驅，為許多人帶來屍體。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stunted Deer", "發育不良的鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Where did that eye go..", "那隻眼睛去哪裡了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Augmented Deer", "增強鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps it will like this form better than the last one...", "也許牠會比上一個形態更喜歡這副模樣……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaminskeer", "卡明斯基鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaminsk-eer, my very first deer-th cards.", "卡明斯基鹿，我的第一張鹿系死亡卡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kayceer", "凱茜鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems you found yourself as a Deer-th card Kaycee.", "看來你把自己變成了一張鹿系死亡卡，凱茜。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loui-Stag", "鹿薏絲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the Loui-Stag, converted from it's humanity.", "鹿薏絲，已由人類轉化而成。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reginelk", "雷金麋鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reginelk, i might have repurposed some of my deathcards...", "雷金麋鹿，我可能挪用了幾張死亡卡來製作它……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amoedeer", "阿米巴鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the consequences of forced evolution.", "強制進化的後果。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspideer", "蝕心鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer hasn't reached it's primal form, may you help it evolve?", "這頭鹿尚未達到原始形態，你能幫牠進化嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primal Aspideer", "原始蝕心鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Deer", "盲鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "injured after a brawl with predators, the blind deer stands no chance.", "盲鹿在與掠食者搏鬥時受了傷，已經無力抵抗。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bowing Deer", "垂首鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the polite bowing deer, it shows its gratitude to you.", "有禮的垂首鹿，正向你表達謝意。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bus", "巴士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the devious bus, the cause of most roadkill.", "狡猾的巴士，許多動物慘死車輪之下的元兇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armadeerlo", "犰狳鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Deer", "死鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a carcass, it has value to the trader.", "一具屍體，毛皮商會感興趣的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Jackalope", "死鹿角兔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a carcass, it was killed in an ambush by hunters.", "一具屍體，死於獵人的伏擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerror", "迷失鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the apex predator.", "頂級掠食者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Ant", "鹿蟻", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer ant, providing power to it's fellow ant-lered.", "鹿蟻，為有角的蟻類同伴提供力量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deeratina", "鹿緹娜", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the demonic deeratina, it posseses whoever it lays its sight on.", "惡魔般的鹿緹娜，凡被牠盯上的都會遭到附身。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear", "鹿熊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the rampaged dear, what had angered it has perished, this vile mix of deer and bear is an untouchable beast.", "狂怒的鹿熊，惹怒牠的東西早已滅亡。這邪惡的鹿熊混種是無可匹敵的野獸。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sky Deer", "天空鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a shapeshifting deer, it is stuck in it's bird form.", "善於變形的鹿，現在困在鳥類形態中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Deer", "海洋鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a shapeshifting deer, it is stuck in it's fish form.", "善於變形的鹿，現在困在魚的形態中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerel Ball", "松鼠鹿球", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the swift deerel ball, antlered squirrels connected to each other with pure sheer-will.", "迅敏的松鼠鹿球，有角的松鼠憑著純粹的意志彼此相連。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerer", "逐鹿者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doing tasks costs money.", "執行任務需要花錢。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerman", "鹿人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter how much it tries to scream, It remain silent.", "無論牠如何奮力尖叫，始終發不出聲音。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deern't", "鹿非鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer is... this isn't a deer.", "這頭鹿是……這根本不是鹿。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deeroboros", "銜尾鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it works differently than it's sibling, it does not strengthen through death, but through progress.", "牠與同類不同，並不靠死亡變強，而是靠進展。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Pile", "鹿骸堆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this pile of bones screams in agony, as it begs for power.", "這堆骨頭痛苦地尖叫，苦苦渴求力量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Worm", "蠕蟲鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a dangerous parasite.", "危險的寄生蟲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Findeer", "尋骨鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the excitable bone findeer, it happily digs through the dirt for bones.", "興奮的尋骨鹿，快樂地在泥土裡挖掘骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dire Elk", "冰原麋鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The raging Dire Elk, its antlers rip apart most prey with ease", "狂怒的冰原麋鹿，牠的鹿角能輕易撕碎大多數獵物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calamian Deer", "喀拉米豚鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the calamian deer, this endangered creature cannot afford to die.", "喀拉米豚鹿，這瀕危的生物不能輕易死去。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deeeeer", "鉅鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the chunky Deeeeer, it's size protects adjacent allies..", "壯碩的鉅鹿，以巨大的身軀保護相鄰的盟友。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerfox", "狐鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer-fox, loyal to it's companion.", "狐鹿，對同伴忠心耿耿。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerfox Fawn", "狐鹿幼崽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deerfox fawn, i found this from somewhere else.", "狐鹿幼崽，我從別的地方找到的。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frog Deer", "蛙鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the humble deerfrog, it hops around happily.", "溫順的蛙鹿，快樂地蹦來蹦去。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen Deer", "冰封鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer inside has been crystalized for far too long.", "裡面的鹿已經結晶太久了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Stag", "金色雄鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the golden stag, searching for his sister, lured away by an impostor.", "金色雄鹿尋找著妹妹，卻被冒牌貨引走。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grazing Deer", "吃草的鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer enjoys its meal even during battle.", "這頭鹿即使在戰鬥中也樂於進食。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Deer", "無頭鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it will not stop bleeding, make use of it's situation.", "牠會流血不止，利用這個情況吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hunter", "獵人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imposdeer", "偽裝鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this feels off...", "感覺不太對勁……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tired Deer?", "疲寐鹿？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the fierce jackalope, it calls a mate to help the fight.", "兇猛的鹿角兔，會叫來同伴一起戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long Deer", "長鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the long deer, it might need some push to expand.", "長鹿，可能需要推一把才能伸展開來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerguin", "鹿企獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the quick deerguin, it pounces swiftly.", "迅捷的鹿企獸，撲擊快如閃電。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shed Antlers", "脫落的鹿角", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this antlers has been shed long after.", "這隻鹿角早已脫落。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maze Deer", "迷宮鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it sheds continously as it's antlers rapidly grow.", "鹿角生長迅速，不斷脫落。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megaloceros", "大角鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the extinct megaloceros, reborn to fight another day.", "早已滅絕的大角鹿，再度重生，準備繼續戰鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moose Fawn", "駝鹿幼崽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the youthful moose, even in its childhood, it is powerful.", "年幼的雄駝鹿，雖然年紀小卻很強壯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Deer", "水晶鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "made of crystal, this card can power the needy.", "這張卡由水晶製成，能為需要的同伴提供力量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Mage", "鹿法師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer mage, it requires a certain power to live.", "鹿法師，必須依靠特定力量才能存活。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noelle", "諾艾爾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the frail Noelle, it has potential to be stronger.", "脆弱的諾艾爾，有潛力變得更強。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerthulhu", "克蘇鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the gigantic Deerthulhu, it slashes all opponents with it's might.", "巨大的克蘇鹿，用力量橫掃所有對手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEER?", "鹿？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Legged Deer", "獨腿鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "died a brutal death, it came back to find it's killer.", "慘遭殺害後歸來，尋找殺害牠的兇手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Knight", "鹿騎士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the loyal deer knight, it's fancy strikes can encourage others to it's calling.", "忠心的鹿騎士，華麗的攻擊能鼓舞其他人響應牠的號召。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Osteocoileus", "骨卷鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this skeleton isnt hollow, infact, it is filled to the brim with souls.", "這具骷髏並非空心，而是塞滿了靈魂。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peryton", "鹿角獅鷲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the peryton, the perfect mix of feathers and fur.", "鹿角獅鷲，羽毛與獸毛完美融合。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noelle Pog", "諾艾爾驚訝", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prickly Deer", "尖刺鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its spiny quills shoots out after death.", "牠死後，尖刺便會射出。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongkkall", "叉角鰻羚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slithering predator of the deep. It somehow learned how to grow antlers.", "深海中蜿蜒游動的掠食者，不知怎麼長出了鹿角。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pudu", "普度鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the miniscule pudu, a small deer, for a small choice.", "小小的普度鹿，小小的鹿，一個小小的選擇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raged Moose", "狂怒駝鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the raged moose, it was startled whilst sleeping.", "狂怒的雄駝鹿，在睡夢中受到了驚嚇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reindeer", "馴鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the reindeer, just because it's docile doesnt mean it cant lend a hand.", "馴鹿，即使性情溫順，也能幫上一把。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reindeer Fawn", "馴鹿幼崽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the curious fawn, it's docile nature make its reluctant to fight.", "好奇的幼鹿，性情溫順，不願爭鬥。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rudolph", "魯道夫", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer's glowing nose guide other's to a safer path.", "這頭鹿發光的鼻子為其他人指引更安全的道路。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Short Elk", "短身麋鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pitiful creature. This elk has been truly... scrungled.", "可憐的生物。這頭麋鹿真是……被擠扁了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted Deer", "斑點鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the Spotted deer, don't startle this armed deer.", "斑點鹿，別驚擾這頭全副武裝的鹿。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted Fawn", "斑點鹿幼崽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the Spotted fawn, it's spots are never lost when becoming stronger.", "斑點鹿幼崽，變強之後也不會失去斑點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sire", "尊主", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Space Deer", "宇宙鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the space deer, it dictates where everything should go.", "宇宙鹿，決定萬物該去往何處。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spi-Deer", "蛛鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the SPI-DEER, this creature was made by a bored demigod.", "蛛鹿，是無聊的半神造出的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "i... dont know where this came from.", "我……不知道這東西從哪裡來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore-galope", "孢躍鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deeranged spore-galope, it was never the same since the visit from the mycologists.", "瘋狂的孢躍鹿，自真菌學家來訪後就再也沒恢復原樣。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tentakelpie", "觸幻鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the shape-shifting tentakelpie, it shows its true form during hunts.", "會變形的觸幻鹿，狩獵時才會露出真面目。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Throwback Deer", "溯古鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the persistent throwback deer, how it survives through the years even confuses the scrybe of beasts.", "頑強的溯古鹿，牠如何能存活這麼多年，連野獸占卜者也感到困惑。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tired Deer", "疲寐鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer is sleeping, i suggest waking it up.", "這頭鹿在睡覺，我建議把牠叫醒。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Deer", "覺醒鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "now awakened, it moves around for a perfect strike.", "牠已經醒來，四處移動，尋找完美一擊的機會。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Water Deer", "獐", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer that grows fangs than antlers, this is the nature of the WATER DEER.", "這種鹿長的是獠牙，而非鹿角。獐就是如此。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakened Deer", "衰弱鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakened Fawn", "衰弱幼鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Stag", "白雄鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the white stag, they say it brings good luck.", "白雄鹿，據說能帶來好運。", Language.ChineseTraditional);



        }
    }
    public class ApellaDiseasedCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Apella_Diseased_Cards_Mod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack_Of_The_Diseased", "疫病之群擴展包", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Creatures of the Woods have Befell a Disease. They have been reborn into a New Form.", "森林中的生物染上了疫病，以全新的形態重生。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "airborne dragon", "浮空飛龍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex predator of the sky", "天空的頂級掠食者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feast for all", "所有人的盛宴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trapfrog", "陷阱蛙", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trapper is gonna be upset", "獵人要難過了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hydra dragon", "九頭龍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Three heads are better than one", "三個頭總比一個好", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mule", "騾子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "water dragon", "水龍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such an amazing creature", "多麼驚人的生物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The prospector will be upset", "礦工要難過了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "weasel", "伶鼬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe you can find some use for this worthless creature", "也許你能為這無用的生物找到用途", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased adder", "瘟疫蝰蛇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a horrible fate", "多麼悲慘的命運", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased airborne dragon", "瘟疫浮空飛龍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's become an unholy nightmare", "牠變成了邪惡的夢魘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased alpha", "瘟疫獸群領袖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor thing is about to rot", "這可憐的傢伙快要腐爛了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased bat", "瘟疫蝙蝠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hate these things", "我討厭這些東西", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased bait", "瘟疫魚餌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free bones to ye", "免費的骨頭送給你", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased bullfrog", "瘟疫牛蛙", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it's getting ready to pop", "看起來快要爆開了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased coyote", "瘟疫郊狼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a feral beast", "多麼狂野的野獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased elk", "瘟疫麋鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hmm scary lookin", "嗯，看起來很嚇人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "rusty trapfrog", "生鏽的陷阱蛙", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased grizzly", "瘟疫灰熊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has taken it", "牠已被疫病吞噬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased hydra dragon", "瘟疫九頭龍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a shame what happened to this creature", "這生物遭遇如此下場，真是可惜", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased magpie", "瘟疫喜鵲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even more wild lookin", "看起來更狂野了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased mantis", "瘟疫螳螂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh my god, it is hideous", "天啊，牠真醜", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased mole", "瘟疫鼴鼠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was cute before the disease got to it", "染病之前還挺可愛的", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased moleman", "瘟疫鼴鼠人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has made this into even more of a monster", "疫病讓牠更像怪物了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased mule", "瘟疫騾子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what was really in there", "原來裡面真正藏著的是這東西", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased ouroboros", "瘟疫銜尾蛇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle, even with the disease", "即使身染疫病，仍在無盡循環中", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased packrat", "瘟疫林鼠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still useful", "還是有用的", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased porcupine", "瘟疫豪豬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It grew a tail...", "牠長出尾巴了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased rattler", "瘟疫響尾蛇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has given this thing poison", "疫病讓這東西有了毒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased raven", "瘟疫渡鴉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like it has gone mad", "看起來牠已經發狂了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased ringworm", "瘟疫環形蟲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased skunk", "瘟疫臭鼬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This damned disease has gotten to even the smallest of critters", "這該死的疫病，連最弱小的動物也不放過", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased smoke", "瘟疫燭煙", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That thing scares me", "那東西嚇到我了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased urayuli", "瘟疫毛人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's gotten weaker", "牠變弱了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased vulture", "瘟疫禿鷲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's grown a second head", "牠長出了第二個頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased water dragon", "瘟疫水龍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's such a pitiful creature now", "現在牠真是個可憐的生物", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased weasel", "瘟疫伶鼬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not as worthless now I see", "現在看來也不是一無是處", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased wolf", "瘟疫野狼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even more rabid than it's kin", "比牠的同類還要狂暴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased wolfcub", "瘟疫狼崽", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh god its eye!", "天啊，牠的眼睛！", Language.ChineseTraditional);


        }
    }
    public class LethalCabinMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for LethalCabin Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lethal Cabin", "致命小屋", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Celestial Body: Inscryption.\n Population: Sparse.\n Conditions: Unknown.\n Fauna: [count] species.", "天體：邪惡冥刻。\n族群數量：稀少。\n環境：未知。\n動物群：[count]個物種。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hygrodere", "濕黏怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A eukaryotic organism that can multiply to millions with incredible speed.", "一種能以驚人速度繁殖至數百萬個體的真核生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jester", "小丑怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know as much as I do. I just call it the Jester.", "你和我知道的一樣多。我只管它叫小丑怪。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kidnapper Fox", "擄掠狐", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large mammal with a horizontal jaw and unique skull shape giving it a great biting strength, and a long, frog-like tongue which can reach even twice the length of its spindly body.", "大型哺乳動物，橫向的下顎與特殊的顱骨形狀賦予牠強大的咬合力；其青蛙般的長舌甚至能達到瘦長身軀的兩倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Landmine", "地雷", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manticoil", "四翼鴉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poses little threat and has a generally passive temperament, although it's capable of transmitting deadly diseases.", "威脅很小，性情大致溫順，但能傳播致命疾病。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masked", "假面怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mask Hornets", "假面胡蜂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious creature that takes the form of an escape door in order to lure in potential prey.", "一種神秘生物，會化成逃生門的模樣引誘獵物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nutcracker", "胡桃夾子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "watches with one tireless eye, which only senses movement. It remembers the last creature it noticed, whether they are moving or not.", "牠用一隻不知疲倦的眼睛監視四周，只能感知動靜。牠會記住最後注意到的生物，無論對方是否移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Bird", "老鳥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An autonomous, offensive weapon of war with a humanoid design. Equipped with a spotlight, rocket legs, an acoustic device and a missile launcher, they are truly a sight to behold.", "人形的自主攻擊型戰爭兵器，配備探照燈、火箭腿、聲響裝置和飛彈發射器，外觀令人震撼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roaming Locusts", "遊蕩蝗群", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlike some species which are more prone to jump or fly, roaming locusts are almost never grounded and stay close together even when in smaller numbers.", "有些物種較常跳躍或飛行，遊蕩蝗群則幾乎不落地，即使數量不多也會緊緊聚在一起。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry Turret", "哨兵炮塔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snare Flea", "誘捕蚤", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very large arthropod that possesses the ability to tighten itself around large prey to suffocate.", "巨大的節肢動物，能緊緊纏住大型獵物使其窒息。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore Lizard", "孢子蜥蜴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bulb on its tail secretes a chemical which attracts and accelerates the growth of a fungus, which it can then shake to release spores as a defense mechanism.", "牠尾巴上的球狀物會分泌化學物質，吸引真菌並加速其生長。牠能搖動球體釋放孢子，以此防禦。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thumper", "重擊者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highly aggressive, carnivorous species of hunters, typically at the top of their food chain.", "攻擊性極強的肉食性獵手，通常位於食物鏈頂端。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tulip Snake", "鬱金香蜥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifting heavy and large objects into the air has often been observed as a part of the tulip snake's mating display. They are capable of carrying rocks, plants and even other creatures at least twice their size in an effort to impress their potential mate.", "人們經常觀察到鬱金香蜥在求偶時把巨大沉重的物體舉到空中。牠們能搬起石頭、植物，甚至是體型至少有自己兩倍大的生物，以博取潛在伴侶的青睞。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vain Shroud", "虛榮蔽叢", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baboon Hawk", "狒狒鷹", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As lone scouts, baboon hawks are generally timid and won't attack unless provoked. In greater numbers they can become a great danger.", "狒狒鷹獨自偵察時通常膽小，除非受到挑釁才會攻擊。但數量一多便可能十分危險。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barber", "剃頭怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Also known as the Clay Surgeon, Barber is a pack-forming creature that follows a Master Barber's beat to move and attack unsuspecting prey", "剃頭怪又稱泥陶外科醫師，是一種群居生物。牠們跟隨剃頭大師的節奏行動，攻擊毫無防備的獵物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bunker Spider", "地堡蜘蛛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This enormous arachnid produces silk and lays it around its chosen nesting area, then waits for it to be tripped on.", "這種巨大的蛛形動物在選定的巢穴周圍布下蛛絲，然後等獵物觸網。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Butler", "管家", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deformed like a deflated balloon, this humanoid smells of rotten meat and, if you listen close, you can hear a faint sound of flies buzzing inside...", "這人形生物扭曲得像洩了氣的氣球，身上散發腐肉的氣味。仔細聽，還能聽見體內傳來微弱的蒼蠅嗡嗡聲……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Bees", "電路蜂", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Also known as red bees, these social insects possess the aBEElity to create a field of electrostatic charge.", "這種群居昆蟲又稱紅蜂，能夠產生靜電場。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coil-Head", "彈簧頭", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Known to combust into flames when being dissected or even deactivated, and carries dangerously high levels of radioactive particles.", "據說牠在被解剖甚至停用時都會起火燃燒，身上還帶有含量極高、十分危險的放射性粒子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Company Cruiser", "公司巡航車", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeb", "傑布", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We trust you'll be a great asset to the Company.", "我們相信你會成為公司的得力資產。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earth Leviathan", "大地利維坦", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can burrow as far as 40 meters underground, judging by the incredible excavations it can leave behind.", "從牠留下的巨大挖掘痕跡判斷，牠能鑽入地下深達40公尺。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eyeless Dog", "無眼獵犬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large mammal, hunting in very large packs. They are endurance hunters and attempt to make up for their lack of sight with their sense of hearing.", "大型哺乳動物，以大型群體狩獵。牠們擅長持久追獵，並用聽覺彌補視力的缺失。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Keeper", "森林守護者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhibits a curious behavior similar to that of a human child the age of 5 or 6. It will eat anything it find fascinating.", "行為有如五、六歲的人類孩童，會吃掉任何讓牠覺得有趣的東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Girl", "女鬼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hoarding Bug", "囤積蟲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Given its name due to its territorial nature, they will seek out any object they can find and will protect these objects as a part of the nest.", "因領地意識強烈而得名。牠們會尋找任何能找到的物品，視為巢穴的一部分加以保護。", Language.ChineseTraditional);




        }
    }
    public class RemoxedBossesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Remoxed_Bosses Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Crate", "亡者箱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will deal 1 damage to the Scale in favor for the Player.", "帶有此印記的卡牌死亡時，天平向玩家有利的方向傾斜1點。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dropped Gem", "遺落寶石", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dropped Pearl", "遺落珍珠", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanted Frog", "附魔蛙", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Crew", "寶石小隊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Trap", "寶石陷阱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will kill the opposing card.", "帶有此印記的卡牌死亡時，消滅對面的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Nugget", "寶石礦塊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minecart", "礦車", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Seaman", "魔思力水手", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem powered Trap", "寶石驅動陷阱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Powder", "橘色粉末", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will grant the opossing card +1 Attack Power and the Orange Mox Sigil.", "帶有此印記的卡牌死亡時，對面的卡牌獲得+1攻擊力與橘色魔思力印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overloaded", "過載", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move in the inscribed direction and leave behind a Orange Mox.", "擁有者的回合結束時，帶有此印記的卡牌會沿印記方向移動，並在原位留下一張橘色魔思力卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oyster", "牡蠣", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remoxed Bosses", "寶石重製頭目", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Re-adds the Great White to the card pool.", "將大白鯊重新加入卡池。", Language.ChineseTraditional);

        }
    }
    public class TerrariascryptionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Terrariascryption Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hivemind", "蜂群意識", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of Crimson tribes on the board.", "此印記所表示的數值等於檯面上猩紅族類的數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare think that you can skip this fight?", "你竟敢以為自己能跳過這場戰鬥？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare think that you can skip this fight? Face Moonlord, you coward!", "你竟敢以為自己能跳過這場戰鬥？面對月亮領主吧，懦夫！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation won't interrupt this fight!", "[c:bR]飢餓不會中斷這場戰鬥！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Flames", "詛咒之火", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gets harmed by Acids every turn.", "[creature]每回合都會受到酸液傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Protected", "防火", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can not be damaged by cursed flames.", "[creature]不會受到詛咒之火的傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Flamethrower", "詛咒噴火器", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] discharges cursed flames to harm the opposing creature over time.", "[creature]釋放詛咒之火，持續傷害對面的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AngryTrapper", "憤怒獵人", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Man Eater consumes enough human flesh, it undergoes a cocoon-like metamorphosis into a far deadlier form.", "食人怪吞食足夠的人肉後，會經歷如同結繭般的蛻變，變成致命得多的形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Crawler", "血爬蟲", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Most spiders operate independently, but ones touched by the Crimson hive coordinate together to consume life.", "大多數蜘蛛獨自行動，但受到猩紅蜂巢影響的蜘蛛會協同行動，吞噬生命。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Mummy", "血木乃伊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The blood-dripping organic matter in these mummies display far better preservation than the rest of their ilk.", "這些木乃伊不斷滴血的有機組織，比同類的其他個體保存得更好。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Slime", "藍色史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A simple, gelatinous creature that swallows anything and everything whole! It takes a long time to digest anything.", "簡單的膠狀生物，什麼都會整個吞下！牠消化任何東西都要花很長時間。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corruptor", "腐化者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like a cancer, the putrid creatures born from the Corruption mutate and grow into bigger, more deadly forms which discharge acids.", "從腐化之地誕生的腐爛生物，如癌症般不斷變異生長，成為更大、更致命，會噴吐酸液的形態。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupt Slime", "腐化史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steeped in the power of Corruption, these slimes can survive being cut apart into smaller pieces, unlike their untainted brethren.", "浸透腐化之力的史萊姆，即使被切成小塊也能存活，未受污染的同類卻做不到。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimera", "猩紅喀邁拉", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most common horror to be born from the Crimson, it seeks to consume pure things with unrelenting hunger.", "猩紅之地最常見的恐怖造物，永不止息地渴望吞噬純淨之物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dasher", "疾衝者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will Dash in the direction inscribed on the sigil, Attacking whoever stands infront of it.", "持牌人的回合結束時，[creature]會沿印記方向疾衝，攻擊前方的對象。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerclops", "獨眼巨鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from a distant land, this cyclopic monstrosity lurks in cold places, wreaking havoc on those who disturb it.", "這隻獨眼怪獸來自遙遠之地，潛伏在寒冷的地方，對打擾牠的人肆意破壞。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Demon", "惡魔", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Demons are the infantry of the underworld. Unlike their lesser brothers, they cast shadow magic rather than hell magic.", "惡魔是地獄的步兵。牠們與低階同類不同，施展的是暗影魔法，而非地獄魔法。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worm-like monstrosities are the Corruption's most favored creatures, tunneling underneath unsuspecting victims.", "蠕蟲般的怪物是腐化之地最偏愛的生物，會在毫無防備的獵物腳下掘出地道。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eater of Souls", "噬魂怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Birthed from the Corruption as a being of pure malice, its sole instincts are to pursue, punish, and kill.", "牠誕生於腐化之地，是純粹惡意的化身，唯一的本能就是追逐、懲罰與殺戮。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eater of Worlds", "吞世者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conceived from the bottomless malice of the Corruption, this mighty abyssal worm tunnels wildly to devour all in its path.", "這條強大的深淵巨蟲由腐化之地無盡的惡意孕育而生，瘋狂鑽掘，吞噬沿途的一切。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empress of Light", "光之女皇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beneath the Hallow's cleansing blanket lies a vengeful fae goddess bent on scrubbing the land of any and all impurity.", "聖地潔淨的表象之下藏著一位復仇心切的仙靈女神，誓要掃除這片土地上的一切污穢。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon lord", "月亮領主", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye Of Cthulu", "克蘇魯之眼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A piece of Cthulhu ripped from his body centuries ago in a bloody war. It wanders the night seeking its host body... and revenge!", "數百年前在一場血腥戰爭中，牠被從克蘇魯身上扯下。如今在夜間遊蕩，尋找本體……以及復仇！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye Servant", "僕從之眼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Face Monster", "臉怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It would be unwise to face off with one of these unfeeling, hungry mutations. Their mouths are large enough to devour all things.", "與這些冷酷飢餓的變異體正面交鋒並不明智，牠們的巨口足以吞下任何東西。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon Awakening", "月之覺醒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Creature behind the Moon has awoken...", "月亮背後的生物甦醒了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Tortoise", "巨型陸龜", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one takes the giant tortoises seriously. Not until they come hurtling through the air, a spinning, spiky ball of death.", "沒有人會把巨型陸龜當回事，直到牠們變成旋轉的致命刺球，呼嘯著騰空而來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herpling", "蹦蹦獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These hyper, demented, slug-like fiends serve the crimson horde with an unstoppable appetite for blood and flesh.", "這些亢奮瘋狂、形似蛞蝓的魔物效命於猩紅大軍，對血肉的渴望永不止息。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hooked", "鉤爪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook", "鉤子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will summon Hooks on either side of it.", "[creature]會在自身兩側召喚鉤子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if [creature] is not surrounded by a card bearing the Hooked Sigil it will loose all attack.", "如果[creature]周圍沒有帶有鉤爪印記的卡牌，就會失去所有攻擊力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aggressive flying insects which swarm the jungle depths. Their venomous barbs discharge over great distances at high velocity.", "這些極具攻擊性的飛蟲在叢林深處成群活動，能高速遠距離射出帶毒的尖刺。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Slime", "冰雪史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimes that spent too long in arctic temperatures may begin to partially freeze, developing a shifting layer of ice on their surface.", "長時間處於極寒環境的史萊姆可能會部分凍結，表面逐漸形成一層變動的冰。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Ice Slime", "尖刺冰雪史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Ice Slime has large ice shards in its mass from excessive exposure to the cold.Somehow, it is able to launch these at its prey.", "這隻冰雪史萊姆長期暴露在寒冷環境中，體內形成了巨大的冰片。不知為何，牠能將冰片射向獵物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor", "靈液", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gets damaged for the damage * 2.", "[creature]受到的傷害翻倍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Protected", "靈液防護", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creatures]s defense can not be lowered by ichor.", "[creature]的防禦力不會被靈液降低。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Discharging", "靈液噴發", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] discharges Ichor to lower the opposing creatures defenses.", "[creature]會釋放靈液，降低對面生物的防禦力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Sticker", "靈液黏怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled to the brim with powerful ichor, these squid-like abominations spew their corrosive bio-fluid at their prey.", "這些魷魚般的畸形怪物體內充滿強力靈液，會向獵物噴出腐蝕性的體液。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King Slime", "史萊姆王", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimes normally aren't intelligent, but occasionally they merge together to become a powerful force to swallow all things.", "史萊姆通常沒有智慧，但有時會彼此融合，形成一股吞噬萬物的強大力量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engulfer", "吞食者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. Creatures in the way will be engulfed.", "持牌人的回合結束時，[creature]會沿印記方向移動，吞食路上的生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lavaborne", "熔岩之身", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will hide underneath Lava. Any card willing to attack will be damaged by the Lava", "[creature]會藏在熔岩下。任何試圖攻擊牠的卡牌都會受到熔岩傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leap", "跳躍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to choose an empty slot to move [creature] into and deal 1 damage to the opposing slot.", "支付2根骨頭，選擇一個空卡槽將[creature]移入，並對其對面卡槽造成1點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lunar Spells", "月之法術", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will create Spells as it strafes.", "[creature]側移時會產生法術。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LunaticCultist", "拜月教邪教徒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lightning Orb", "閃電球", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Mist", "冰霧", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lord of the Moon", "月亮領主", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chest", "箱子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talking to a chest doesn't cause craziness, but if the chest answers back, it may cause death! It still contains rare treasure, regardless!", "和寶箱說話不會讓人發狂，但要是寶箱回答，可能會送命！不管怎樣，裡面仍有稀世珍寶！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupted Mimic", "腐化模仿者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimics which fall to Corruption grow larger and more powerful as a result. They can be birthed from ordinary chests by force.", "遭到腐化的模仿者因此變得更大、更強。普通寶箱也可以被強制轉化，孕育出牠們。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Mimic", "猩紅模仿者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "True Eye", "真眼", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phase Switcher", "相位切換", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon Death, [creature] will reach its next Phase.", "[creature]死亡時，會進入下一個階段。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Pillar", "星雲柱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Pillar", "日耀柱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stardust Pillar", "星塵柱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vortex Pillar", "星旋柱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pixie", "妖精", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A larger, more luminous form of fairy. Pixies provide the Hallow with more blessed light and aid in the cleansing of the land.", "體型較大、更加明亮的仙靈。妖精為聖地帶來更多神聖的光芒，協助淨化大地。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plantera", "世紀之花", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dormant, yet powerful floral guardian awoken by the fallout of Cthulhu's destroyed machinations. Its reach spans the entire jungle.", "沉睡而強大的花之守護者，因克蘇魯被摧毀的機關所引發的餘波而甦醒。牠的勢力遍及整片叢林。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Planteras Hook", "世紀花鉤", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purple Slime", "紫色史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will spit out a randomly chosen Rare Card upon being placed.", "放置[creature]時，牠會吐出一張隨機挑選的稀有卡片。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Slime", "紅色史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who needs muscles, skin, or even eyeballs? Skeletons get by with just the bones on their back, just as deadly as more fleshy foes.", "誰需要肌肉、皮膚甚至眼球？骷髏只靠一身骨頭就能生存，和有血有肉的敵人一樣致命。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Serpent", "骨蛇", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mighty serpentine dragons once ruled hell, but long ago shed their obsidian scales.A skeletal husk is all that remains.", "強大的蛇形巨龍曾統治地獄，卻在很久以前褪去了黑曜石鱗片，如今只剩骸骨空殼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimer", "惡翅史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slimer has become airborne with wings of unknown origin. The wings are easily knocked off with force, depriving it of its flight.", "惡翅史萊姆長出了來歷不明的翅膀，得以飛行。翅膀容易被打掉，失去翅膀後便無法飛行。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Man Eater", "食人怪", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sharp-toothed plant with a taste for human flesh. It has the ability to hide inside the mud and reach over great distances.", "嗜食人肉、長著利齒的植物，能藏在泥土裡，並伸到很遠的地方。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryad", "樹妖", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time are flowing. And well, you are not aging very gracefully.", "時光的沙流逝不止，而你嘛，老得可不太好看。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guide", "嚮導", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They say there is a person who will tell you how to survive in this land... oh wait. That's me.", "聽說有個人會告訴你如何在這片土地上生存……喔，等等。那個人就是我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tree but ded.", "一棵樹，但死了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cool Slime", "酷酷史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Easily the coolest slime around, no question. You can tell from the backwards hat and indecipherable slang.", "毫無疑問，這是附近最酷的史萊姆。從反戴的帽子和聽不懂的俚語就看得出來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clumsy Slime", "笨拙史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slime was a little confused when the other slimes started putting on hats and accessories. But it did its best.", "其他史萊姆開始戴帽子和飾品時，這隻史萊姆有些困惑，但牠盡力了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nerdy Slime", "書呆子史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a smidge cleverer than other slimes, this slime discovered how to coexist with humans. The secret: accessorizing!", "這隻史萊姆比其他同類稍微聰明一點，發現了和人類共存的方法。秘訣就是：戴飾品！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surly Slime", "暴躁史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irascible and insufferable, this grumpy slime is probably up to no good. Probably. Its the thought that counts really.", "這隻暴躁的史萊姆脾氣差又惹人厭，大概沒安好心。大概啦。反正心意最重要。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Slime", "長老史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Older, though not necessarily wiser, the other slimes look up to the Elder Slime. If it survived this long, it must know something!", "牠年紀較大，卻未必比較有智慧。其他史萊姆都敬仰長老史萊姆，畢竟活了這麼久，總該有些本事！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diva Slime", "天后史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Born of the combined energies of Shimmer and the Queen Slime, this slime is full of boundless energy and enthusiasm! And so fancy!", "由微光與史萊姆女王的能量融合而生，這隻史萊姆充滿無盡的活力與熱情！而且好華麗！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystic Slime", "神秘史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slime knows that great witches wear impressive hats, but it only found a droopy one. Might explain the backfired polymorph!", "這隻史萊姆知道厲害的女巫會戴氣派的帽子，但牠只找到一頂軟塌塌的帽子。這或許能解釋為什麼變形術會反噬！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squire Slime", "侍從史萊姆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hero amongst slimes, it wields the greatest arms and armor known to its kind. It doesn't actually know how to use them, but its a start.", "史萊姆中的英雄，持有同類所知最好的武器與盔甲。牠其實不會用，不過這也是個開始。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unicorn", "獨角獸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These majestic single-horned equines storm angrily through the hallowed land in search of lowly intrusions needing to be cleansed away.", "這些威武的獨角馬憤怒地奔馳於聖地，尋找需要清除的卑劣入侵者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wall Creator", "築牆者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will create a Wall on [creature]s Side.", "[creature]會在[creature]這一側生成一面牆。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wall of Flesh", "血肉牆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serving as the world's core and guardian, the towering demon lord exists to keep powerful ancient spirits sealed away.", "這位高聳的惡魔領主是世界的核心與守護者，存在的目的就是封印強大的遠古靈魂。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Middle Strike", "中央打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right Strike", "向右打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Left Strike", "向左打擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the slot to its right. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature]只攻擊同側右邊卡槽中的卡牌。目標卡槽為空時，傷害會轉向對手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the slot to its left. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature]只攻擊同側左邊卡槽中的卡牌。目標卡槽為空時，傷害會轉向對手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrascryption", "泰拉瑞亞冥刻", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack contains a bunch of awesome Terraria themed Cards!", "這個卡牌包包含許多超棒的泰拉瑞亞主題卡牌！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fortunate draw.", "抽得真幸運。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be safe", "注意安全", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect", "完美", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time are flowing.", "時光的沙流逝不止。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Hope you aren't making a Mistake!", "希望你沒弄錯！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think this works?", "你覺得這樣行嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh what a misplay?", "喔，這步走得真糟！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh!", "喔！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Me.", "選我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't Sacrifice me.", "別獻祭我。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you need to....", "如果你需要的話……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop that.", "住手。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Angler...", "釣魚人……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how disgusting", "真噁心", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just defeat him already", "快點打敗他吧", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boss time, eh?", "要打頭目了，對吧？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor.", "真是榮幸。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is great!", "太棒了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor", "真是榮幸", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fingers crossed", "祈禱好運", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nice Deck.", "牌組不錯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iam here to help You!", "我是來幫你的！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lucky.", "真幸運。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't die", "別死了", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "not the worst draw.", "抽得不算差。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good Choice!", "選得好！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iam a Guide afterall.", "畢竟我可是嚮導。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OK...", "好吧……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its a Good Choice.", "這是個好選擇。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total misplay.", "完全走錯了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yep.", "沒錯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Hope this is right!", "希望這是對的！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sure I guess?", "應該是吧？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Who you want.", "選你想要的吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice me if you need to.", "如果需要的話，就獻祭我吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will still guide you!", "我還是會指引你的！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector. Watch out for his Pickaxe.", "是礦工。小心他的鎬子。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector...", "礦工……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill the Mule for Cards", "殺掉騾子就能拿到卡牌", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mule's key", "騾子是關鍵", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you sure about this?", "你確定要這麼做？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Corruption is waiting for you!", "腐化之地在等著你！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson is waiting for you!", "猩紅之地在等著你！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Brain of Cthulu has awoken!", "克蘇魯之腦甦醒了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a flaming celestial event known as 'solar flares', this tower holds the seal locking away a terrifying tyrant.", "這座塔代表名為「太陽閃焰」的熾熱天象，塔中設有封印，禁錮著一名恐怖的暴君。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a deep celestial void known as 'vortex', this tower holds the seal locking away a terrifying tyrant.", "這座塔代表名為「星旋」的深邃天體虛空，塔中設有封印，禁錮著一名恐怖的暴君。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a stormy celestial body known as 'nebula', this tower holds the seal locking away a terrifying tyrant.", "這座塔代表名為「星雲」的風暴天體，塔中設有封印，禁錮著一名恐怖的暴君。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a glittering celestial remnant known as 'stardust', this tower holds the seal locking away a terrifying tyrant.", "這座塔代表名為「星塵」的閃爍天體殘骸，塔中設有封印，禁錮著一名恐怖的暴君。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And so arrives the Moonlord, harbringer of all Destruction.", "月亮領主降臨，帶來一切毀滅。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You saved us all!", "你拯救了我們所有人！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eater of Worlds has awoken!", "吞世者甦醒了！", Language.ChineseTraditional);

        }
    }
    public class BittysRegionsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for BittysRegions Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TIME TO FORGE METAL!", "該鍛造金屬了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GO MY KNIGHTS!", "上吧，我的騎士們！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah... no materials...", "啊……沒有材料了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>You may claim those are your cards...</color>", "<color=#32CD32>你可以說這些是你的卡牌……</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>But the spiders inside them are MINE!</color>", "<color=#32CD32>但裡面的蜘蛛是我的！</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>A shame... There's none of my spiders on your side...</color>", "<color=#32CD32>可惜……你那一側沒有我的蜘蛛……</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>A spider's bite always strikes when least expected...</color>", "<color=#32CD32>蜘蛛總在最出人意料的時候咬人……</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mad laughter of a wild dog.", "野狗瘋狂的笑聲。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chihuahua", "吉娃娃", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Savage and vicious, all wrapped up in a tiny package.", "小小的身軀裡藏著凶狠與殘暴。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodpecker", "啄木鳥", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The persistent Woodpecker, it strikes endlessly.", "堅持不懈的啄木鳥，不斷發動攻擊。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-rolling squirrel ball, a strange and bizzare phenomenon.", "不停滾動的松鼠球，這是個奇妙又古怪的現象。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mighty hawk, champion of the skies.", "威猛的隼鷹，天空的冠軍。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seagull", "海鷗", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Known as rats of the skies... Or was that another bird?", "被稱為天空中的老鼠……還是那指的是另一種鳥？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hermit Crab", "寄居蟹", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The humble hermit crab. Always seeking a new home.", "平凡的寄居蟹，總是在尋找新家。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rock Wall", "石牆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sheer wall of rock.", "一面陡峭的岩壁。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A world on fire.", "整個世界都在燃燒。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flaming Tree", "燃燒之樹", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Pile", "煤堆", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel for the flames.", "火焰的燃料。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shackle", "鐐銬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bindings forged in flames.", "在火中鍛造的束縛之具。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight", "騎士", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creations of steel and fire.", "鋼鐵與火焰的造物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turtle Rock", "龜岩", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Covered in rocks, with strength to reflect it.", "渾身覆滿岩石，力量也與之相稱。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flamemingo", "火烈鳳", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Phoenix. Always comes back.", "威武的鳳凰，總會再次歸來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flamingo in terrible pain. Not to be mistaken with the majestic Phoenix.", "一隻痛苦萬分的火烈鳥，別和威武的鳳凰搞混了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drake", "幼龍", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dwellers of volcanos and other infernal places.", "棲息在火山與其他地獄般的地方。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salamander", "火蜥蜴", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slippery little creature.", "一隻滑溜溜的小生物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flaming Salmon", "燃燒鮭魚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Salmon scarred by searing flames. Native to lava pools.", "被烈焰灼傷的鮭魚，原生於熔岩池。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A savage beast of the depths.", "來自深處的凶暴野獸。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Ant", "火蟻", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hundreds scurry from their anthill.", "數百隻從蟻丘裡奔出。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Boy", "煤童", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A freakish creation. It bites.", "一個怪異的造物。牠會咬人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brood Mother", "育雛母蛛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mother of many, stored inside her own body.", "無數幼蛛的母親，牠們都藏在母親體內。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Childlike wonder, monsterous body.", "孩童般的好奇心，怪物般的身軀。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Spider", "寄生蜘蛛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infesting everything it touches.", "寄生於牠接觸到的一切。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg Sack", "卵囊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sac of eggs.", "一袋卵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Daddy Long Legs", "長腳蜘蛛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tall and spindly, father of none.", "身形高挑，長腿細瘦，卻不是誰的父親。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pillar?", "石柱？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pillar?", "一根石柱？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Spider", "狼蛛", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As deadly as a normal wolf, but more skittish.", "和普通野狼一樣致命，但更加膽小易驚。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Night Mare", "夢魘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fragment of a darkened dream. It harms everything, including allies.", "幽暗夢境的碎片。牠會傷害一切，包括盟友。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rampaging monster of many legs.", "一隻橫衝直撞的多足怪物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doom Clock", "末日時鐘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient calendar foretelling the end of the world.", "預言世界末日的古老曆法。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chair", "椅子", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange metal chair.", "一把奇怪的金屬椅。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elk Mage", "麋鹿法師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ambitious Elk, making its way in the world.", "雄心勃勃的麋鹿，正在世上闖出自己的路。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mus-Elk Mage", "肌肉麋鹿法師", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Muscle Mage's incarnation. Muscular and beautiful.", "健壯法師的化身，強壯又美麗。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glowing Buck", "發光雄鹿", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully fledged master of luminescence.", "真正精通發光之術的大師。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fading light.", "逐漸消逝的光。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack adds [count] new cards that are found in every region. (There are more cards that are region specific!)", "此卡牌包新增了[count]張在所有區域都能找到的卡牌。（還有更多只在特定區域出現的卡牌！）", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The damp air of the underground...", "地下潮濕的空氣……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And water dripping down stalagmites...", "還有沿著石筍滴下的水……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You entered... [c:bG]The Infested Caves.[c:]", "你進入了……[c:bG]蟲患洞窟。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Webs line the walls...", "蛛網覆滿牆壁……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The skittering of many legs echo throughout the caverns...", "無數條腿爬動的聲音在洞窟中迴盪……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With trepidation, you enter... [c:bG]The Infested Caves.[c:]", "你懷著恐懼，走進……[c:bG]蟲患洞窟。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cool air of the caverns greeted your face...", "洞窟涼爽的空氣迎面而來……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you crept below...", "你悄悄走向地下……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Into [c:bG]The Infested Caves.[c:]", "進入了[c:bG]蟲患洞窟。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smell of sulfur...", "硫磺的氣味……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And falling ash...", "還有飄落的灰燼……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You reach... [c:bG]The Lava Flow.[c:]", "你抵達了……[c:bG]熔岩流地帶。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You see the land glowing in the distance...", "你看見遠方的大地泛著光……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Molten rock, flowing in rivers...", "熔融的岩石，匯成河流……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have reached... [c:bG]The Lava Flow.[c:]", "你已抵達……[c:bG]熔岩流地帶。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The landscape is dark with ash...", "大地被灰燼染得一片昏暗……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees are burning...", "樹木正在燃燒……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You tread through... [c:bG]The Lava Flow.[c:]", "你穿行於……[c:bG]熔岩流地帶。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time you will choose a region specific card.", "這次你要選擇一張區域限定卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose wisely.", "慎重選擇吧。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You approach a great stone forge.", "你走近一座巨大的石製鍛爐。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems that you aren't alone.", "看來你並不孤單。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The clanging of metal reverberates around you.", "金屬敲擊的聲音在你四周迴盪。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sparks spill from the forge.", "火花從鍛爐中四濺。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You run into a nearby cave to escape the smell of sulfur.", "你跑進附近的洞窟，躲避硫磺的氣味。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "However, this cave is inhabited.", "然而這座洞窟已有住客。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am the blacksmith, [c:bG]Martel.[c:]", "我是鐵匠，[c:bG]馬特爾。[c:]", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The old man has given me the opportunity to face you properly...", "那位老人讓我有機會和你堂堂正正地交手……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am the blacksmith.", "我是鐵匠。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's forge you into a fine creation.", "就讓我把你鍛造成一件精良的造物。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you... are the iron.", "而你……就是鐵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time, challenger.", "時候到了，挑戰者。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for you to see the true meaning of... PERFECTION.", "是時候讓你見識……完美的真正意義。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You approach the deepest part of the cave.", "你走近洞窟最深處。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long legs creep out of the shadows, as many smaller spiders skitter around.", "長腿從暗影中探出，許多小蜘蛛在四周爬動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A light hearted voice calls out to you.", "一個輕快的聲音對你說話。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>Ahuhuhu~</color>", "<color=#32CD32>啊呵呵呵～</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>My, who do we have here?</color>", "<color=#32CD32>哎呀，看看是誰來了？</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>It's been so long since I've seen a Challenger...</color>", "<color=#32CD32>好久沒見過挑戰者了……</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>Let's have some fun...</color>", "<color=#32CD32>一起玩玩吧……</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>I am the queen of the spiders,</color>", "<color=#32CD32>我是蜘蛛女王，</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>And You're LUNCH!</color>", "<color=#32CD32>而你是午餐！</color>", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is this...", "這是……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new map?", "一張新地圖？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who stands at the end of this path...", "我不知道這條路的盡頭有誰在等著……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're not meant to see this dialogue.", "你本不該看到這段對話。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something has gone wrong.", "出了什麼差錯。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insect Swarm", "昆蟲群", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of insects that the owner has on their side of the table.", "此印記所表示的數值等於擁有者這一側檯面上的昆蟲數量。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create Terrain", "創造地形", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random terrain is created on the opposing space.", "打出[creature]時，在正對面的位置隨機生成一個地形。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg Sacks", "卵囊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, Spiderlings are created on the owner's empty spaces.", "[creature]死亡時，在擁有者的空位上生成幼蛛。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many Legs", "多足", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a Leg is created in its place and a card bearing this sigil moves to the right.", "[creature]受到攻擊時，在原位生成一條腿，帶有此印記的卡牌向右移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Stock", "骨頭儲備", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a bone is generated for card on the owner's side of the board.", "打出[creature]時，擁有者這一側檯面上每張卡牌都生成一根骨頭。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flip Attack", "反轉攻擊", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, swap its Power and Health.", "[creature]攻擊時，互換其攻擊力與生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inflamed", "灼燒", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, discard the oldest card in your hand.", "[creature]受到攻擊時，棄置手牌中最早的一張卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recursive", "循環再生", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes or is discarded, a copy of it is created in your deck.", "[creature]死亡或被棄置時，在你的牌組中生成一張牠的副本。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scuttler", "疾行者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of battle, [creature] will move in the direction inscribed in the sigil.", "戰鬥開始時，[creature]會沿印記所示方向移動。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Growth", "幽暗滋長", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent and opposing cards gain 1 power and lose 1 health.", "[creature]死亡時，同一側左右相鄰的卡牌及正對面的卡牌獲得1點攻擊力，失去1點生命力。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] counts down. If this sigil reaches 0, you lose.", "每回合結束時，[creature]會倒數。若此印記的數值降到0，你就輸了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muscle Milk", "肌肉牛奶", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be played on other cards. When [creature] is played on another card, it gains 1 power and loses 1 health.", "[creature]可以打在其他卡牌上。將[creature]打在另一張卡牌上時，被覆蓋的卡牌獲得1點攻擊力和1點生命力，然後此生物死亡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoning", "召喚", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card of the same cost tier is summoned to the right.", "打出[creature]時，在右側隨機召喚一張同費用等級的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrain Dweller", "地形寄居者", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be played on terrain cards. When [creature] is played on a terrain card, the terrain gains this creature's stats and sigils.", "[creature]可以打在地形卡牌上。將[creature]打在地形卡牌上時，該地形獲得此生物的屬性和印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blazing Deck", "燃燒牌組", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will draw 1 card from your deck with Fleeting.", "擁有者的回合開始時，[creature]會從你的牌組抽取1張帶有稍縱即逝印記的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellows", "風箱", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, draw 1 card from your side deck with Fleeting.", "[creature]受到攻擊時，從副牌組抽取1張帶有稍縱即逝印記的卡牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Swarm", "松鼠群", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and drop a Squirrel in its old space. Creatures that are in the way will be pushed in the same direction.", "擁有者的回合結束時，[creature]會沿印記所示方向移動，並在原位留下一隻松鼠。擋路的生物會被推向相同方向。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, deal a single damage point to the opposing card.", "打出[creature]時，對正面卡牌造成1點傷害。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Limit", "手牌上限", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] is in your hand or on the board, discard your oldest card until you have 4 or less cards in your hand, or the oldest card has this sigil.", "每回合結束時，若[creature]在你的手牌或檯面上，便棄置你最早入手的卡牌，直到手牌剩下4張或更少，或最早入手的卡牌帶有此印記為止。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Devour", "吞噬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing card is consumed. If this creature dies, the consumed creature is returned to the hand.", "打出[creature]時，吞食對面的卡牌。若此生物死亡，被吞食的生物會回到手牌。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discard Shield", "棄牌護盾", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards in your hand have Fleeting removed from them. When a card is drawn, Fleeting is removed from it.", "打出[creature]時，移除手中所有卡牌的稍縱即逝印記。抽取卡牌時，移除該卡牌的稍縱即逝印記。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anthill", "蟻丘", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is discarded while [creature] is on the board, create a Fire Ant in your hand.", "[creature]在檯面上時，每當卡牌被棄置，在你的手牌中生成一隻火蟻。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spider's Host", "蜘蛛宿主", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a spiderling crawls out.", "[creature]死亡時，一隻幼蛛會爬出來。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Bite", "寄生之咬", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks another creature, that creature's sigils are removed and becomes host to a spiderling.", "[creature]攻擊另一個生物時，移除該生物的印記，使其成為幼蛛的宿主。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AH HA HA!", "啊哈哈哈！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S ME!", "是我！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LIGHT, LIGHT!", "光，光！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I BURN!", "我在燃燒！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I SEE YOU!", "我看見你了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES!", "對！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN, BURN!", "燒吧，燒吧！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DIE, DIE!", "去死，去死！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I BURN SO BRIGHTLY!", "我燃燒得好耀眼！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "COAL BOY, AWAY!", "煤童出動！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERFECT!", "完美！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AHAHAHAH", "啊哈哈哈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AHAHAHAHA", "啊哈哈哈哈", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BLINDING LIGHT!", "耀眼的光！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EVERYONE SHALL KNOW MY PAIN!", "大家都要體會我的痛苦！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO COLD...", "好冷……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARKNESS...", "黑暗……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FADING...", "漸漸消逝……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RELEASE!", "解脫！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PICK ME!", "選我！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL SHINE!", "我會閃閃發光！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LIGHT BECKONS!", "光在召喚！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ME, ME!", "我，我！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO BRIGHT!", "好亮！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reminds me of him...", "讓我想起他……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO GOOD FROM DARK!", "黑暗中沒有好東西！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ASHES, LIGHT!", "灰燼，光！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LIGHT BECKONS!", "光在召喚！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FLAMES!", "火焰！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT HURTS!", "好痛！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARKNESS, DARKNESS!", "黑暗，黑暗！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M BURNING!", "我在燃燒！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DOOM APPROACHES...", "末日將至……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "REJOICE!", "歡呼吧！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ever closer to him...", "離他越來越近了……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I TRANSCEND!", "我超越了！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LIGHT!", "光！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STARS, HORSESHOES!", "星星，馬蹄鐵！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TRIAL BY FIRE!", "烈火試煉！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARKNESS HIDING!", "黑暗在躲藏！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DID YOU GET IT?", "你懂了嗎？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM COAL BOY!", "我是煤童！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOY OF COAL!", "煤之子！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU!", "你！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PICKAXE MAN!", "拿鎬子的人！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE MINES COAL!", "他挖煤！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOLD SHINES BRIGHTLY!", "黃金亮閃閃！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN THE DOGS!", "燒掉那些狗！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOSS TIME!", "頭目時間！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AHAHAHAHAHAHAHAHA!", "啊哈哈哈哈哈哈哈哈！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FISH MAN!", "魚人！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUCKETS OF FISH!", "一桶桶的魚！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIIIISH!", "魚——！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO DARK AND COLD...", "又黑又冷……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TWINS?", "雙子？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHINY KNIVES!", "閃亮的刀！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIM!", "是他！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The moon...", "月亮……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMBODIMENT OF DARKNESS...", "黑暗的化身……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PHANTOMS, DEMONS!", "幽靈，惡魔！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DARK, DARK!", "黑暗，黑暗！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MOONLIGHT...", "月光……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TRI CANDLE LIGHT!", "三支燭光！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHERE'S THE SUN?", "太陽在哪裡？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HEAVE,", "嘿喲，", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HO!", "嘿！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GUNPOWDER!", "火藥！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOOM!", "轟！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't burn water...", "水是燒不起來的……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CREATE SPARKS!", "擦出火花！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite!", "點火！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MASTER!", "大師！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S HIM! IT'S HIM!", "是他！是他！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have brought me into your hand.", "你將我帶到了手中。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello again.", "又見面了。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For glory!", "為了榮耀！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EN GUARDE!", "準備應戰！", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reforged...", "重鑄……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heat and iron.", "熱與鐵。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will be good.", "這會很棒。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you must.", "如果你非要如此。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only a flesh wound.", "只是皮肉傷。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ergh.", "呃。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oof.", "唔。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will not fail.", "我不會失敗。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stronger...", "更強……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I grow.", "我在成長。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A trial...", "一場試煉……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I shouldn't be here.", "我不該在這裡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And yet I am.", "然而我就在這裡。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He mines ore for the Master.", "他為大師採礦。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the old man's permission of course.", "當然，也得到了老人的許可。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector.", "礦工。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He races against the Diver...", "他與潛行者賽跑……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Angler.", "釣魚人。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't actually know what they do.", "其實我不知道他們做些什麼。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who are they?", "他們是誰？", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The old man...", "那位老人……", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He trades with the master sometimes.", "他有時和大師交易。", Language.ChineseTraditional);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Master.", "大師。", Language.ChineseTraditional);


        }
    }
